import type { AstropressPlatformAdapter } from "../platform-contracts";
import { resolveAstropressHostedProviderFromEnv } from "../project-env";
import {
	type AstropressAppwriteHostedAdapterOptions,
	createAstropressAppwriteHostedAdapter,
} from "./appwrite";
import { type AstropressNeonHostedAdapterOptions, createAstropressNeonHostedAdapter } from "./neon";
import {
	type AstropressNhostHostedAdapterOptions,
	createAstropressNhostHostedAdapter,
} from "./nhost";
import {
	type AstropressPocketbaseHostedAdapterOptions,
	createAstropressPocketbaseHostedAdapter,
} from "./pocketbase";
import {
	type AstropressSupabaseHostedAdapterOptions,
	createAstropressSupabaseHostedAdapter,
} from "./supabase";
import {
	type AstropressTursoHostedAdapterOptions,
	createAstropressTursoHostedAdapter,
} from "./turso";

export type AstropressHostedProviderKind =
	| "supabase"
	| "appwrite"
	| "pocketbase"
	| "nhost"
	| "neon"
	| "turso";

export type AstropressHostedAdapterOptions =
	| ({
			provider?: "supabase";
			env?: Record<string, string | undefined>;
	  } & AstropressSupabaseHostedAdapterOptions)
	| ({
			provider: "appwrite";
			env?: Record<string, string | undefined>;
	  } & AstropressAppwriteHostedAdapterOptions)
	| ({
			provider: "pocketbase";
			env?: Record<string, string | undefined>;
	  } & AstropressPocketbaseHostedAdapterOptions)
	| ({
			provider: "nhost";
			env?: Record<string, string | undefined>;
	  } & AstropressNhostHostedAdapterOptions)
	| ({
			provider: "neon";
			env?: Record<string, string | undefined>;
	  } & AstropressNeonHostedAdapterOptions)
	| ({
			provider: "turso";
			env?: Record<string, string | undefined>;
	  } & AstropressTursoHostedAdapterOptions);

export function resolveAstropressHostedProvider(
	provider?: string | null,
): AstropressHostedProviderKind {
	return resolveAstropressHostedProviderFromEnv({
		ASTROPRESS_HOSTED_PROVIDER: provider ?? undefined,
	});
}

export function createAstropressHostedAdapter(
	options: AstropressHostedAdapterOptions = {},
): AstropressPlatformAdapter {
	const provider = resolveAstropressHostedProvider(
		options.provider ?? resolveAstropressHostedProviderFromEnv(options.env ?? process.env),
	);

	if (provider === "appwrite") {
		return createAstropressAppwriteHostedAdapter(
			options as Extract<AstropressHostedAdapterOptions, { provider: "appwrite" }>,
		);
	}

	if (provider === "pocketbase") {
		return createAstropressPocketbaseHostedAdapter(
			options as Extract<AstropressHostedAdapterOptions, { provider: "pocketbase" }>,
		);
	}

	if (provider === "nhost") {
		return createAstropressNhostHostedAdapter(
			options as Extract<AstropressHostedAdapterOptions, { provider: "nhost" }>,
		);
	}

	if (provider === "neon") {
		return createAstropressNeonHostedAdapter(
			options as Extract<AstropressHostedAdapterOptions, { provider: "neon" }>,
		);
	}

	if (provider === "turso") {
		return createAstropressTursoHostedAdapter(
			options as Extract<AstropressHostedAdapterOptions, { provider: "turso" }>,
		);
	}

	return createAstropressSupabaseHostedAdapter(
		options as Extract<AstropressHostedAdapterOptions, { provider?: "supabase" }>,
	);
}

src/adapters/pocketbase.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import { stripTrailingSlashes } from "../path-helpers";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressPocketbaseHostedConfig {
	url: string;
	email: string;
	password: string;
	apiBaseUrl: string;
	previewBaseUrl: string;
}

export type AstropressPocketbaseAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

export function createAstropressPocketbaseAdapter(
	options: AstropressPocketbaseAdapterOptions = {},
) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "pocketbase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
	});
}

export interface AstropressPocketbaseHostedAdapterOptions
	extends AstropressPocketbaseAdapterOptions {
	config?: AstropressPocketbaseHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressPocketbaseHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressPocketbaseHostedConfig {
	const url = env.POCKETBASE_URL?.trim();
	const email = env.POCKETBASE_EMAIL?.trim();
	const password = env.POCKETBASE_PASSWORD?.trim();

	if (!url || !email || !password) {
		throw new Error(
			"PocketBase hosted config requires POCKETBASE_URL, POCKETBASE_EMAIL, and POCKETBASE_PASSWORD.",
		);
	}

	return {
		url,
		email,
		password,
		apiBaseUrl: `${stripTrailingSlashes(url)}/api/astropress`,
		previewBaseUrl: stripTrailingSlashes(url),
	};
}

export function createAstropressPocketbaseHostedAdapter(
	options: AstropressPocketbaseHostedAdapterOptions = {},
) {
	const config = options.config ?? readAstropressPocketbaseHostedConfig(options.env);
	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "pocketbase",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: `${config.email}:${config.password}`,
			previewBaseUrl: `${config.previewBaseUrl}/preview`,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
			},
		});
	}

	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "pocketbase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${config.previewBaseUrl}/preview`,
				};
			},
		},
	});
}

