import type {
	AstropressPlatformAdapter,
	MediaAssetRecord,
	RevisionRecord,
} from "../platform-contracts";
import { normalizeProviderCapabilities } from "../platform-contracts";
import { registerHealthCheck } from "../runtime-health";
import { createAstropressSqliteAdminRuntime } from "../sqlite-admin-runtime";
import {
	type AstropressSqliteSeedToolkit,
	createDefaultAstropressSqliteSeedToolkit,
} from "../sqlite-bootstrap";
import {
	appendSqliteRevision,
	deleteSqliteContentRecord,
	getSqliteMedia,
	listSqliteContentRecords,
	putSqliteMedia,
	saveSqliteContentRecord,
} from "./sqlite-helpers.js";

export interface AstropressSqliteAdapterOptions {
	dbPath?: string;
	workspaceRoot?: string;
	seedToolkit?: AstropressSqliteSeedToolkit;
}

export function createAstropressSqliteAdapter(
	options: AstropressSqliteAdapterOptions = {},
): AstropressPlatformAdapter {
	const seedToolkit = options.seedToolkit ?? createDefaultAstropressSqliteSeedToolkit();
	const workspaceRoot = options.workspaceRoot ?? process.cwd();
	const dbPath = options.dbPath ?? seedToolkit.getDefaultAdminDbPath(workspaceRoot);
	let seeded = false;
	let database: ReturnType<AstropressSqliteSeedToolkit["openSeedDatabase"]> | null = null;

	function ensureDatabase() {
		if (!seeded) {
			seedToolkit.seedDatabase({ dbPath, workspaceRoot });
			seeded = true;
		}
		if (!database) {
			database = seedToolkit.openSeedDatabase(dbPath);
		}
		return database;
	}

	registerHealthCheck(() => {
		ensureDatabase().prepare("SELECT 1").get();
	});

	const actor = {
		email: "admin@example.com",
		role: "admin" as const,
		name: "Astropress SQLite",
	};
	const runtime = createAstropressSqliteAdminRuntime({
		getDatabase: ensureDatabase,
	});

	return {
		capabilities: normalizeProviderCapabilities({
			name: "sqlite",
			hostedAdmin: true,
			previewEnvironments: true,
			serverRuntime: true,
			database: true,
			objectStorage: false,
			gitSync: true,
		}),
		auth: {
			async signIn(email, password) {
				const user = await runtime.authenticatePersistedAdminUser(email, password);
				if (!user) return null;
				const sessionId = runtime.sqliteAdminStore.auth.createSession(user, {});
				runtime.sqliteAdminStore.auth.recordSuccessfulLogin(user);
				return {
					id: sessionId,
					email: user.email,
					isAdmin: user.role === "admin",
				};
			},
			async signOut(sessionId) {
				const user = runtime.sqliteAdminStore.auth.getSessionUser(sessionId);
				runtime.sqliteAdminStore.auth.revokeSession(sessionId);
				if (user) runtime.sqliteAdminStore.auth.recordLogout(user);
			},
			async getSession(sessionId) {
				const user = runtime.sqliteAdminStore.auth.getSessionUser(sessionId);
				return user
					? {
							id: sessionId,
							email: user.email,
							isAdmin: user.role === "admin",
						}
					: null;
			},
		},
		content: {
			async list(kind) {
				return listSqliteContentRecords(runtime, ensureDatabase, kind);
			},
			async get(id) {
				const normalizedId = id.trim();
				if (!normalizedId) return null;
				const all = await this.list();
				return (
					all.find((record) => record.id === normalizedId || record.slug === normalizedId) ?? null
				);
			},
			async save(record) {
				return saveSqliteContentRecord(runtime, record, actor);
			},
			async delete(id) {
				const existing = await this.get(id);
				if (!existing) return;
				deleteSqliteContentRecord(runtime, existing, actor);
			},
		},
		media: {
			async put(asset: MediaAssetRecord) {
				putSqliteMedia(ensureDatabase, asset, actor.email);
				return asset;
			},
			async get(id) {
				return getSqliteMedia(runtime, id);
			},
			async delete(id) {
				runtime.sqliteAdminStore.media.deleteMediaAsset(id, actor);
			},
		},
		revisions: {
			async list(recordId) {
				return (runtime.sqliteAdminStore.content.getContentRevisions(recordId) ?? []).map(
					(revision): RevisionRecord => ({
						id: revision.id,
						recordId: revision.slug,
						createdAt: revision.createdAt,
						actorId: revision.createdBy ?? null,
						summary: revision.revisionNote ?? null,
						// audit-boundary: opaque-passthrough -- driver row-shape mirror; values narrowed at consumer
						snapshot: revision as unknown as Record<string, unknown>,
					}),
				);
			},
			async append(revision) {
				appendSqliteRevision(
					ensureDatabase,
					revision as {
						id: string;
						recordId: string;
						// audit-boundary: opaque-passthrough -- driver row-shape mirror; values narrowed at consumer
						snapshot: Record<string, unknown>;
						summary?: string | null;
						createdAt: string;
						actorId?: string | null;
					},
					actor.email,
				);
				return revision;
			},
		},
	};
}

src/admin-action-mailchimp-import.ts.source:
import type { APIContext } from "astro";
import { getNewsletterConfig } from "./runtime-env";
import { createLogger } from "./runtime-logger";

const logger = createLogger("MailchimpImport");

export interface MailchimpImportResult {
	ok: boolean;
	imported: number;
	skipped: number;
	error?: string;
}

/**
 * Parses a Mailchimp audience CSV export.
 * Required column: "Email Address"
 * Optional columns: "First Name", "Last Name"
 * Returns cleaned subscriber records ready for Listmonk bulk import.
 */
function parseMailchimpCsv(csv: string): Array<{ email: string; name: string }> {
	const lines = csv.trim().split(/\r?\n/);
	if (lines.length < 2) return [];

	const headers = lines[0]?.split(",").map((h) => h.replace(/^"|"$/g, "").trim());
	const emailIdx = headers.findIndex((h) => h.toLowerCase() === "email address");
	const firstIdx = headers.findIndex((h) => h.toLowerCase() === "first name");
	const lastIdx = headers.findIndex((h) => h.toLowerCase() === "last name");

	if (emailIdx === -1) return [];

	const records: Array<{ email: string; name: string }> = [];
	for (let i = 1; i < lines.length; i++) {
		const cols = lines[i]?.split(",").map((c) => c.replace(/^"|"$/g, "").trim());
		const email = cols[emailIdx] ?? "";
		if (!email?.includes("@")) continue;
		const first = firstIdx !== -1 ? (cols[firstIdx] ?? "") : "";
		const last = lastIdx !== -1 ? (cols[lastIdx] ?? "") : "";
		const name = [first, last].filter(Boolean).join(" ") || email;
		records.push({ email, name });
	}
	return records;
}

export async function runMailchimpImport(
	csvText: string,
	locals: APIContext["locals"],
): Promise<MailchimpImportResult> {
	const cfg = getNewsletterConfig(locals);

	if (
		cfg.mode !== "listmonk" ||
		!cfg.listmonkApiUrl ||
		!cfg.listmonkApiUsername ||
		!cfg.listmonkApiPassword ||
		!cfg.listmonkListId
	) {
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error:
				"Listmonk is not configured. Set NEWSLETTER_DELIVERY, LISTMONK_API_URL, LISTMONK_API_USERNAME, LISTMONK_API_PASSWORD, and LISTMONK_LIST_ID.",
		};
	}

	const records = parseMailchimpCsv(csvText);
	if (records.length === 0) {
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error: 'No valid subscriber rows found. Make sure the file has an "Email Address" column.',
		};
	}

	const auth = btoa(`${cfg.listmonkApiUsername}:${cfg.listmonkApiPassword}`);
	const listId = Number(cfg.listmonkListId);

	// Listmonk bulk import: POST /api/subscribers/import with CSV records string
	const csvBody = ["email,name", ...records.map((r) => `${r.email},${r.name}`)].join("\n");

	try {
		const res = await fetch(`${cfg.listmonkApiUrl}/api/subscribers/import`, {
			method: "POST",
			headers: {
				Authorization: `Basic ${auth}`,
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				mode: "subscribe",
				subscription_status: "confirmed",
				delims: ",",
				lists: [listId],
				records: csvBody,
			}),
		});

		if (!res.ok) {
			const body = await res.text();
			logger.error("Listmonk bulk import error", { status: res.status, body });
			return {
				ok: false,
				imported: 0,
				skipped: 0,
				error: `Listmonk returned ${res.status}. Check your credentials.`,
			};
		}

		logger.info("Mailchimp import completed", { count: records.length });
		return { ok: true, imported: records.length, skipped: 0 };
	} catch (err) {
		logger.error("Mailchimp import network error", { err });
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error: "Network error reaching Listmonk. Check LISTMONK_API_URL.",
		};
	}
}

src/admin-action-utils.ts.source:
import type { APIRoute } from "astro";
import { logAccessDeny } from "./access/audit-deny.js";
import { getAccessContext } from "./access/index.js";
import {
	ADMIN_ACTION_LOGGER_CONTEXT,
	DEFAULT_ACTION_DENIED_MESSAGE,
	DEFAULT_ADMIN_REQUIRED_MESSAGE,
	DEFAULT_INVALID_CSRF_MESSAGE,
	DEFAULT_INVALID_ORIGIN_MESSAGE,
	DEFAULT_LOGIN_PATH,
	DEFAULT_UNEXPECTED_MESSAGE,
	LEGACY_SESSION_COOKIE,
	LOCAL_SESSION_COOKIE,
	SECURE_SESSION_COOKIE,
} from "./admin-action-utils-data";
import { isAuthUserAdmin } from "./platform-contracts.js";
import { getRuntimeCsrfToken, getRuntimeSessionUser } from "./runtime-admin-auth";
import { getLoginSecurityConfig, getRuntimeEnv } from "./runtime-env.js";
import { createLogger } from "./runtime-logger.js";
import { createAstropressSecureRedirect, isTrustedRequestOrigin } from "./security-headers.js";

const logger = createLogger(ADMIN_ACTION_LOGGER_CONTEXT);

type AdminActionContext = Parameters<NonNullable<APIRoute>>[0];
type AdminSessionUser = NonNullable<Awaited<ReturnType<typeof getRuntimeSessionUser>>>;

type GuardOptions = {
	failurePath: string;
	loginPath?: string;
	requireAdmin?: boolean;
	/**
	 * ABAC action ID required to run this handler. When set, the access
	 * engine evaluates `can(requireAction)` against the session subject;
	 * a deny short-circuits the request with `actionRequiredMessage` (or
	 * the engine's reason). Admins bypass evaluation by definition.
	 */
	requireAction?: string;
	invalidCsrfMessage?: string;
	invalidOriginMessage?: string;
	adminRequiredMessage?: string;
	actionDeniedMessage?: string;
	unexpectedMessage?: string;
};

type GuardResult =
	| { ok: true; sessionUser: AdminSessionUser; formData: FormData }
	| { ok: false; response: Response };

type ActionContext = {
	sessionUser: AdminSessionUser;
	actor: { email: string; role: AdminSessionUser["role"]; name: string };
	formData: FormData;
	locals: AdminActionContext["locals"];
	request: Request;
	fail: (message: string, overridePath?: string) => Response;
	redirect: (location: string, status?: number) => Response;
};

export function actionRedirect(location: string, status = 302): Response {
	return createAstropressSecureRedirect(location, status, {
		forceHsts: location.startsWith("https://"),
	});
}

export function actionErrorRedirect(path: string, message: string): Response {
	const url = new URL(path, "https://astropress.invalid");
	url.searchParams.set("error", "1");
	url.searchParams.set("message", message);
	return actionRedirect(url.pathname + url.search);
}

/**
 * Success counterpart to {@link actionErrorRedirect}: redirects to `path`
 * carrying a free-text confirmation in `?notice=1&message=…`, which AdminLayout
 * surfaces in its action-notice live region.
 */
export function actionNoticeRedirect(path: string, message: string): Response {
	const url = new URL(path, "https://astropress.invalid");
	url.searchParams.set("notice", "1");
	url.searchParams.set("message", message);
	return actionRedirect(url.pathname + url.search);
}

async function checkActionPermission(
	context: AdminActionContext,
	options: GuardOptions,
	sessionUser: { email: string },
): Promise<Response | null> {
	if (!options.requireAction) return null;
	const access = await getAccessContext({ locals: context.locals });
	const decision = access?.can(options.requireAction);
	if (decision && decision.decision !== "deny") return null;
	if (decision) {
		await logAccessDeny(context.locals, {
			subjectEmail: access?.subject.email ?? sessionUser.email,
			action: options.requireAction,
			decision,
		});
	}
	return actionErrorRedirect(
		options.failurePath,
		options.actionDeniedMessage ?? decision?.reason ?? DEFAULT_ACTION_DENIED_MESSAGE,
	);
}

async function checkCsrf(
	context: AdminActionContext,
	options: GuardOptions,
	sessionToken: string | undefined,
	formData: FormData,
): Promise<Response | null> {
	const expectedToken =
		(await getRuntimeCsrfToken(sessionToken, context.locals)) ??
		(getRuntimeEnv("PLAYWRIGHT_E2E_MODE") === "admin-harness"
			? (context.locals.csrfToken ?? null)
			: null);
	const submittedToken = String(formData.get("_csrf") ?? "");
	if (expectedToken && submittedToken === expectedToken) return null;
	return actionErrorRedirect(
		options.failurePath,
		options.invalidCsrfMessage ?? DEFAULT_INVALID_CSRF_MESSAGE,
	);
}

export async function requireAdminFormAction(
	context: AdminActionContext,
	options: GuardOptions,
): Promise<GuardResult> {
	const secureCookies = getLoginSecurityConfig(context.locals).secureCookies;
	const sessionCookieName = secureCookies ? SECURE_SESSION_COOKIE : LOCAL_SESSION_COOKIE;
	const sessionToken =
		context.cookies.get(sessionCookieName)?.value ??
		context.cookies.get(LEGACY_SESSION_COOKIE)?.value;
	const harnessAdminUser =
		getRuntimeEnv("PLAYWRIGHT_E2E_MODE") === "admin-harness" ? context.locals.adminUser : null;
	// The harness injects an AuthUser; project it onto the AdminSessionUser shape
	// ({ email, role, name, isAdmin }) the rest of this guard and ActionContext use.
	const harnessSessionUser: AdminSessionUser | null = harnessAdminUser
		? {
				email: harnessAdminUser.email,
				role: harnessAdminUser.isAdmin ? "admin" : "editor",
				name: harnessAdminUser.name ?? harnessAdminUser.email,
				isAdmin: harnessAdminUser.isAdmin,
			}
		: null;
	const sessionUser =
		(await getRuntimeSessionUser(sessionToken, context.locals)) ?? harnessSessionUser;

	if (!sessionUser) {
		return {
			ok: false,
			response: actionRedirect(options.loginPath ?? DEFAULT_LOGIN_PATH),
		};
	}

	if (options.requireAdmin && !isAuthUserAdmin(sessionUser)) {
		return {
			ok: false,
			response: actionErrorRedirect(
				options.failurePath,
				options.adminRequiredMessage ?? DEFAULT_ADMIN_REQUIRED_MESSAGE,
			),
		};
	}

	const denyResponse = await checkActionPermission(context, options, sessionUser);
	if (denyResponse) return { ok: false, response: denyResponse };

	if (!isTrustedRequestOrigin(context.request)) {
		return {
			ok: false,
			response: actionErrorRedirect(
				options.failurePath,
				options.invalidOriginMessage ?? DEFAULT_INVALID_ORIGIN_MESSAGE,
			),
		};
	}

	const formData = await context.request.formData();
	const csrfFailure = await checkCsrf(context, options, sessionToken, formData);
	if (csrfFailure) return { ok: false, response: csrfFailure };

	return { ok: true, sessionUser, formData };
}

export async function withAdminFormAction(
	context: AdminActionContext,
	options: GuardOptions,
	run: (action: ActionContext) => Promise<Response> | Response,
): Promise<Response> {
	const actionPath = new URL(context.request.url).pathname;
	try {
		const guarded = await requireAdminFormAction(context, options);
		if (!guarded.ok) {
			return guarded.response;
		}

		const { sessionUser, formData } = guarded;
		logger.info("admin action", {
			path: actionPath,
			actor: sessionUser.email,
			role: sessionUser.role,
		});
		return await run({
			sessionUser,
			actor: {
				email: sessionUser.email,
				role: sessionUser.role,
				name: sessionUser.name,
			},
			formData,
			locals: context.locals,
			request: context.request,
			fail: (message, overridePath) => {
				logger.warn("admin action failed", {
					path: actionPath,
					actor: sessionUser.email,
					message,
				});
				return actionErrorRedirect(overridePath ?? options.failurePath, message);
			},
			redirect: actionRedirect,
		});
	} catch (err) {
		logger.error("admin action error", {
			path: actionPath,
			error: String(err),
		});
		return actionErrorRedirect(
			options.failurePath,
			options.unexpectedMessage ?? DEFAULT_UNEXPECTED_MESSAGE,
		);
	}
}

