src/deploy/shared.ts.source:
import { cp, mkdir, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { stripTrailingSlashes } from "../path-helpers";

export interface AstropressPreparedDeploymentOptions {
	provider: string;
	outputDir?: string;
	baseUrl?: string;
}

export async function prepareAstropressDeployment(
	input: {
		buildDir: string;
		projectName: string;
		environment?: string;
	},
	options: AstropressPreparedDeploymentOptions,
) {
	const baseOutputDir = resolve(
		options.outputDir ?? join(input.buildDir, "..", ".astropress", "deployments", options.provider),
	);
	const targetDir = join(baseOutputDir, input.projectName);
	await rm(targetDir, { recursive: true, force: true });
	await mkdir(dirname(targetDir), { recursive: true });
	await cp(input.buildDir, targetDir, { recursive: true });

	const metadata = {
		provider: options.provider,
		projectName: input.projectName,
		preparedAt: new Date().toISOString(),
		environment: input.environment ?? "production",
	};
	await writeFile(
		join(targetDir, ".astropress-deploy.json"),
		`${JSON.stringify(metadata, null, 2)}\n`,
	);

	let url: string | undefined;
	if (options.baseUrl) {
		const trimmed = stripTrailingSlashes(options.baseUrl);
		url = `${trimmed}/${input.projectName}/`;
	}

	return {
		deploymentId: `${options.provider}:${input.projectName}:${Date.now()}`,
		url,
	};
}

src/donations.ts.source:
import type { DonationsConfig } from "./config";
import { stripTrailingSlashes } from "./path-helpers";
import type { AstropressDonationsProviders } from "./project-scaffold";

export interface DonationSnippets {
	/** GiveLively widget HTML, or "" when not configured or opted out. */
	giveLively: string;
	/** Liberapay static button HTML, or "" when not configured. Never suppressed by DNT/GPC. */
	liberapay: string;
	/** PledgeCrypto widget HTML, or "" when not configured or opted out. */
	pledgeCrypto: string;
	/** PledgeCrypto head `<script>` tag, or "" when not configured or opted out. */
	pledgeCryptoHeadScript: string;
	/** schema.org DonateAction JSON-LD block, or "" when no providers are configured. */
	jsonLd: string;
}

/**
 * Resolves donation widget snippets for all configured providers.
 *
 * GiveLively and PledgeCrypto snippets are suppressed when the visitor has
 * opted out of tracking (DNT: 1 or Sec-GPC: 1). Liberapay is static HTML
 * with no external JavaScript and is never suppressed.
 *
 * @param donations - The DonationsConfig from registerCms(), or undefined.
 * @param siteUrl - The canonical site URL, used in the JSON-LD DonateAction block.
 * @param optedOut - True when the visitor has sent DNT: 1 or Sec-GPC: 1.
 */
export function resolveDonationSnippets(
	donations: DonationsConfig | undefined,
	siteUrl: string,
	optedOut: boolean,
): DonationSnippets {
	const any = !!(donations?.giveLively || donations?.liberapay || donations?.pledgeCrypto);

	const giveLively =
		!optedOut && donations?.giveLively
			? buildGiveLivelySnippet(donations.giveLively.orgSlug, donations.giveLively.campaignSlug)
			: "";

	const liberapay = donations?.liberapay ? buildLiberapaySnippet(donations.liberapay.username) : "";

	const pledgeCrypto =
		!optedOut && donations?.pledgeCrypto
			? buildPledgeCryptoSnippet(donations.pledgeCrypto.partnerKey)
			: "";

	const pledgeCryptoHeadScript =
		!optedOut && donations?.pledgeCrypto
			? `<script src="https://widget.pledgecrypto.com/pledge-widget.js" defer></script>`
			: "";

	const donateUrl = `${stripTrailingSlashes(siteUrl)}/donate`;
	const jsonLd = any
		? JSON.stringify({
				"@context": "https://schema.org",
				"@type": "DonateAction",
				url: donateUrl,
				target: donateUrl,
			})
		: "";

	return {
		giveLively,
		liberapay,
		pledgeCrypto,
		pledgeCryptoHeadScript,
		jsonLd,
	};
}

function escAttr(value: string): string {
	return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

function buildGiveLivelySnippet(orgSlug: string, campaignSlug?: string): string {
	const identifier = escAttr(campaignSlug ? `${orgSlug}/${campaignSlug}` : `${orgSlug}/${orgSlug}`);
	return [
		`<script src="https://assets.givelively.org/widget/simple_fundraiser.js" defer></script>`,
		`<div id="give-lively-widget" class="gl-simple-fundraiser-widget"`,
		`  data-campaign-identifier="${identifier}">`,
		"</div>",
	].join("\n");
}

function buildLiberapaySnippet(username: string): string {
	const safe = escAttr(username);
	return [
		`<a href="https://liberapay.com/${safe}/donate">`,
		`  <img alt="Donate using Liberapay"`,
		`    src="https://liberapay.com/assets/widgets/donate.svg">`,
		"</a>",
	].join("\n");
}

function buildPledgeCryptoSnippet(partnerKey: string): string {
	return `<div class="plg-donate" data-partner-key="${escAttr(partnerKey)}"></div>`;
}

/**
 * Returns a Record of env-example key/value pairs for the enabled donation providers.
 * Used by the scaffold to populate `.env.example`.
 */
export function buildDonationsEnvExample(
	donations: AstropressDonationsProviders | undefined,
): Record<string, string> {
	if (!donations) return {};
	const result: Record<string, string> = {};
	if (donations.giveLively) {
		result.GIVELIVELY_ORG_SLUG = "replace-with-your-org-slug";
		result.GIVELIVELY_CAMPAIGN_SLUG = "replace-with-your-campaign-slug-or-remove";
	}
	if (donations.liberapay) {
		result.LIBERAPAY_USERNAME = "replace-with-your-liberapay-username";
	}
	if (donations.pledgeCrypto) {
		result.PLEDGE_PARTNER_KEY = "[YOUR_PLEDGE_PARTNER_KEY]";
	}
	return result;
}

src/hosted-api-adapter.ts.source:
import { stripTrailingSlashes } from "./path-helpers";
import {
	type AstropressPlatformAdapter,
	type AuthStore,
	type AuthUser,
	assertProviderContract,
	type ContentStore,
	type ContentStoreRecord,
	type MediaAssetRecord,
	type MediaStore,
	normalizeProviderCapabilities,
	type ProviderCapabilities,
	type RevisionRecord,
	type RevisionStore,
} from "./platform-contracts";

type AstropressFetch = typeof fetch;

export interface AstropressHostedApiAdapterOptions {
	providerName: ProviderCapabilities["name"];
	apiBaseUrl: string;
	accessToken?: string;
	previewBaseUrl?: string;
	defaultCapabilities?: Partial<Omit<ProviderCapabilities, "name">>;
	fetchImpl?: AstropressFetch;
}

function joinApiUrl(baseUrl: string, path: string) {
	return `${stripTrailingSlashes(baseUrl)}/${path.replace(/^\//, "")}`;
}

async function readJson<T>(response: Response): Promise<T> {
	if (!response.ok) {
		throw new Error(`Astropress hosted API request failed with ${response.status}.`);
	}
	return (await response.json()) as T;
}

function createHeaders(accessToken?: string, extra?: Record<string, string>) {
	return {
		"content-type": "application/json",
		...(accessToken ? { authorization: `Bearer ${accessToken}` } : {}),
		...extra,
	};
}

export function createAstropressHostedApiAdapter(
	options: AstropressHostedApiAdapterOptions,
): AstropressPlatformAdapter {
	const fetchImpl = options.fetchImpl ?? fetch;
	const capabilities = normalizeProviderCapabilities({
		name: options.providerName,
		hostedAdmin: true,
		previewEnvironments: true,
		serverRuntime: true,
		database: true,
		objectStorage: true,
		gitSync: true,
		...options.defaultCapabilities,
	});

	const requestJson = async <T>(path: string, init: RequestInit = {}): Promise<T> => {
		const response = await fetchImpl(joinApiUrl(options.apiBaseUrl, path), {
			...init,
			headers: createHeaders(
				options.accessToken,
				init.headers as Record<string, string> | undefined,
			),
		});
		return readJson<T>(response);
	};

	const content: ContentStore = {
		async list(kind) {
			const query = kind ? `?kind=${encodeURIComponent(kind)}` : "";
			return requestJson<ContentStoreRecord[]>(`content${query}`);
		},
		async get(id) {
			return requestJson<ContentStoreRecord | null>(`content/${encodeURIComponent(id)}`);
		},
		async save(record) {
			return requestJson<ContentStoreRecord>("content", {
				method: "POST",
				body: JSON.stringify(record),
			});
		},
		async delete(id) {
			await requestJson<{ ok: true }>(`content/${encodeURIComponent(id)}`, {
				method: "DELETE",
			});
		},
	};

	const media: MediaStore = {
		async put(asset) {
			return requestJson<MediaAssetRecord>("media", {
				method: "POST",
				body: JSON.stringify(asset),
			});
		},
		async get(id) {
			return requestJson<MediaAssetRecord | null>(`media/${encodeURIComponent(id)}`);
		},
		async delete(id) {
			await requestJson<{ ok: true }>(`media/${encodeURIComponent(id)}`, {
				method: "DELETE",
			});
		},
	};

	const revisions: RevisionStore = {
		async list(recordId) {
			return requestJson<RevisionRecord[]>(`revisions?recordId=${encodeURIComponent(recordId)}`);
		},
		async append(revision) {
			return requestJson<RevisionRecord>("revisions", {
				method: "POST",
				body: JSON.stringify(revision),
			});
		},
	};

	const auth: AuthStore = {
		async signIn(email, password) {
			return requestJson<AuthUser | null>("auth/sign-in", {
				method: "POST",
				body: JSON.stringify({ email, password }),
			});
		},
		async signOut(sessionId) {
			await requestJson<{ ok: true }>("auth/sign-out", {
				method: "POST",
				body: JSON.stringify({ sessionId }),
			});
		},
		async getSession(sessionId) {
			return requestJson<AuthUser | null>(`auth/session/${encodeURIComponent(sessionId)}`);
		},
	};

	return assertProviderContract({
		capabilities,
		content,
		media,
		revisions,
		auth,
		preview: options.previewBaseUrl
			? {
					async create(input) {
						return {
							url: joinApiUrl(
								options.previewBaseUrl as string,
								`preview/${encodeURIComponent(input.recordId)}`,
							),
							expiresAt: input.expiresAt,
						};
					},
				}
			: undefined,
	});
}

src/html-sanitization.ts.source:
import {
	allowedAttributes,
	allowedGlobalAttributes,
	allowedSchemes,
	allowedTags,
	dropContentTags,
	srcsetAttributes,
	urlAttributes,
} from "./html-sanitization-data.js";

function isAllowedUrl(value: string) {
	if (!value || value.startsWith("//")) {
		return false;
	}

	const schemeMatch = value.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/);
	if (!schemeMatch) {
		return true;
	}

	return allowedSchemes.has(schemeMatch[1].toLowerCase());
}

function sanitizeSrcset(value: string) {
	const candidates = value
		.split(",")
		.map((candidate) => candidate.trim())
		.filter((candidate) => {
			const [url] = candidate.split(/\s/, 1);
			return Boolean(url) && isAllowedUrl(url);
		});

	return candidates.length > 0 ? candidates.join(", ") : null;
}

function sanitizeAttribute(tagName: string, attributeName: string, attributeValue: string) {
	const allowedForTag = allowedAttributes.get(tagName);
	const isAllowed = allowedForTag?.has(attributeName) || allowedGlobalAttributes.has(attributeName);

	if (!isAllowed) {
		return null;
	}

	const trimmedValue = attributeValue.trim();
	if (!trimmedValue && attributeName !== "class") {
		return null;
	}

	if (urlAttributes.has(attributeName)) {
		return isAllowedUrl(trimmedValue) ? trimmedValue : null;
	}

	if (srcsetAttributes.has(attributeName)) {
		return sanitizeSrcset(trimmedValue);
	}

	return trimmedValue;
}

export async function sanitizeHtml(html: string): Promise<string> {
	if (typeof globalThis.HTMLRewriter === "undefined") {
		return sanitizeHtmlLibrary(html, {
			allowedTags: [...allowedTags],
			allowedAttributes: Object.fromEntries(
				[...allowedAttributes.entries()].map(([tagName, attributes]) => [tagName, [...attributes]]),
			),
			allowedSchemes: [...allowedSchemes],
			allowProtocolRelative: false,
			nonBooleanAttributes: ["class"],
			transformTags: {
				a: (tagName, attribs) => ({
					tagName,
					attribs: {
						...attribs,
						rel: "noopener noreferrer",
					},
				}),
			},
		});
	}

	const rewriter = new HTMLRewriter().on("*", {
		element(el) {
			const tag = el.tagName.toLowerCase();

			if (dropContentTags.has(tag)) {
				el.remove();
				return;
			}

			if (!allowedTags.has(tag)) {
				el.removeAndKeepContent();
				return;
			}

			for (const [name, value] of el.attributes) {
				const sanitized = sanitizeAttribute(tag, name, value);
				if (sanitized === null) {
					el.removeAttribute(name);
				} else if (sanitized !== value) {
					el.setAttribute(name, sanitized);
				}
			}

			if (tag === "a") {
				el.setAttribute("rel", "noopener noreferrer");
			}
		},
	});

	return rewriter.transform(new Response(html)).text();
}

import sanitizeHtmlLibrary from "sanitize-html";

