src/integrations/providers/github-deploy.source:
/**
 * GitHub OAuth provider for the deploy-hooks domain.
 *
 * Phase 6 lands GitHub as the first OAuth-flow provider. The connect
 * surface here pins only the access token — the OAuth start/callback
 * routes (Phase 6b) seal the token via the Phase 2 envelope after a
 * successful state verification, then call this provider's verify()
 * to make sure the token actually has access before persisting.
 *
 * verify() runs a GET against `/user` and classifies the response:
 *
 *   200          → token valid                  → connected
 *   401          → token rejected               → INTEGRATION_AUTH_REJECTED
 *   403          → token lacks scope            → INTEGRATION_AUTH_REJECTED
 *   404          → unexpected (api shape)       → INTEGRATION_VERIFY_FAILED
 *   429          → rate-limited                 → INTEGRATION_RATE_LIMITED
 *   other ¬ok    → INTEGRATION_VERIFY_FAILED
 */

import { z } from "zod";

import type { IntegrationErrorCode } from "../../integration-error-sanitizer.js";
import { registerDeployHooks } from "../domains.js";
import type { RegisteredProvider } from "../registry.js";

export const GITHUB_DEPLOY_FIELDS = z.object({
	accessToken: z.string().min(1),
});

export type GithubDeployFields = z.infer<typeof GITHUB_DEPLOY_FIELDS>;

const HOST = "https://api.github.com";
const USER_PATH = "/user";

export class GithubDeployVerifyError extends Error {
	constructor(public readonly code: IntegrationErrorCode) {
		super(code);
		this.name = "GithubDeployVerifyError";
	}
}

export interface GithubDeployVerifyDeps {
	readonly fetch?: typeof fetch;
}

export function buildGithubUserUrl(): string {
	return new URL(USER_PATH, HOST).toString();
}

export function buildGithubAuthHeader(accessToken: string): string {
	return `Bearer ${accessToken}`;
}

/**
 * Pure mapping from a `/user` response to either `null` (success) or
 * a typed integration error code. Pinned independently so a typo in
 * the status table is caught by a unit test.
 */
export function classifyGithubStatus(res: Response): IntegrationErrorCode | null {
	if (res.status === 401 || res.status === 403) {
		return "INTEGRATION_AUTH_REJECTED";
	}
	if (res.status === 429) {
		return "INTEGRATION_RATE_LIMITED";
	}
	if (res.ok) {
		return null;
	}
	return "INTEGRATION_VERIFY_FAILED";
}

export async function verifyGithubDeploy(
	fields: GithubDeployFields,
	ctx: { signal: AbortSignal },
	deps: GithubDeployVerifyDeps = {},
): Promise<void> {
	const fetchImpl = deps.fetch ?? fetch;
	const res = await fetchImpl(buildGithubUserUrl(), {
		method: "GET",
		headers: {
			Authorization: buildGithubAuthHeader(fields.accessToken),
			Accept: "application/vnd.github+json",
			"X-GitHub-Api-Version": "2022-11-28",
			"User-Agent": "astropress-deploy-hooks",
		},
		signal: ctx.signal,
	});
	const code = classifyGithubStatus(res);
	if (code !== null) {
		throw new GithubDeployVerifyError(code);
	}
}

export function registerGithubDeploy(): RegisteredProvider<GithubDeployFields> {
	return registerDeployHooks<GithubDeployFields>({
		id: "github",
		label: "GitHub",
		fields: GITHUB_DEPLOY_FIELDS,
		verify: verifyGithubDeploy,
		defaultErrorCode: "INTEGRATION_AUTH_REJECTED",
	});
}

src/integrations/registry.ts.source:
/**
 * Per-domain integration registry. Phase 3 of integration-honesty.
 *
 * Each registered provider declares:
 *   - `id`         — short stable identifier (`"listmonk"`, `"plausible"`).
 *   - `label`      — human-readable display name shown in the connect UI.
 *   - `fields`     — Zod schema for the secret payload that connect()
 *                    seals via the Phase 2 envelope.
 *   - `verify`     — async callback the connect action runs against the
 *                    decoded payload before persisting. Throws to mark
 *                    the row as `error` with a typed code.
 *   - `runtimeShape` — optional Zod schema for the decoded fields the
 *                      runtime read path expects. Defaults to `fields`.
 *
 * The registry is a transient, in-memory map. Hosts call
 * `registerProvider()` from their setup module (alongside or instead
 * of `registerCms()`); admin actions and runtime adapters look
 * providers up by `(domain, providerId)`.
 *
 * Domain identifiers are deliberately a closed set so a typo at a
 * call site is a TypeScript error, not a silent miss.
 */
import type { z } from "zod";

import type { IntegrationErrorCode } from "../integration-error-sanitizer.js";
import { INTEGRATION_DOMAINS, type IntegrationDomain } from "./registry-data.js";

export { INTEGRATION_DOMAINS, type IntegrationDomain };

export interface ProviderDefinition<TFields extends Record<string, string>> {
	readonly id: string;
	readonly label: string;
	readonly fields: z.ZodType<TFields>;
	readonly verify?: (fields: TFields, ctx: { signal: AbortSignal }) => Promise<void>;
	readonly runtimeShape?: z.ZodType<TFields>;
	/**
	 * Optional override for what error code a thrown {@link verify}
	 * should map to when the thrown value carries no usable hint. The
	 * default sanitiser handles most cases, but providers like Plausible
	 * want a 403 to map to `INTEGRATION_AUTH_REJECTED` rather than
	 * `INTEGRATION_VERIFY_FAILED`.
	 */
	readonly defaultErrorCode?: IntegrationErrorCode;
}

export interface RegisteredProvider<TFields extends Record<string, string> = Record<string, string>>
	extends ProviderDefinition<TFields> {
	readonly domain: IntegrationDomain;
}

export class IntegrationRegistryError extends Error {
	constructor(
		public readonly code: "DUPLICATE_PROVIDER" | "UNKNOWN_DOMAIN",
		message: string,
	) {
		super(message);
		this.name = "IntegrationRegistryError";
	}
}

const registry = new Map<string, RegisteredProvider>();

function key(domain: IntegrationDomain, providerId: string): string {
	return `${domain}|${providerId}`;
}

export function registerProvider<TFields extends Record<string, string>>(
	domain: IntegrationDomain,
	definition: ProviderDefinition<TFields>,
): RegisteredProvider<TFields> {
	if (!INTEGRATION_DOMAINS.includes(domain)) {
		throw new IntegrationRegistryError("UNKNOWN_DOMAIN", `unknown integration domain: ${domain}`);
	}
	const k = key(domain, definition.id);
	if (registry.has(k)) {
		throw new IntegrationRegistryError(
			"DUPLICATE_PROVIDER",
			`provider ${definition.id} already registered for domain ${domain}`,
		);
	}
	const entry: RegisteredProvider<TFields> = { domain, ...definition };
	registry.set(k, entry as unknown as RegisteredProvider);
	return entry;
}

export function getProvider<TFields extends Record<string, string>>(
	domain: IntegrationDomain,
	providerId: string,
): RegisteredProvider<TFields> | undefined {
	return registry.get(key(domain, providerId)) as RegisteredProvider<TFields> | undefined;
}

export function listProviders(domain: IntegrationDomain): readonly RegisteredProvider[] {
	const out: RegisteredProvider[] = [];
	for (const [k, v] of registry) {
		if (k.startsWith(`${domain}|`)) out.push(v);
	}
	return out;
}

/**
 * Test-only helper: clear all registered providers. Production code
 * never calls this — providers register at boot and live for the
 * process lifetime.
 */
export function _resetRegistryForTests(): void {
	registry.clear();
}

src/integrations/runtime.ts.source:
/**
 * Runtime read path for connected integrations. Adapter code that
 * needs the live API key/secret for a connected provider calls
 * {@link getConnectedProvider} once per request and is handed back
 * the typed-validated decoded fields.
 *
 * The status surface (sidebar badges, dashboards) never goes through
 * this module — those callers use {@link IntegrationsRepository.listStatuses}
 * which never touches ciphertext.
 */

import type { RootSecretCandidates } from "../integration-secret-envelope.js";
import type { IntegrationsRepository } from "../sqlite-runtime/integrations.js";

import { getProvider, type IntegrationDomain, listProviders } from "./registry.js";

export interface ConnectedProvider<
	TFields extends Record<string, string> = Record<string, string>,
> {
	readonly domain: IntegrationDomain;
	readonly providerId: string;
	readonly fields: TFields;
}

export interface GetConnectedProviderArgs {
	readonly domain: IntegrationDomain;
	readonly repo: IntegrationsRepository;
	readonly rootSecrets: RootSecretCandidates;
}

/**
 * Find the active connected provider for a domain and return its
 * decoded secret fields. Returns `undefined` when:
 *   - no connected row exists for the domain;
 *   - several providers are connected but none is marked active — the
 *     selection is ambiguous, so we refuse to guess (#127). The admin must
 *     pick one via `setActiveProvider` before the runtime read resolves;
 *   - the resolved row points at a provider id that is not registered.
 *
 * Resolution: prefer the explicitly active connected row; if exactly one
 * provider is connected, treat it as active (the common single-provider case
 * needs no manual selection). The previous behaviour silently picked the first
 * connected provider in list order, which is the bug #127 reports.
 *
 * Throws on decryption failure (KEK/DEK mismatch is operationally
 * fatal — we never want to silently degrade to the unconnected path).
 */
export async function getConnectedProvider<
	TFields extends Record<string, string> = Record<string, string>,
>(args: GetConnectedProviderArgs): Promise<ConnectedProvider<TFields> | undefined> {
	const statuses = args.repo.listStatuses();
	const connected = statuses.filter((s) => s.domain === args.domain && s.status === "connected");
	if (connected.length === 0) return undefined;
	const active =
		connected.find((s) => s.isActive) ?? (connected.length === 1 ? connected[0] : undefined);
	if (!active) return undefined;
	const provider = getProvider<TFields>(args.domain, active.provider);
	if (!provider) return undefined;
	const fields = await args.repo.findSecret<TFields>(
		args.domain,
		active.provider,
		args.rootSecrets,
	);
	const shape = provider.runtimeShape ?? provider.fields;
	const parsed = shape.safeParse(fields);
	if (!parsed.success) return undefined;
	return {
		domain: args.domain,
		providerId: active.provider,
		fields: parsed.data,
	};
}

/**
 * Per-request memoiser. Adapter call sites typically need the
 * decoded fields more than once per request (verify, send, log
 * sanitisation). Wrap a {@link getConnectedProvider} call in a
 * weak per-request cache to avoid re-decrypting on every read.
 */
export function createRequestProviderCache(
	args: GetConnectedProviderArgs,
): () => Promise<ConnectedProvider | undefined> {
	let cached: Promise<ConnectedProvider | undefined> | null = null;
	return () => {
		if (!cached) {
			cached = getConnectedProvider(args);
		}
		return cached;
	};
}

export function listRegisteredProvidersForDomain(
	domain: IntegrationDomain,
): ReadonlyArray<{ id: string; label: string }> {
	return listProviders(domain).map((p) => ({ id: p.id, label: p.label }));
}

