import { parseIdList } from "./admin-normalizers";
import { withLocalStoreFallback } from "./admin-store-dispatch";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";
import {
	insertContentRevision,
	SQL_SELECT_REVISION,
	UPSERT_CONTENT_OVERRIDE_NO_META_SQL,
} from "./runtime-actions-content-helpers";
import {
	ensureD1BaselineRevision,
	findPageRecord,
	replaceD1ContentAssignments,
} from "./runtime-actions-content-shared";
import type { RevisionRow } from "./runtime-actions-content-types";

export async function restoreRuntimeRevision(
	slug: string,
	revisionId: string,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const pageRecord = await findPageRecord(slug, locals);
			if (!pageRecord) {
				return {
					ok: false as const,
					error: "The selected content record could not be found.",
				};
			}

			await ensureD1BaselineRevision(db, pageRecord);

			const revision = await db
				.prepare(SQL_SELECT_REVISION)
				.bind(pageRecord.slug, revisionId)
				.first<RevisionRow>();

			if (!revision) {
				return { ok: false as const, error: "Revision not found." };
			}

			await db
				.prepare(UPSERT_CONTENT_OVERRIDE_NO_META_SQL)
				.bind(
					pageRecord.slug,
					revision.title,
					revision.status,
					revision.body,
					revision.seo_title,
					revision.meta_description,
					revision.excerpt,
					revision.og_title,
					revision.og_description,
					revision.og_image,
					revision.scheduled_at,
					revision.canonical_url_override,
					revision.robots_directive,
					actor.email,
				)
				.run();

			await replaceD1ContentAssignments(db, pageRecord.slug, {
				authorIds: parseIdList(revision.author_ids),
				categoryIds: parseIdList(revision.category_ids),
				tagIds: parseIdList(revision.tag_ids),
			});

			const revSeo = {
				excerpt: revision.excerpt,
				ogTitle: revision.og_title,
				ogDescription: revision.og_description,
				ogImage: revision.og_image,
				canonicalUrlOverride: revision.canonical_url_override,
				robotsDirective: revision.robots_directive,
			};
			await insertContentRevision(db, pageRecord.slug, {
				title: revision.title,
				status: revision.status,
				scheduledAt: revision.scheduled_at,
				body: revision.body ?? "",
				seoTitle: revision.seo_title,
				metaDescription: revision.meta_description,
				seo: revSeo,
				authorIds: revision.author_ids ?? "[]",
				categoryIds: revision.category_ids ?? "[]",
				tagIds: revision.tag_ids ?? "[]",
				revisionNote: revision.revision_note,
				actor,
			});

			await recordD1Audit(
				locals,
				actor,
				"content.restore",
				"content",
				pageRecord.slug,
				`Restored revision ${revisionId} for ${slug}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.restoreRevision(slug, revisionId, actor),
	);
}

src/runtime-actions-integrations.ts.source:
/**
 * Runtime-action wrappers for the per-domain integration registry.
 *

 * Each function takes Astro `App.Locals`, dispatches via
 * `withLocalStoreFallback()` to obtain the host's
 * `IntegrationsRepository`, and routes through the registry's
 * `connectIntegration` / `reverifyIntegration` helpers from
 * `integrations/connect-flow.ts`. This keeps the Astro action
 * endpoints (`pages/ap-admin/actions/integration-*.ts`) thin —
 * they own ABAC, CSRF, and the redirect, but no envelope or
 * Zod-schema awareness.
 *
 * If the local admin store does not expose `integrations` (e.g. an
 * older host that hasn't applied the connected_integrations
 * migration), the helpers return a typed
 * `INTEGRATIONS_NOT_AVAILABLE` error instead of throwing — the
 * admin UI flashes the localised hint and the operator can run
 * the migration before retrying.
 */

import { withLocalStoreFallback } from "./admin-store-dispatch.js";
import {
	type ConnectIntegrationResult,
	connectIntegration,
	reverifyIntegration,
} from "./integrations/connect-flow.js";
import { getProvider, type IntegrationDomain } from "./integrations/registry.js";
import { getAstropressRootSecret } from "./runtime-env.js";
import { createD1IntegrationsRepository } from "./sqlite-runtime/integrations-d1.js";

export type RuntimeIntegrationActionResult =
	| ConnectIntegrationResult
	| {
			readonly ok: false;
			readonly status: "error";
			readonly code: "INTEGRATIONS_NOT_AVAILABLE";
	  }
	| {
			readonly ok: false;
			readonly status: "error";
			readonly code: "INTEGRATION_PROVIDER_NOT_FOUND";
	  }
	| {
			readonly ok: false;
			readonly status: "error";
			readonly code: "ROOT_SECRET_UNCONFIGURED";
	  };

export interface ConnectIntegrationActionInput<
	TFields extends Record<string, string> = Record<string, string>,
> {
	readonly domain: IntegrationDomain;
	readonly providerId: string;
	readonly fields: TFields;
	readonly configJson?: string;
}

export async function connectIntegrationAction<TFields extends Record<string, string>>(
	locals: App.Locals | null | undefined,
	input: ConnectIntegrationActionInput<TFields>,
): Promise<RuntimeIntegrationActionResult> {
	const provider = getProvider<TFields>(input.domain, input.providerId);
	if (!provider) {
		return {
			ok: false,
			status: "error",
			code: "INTEGRATION_PROVIDER_NOT_FOUND",
		};
	}
	// #126: fail closed when no real root secret is configured. getAstropressRootSecret
	// throws in production rather than sealing provider credentials under the public
	// dev fallback; surface it as an explicit typed error before any persistence.
	let rootSecret: string;
	try {
		rootSecret = getAstropressRootSecret(locals);
	} catch {
		return {
			ok: false,
			status: "error",
			code: "ROOT_SECRET_UNCONFIGURED",
		};
	}
	const now = new Date().toISOString();
	return withLocalStoreFallback<RuntimeIntegrationActionResult>(
		locals,
		async (db) => {
			const repo = createD1IntegrationsRepository({ getDb: () => db, now });
			return connectIntegration(repo, {
				provider,
				fields: input.fields,
				configJson: input.configJson,
				now,
				rootSecret,
			});
		},
		async (store) => {
			const repo = store.integrations;
			if (!repo) {
				return {
					ok: false,
					status: "error",
					code: "INTEGRATIONS_NOT_AVAILABLE",
				};
			}
			return connectIntegration(repo, {
				provider,
				fields: input.fields,
				configJson: input.configJson,
				now,
				rootSecret,
			});
		},
	);
}

export async function reverifyIntegrationAction<TFields extends Record<string, string>>(
	locals: App.Locals | null | undefined,
	domain: IntegrationDomain,
	providerId: string,
	fields: TFields,
): Promise<RuntimeIntegrationActionResult> {
	const provider = getProvider<TFields>(domain, providerId);
	if (!provider) {
		return {
			ok: false,
			status: "error",
			code: "INTEGRATION_PROVIDER_NOT_FOUND",
		};
	}
	const now = new Date().toISOString();
	return withLocalStoreFallback<RuntimeIntegrationActionResult>(
		locals,
		async (db) => {
			const repo = createD1IntegrationsRepository({ getDb: () => db, now });
			return reverifyIntegration(repo, provider, fields, now);
		},
		async (store) => {
			const repo = store.integrations;
			if (!repo) {
				return {
					ok: false,
					status: "error",
					code: "INTEGRATIONS_NOT_AVAILABLE",
				};
			}
			return reverifyIntegration(repo, provider, fields, now);
		},
	);
}

export async function setActiveIntegrationProviderAction(
	locals: App.Locals | null | undefined,
	domain: IntegrationDomain,
	providerId: string,
): Promise<
	{ ok: true } | { ok: false; code: "INTEGRATIONS_NOT_AVAILABLE" | "INTEGRATION_NOT_CONNECTED" }
> {
	const now = new Date().toISOString();
	return withLocalStoreFallback<
		{ ok: true } | { ok: false; code: "INTEGRATIONS_NOT_AVAILABLE" | "INTEGRATION_NOT_CONNECTED" }
	>(
		locals,
		async (db) => {
			const repo = createD1IntegrationsRepository({ getDb: () => db, now });
			const ok = await repo.setActiveProvider(domain, providerId);
			return ok ? { ok: true } : { ok: false, code: "INTEGRATION_NOT_CONNECTED" };
		},
		async (store) => {
			const repo = store.integrations;
			if (!repo) return { ok: false, code: "INTEGRATIONS_NOT_AVAILABLE" };
			const ok = repo.setActiveProvider(domain, providerId);
			return ok ? { ok: true } : { ok: false, code: "INTEGRATION_NOT_CONNECTED" };
		},
	);
}

export async function disconnectIntegrationAction(
	locals: App.Locals | null | undefined,
	domain: IntegrationDomain,
	providerId: string,
): Promise<{ ok: true } | { ok: false; code: "INTEGRATIONS_NOT_AVAILABLE" }> {
	const now = new Date().toISOString();
	return withLocalStoreFallback<{ ok: true } | { ok: false; code: "INTEGRATIONS_NOT_AVAILABLE" }>(
		locals,
		async (db) => {
			const repo = createD1IntegrationsRepository({ getDb: () => db, now });
			await repo.disconnect(domain, providerId);
			return { ok: true };
		},
		async (store) => {
			const repo = store.integrations;
			if (!repo) return { ok: false, code: "INTEGRATIONS_NOT_AVAILABLE" };
			repo.disconnect(domain, providerId);
			return { ok: true };
		},
	);
}

src/runtime-actions-password-reset.ts.source:
// ─── Password Reset Actions ───────────────────────────────────────────────────
// Extracted from runtime-actions-users.ts to keep that file under the 400-line limit.

import { normalizeEmail } from "./admin-normalizers";
import { getAdminDb, withLocalStoreFallback } from "./admin-store-dispatch";
import { createKmacDigest } from "./crypto-primitives";
import { hashPassword } from "./crypto-utils";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";
import { getAstropressRootSecret } from "./runtime-env";

async function hashOpaqueToken(token: string) {
	return createKmacDigest(token, getAstropressRootSecret(), "password-reset-token");
}

async function getD1PasswordResetToken(rawToken: string, locals?: App.Locals | null) {
	const db = getAdminDb(locals);
	if (!db || !rawToken.trim()) {
		return null;
	}

	const row = await db
		.prepare(
			`
        SELECT t.id, t.user_id, t.expires_at, t.consumed_at,
               u.email, u.name,
               CASE WHEN u.is_admin = 1 THEN 'admin' ELSE 'editor' END AS role,
               u.active
        FROM password_reset_tokens t
        JOIN admin_users u ON u.id = t.user_id
        WHERE t.token_hash = ?
        LIMIT 1
      `,
		)
		.bind(await hashOpaqueToken(rawToken))
		.first<{
			id: string;
			user_id: number;
			expires_at: string;
			consumed_at: string | null;
			email: string;
			name: string;
			role: "admin" | "editor";
			active: number;
		}>();

	if (!row || row.consumed_at || row.active !== 1 || Date.parse(row.expires_at) < Date.now()) {
		return null;
	}

	return row;
}

export async function createRuntimePasswordResetToken(
	email: string,
	actor?: Actor | null,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const normalizedEmail = normalizeEmail(email);
			if (!normalizedEmail) {
				return { ok: false as const, error: "Email is required." };
			}

			const user = await db
				.prepare(
					`
            SELECT id, email,
                   CASE WHEN is_admin = 1 THEN 'admin' ELSE 'editor' END AS role,
                   name
            FROM admin_users
            WHERE email = ?
              AND active = 1
            LIMIT 1
          `,
				)
				.bind(normalizedEmail)
				.first<{
					id: number;
					email: string;
					role: "admin" | "editor";
					name: string;
				}>();

			if (!user) {
				return actor
					? { ok: false as const, error: "That admin user could not be found." }
					: { ok: true as const, resetUrl: null as string | null };
			}

			await db
				.prepare(
					`
            UPDATE password_reset_tokens
            SET consumed_at = CURRENT_TIMESTAMP
            WHERE user_id = ?
              AND consumed_at IS NULL
          `,
				)
				.bind(user.id)
				.run();

			const rawToken = crypto.randomUUID();
			const tokenId = `reset-${crypto.randomUUID()}`;
			const expiresAt = new Date(Date.now() + 60 * 60 * 1000).toISOString();

			await db
				.prepare(
					`
            INSERT INTO password_reset_tokens (id, user_id, token_hash, expires_at, requested_by)
            VALUES (?, ?, ?, ?, ?)
          `,
				)
				.bind(tokenId, user.id, await hashOpaqueToken(rawToken), expiresAt, actor?.email ?? null)
				.run();

			if (actor) {
				await recordD1Audit(
					locals,
					actor,
					"auth.password_reset_issue",
					"auth",
					normalizedEmail,
					`Issued a password reset link for ${normalizedEmail}.`,
				);
			}

			return {
				ok: true as const,
				resetUrl: `/ap-admin/reset-password?token=${encodeURIComponent(rawToken)}`,
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.createPasswordResetToken(email, actor ?? null),
	);
}

export async function getRuntimePasswordResetRequest(rawToken: string, locals?: App.Locals | null) {
	return withLocalStoreFallback(
		locals,
		async () => {
			const row = await getD1PasswordResetToken(rawToken, locals);
			if (!row) {
				return null;
			}
			return {
				email: row.email,
				name: row.name,
				role: row.role,
				expiresAt: row.expires_at,
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.getPasswordResetRequest(rawToken),
	);
}

export async function consumeRuntimePasswordResetToken(
	rawToken: string,
	password: string,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const trimmedPassword = password.trim();
			if (trimmedPassword.length < 12) {
				return {
					ok: false as const,
					error: "Password must be at least 12 characters.",
				};
			}

			const row = await getD1PasswordResetToken(rawToken, locals);
			if (!row) {
				return {
					ok: false as const,
					error: "That password reset link is invalid or has expired.",
				};
			}

			await db
				.prepare("UPDATE admin_users SET password_hash = ? WHERE id = ?")
				.bind(await hashPassword(trimmedPassword), row.user_id)
				.run();
			await db
				.prepare("UPDATE password_reset_tokens SET consumed_at = CURRENT_TIMESTAMP WHERE id = ?")
				.bind(row.id)
				.run();
			await db
				.prepare(
					`
            UPDATE admin_sessions
            SET revoked_at = CURRENT_TIMESTAMP
            WHERE user_id = ?
              AND revoked_at IS NULL
          `,
				)
				.bind(row.user_id)
				.run();

			await recordD1Audit(
				locals,
				{ email: row.email, role: row.role, name: row.name },
				"auth.password_reset_complete",
				"auth",
				row.email,
				`${row.email} completed a password reset.`,
			);

			return {
				ok: true as const,
				user: {
					email: row.email,
					role: row.role,
					name: row.name,
				},
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.consumePasswordResetToken(rawToken, password),
	);
}

src/runtime-actions-users.ts.source:
import { normalizeEmail } from "./admin-normalizers";
import { getAdminDb, withLocalStoreFallback } from "./admin-store-dispatch";
import { createKmacDigest } from "./crypto-primitives";
import { hashPassword } from "./crypto-utils";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";
import { getAstropressRootSecret } from "./runtime-env";

// ─── Password reset — extracted to runtime-actions-password-reset.ts ──────────
export {
	consumeRuntimePasswordResetToken,
	createRuntimePasswordResetToken,
	getRuntimePasswordResetRequest,
} from "./runtime-actions-password-reset";

function normalizeRole(role: string): "admin" | "editor" | "" {
	if (role === "admin") return "admin";
	if (role === "editor") return "editor";
	return "";
}

function isValidEmailFormat(email: string): boolean {
	return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

async function hashOpaqueToken(token: string) {
	return createKmacDigest(token, getAstropressRootSecret(), "invite-token");
}

async function getD1InviteToken(rawToken: string, locals?: App.Locals | null) {
	const db = getAdminDb(locals);
	if (!db || !rawToken.trim()) {
		return null;
	}

	const row = await db
		.prepare(
			`
        SELECT i.id, i.user_id, i.expires_at, i.accepted_at,
               u.email, u.name,
               CASE WHEN u.is_admin = 1 THEN 'admin' ELSE 'editor' END AS role,
               u.active
        FROM user_invites i
        JOIN admin_users u ON u.id = i.user_id
        WHERE i.token_hash = ?
        LIMIT 1
      `,
		)
		.bind(await hashOpaqueToken(rawToken))
		.first<{
			id: string;
			user_id: number;
			expires_at: string;
			accepted_at: string | null;
			email: string;
			name: string;
			role: "admin" | "editor";
			active: number;
		}>();

	if (!row || row.accepted_at || row.active !== 1 || Date.parse(row.expires_at) < Date.now()) {
		return null;
	}

	return row;
}

export async function inviteRuntimeAdminUser(
	input: { name: string; email: string; role: string },
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const name = input.name.trim();
			const email = normalizeEmail(input.email);
			const role = normalizeRole(input.role);

			if (!name || !email || !role) {
				return {
					ok: false as const,
					error: "Name, email, and role are required.",
				};
			}

			if (!isValidEmailFormat(email)) {
				return { ok: false as const, error: "Enter a valid email address." };
			}

			const existing = await db
				.prepare("SELECT id FROM admin_users WHERE email = ? LIMIT 1")
				.bind(email)
				.first<{ id: number }>();
			if (existing) {
				return {
					ok: false as const,
					error: "That email address already belongs to an admin user.",
				};
			}

			await db
				.prepare(
					`
            INSERT INTO admin_users (email, password_hash, name, active, is_admin)
            VALUES (?, ?, ?, 1, ?)
          `,
				)
				.bind(email, await hashPassword(crypto.randomUUID()), name, role === "admin" ? 1 : 0)
				.run();

			const user = await db
				.prepare("SELECT id FROM admin_users WHERE email = ? LIMIT 1")
				.bind(email)
				.first<{ id: number }>();
			/* v8 ignore next 3 */
			if (!user) {
				return {
					ok: false as const,
					error: "The invited user could not be created.",
				};
			}

			const rawToken = crypto.randomUUID();
			const inviteId = `invite-${crypto.randomUUID()}`;
			const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

			await db
				.prepare(
					`
            INSERT INTO user_invites (id, user_id, token_hash, expires_at, invited_by)
            VALUES (?, ?, ?, ?, ?)
          `,
				)
				.bind(inviteId, user.id, await hashOpaqueToken(rawToken), expiresAt, actor.email)
				.run();

			await recordD1Audit(
				locals,
				actor,
				"user.invite",
				"auth",
				email,
				`Invited ${email} as an ${role} user.`,
			);
			return {
				ok: true as const,
				inviteUrl: `/ap-admin/accept-invite?token=${encodeURIComponent(rawToken)}`,
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.inviteAdminUser(input, actor),
	);
}

export async function getRuntimeInviteRequest(rawToken: string, locals?: App.Locals | null) {
	return withLocalStoreFallback(
		locals,
		async () => {
			const row = await getD1InviteToken(rawToken, locals);
			if (!row) {
				return null;
			}
			return {
				email: row.email,
				name: row.name,
				role: row.role,
				expiresAt: row.expires_at,
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.getInviteRequest(rawToken),
	);
}

export async function consumeRuntimeInviteToken(
	rawToken: string,
	password: string,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const trimmedPassword = password.trim();
			if (trimmedPassword.length < 12) {
				return {
					ok: false as const,
					error: "Password must be at least 12 characters.",
				};
			}

			const row = await getD1InviteToken(rawToken, locals);
			/* v8 ignore next 3 */
			if (!row) {
				return {
					ok: false as const,
					error: "That invitation link is invalid or has expired.",
				};
			}

			await db
				.prepare("UPDATE admin_users SET password_hash = ? WHERE id = ?")
				.bind(await hashPassword(trimmedPassword), row.user_id)
				.run();
			await db
				.prepare(
					`
            UPDATE user_invites
            SET accepted_at = CURRENT_TIMESTAMP
            WHERE user_id = ?
              AND accepted_at IS NULL
          `,
				)
				.bind(row.user_id)
				.run();

			await recordD1Audit(
				locals,
				{ email: row.email, role: row.role, name: row.name },
				"auth.invite_accept",
				"auth",
				row.email,
				`${row.email} accepted an admin invitation.`,
			);

			return {
				ok: true as const,
				user: {
					email: row.email,
					role: row.role,
					name: row.name,
				},
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.consumeInviteToken(rawToken, password),
	);
}

export async function suspendRuntimeAdminUser(
	email: string,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const normalizedEmail = normalizeEmail(email);
			if (!normalizedEmail) {
				return { ok: false as const, error: "Email is required." };
			}

			if (normalizedEmail === actor.email.toLowerCase()) {
				return {
					ok: false as const,
					error: "You cannot suspend the account you are currently using.",
				};
			}

			const target = await db
				.prepare("SELECT id FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
				.bind(normalizedEmail)
				.first<{ id: number }>();
			if (!target) {
				return {
					ok: false as const,
					error: "That admin user could not be suspended.",
				};
			}

			await db.prepare("UPDATE admin_users SET active = 0 WHERE id = ?").bind(target.id).run();
			await db
				.prepare(
					`
            UPDATE admin_sessions
            SET revoked_at = CURRENT_TIMESTAMP
            WHERE user_id = ?
              AND revoked_at IS NULL
          `,
				)
				.bind(target.id)
				.run();

			await recordD1Audit(
				locals,
				actor,
				"user.suspend",
				"auth",
				normalizedEmail,
				`Suspended ${normalizedEmail}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.suspendAdminUser(email, actor),
	);
}

export async function unsuspendRuntimeAdminUser(
	email: string,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const normalizedEmail = normalizeEmail(email);
			if (!normalizedEmail) {
				return { ok: false as const, error: "Email is required." };
			}

			const target = await db
				.prepare("SELECT id FROM admin_users WHERE email = ? AND active = 0 LIMIT 1")
				.bind(normalizedEmail)
				.first<{ id: number }>();
			if (!target) {
				return {
					ok: false as const,
					error: "That admin user could not be restored.",
				};
			}

			await db.prepare("UPDATE admin_users SET active = 1 WHERE id = ?").bind(target.id).run();
			await recordD1Audit(
				locals,
				actor,
				"user.restore",
				"auth",
				normalizedEmail,
				`Restored ${normalizedEmail}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.unsuspendAdminUser(email, actor),
	);
}

