// ─── Runtime Mutation Store ───────────────────────────────────────────────────
// Extracted from runtime-page-store.ts to keep that file under the 400-line limit.

import { safeLoadLocalAdminStore } from "./admin-store-dispatch";
import { createD1AdminMutationStore } from "./d1-admin-store";
import type { TestimonialStatus, TestimonialSubmissionInput } from "./persistence-types";
import { getCloudflareBindings } from "./runtime-env";

function createStaticMutationStore() {
	return {
		submissions: {
			submitContact: async (input: {
				name: string;
				email: string;
				message: string;
				submittedAt: string;
			}) => ({
				ok: true as const,
				submission: {
					id: crypto.randomUUID(),
					...input,
				},
			}),
			submitTestimonial: async (_input: TestimonialSubmissionInput) => ({
				ok: true as const,
				id: `testimonial-${crypto.randomUUID()}`,
			}),
			moderateTestimonial: async (
				_id: string,
				_status: TestimonialStatus,
				_actorEmail: string,
			) => ({
				ok: true as const,
			}),
		},
		comments: {
			submitPublicComment: async (input: {
				author: string;
				email: string;
				body: string;
				route: string;
				submittedAt: string;
			}) => ({
				ok: true as const,
				comment: {
					id: crypto.randomUUID(),
					status: "pending" as const,
					policy: "open-moderated" as const,
					...input,
				},
			}),
		},
		rateLimits: {
			checkRateLimit: async () => true,
			peekRateLimit: async () => true,
			recordFailedAttempt: async () => {},
		},
	};
}

async function getMutationStore(locals?: App.Locals | null) {
	const db = getCloudflareBindings(locals).DB;

	if (db) {
		return createD1AdminMutationStore(db);
	}

	const localAdminStore = await safeLoadLocalAdminStore();
	if (!localAdminStore) {
		return createStaticMutationStore();
	}

	return {
		submissions: {
			submitContact: async (input: {
				name: string;
				email: string;
				message: string;
				submittedAt: string;
			}) => localAdminStore.submitContact(input),
			submitTestimonial: async (input: TestimonialSubmissionInput) =>
				localAdminStore.submitTestimonial(input),
			moderateTestimonial: async (id: string, status: TestimonialStatus, actorEmail: string) =>
				localAdminStore.moderateTestimonial(id, status, {
					email: actorEmail,
					role: "admin",
					name: actorEmail,
				}),
		},
		comments: {
			submitPublicComment: async (input: {
				author: string;
				email: string;
				body: string;
				route: string;
				submittedAt: string;
			}) => localAdminStore.submitPublicComment(input),
		},
		rateLimits: {
			checkRateLimit: async (key: string, max: number, windowMs: number) =>
				localAdminStore.checkRateLimit(key, max, windowMs),
			peekRateLimit: async (key: string, max: number, windowMs: number) =>
				localAdminStore.peekRateLimit(key, max, windowMs),
			recordFailedAttempt: async (key: string, max: number, windowMs: number) =>
				localAdminStore.recordFailedAttempt(key, max, windowMs),
		},
	};
}

export async function checkRuntimeRateLimit(
	key: string,
	max: number,
	windowMs: number,
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).rateLimits.checkRateLimit(key, max, windowMs);
}

export async function peekRuntimeRateLimit(
	key: string,
	max: number,
	windowMs: number,
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).rateLimits.peekRateLimit(key, max, windowMs);
}

export async function recordRuntimeFailedAttempt(
	key: string,
	max: number,
	windowMs: number,
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).rateLimits.recordFailedAttempt(key, max, windowMs);
}

export async function submitRuntimeContact(
	input: { name: string; email: string; message: string; submittedAt: string },
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).submissions.submitContact(input);
}

export async function submitRuntimePublicComment(
	input: {
		author: string;
		email: string;
		body: string;
		route: string;
		submittedAt: string;
	},
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).comments.submitPublicComment(input);
}

export async function submitRuntimeTestimonial(
	input: TestimonialSubmissionInput,
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).submissions.submitTestimonial(input);
}

export async function moderateRuntimeTestimonial(
	id: string,
	status: TestimonialStatus,
	actor: { email: string; role: string; name: string },
	locals?: App.Locals | null,
) {
	return (await getMutationStore(locals)).submissions.moderateTestimonial(id, status, actor.email);
}

src/runtime-route-registry-archives.ts.source:
import { normalizePath } from "./admin-normalizers";
import { recordD1Audit } from "./d1-audit";
import type { D1DatabaseLike } from "./d1-database";
import { getCloudflareBindings } from "./runtime-env";
import {
	loadSafeLocalCmsRegistry,
	type RuntimeArchiveRouteRecord,
	withSafeRouteRegistryFallback,
} from "./runtime-route-registry-dispatch";

interface Actor {
	email: string;
	role: "admin" | "editor";
	name: string;
}

export async function getRuntimeArchiveRoute(pathname: string, locals?: App.Locals | null) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		return local ? local.getArchiveRoute(normalizedPath) : null;
	}

	return withSafeRouteRegistryFallback(
		(local) => local.getArchiveRoute(normalizedPath),
		null,
		async () => {
			const row = await db
				.prepare(
					`
            SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.updated_at
            FROM cms_route_variants v
            INNER JOIN cms_route_groups g ON g.id = v.group_id
            WHERE g.kind = 'archive' AND v.path = ?
            LIMIT 1
          `,
				)
				.bind(normalizedPath)
				.first<{
					path: string;
					title: string;
					summary: string | null;
					seo_title: string | null;
					meta_description: string | null;
					canonical_url_override: string | null;
					robots_directive: string | null;
					updated_at: string;
				}>();

			if (!row) {
				return null;
			}

			return {
				path: row.path,
				title: row.title,
				summary: row.summary ?? undefined,
				seoTitle: row.seo_title ?? undefined,
				metaDescription: row.meta_description ?? undefined,
				canonicalUrlOverride: row.canonical_url_override ?? undefined,
				robotsDirective: row.robots_directive ?? undefined,
				updatedAt: row.updated_at,
			} satisfies RuntimeArchiveRouteRecord;
		},
	);
}

function validateArchiveRouteInput(input: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}) {
	const title = input.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." } as const;
	}

	const summary = input.summary?.trim() || null;
	const seoTitle = input.seoTitle?.trim() || title;
	const metaDescription = input.metaDescription?.trim() || summary || "";
	const canonicalUrlOverride = input.canonicalUrlOverride?.trim() || null;
	const robotsDirective = input.robotsDirective?.trim() || null;

	return {
		ok: true as const,
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
	};
}

async function persistArchiveRouteChanges(
	db: D1DatabaseLike,
	routeId: string,
	normalizedPath: string,
	validated: {
		title: string;
		summary: string | null;
		seoTitle: string;
		metaDescription: string;
		canonicalUrlOverride: string | null;
		robotsDirective: string | null;
	},
	revisionNote: string | undefined,
	actor: Actor,
	locals: App.Locals | null | undefined,
) {
	await db
		.prepare(
			`
        UPDATE cms_route_variants
        SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?,
            updated_at = CURRENT_TIMESTAMP, updated_by = ?
        WHERE id = ?
      `,
		)
		.bind(
			validated.title,
			validated.summary,
			validated.seoTitle,
			validated.metaDescription,
			validated.canonicalUrlOverride,
			validated.robotsDirective,
			actor.email,
			routeId,
		)
		.run();

	await db
		.prepare(
			`
        INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by)
        VALUES (?, ?, ?, 'en', ?, ?, ?)
      `,
		)
		.bind(
			`revision:${routeId}:${crypto.randomUUID()}`,
			routeId,
			normalizedPath,
			JSON.stringify({
				path: normalizedPath,
				title: validated.title,
				summary: validated.summary,
				seoTitle: validated.seoTitle,
				metaDescription: validated.metaDescription,
				canonicalUrlOverride: validated.canonicalUrlOverride,
				robotsDirective: validated.robotsDirective,
			}),
			revisionNote?.trim() || null,
			actor.email,
		)
		.run();

	await recordD1Audit(
		locals,
		actor,
		"archive.update",
		"content",
		normalizedPath,
		`Updated archive route ${normalizedPath}.`,
	);

	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title: validated.title,
			summary: validated.summary ?? undefined,
			seoTitle: validated.seoTitle,
			metaDescription: validated.metaDescription,
			canonicalUrlOverride: validated.canonicalUrlOverride ?? undefined,
			robotsDirective: validated.robotsDirective ?? undefined,
		} satisfies RuntimeArchiveRouteRecord,
	};
}

export async function saveRuntimeArchiveRoute(
	pathname: string,
	input: {
		title: string;
		summary?: string;
		seoTitle?: string;
		metaDescription?: string;
		canonicalUrlOverride?: string;
		robotsDirective?: string;
		revisionNote?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		if (!local) {
			return {
				ok: false as const,
				error: "The runtime content registry is unavailable.",
			};
		}
		/* v8 ignore next 2 */
		return local.saveArchiveRoute(normalizedPath, input, actor);
	}

	const route = await db
		.prepare(
			`
        SELECT v.id
        FROM cms_route_variants v
        INNER JOIN cms_route_groups g ON g.id = v.group_id
        WHERE g.kind = 'archive' AND v.path = ?
        LIMIT 1
      `,
		)
		.bind(normalizedPath)
		.first<{ id: string }>();

	if (!route) {
		return {
			ok: false as const,
			error: "The selected archive route could not be found.",
		};
	}

	const validated = validateArchiveRouteInput(input);
	if (!validated.ok) {
		return validated;
	}

	return persistArchiveRouteChanges(
		db,
		route.id,
		normalizedPath,
		validated,
		input.revisionNote,
		actor,
		locals,
	);
}

src/runtime-route-registry-system.ts.source:
import { normalizePath } from "./admin-normalizers";
import { recordD1Audit } from "./d1-audit";
import type { D1DatabaseLike } from "./d1-database";
import { getCloudflareBindings } from "./runtime-env";
import {
	loadSafeLocalCmsRegistry,
	localeFromPath,
	parseSettings,
	type RuntimeSystemRouteRecord,
	withSafeRouteRegistryFallback,
} from "./runtime-route-registry-dispatch";

interface Actor {
	email: string;
	role: "admin" | "editor";
	name: string;
}

function mapSystemRow(
	row:
		| {
				path: string;
				title: string;
				summary: string | null;
				body_html: string | null;
				settings_json: string | null;
				updated_at: string;
				render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
		  }
		| null
		| undefined,
): RuntimeSystemRouteRecord | null {
	if (!row) {
		return null;
	}

	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		bodyHtml: row.body_html ?? undefined,
		settings: parseSettings(row.settings_json),
		updatedAt: row.updated_at,
		renderStrategy: row.render_strategy,
	};
}

export async function listRuntimeSystemRoutes(locals?: App.Locals | null) {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		/* v8 ignore next 2 */
		return local ? local.listSystemRoutes() : [];
	}

	return withSafeRouteRegistryFallback(
		(local) => local.listSystemRoutes(),
		[],
		async () => {
			const rows = (
				await db
					.prepare(
						`
              SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy
              FROM cms_route_variants v
              INNER JOIN cms_route_groups g ON g.id = v.group_id
              WHERE g.kind = 'system'
              ORDER BY v.path ASC
            `,
					)
					.all<{
						path: string;
						title: string;
						summary: string | null;
						body_html: string | null;
						settings_json: string | null;
						updated_at: string;
						render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
					}>()
			).results;

			return rows
				.map((row) => mapSystemRow(row))
				.filter((route): route is RuntimeSystemRouteRecord => route !== null);
		},
	);
}

export async function getRuntimeSystemRoute(pathname: string, locals?: App.Locals | null) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		/* v8 ignore next 2 */
		return local ? local.getSystemRoute(normalizedPath) : null;
	}

	return withSafeRouteRegistryFallback(
		(local) => local.getSystemRoute(normalizedPath),
		null,
		async () => {
			const row = await db
				.prepare(
					`
            SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy
            FROM cms_route_variants v
            INNER JOIN cms_route_groups g ON g.id = v.group_id
            WHERE g.kind = 'system' AND v.path = ?
            LIMIT 1
          `,
				)
				.bind(normalizedPath)
				.first<{
					path: string;
					title: string;
					summary: string | null;
					body_html: string | null;
					settings_json: string | null;
					updated_at: string;
					render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
				}>();

			return mapSystemRow(row);
		},
	);
}

function validateSystemRouteInput(input: {
	title: string;
	summary?: string;
	bodyHtml?: string;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	settings?: Record<string, unknown> | null;
}) {
	const title = input.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." } as const;
	}

	const summary = input.summary?.trim() || null;
	const bodyHtml = input.bodyHtml?.trim() || null;
	const settingsJson = input.settings ? JSON.stringify(input.settings) : null;

	return { ok: true as const, title, summary, bodyHtml, settingsJson };
}

function buildSystemRouteSnapshot(
	normalizedPath: string,
	validated: { title: string; summary: string | null; bodyHtml: string | null },
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	settings: Record<string, unknown> | null | undefined,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
) {
	return JSON.stringify({
		path: normalizedPath,
		title: validated.title,
		summary: validated.summary,
		bodyHtml: validated.bodyHtml,
		settings: settings ?? null,
		renderStrategy,
	});
}

function buildSystemRouteResult(
	normalizedPath: string,
	validated: { title: string; summary: string | null; bodyHtml: string | null },
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	settings: Record<string, unknown> | null | undefined,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
) {
	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title: validated.title,
			summary: validated.summary ?? undefined,
			bodyHtml: validated.bodyHtml ?? undefined,
			settings: settings ?? null,
			renderStrategy,
		} satisfies RuntimeSystemRouteRecord,
	};
}

const UPDATE_SYSTEM_VARIANT_SQL = `
  UPDATE cms_route_variants
  SET
    title = ?,
    summary = ?,
    body_html = ?,
    settings_json = ?,
    seo_title = ?,
    meta_description = ?,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = ?
  WHERE id = ?
`;

const INSERT_SYSTEM_REVISION_SQL = `
  INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by)
  VALUES (?, ?, ?, ?, ?, ?, ?)
`;

async function persistSystemRouteChanges(
	db: D1DatabaseLike,
	routeId: string,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
	normalizedPath: string,
	validated: {
		title: string;
		summary: string | null;
		bodyHtml: string | null;
		settingsJson: string | null;
	},
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	settings: Record<string, unknown> | null | undefined,
	revisionNote: string | undefined,
	actor: Actor,
	locals: App.Locals | null | undefined,
) {
	const metaDescription = validated.summary ?? validated.title;
	await db
		.prepare(UPDATE_SYSTEM_VARIANT_SQL)
		.bind(
			validated.title,
			validated.summary,
			validated.bodyHtml,
			validated.settingsJson,
			validated.title,
			metaDescription,
			actor.email,
			routeId,
		)
		.run();

	await db
		.prepare(INSERT_SYSTEM_REVISION_SQL)
		.bind(
			`revision:${routeId}:${crypto.randomUUID()}`,
			routeId,
			normalizedPath,
			localeFromPath(normalizedPath),
			buildSystemRouteSnapshot(normalizedPath, validated, settings, renderStrategy),
			revisionNote?.trim() || null,
			actor.email,
		)
		.run();

	await recordD1Audit(
		locals,
		actor,
		"system.update",
		"content",
		normalizedPath,
		`Updated system route ${normalizedPath}.`,
	);

	return buildSystemRouteResult(normalizedPath, validated, settings, renderStrategy);
}

export async function saveRuntimeSystemRoute(
	pathname: string,
	input: {
		title: string;
		summary?: string;
		bodyHtml?: string;
		// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
		settings?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		if (!local) {
			return {
				ok: false as const,
				error: "The runtime content registry is unavailable.",
			};
		}
		/* v8 ignore next 2 */
		return local.saveSystemRoute(normalizedPath, input, actor);
	}

	const route = await db
		.prepare(
			`
        SELECT v.id, g.render_strategy
        FROM cms_route_variants v
        INNER JOIN cms_route_groups g ON g.id = v.group_id
        WHERE g.kind = 'system' AND v.path = ?
        LIMIT 1
      `,
		)
		.bind(normalizedPath)
		.first<{
			id: string;
			render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
		}>();

	if (!route) {
		return {
			ok: false as const,
			error: "The selected system route could not be found.",
		};
	}

	const validated = validateSystemRouteInput(input);
	if (!validated.ok) {
		return validated;
	}

	return persistSystemRouteChanges(
		db,
		route.id,
		route.render_strategy,
		normalizedPath,
		validated,
		input.settings,
		input.revisionNote,
		actor,
		locals,
	);
}

src/sections/render-prep.ts.source:
/**
 * Pre-render helpers for the section dispatcher.
 *
 * The dispatcher needs:
 *   - a Map<mediaId, publicUrl> for sections that reference media
 *   - a list of testimonial records for testimonials sections
 *
 * Both are gathered server-side so the components themselves stay
 * pure (props-in, HTML-out) and the public route only does one set
 * of DB lookups instead of N per-section ones.
 */

import { getRuntimeMediaResolutionOptions, type MediaRecord, resolveMediaUrl } from "../media";
import type { Section, TestimonialsSection } from "./schema";

export interface MediaLike extends MediaRecord {
	id: string;
}

export interface TestimonialLike {
	id: string;
	name: string;
	role?: string | null;
	company?: string | null;
	quote: string;
	status?: string | null;
	featured?: boolean;
}

export interface SectionRenderContext {
	mediaUrls: Record<string, string>;
	testimonials: TestimonialLike[];
}

export function collectMediaIds(sections: Section[]): string[] {
	const ids = new Set<string>();
	for (const section of sections) {
		if (section.kind === "hero" || section.kind === "image-text") {
			if (section.mediaId) ids.add(section.mediaId);
		} else if (section.kind === "gallery") {
			for (const id of section.mediaIds) {
				if (id) ids.add(id);
			}
		}
	}
	return [...ids];
}

export function buildMediaUrlMap(
	records: MediaLike[],
	locals?: App.Locals | null,
): Record<string, string> {
	const opts = getRuntimeMediaResolutionOptions(locals);
	const out: Record<string, string> = {};
	for (const record of records) {
		const url = resolveMediaUrl(record, opts);
		if (url) out[record.id] = url;
	}
	return out;
}

/**
 * Store-level testimonial submission, as returned by getRuntimeTestimonials.
 * Structural (not the persistence type) so hosts with custom runtimes can
 * feed their own records through the same public mapping.
 */
export interface TestimonialSubmissionLike {
	id: string;
	name: string;
	role?: string;
	company?: string;
	beforeState?: string;
	transformation?: string;
	specificResult?: string;
	consentToPublish: boolean;
	status?: string | null;
}

/**
 * Map a store submission to the shape the section renderers consume, or null
 * when it must not appear publicly. This is the single choke point for the
 * two public-display gates: consentToPublish, and having any quotable text
 * (specificResult, falling back to transformation). The store's "featured"
 * status becomes the renderer's featured flag; featured implies approved.
 */
export function toPublicTestimonial(s: TestimonialSubmissionLike): TestimonialLike | null {
	if (!s.consentToPublish) return null;
	const quote = s.specificResult || s.transformation || "";
	if (!quote) return null;
	const featured = s.status === "featured";
	return {
		id: s.id,
		name: s.name,
		role: s.role ?? null,
		company: s.company ?? null,
		quote,
		featured,
		status: featured ? "approved" : (s.status ?? "approved"),
	};
}

export interface SectionContentReaders {
	listMediaAssets(): Promise<MediaLike[]>;
	listPublicTestimonials(): Promise<TestimonialSubmissionLike[]>;
}

/**
 * Build the render context for a parsed sections array. Only touches the
 * store for what the sections actually reference: media lookups are skipped
 * when no section carries a mediaId, testimonial lookups when no
 * testimonials section exists — so prerendering a plain text page costs no
 * extra reads.
 */
export async function buildSectionRenderContext(
	sections: Section[],
	readers: SectionContentReaders,
	locals?: App.Locals | null,
): Promise<SectionRenderContext> {
	const mediaIds = new Set(collectMediaIds(sections));
	const mediaUrls = mediaIds.size
		? buildMediaUrlMap(
				(await readers.listMediaAssets()).filter((record) => mediaIds.has(record.id)),
				locals,
			)
		: {};
	const testimonials = sections.some((section) => section.kind === "testimonials")
		? (await readers.listPublicTestimonials())
				.map(toPublicTestimonial)
				.filter((t): t is TestimonialLike => t !== null)
		: [];
	return { mediaUrls, testimonials };
}

function isApproved(t: TestimonialLike): boolean {
	return (t.status ?? "approved") === "approved";
}

export function selectTestimonialsForSection(
	section: TestimonialsSection,
	all: TestimonialLike[],
): TestimonialLike[] {
	if (section.source === "ids" && section.ids) {
		const wanted = new Set(section.ids);
		return all.filter((t) => wanted.has(t.id));
	}
	if (section.source === "featured") {
		return all.filter((t) => t.featured === true && isApproved(t));
	}
	return all.filter(isApproved);
}

src/sections/schema.ts.source:
/**
 * Section schema for the structured page editor.
 *
 * Sections are the unit of content for marketing / landing-style pages.
 * Each section has a kind discriminator and a per-kind shape. Sections
 * are persisted as JSON in cms_route_variants.sections_json and rendered
 * by per-kind Astro components on the public site.
 *
 * Types + scalar helpers live in `./schema-helpers`. Per-kind parsers
 * live in `./schema-parsers`. This file is the public API + dispatcher.
 */

import type { Section, SectionParseError, SectionsParseResult } from "./schema-helpers";
import { isNonEmptyString, isObject } from "./schema-helpers";
import {
	parseCtaBanner,
	parseFaq,
	parseFeatureGrid,
	parseGallery,
	parseHero,
	parseImageText,
	parseRichText,
	parseTestimonials,
} from "./schema-parsers";

export type {
	CtaBannerSection,
	CtaButton,
	CtaTone,
	FaqItem,
	FaqSection,
	FeatureGridSection,
	FeatureItem,
	GallerySection,
	GridColumns,
	HeroSection,
	ImageSide,
	ImageTextSection,
	RichTextSection,
	Section,
	SectionAlignment,
	SectionBase,
	SectionKind,
	SectionParseError,
	SectionsParseFailure,
	SectionsParseResult,
	SectionsParseSuccess,
	TestimonialLayout,
	TestimonialSource,
	TestimonialsSection,
} from "./schema-helpers";

export {
	isNonEmptyString,
	isObject,
	isOptionalString,
	isStringArray,
	parseAlignment,
	parseColumns,
	parseCtaButton,
	parseImageSide,
	parseTestimonialLayout,
	parseTestimonialSource,
	parseTone,
	SECTION_KINDS,
} from "./schema-helpers";

function parseSection(raw: unknown, path: string, errors: SectionParseError[]): Section | null {
	if (!isObject(raw)) {
		errors.push({ path, message: "section must be an object" });
		return null;
	}
	if (!isNonEmptyString(raw.id)) {
		errors.push({ path: `${path}.id`, message: "id is required" });
		return null;
	}
	const kind = raw.kind;
	switch (kind) {
		case "hero":
			return parseHero(raw, path, errors);
		case "feature-grid":
			return parseFeatureGrid(raw, path, errors);
		case "testimonials":
			return parseTestimonials(raw, path, errors);
		case "cta-banner":
			return parseCtaBanner(raw, path, errors);
		case "image-text":
			return parseImageText(raw, path, errors);
		case "faq":
			return parseFaq(raw, path, errors);
		case "gallery":
			return parseGallery(raw, path, errors);
		case "rich-text":
			return parseRichText(raw, path, errors);
		default:
			errors.push({
				path: `${path}.kind`,
				message: `unknown section kind: ${String(kind)}`,
			});
			return null;
	}
}

/**
 * Parse a sections payload. Accepts either an array of sections, a `{sections: [...]}` envelope,
 * or null/empty (returns []).
 */
export function parseSections(input: unknown): SectionsParseResult {
	const errors: SectionParseError[] = [];
	if (input == null) return { ok: true, sections: [] };
	let arr: unknown;
	if (Array.isArray(input)) {
		arr = input;
	} else if (isObject(input) && Array.isArray(input.sections)) {
		arr = input.sections;
	} else if (isObject(input) && Object.keys(input).length === 0) {
		return { ok: true, sections: [] };
	} else {
		return {
			ok: false,
			errors: [{ path: "$", message: "sections payload must be an array" }],
		};
	}
	const sections: Section[] = [];
	(arr as unknown[]).forEach((item, idx) => {
		const parsed = parseSection(item, `$[${idx}]`, errors);
		if (parsed) sections.push(parsed);
	});
	if (errors.length > 0) return { ok: false, errors };
	return { ok: true, sections };
}

export function parseSectionsFromJson(json: string): SectionsParseResult {
	if (json.trim().length === 0) return { ok: true, sections: [] };
	let parsed: unknown;
	try {
		parsed = JSON.parse(json);
	} catch (err) {
		return {
			ok: false,
			errors: [
				{
					path: "$",
					message: `invalid JSON: ${(err as Error).message}`,
				},
			],
		};
	}
	return parseSections(parsed);
}

