src/settings-repository-factory.ts.source:
import type { Actor, SettingsRepository } from "./persistence-types";
import { defaultSiteSettings, type SiteSettings } from "./site-settings";

export interface AstropressSettingsRepositoryInput {
	getSettings: SettingsRepository["getSettings"];
	persistSettings(settings: SiteSettings, actor: Actor): void;
	recordSettingsAudit(actor: Actor): void;
}

export function createAstropressSettingsRepository(
	input: AstropressSettingsRepositoryInput,
): SettingsRepository {
	return {
		getSettings: (...args) => input.getSettings(...args),
		saveSettings(partial, actor) {
			const current = input.getSettings() ?? defaultSiteSettings;
			const updated: SiteSettings = {
				siteTitle: partial.siteTitle ?? current.siteTitle,
				siteTagline: partial.siteTagline ?? current.siteTagline,
				donationUrl: partial.donationUrl ?? current.donationUrl,
				newsletterEnabled: partial.newsletterEnabled ?? current.newsletterEnabled,
				commentsDefaultPolicy: partial.commentsDefaultPolicy ?? current.commentsDefaultPolicy,
				adminSlug: partial.adminSlug ?? current.adminSlug,
			};

			input.persistSettings(updated, actor);
			input.recordSettingsAudit(actor);

			return { ok: true as const, settings: updated };
		},
	};
}

src/sqlite-bootstrap-migrations.ts.source:
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import type { AstropressRollbackResult, SqliteDatabaseLike } from "./sqlite-bootstrap-helpers";

/**
 * Run incremental SQL migrations from a directory against a live SQLite database.
 *
 * Migration files must be named with a numeric prefix (e.g. `0001_add_column.sql`).
 * They are applied in lexicographic order. Applied migrations are recorded in
 * `schema_migrations` so they are never re-run.
 */
export function runAstropressMigrations(
	db: SqliteDatabaseLike,
	migrationsDir: string,
): { applied: string[]; skipped: string[] } {
	const applied: string[] = [];
	const skipped: string[] = [];

	db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rollback_sql TEXT
  )`);

	const migrationCols = new Set(
		(
			db.prepare("PRAGMA table_info(schema_migrations)").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);
	if (!migrationCols.has("rollback_sql")) {
		db.exec("ALTER TABLE schema_migrations ADD COLUMN rollback_sql TEXT");
	}

	const alreadyApplied = new Set(
		(
			db.prepare("SELECT name FROM schema_migrations").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);

	if (!existsSync(migrationsDir)) return { applied, skipped };

	for (const file of readdirSync(migrationsDir)
		.filter((f) => f.endsWith(".sql"))
		.sort()) {
		if (alreadyApplied.has(file)) {
			skipped.push(file);
			continue;
		}
		const sql = readFileSync(path.join(migrationsDir, file), "utf8");
		db.exec(sql);

		const downFilePath = path.join(migrationsDir, file.replace(/\.sql$/, ".down.sql"));
		const rollbackSql = existsSync(downFilePath) ? readFileSync(downFilePath, "utf8") : null;
		db.prepare("INSERT INTO schema_migrations (name, rollback_sql) VALUES (?, ?)").run(
			file,
			rollbackSql,
		);
		applied.push(file);
	}

	return { applied, skipped };
}

/**
 * The number of framework-owned migrations Astropress applies during bootstrapping.
 * Used by `checkSchemaVersionAhead` to detect host-app migrations.
 */
export const ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE = 1;

/**
 * Checks whether the database `schema_migrations` table has more entries than the
 * framework's known baseline.
 */
export function checkSchemaVersionAhead(
	db: SqliteDatabaseLike,
	frameworkBaseline = ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE,
): { isAhead: boolean; dbCount: number; frameworkCount: number } | null {
	try {
		const row = db.prepare("SELECT COUNT(*) as count FROM schema_migrations").get() as
			| { count: number }
			| undefined;
		if (!row) return null;
		return {
			isAhead: row.count > frameworkBaseline,
			dbCount: row.count,
			frameworkCount: frameworkBaseline,
		};
	} catch {
		return null;
	}
}

/**
 * Rolls back the most recently applied migration by executing its `rollback_sql` and
 * removing its record from `schema_migrations`. Returns the name of the rolled-back
 * migration, or `null` if there are no applied migrations or the last one has no rollback SQL.
 */
export function rollbackAstropressLastMigration(db: SqliteDatabaseLike): string | null {
	const last = db
		.prepare("SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1")
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!last) return null;
	if (last.rollback_sql) {
		db.exec(last.rollback_sql);
	}
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(last.name);
	return last.name;
}

export function rollbackAstropressLastMigrationWithOptions(
	db: SqliteDatabaseLike,
	options: { dryRun?: boolean } = {},
): AstropressRollbackResult {
	const dryRun = options.dryRun ?? false;
	const row = db
		.prepare("SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1")
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!row) {
		return { migrationName: null, status: "no_migrations", dryRun };
	}
	if (!row.rollback_sql) {
		return { migrationName: row.name, status: "no_rollback_sql", dryRun };
	}
	if (dryRun) {
		return { migrationName: row.name, status: "dry_run", dryRun: true };
	}

	db.exec(row.rollback_sql);
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(row.name);
	return { migrationName: row.name, status: "rolled_back", dryRun: false };
}

src/sqlite-integrity.ts.source:
import {
	loadSqliteDatabase,
	type SqliteDatabaseConstructor,
	type SqliteDatabaseLike,
} from "./sqlite-bootstrap-helpers";

export type IntegrityStatus = "ok" | "corrupt" | "unavailable";

export interface IntegrityCheckResult {
	status: IntegrityStatus;
	mode: "quick" | "full";
	messages: string[];
	error?: string;
}

export interface IntegrityCheckOptions {
	mode?: "quick" | "full";
	/** Override the SQLite driver loader (used by tests). */
	loadDb?: () => Promise<SqliteDatabaseConstructor>;
}

function readPragma(db: SqliteDatabaseLike, mode: "quick" | "full"): string[] {
	const sql = mode === "full" ? "PRAGMA integrity_check" : "PRAGMA quick_check";
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	const rows = db.prepare(sql).all() as Record<string, unknown>[];
	return rows.map((row) => String(Object.values(row)[0]));
}

export function runIntegrityCheckOnOpenDatabase(
	db: SqliteDatabaseLike,
	options: IntegrityCheckOptions = {},
): IntegrityCheckResult {
	const mode = options.mode ?? "quick";
	try {
		const messages = readPragma(db, mode);
		const ok = messages.length === 1 && messages[0].toLowerCase() === "ok";
		return {
			status: ok ? "ok" : "corrupt",
			mode,
			messages,
		};
	} catch (error) {
		return {
			status: "unavailable",
			mode,
			messages: [],
			error: error instanceof Error ? error.message : String(error),
		};
	}
}

async function loadDriver(
	override?: () => Promise<SqliteDatabaseConstructor>,
): Promise<{ ok: true; ctor: SqliteDatabaseConstructor } | { ok: false; error: string }> {
	try {
		const ctor = await (override ?? loadSqliteDatabase)();
		return { ok: true, ctor };
	} catch (error) {
		return {
			ok: false,
			error: `SQLite driver unavailable: ${error instanceof Error ? error.message : String(error)}`,
		};
	}
}

export async function runIntegrityCheck(
	sqlitePath: string,
	options: IntegrityCheckOptions = {},
): Promise<IntegrityCheckResult> {
	const mode = options.mode ?? "quick";
	const driver = await loadDriver(options.loadDb);
	if (!driver.ok) {
		return { status: "unavailable", mode, messages: [], error: driver.error };
	}
	let db: SqliteDatabaseLike | undefined;
	try {
		db = new driver.ctor(sqlitePath);
		return runIntegrityCheckOnOpenDatabase(db, { mode });
	} catch (error) {
		return {
			status: "unavailable",
			mode,
			messages: [],
			error: `Failed to open database at ${sqlitePath}: ${
				error instanceof Error ? error.message : String(error)
			}`,
		};
	} finally {
		db?.close();
	}
}

export interface RepairResult {
	repaired: boolean;
	mode: "dump-replay" | "none";
	messages: string[];
	error?: string;
}

export interface RepairOptions {
	loadDb?: () => Promise<SqliteDatabaseConstructor>;
}

/**
 * Reconstruct a corrupt SQLite database by dumping its readable contents into
 * a new file via `.dump`-style iteration and swapping it in. The original is
 * preserved at `<sqlitePath>.corrupt-<timestamp>` on success.
 */
export async function attemptRepair(
	sqlitePath: string,
	options: RepairOptions = {},
): Promise<RepairResult> {
	const { renameSync, rmSync } = await import("node:fs");
	const messages: string[] = [];

	const driver = await loadDriver(options.loadDb);
	if (!driver.ok) {
		return { repaired: false, mode: "none", messages, error: driver.error };
	}
	const DbClass = driver.ctor;

	const recoveryPath = `${sqlitePath}.recovery-${Date.now()}`;
	const corruptBackupPath = `${sqlitePath}.corrupt-${Date.now()}`;

	let corrupt: SqliteDatabaseLike | undefined;
	let recovery: SqliteDatabaseLike | undefined;
	try {
		corrupt = new DbClass(sqlitePath);
		recovery = new DbClass(recoveryPath);

		const tables = corrupt
			.prepare("SELECT name, sql FROM sqlite_master WHERE type = 'table' AND sql IS NOT NULL")
			.all() as { name: string; sql: string }[];

		for (const { sql } of tables) {
			try {
				recovery.exec(sql);
			} catch (error) {
				messages.push(
					`Skipped schema statement: ${error instanceof Error ? error.message : String(error)}`,
				);
			}
		}

		let rowsCopied = 0;
		for (const { name } of tables) {
			try {
				// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
				const rows = corrupt.prepare(`SELECT * FROM "${name}"`).all() as Record<string, unknown>[];
				const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
				if (columns.length === 0) continue;
				const placeholders = columns.map(() => "?").join(", ");
				const quoted = columns.map((c) => `"${c}"`).join(", ");
				const insert = recovery.prepare(
					`INSERT INTO "${name}" (${quoted}) VALUES (${placeholders})`,
				);
				for (const row of rows) {
					try {
						insert.run(...columns.map((c) => row[c] as unknown));
						rowsCopied++;
					} catch (error) {
						messages.push(
							`Row copy failed in ${name}: ${
								error instanceof Error ? error.message : String(error)
							}`,
						);
					}
				}
			} catch (error) {
				messages.push(
					`Table ${name} could not be read: ${
						error instanceof Error ? error.message : String(error)
					}`,
				);
			}
		}
		messages.push(`Copied ${rowsCopied} row(s) to recovery database`);

		const check = runIntegrityCheckOnOpenDatabase(recovery, { mode: "quick" });
		if (check.status !== "ok") {
			return {
				repaired: false,
				mode: "dump-replay",
				messages: [...messages, ...check.messages],
				error: "Recovery database still fails integrity check",
			};
		}

		corrupt.close();
		corrupt = undefined;
		recovery.close();
		recovery = undefined;

		renameSync(sqlitePath, corruptBackupPath);
		renameSync(recoveryPath, sqlitePath);
		messages.push(`Original preserved at ${corruptBackupPath}`);

		return { repaired: true, mode: "dump-replay", messages };
	} catch (error) {
		try {
			rmSync(recoveryPath, { force: true });
		} catch {
			// Best-effort cleanup.
		}
		return {
			repaired: false,
			mode: "dump-replay",
			messages,
			error: error instanceof Error ? error.message : String(error),
		};
	} finally {
		corrupt?.close();
		recovery?.close();
	}
}

