import { getCmsConfig } from "../config";
import {
	createKmacDigest,
	hashPasswordArgon2id,
	verifyArgon2idPassword,
} from "../crypto-primitives";
import { resolveTokenHashSecret } from "../runtime-prod";

type ContentStatus = "draft" | "review" | "published" | "archived";

interface SqliteStatementLike {
	// node:sqlite / bun:sqlite return `changes` as a plain number for our queries
	// (bigint mode is never enabled), so a required number keeps `.changes > 0`
	// type-safe without a `Number(... ?? 0)` wrapper whose extra arms are
	// unkillable mutation noise.
	// audit-boundary: opaque-passthrough -- mirrors driver bind-arg shape
	run(...params: unknown[]): { changes: number };
	// audit-boundary: opaque-passthrough -- mirrors driver row shape; callers narrow at use
	get(...params: unknown[]): unknown;
	// audit-boundary: opaque-passthrough -- mirrors driver row shape; callers narrow at use
	all(...params: unknown[]): unknown[];
}

export interface AstropressSqliteDatabaseLike {
	exec(sql: string): void;
	prepare(sql: string): SqliteStatementLike;
}

export interface PageRecord {
	slug: string;
	legacyUrl: string;
	title: string;
	templateKey: string;
	listingItems: Array<{
		title: string;
		href: string;
		excerpt: string;
		imageSrc: string;
		imageAlt: string;
	}>;
	paginationLinks: Array<{
		label: string;
		href: string;
		current: boolean;
	}>;
	sourceHtmlPath: string;
	updatedAt: string;
	body?: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	ogTitle?: string;
	ogDescription?: string;
	ogImage?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	kind?: string;
	status?: ContentStatus;
}

export function normalizeStructuredTemplateKey(value: unknown): string | null {
	if (typeof value !== "string" || !value) {
		return null;
	}
	try {
		const { templateKeys } = getCmsConfig();
		// When no template keys are configured, accept the stored key rather than
		// dropping the published page.
		if (templateKeys.length === 0) return value;
		return templateKeys.includes(value) ? value : null;
	} catch {
		// Config not initialized — e.g. `registerCms()` has not run, as during a
		// static build's `getStaticPaths` (middleware doesn't execute there). Accept
		// the stored key so the published page still renders instead of vanishing.
		return value;
	}
}

export function localeFromPath(pathname: string): string {
	let locales: readonly string[];
	try {
		locales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		locales = ["en", "es"];
	}
	for (const locale of locales) {
		if (pathname.startsWith(`/${locale}/`)) return locale;
	}
	// Default to the first locale (usually "en"), or "en" if the list is empty.
	return locales[0] ?? "en";
}

/**
 * Negotiate a locale from an `Accept-Language` request header against the
 * configured `locales` list (or the default `["en", "es"]` fallback).
 *
 * Returns the best-matching locale string, or the first configured locale when
 * no match is found.
 *
 * @example
 * ```ts
 * // Accept-Language: fr-CH, fr;q=0.9, en;q=0.8
 * localeFromAcceptLanguage("fr-CH, fr;q=0.9, en;q=0.8"); // "en" (if locales = ["en","es"])
 * localeFromAcceptLanguage("es;q=0.9, en;q=0.8");          // "es" (if locales = ["en","es"])
 * ```
 */
export function localeFromAcceptLanguage(acceptLanguage: string | null | undefined): string {
	let locales: readonly string[];
	try {
		locales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		locales = ["en", "es"];
	}

	if (!acceptLanguage) return locales[0] ?? "en";

	// Parse "lang-region;q=weight" entries, sorted by weight descending.
	const entries = acceptLanguage
		.split(",")
		.map((part) => {
			// `tag` is trimmed on return and `Number()` ignores whitespace, so no
			// pre-split/pre-parse trim is needed — the split always yields a tag.
			const [tag, qPart] = part.split(";");
			const q = qPart ? Number(qPart.replace("q=", "")) : 1;
			return {
				tag: tag.trim().toLowerCase(),
				q: Number.isFinite(q) ? q : 1,
			};
		})
		.sort((a, b) => b.q - a.q);

	for (const { tag } of entries) {
		// Match exact locale or language prefix (e.g. "fr-CH" matches "fr")
		const matched = locales.find(
			(l) => l.toLowerCase() === tag || tag.startsWith(`${l.toLowerCase()}-`),
		);
		if (matched) return matched;
	}

	return locales[0] ?? "en";
}

export function getSeedPageRecords(): PageRecord[] {
	try {
		return getCmsConfig().seedPages as unknown as PageRecord[];
	} catch {
		return [];
	}
}

/**
 * Hash an opaque token (session / invite / reset / API token) for storage.
 *
 * When `secret` is omitted/undefined (the historical default callers in
 * runtime-actions-users, runtime-actions-password-reset, and the sqlite
 * api-token store), `resolveTokenHashSecret()` supplies the dev fallback in
 * non-production and **throws** in production — keeping the dev ergonomics
 * while failing closed when a real production secret hasn't been wired
 * through. See #132.
 */
export function hashOpaqueToken(token: string, secret?: string | null) {
	return createKmacDigest(token, resolveTokenHashSecret(secret), "sqlite-opaque-token");
}

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function verifyPasswordSync(password: string, storedHash: string) {
	return verifyArgon2idPassword(password, storedHash);
}

export { normalizePath } from "../admin-normalizers";
export {
	normalizeContentStatus,
	normalizeSlug as slugifyTerm,
	parseIdList,
} from "../persistence-commons";

export function serializeIdList(values: number[] | undefined) {
	if (!values) return "[]";
	return JSON.stringify(
		values.filter((entry) => Number.isInteger(entry) && entry > 0).sort((a, b) => a - b),
	);
}

export function parseSystemSettings(value: string | null) {
	try {
		// A null value coerces through JSON.parse to the literal `null` (rejected by
		// the object guard below); "" throws and is caught. So both nullish inputs
		// resolve to null without a dedicated early-return guard.
		const parsed = JSON.parse(value as string) as unknown;
		if (!parsed || typeof parsed !== "object") return null;
		// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
		return parsed as Record<string, unknown>;
	} catch {
		return null;
	}
}

export function normalizeSystemRoutePath(pathname: string) {
	const trimmed = pathname.trim();
	if (!trimmed) {
		return "";
	}
	return trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
}

