import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import {
	ADMIN_USERS_DROP_ROLE_HEAD,
	ADMIN_USERS_DROP_ROLE_TAIL,
	CONTENT_LOCKS_DDL,
	FTS5_INDEX_DDL,
	REBUILD_OVERRIDES_HEAD,
	REBUILD_OVERRIDES_TAIL,
	REBUILD_REVISIONS_FOOTER,
	REBUILD_REVISIONS_MID_AFTER_TAGS,
	REBUILD_REVISIONS_MID_BEFORE_AUTHORS,
} from "./sqlite-schema-compat-data.js";

export function getTableColumns(db: SqliteDatabaseLike, table: string) {
	return (db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>).map(
		(column) => column.name,
	);
}

export function getTableSql(db: SqliteDatabaseLike, table: string) {
	return (
		db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?").get(table) as
			| { sql: string | null }
			| undefined
	)?.sql;
}

export function rebuildContentTablesForCompatibility(
	db: SqliteDatabaseLike,
	options: {
		hasRevisionAuthorIds: boolean;
		hasRevisionCategoryIds: boolean;
		hasRevisionTagIds: boolean;
		hasOverrideScheduledAt: boolean;
		hasRevisionScheduledAt: boolean;
		hasRevisionNote: boolean;
	},
) {
	const authorIdsSelect = options.hasRevisionAuthorIds ? "COALESCE(author_ids, '[]')" : "'[]'";
	const categoryIdsSelect = options.hasRevisionCategoryIds
		? "COALESCE(category_ids, '[]')"
		: "'[]'";
	const tagIdsSelect = options.hasRevisionTagIds ? "COALESCE(tag_ids, '[]')" : "'[]'";
	const overrideScheduledAtSelect = options.hasOverrideScheduledAt ? "scheduled_at" : "NULL";
	const revisionScheduledAtSelect = options.hasRevisionScheduledAt ? "scheduled_at" : "NULL";
	const revisionNoteSelect = options.hasRevisionNote ? "revision_note" : "NULL";

	db.exec(
		REBUILD_OVERRIDES_HEAD +
			overrideScheduledAtSelect +
			REBUILD_OVERRIDES_TAIL +
			revisionScheduledAtSelect +
			REBUILD_REVISIONS_MID_BEFORE_AUTHORS +
			authorIdsSelect +
			",\n      " +
			categoryIdsSelect +
			",\n      " +
			tagIdsSelect +
			REBUILD_REVISIONS_MID_AFTER_TAGS +
			revisionNoteSelect +
			REBUILD_REVISIONS_FOOTER,
	);
}

// Accepts any sqlite handle exposing `prepare`/`exec` (this never closes the
// db), so the request-scoped AstropressSqliteDatabaseLike — which omits close()
// — is a valid argument alongside the bootstrap SqliteDatabaseLike.
export function ensureFts5SearchIndex(db: Pick<SqliteDatabaseLike, "exec" | "prepare">) {
	const existing = db
		.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'content_fts'")
		.get() as { name: string } | undefined;
	if (existing) {
		return;
	}
	db.exec(FTS5_INDEX_DDL);
}

export function ensureLegacySchemaCompatibility(db: SqliteDatabaseLike) {
	const revisionColumns = new Set(getTableColumns(db, "content_revisions"));
	const overrideColumns = new Set(getTableColumns(db, "content_overrides"));
	const needsRevisionColumns =
		!revisionColumns.has("author_ids") ||
		!revisionColumns.has("category_ids") ||
		!revisionColumns.has("tag_ids") ||
		!revisionColumns.has("scheduled_at") ||
		!revisionColumns.has("revision_note");
	const needsOverrideColumns = !overrideColumns.has("scheduled_at");

	if (!overrideColumns.has("metadata")) {
		db.exec("ALTER TABLE content_overrides ADD COLUMN metadata TEXT");
	}

	const mediaColumns = new Set(getTableColumns(db, "media_assets"));
	if (!mediaColumns.has("thumbnail_url")) {
		db.exec("ALTER TABLE media_assets ADD COLUMN thumbnail_url TEXT");
	}
	if (!mediaColumns.has("srcset")) {
		db.exec("ALTER TABLE media_assets ADD COLUMN srcset TEXT");
	}

	const migrationColumns = new Set(getTableColumns(db, "schema_migrations"));
	if (!migrationColumns.has("rollback_sql")) {
		db.exec("ALTER TABLE schema_migrations ADD COLUMN rollback_sql TEXT");
	}

	// #127: explicit active-provider selection. Legacy hosts that applied the
	// connected_integrations table before this column existed get it added with
	// a DEFAULT 0; the runtime treats a sole connected provider as active, so
	// existing single-provider setups keep working without a manual selection.
	const integrationColumns = new Set(getTableColumns(db, "connected_integrations"));
	if (integrationColumns.size > 0 && !integrationColumns.has("is_active")) {
		db.exec("ALTER TABLE connected_integrations ADD COLUMN is_active INTEGER NOT NULL DEFAULT 0");
	}

	// ABAC migration: legacy admin_users may lack is_admin. Add the column
	// with a DEFAULT 0; the terminal rebuild below re-derives the actual
	// value from role (where present) via a CASE in its INSERT...SELECT,
	// so a separate UPDATE backfill here would be redundant.
	const adminUserColumns = new Set(getTableColumns(db, "admin_users"));
	if (adminUserColumns.size > 0 && !adminUserColumns.has("is_admin")) {
		db.exec("ALTER TABLE admin_users ADD COLUMN is_admin INTEGER NOT NULL DEFAULT 0");
	}

	// Terminal access-PR migration: rebuild admin_users without the legacy
	// `role` column. Fires when the column is still present. Idempotent:
	// only runs when role exists.
	const refreshedAdminColumns = new Set(getTableColumns(db, "admin_users"));
	if (refreshedAdminColumns.has("role")) {
		const activeExpr = refreshedAdminColumns.has("active") ? "active" : "1";
		const createdAtExpr = refreshedAdminColumns.has("created_at")
			? "created_at"
			: "CURRENT_TIMESTAMP";
		const nameExpr = refreshedAdminColumns.has("name") ? "name" : "email";
		db.exec(
			ADMIN_USERS_DROP_ROLE_HEAD +
				nameExpr +
				", " +
				activeExpr +
				", " +
				createdAtExpr +
				ADMIN_USERS_DROP_ROLE_TAIL,
		);
	}

	db.exec(CONTENT_LOCKS_DDL);

	const overrideSql = getTableSql(db, "content_overrides") ?? "";
	const revisionSql = getTableSql(db, "content_revisions") ?? "";
	const needsExpandedStatuses =
		!overrideSql.includes("'review'") ||
		!overrideSql.includes("'archived'") ||
		!revisionSql.includes("'review'") ||
		!revisionSql.includes("'archived'");

	if (!needsRevisionColumns && !needsOverrideColumns && !needsExpandedStatuses) {
		return;
	}

	rebuildContentTablesForCompatibility(db, {
		hasRevisionAuthorIds: revisionColumns.has("author_ids"),
		hasRevisionCategoryIds: revisionColumns.has("category_ids"),
		hasRevisionTagIds: revisionColumns.has("tag_ids"),
		hasOverrideScheduledAt: overrideColumns.has("scheduled_at"),
		hasRevisionScheduledAt: revisionColumns.has("scheduled_at"),
		hasRevisionNote: revisionColumns.has("revision_note"),
	});
}

src/sync/git.ts.source:
import { constants, copyFile, mkdir, readdir, rm, stat } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { GitSyncAdapter } from "../platform-contracts";
import { checkpointSqliteWal } from "../sqlite-bootstrap-helpers";
import { runIntegrityCheck } from "../sqlite-integrity";
import { defaultEntries } from "./git-data";

export interface AstropressGitSyncAdapterOptions {
	projectDir: string;
	include?: string[];
	logger?: { info: (msg: string) => void; warn: (msg: string) => void };
}

async function pathExists(pathname: string) {
	try {
		await stat(pathname);
		return true;
	} catch {
		return false;
	}
}

async function copyFileWithReflink(src: string, dest: string): Promise<boolean> {
	try {
		await copyFile(src, dest, constants.COPYFILE_FICLONE);
		return true;
	} catch (err: unknown) {
		const code = (err as NodeJS.ErrnoException).code;
		if (code === "ENOTSUP" || code === "EOPNOTSUPP" || code === "EXDEV") {
			await copyFile(src, dest);
			return false;
		}
		throw err;
	}
}

// Recursive directory copy using COPYFILE_FICLONE (reflink) per file.
// For .sqlite files, checkpoints WAL first so the main file is self-contained.
async function copyTreeWithReflink(
	src: string,
	dest: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; usedReflink: boolean }> {
	const metadata = await stat(src);

	if (!metadata.isDirectory()) {
		if (src.endsWith(".sqlite")) {
			if (options.preCheckIntegrity) {
				const check = await runIntegrityCheck(src, { mode: "quick" });
				if (check.status === "corrupt") {
					throw new Error(
						`Refusing to back up corrupt SQLite database at ${src}: ${check.messages.join("; ")}`,
					);
				}
				if (check.status === "unavailable") {
					warn(`SQLite integrity check unavailable for ${src} before backup: ${check.error}`);
				}
			}
			await checkpointSqliteWal(src, warn);
		}
		const usedReflink = await copyFileWithReflink(src, dest);
		if (options.postCheckIntegrity && dest.endsWith(".sqlite")) {
			const check = await runIntegrityCheck(dest, { mode: "quick" });
			if (check.status !== "ok") {
				warn(
					`Restored SQLite database at ${dest} failed integrity check (${check.status}): ${
						check.messages.join("; ") || check.error || ""
					}`,
				);
			}
		}
		return { fileCount: 1, usedReflink };
	}

	await mkdir(dest, { recursive: true });
	const entries = await readdir(src, { withFileTypes: true });
	let fileCount = 0;
	let usedReflink = false;

	for (const entry of entries) {
		const r = await copyTreeWithReflink(
			join(src, entry.name),
			join(dest, entry.name),
			warn,
			options,
		);
		fileCount += r.fileCount;
		usedReflink = usedReflink || r.usedReflink;
	}

	return { fileCount, usedReflink };
}

async function processIncludes(
	includes: string[],
	srcBase: string,
	destBase: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; anyReflink: boolean }> {
	let fileCount = 0;
	let anyReflink = false;
	for (const entry of includes) {
		const src = resolve(srcBase, entry);
		if (!(await pathExists(src))) continue;
		const dest = resolve(destBase, entry);
		await mkdir(dirname(dest), { recursive: true });
		const r = await copyTreeWithReflink(src, dest, warn, options);
		fileCount += r.fileCount;
		anyReflink = anyReflink || r.usedReflink;
	}
	return { fileCount, anyReflink };
}

export function createAstropressGitSyncAdapter(
	options: AstropressGitSyncAdapterOptions,
): GitSyncAdapter {
	const projectDir = resolve(options.projectDir);
	const include = options.include ?? defaultEntries;
	const log = options.logger?.info ?? (() => {});
	const warn = options.logger?.warn ?? (() => {});

	return {
		async exportSnapshot(targetDir) {
			const outputDir = resolve(targetDir);
			await rm(outputDir, { recursive: true, force: true });
			await mkdir(outputDir, { recursive: true });
			const { fileCount, anyReflink } = await processIncludes(
				include,
				projectDir,
				outputDir,
				warn,
				{ preCheckIntegrity: true },
			);
			log(
				anyReflink
					? `Snapshot exported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot exported using standard copy: ${fileCount} file(s)`,
			);
			return { targetDir: outputDir, fileCount };
		},
		async importSnapshot(sourceDir) {
			const inputDir = resolve(sourceDir);
			// Remove existing entries before restoring, unlike export which starts fresh.
			for (const entry of include) {
				await rm(resolve(projectDir, entry), { recursive: true, force: true });
			}
			const { fileCount, anyReflink } = await processIncludes(include, inputDir, projectDir, warn, {
				postCheckIntegrity: true,
			});
			log(
				anyReflink
					? `Snapshot imported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot imported using standard copy: ${fileCount} file(s)`,
			);
			return { sourceDir: inputDir, fileCount };
		},
	};
}

src/translation-state.ts.source:
export const translationStates = [
	"not_started",
	"partial",
	"fallback_en",
	"translated",
	"reviewed",
	"published",
] as const;

export type TranslationState = (typeof translationStates)[number];

const legacyStateMap: Record<string, TranslationState> = {
	original: "not_started",
	"in-progress": "partial",
	"pending-review": "translated",
	approved: "reviewed",
	"needs-revision": "partial",
	archived: "fallback_en",
	complete: "published",
};

export function normalizeTranslationState(
	value: string | null | undefined,
	fallback: TranslationState = "not_started",
): TranslationState {
	if (!value) {
		return fallback;
	}

	const normalized = value.trim().toLowerCase();
	if ((translationStates as readonly string[]).includes(normalized)) {
		return normalized as TranslationState;
	}

	return legacyStateMap[normalized] ?? fallback;
}

export function isPublishedTranslationState(value: string | null | undefined) {
	return normalizeTranslationState(value) === "published";
}

