import { SQL_INSERT_BASELINE_OVERRIDE, SQL_INSERT_BASELINE_REVISION } from "./content-sql-data";
import type { AstropressSqliteDatabaseLike, PageRecord } from "./utils";

export {
	SQL_INSERT_BASELINE_OVERRIDE,
	SQL_INSERT_BASELINE_REVISION,
	SQL_INSERT_ENTRY,
	SQL_INSERT_REVISION_CONTENT,
	SQL_LIST_REVISIONS_FOR_SLUG,
	SQL_UPSERT_OVERRIDE,
} from "./content-sql-data";

export type RevisionInput = {
	title: string;
	status: string;
	scheduledAt?: string | null;
	body?: string | null;
	seoTitle: string;
	metaDescription: string;
	excerpt?: string | null;
	ogTitle?: string | null;
	ogDescription?: string | null;
	ogImage?: string | null;
	authorIds?: number[];
	categoryIds?: number[];
	tagIds?: number[];
	canonicalUrlOverride?: string | null;
	robotsDirective?: string | null;
	revisionNote?: string | null;
};

export function buildBaselineOverrideParams(pageRecord: PageRecord) {
	return [
		pageRecord.slug,
		pageRecord.title,
		pageRecord.status ?? "published",
		pageRecord.body ?? null,
		pageRecord.seoTitle ?? pageRecord.title,
		pageRecord.metaDescription ?? pageRecord.summary ?? "",
		pageRecord.summary ?? null,
		null,
		null,
		null,
		null,
		null,
		null,
		"seed-import",
	];
}

export function buildBaselineRevisionParams(randomId: () => string, pageRecord: PageRecord) {
	return [
		`revision-${randomId()}`,
		pageRecord.slug,
		pageRecord.title,
		pageRecord.status ?? "published",
		null,
		pageRecord.body ?? null,
		pageRecord.seoTitle ?? pageRecord.title,
		pageRecord.metaDescription ?? pageRecord.summary ?? "",
		pageRecord.summary ?? null,
		null,
		null,
		null,
		null,
		null,
		null,
		"imported-baseline",
		"seed-import",
	];
}

export function ensureBaselineRevisionImpl(
	getDb: () => AstropressSqliteDatabaseLike,
	randomId: () => string,
	pageRecord: PageRecord,
) {
	const db = getDb();
	db.prepare(SQL_INSERT_BASELINE_OVERRIDE).run(...buildBaselineOverrideParams(pageRecord));
	const existing = db
		.prepare("SELECT id FROM content_revisions WHERE slug = ? AND source = 'imported' LIMIT 1")
		.get(pageRecord.slug) as { id: string } | undefined;
	if (existing) return;
	db.prepare(SQL_INSERT_BASELINE_REVISION).run(
		...buildBaselineRevisionParams(randomId, pageRecord),
	);
}

src/sqlite-runtime/flash.ts.source:
import { randomBytes } from "node:crypto";
import type { FlashStore } from "../platform-contracts-helpers";
import type { AstropressSqliteDatabaseLike } from "./utils";

/** Default lifetime of a flash entry — long enough for the redirect, short
 * enough that an abandoned hand-off can't be replayed later. */
export const FLASH_DEFAULT_TTL_MS = 5 * 60 * 1000;

interface FlashRow {
	payload: string;
	expires_at_ms: number;
}

/** Opaque, non-guessable flash id. 18 random bytes → 36 hex chars. */
export function newFlashId(): string {
	return `flash_${randomBytes(18).toString("hex")}`;
}

/**
 * sqlite sibling of {@link FlashStore}. Single-read-then-delete: `consume`
 * always deletes the row it read, so a payload can never be retrieved twice
 * even if the same id is replayed. Expired rows are treated as absent and are
 * swept opportunistically on each `put`.
 */
export function createFlashStore(db: AstropressSqliteDatabaseLike): FlashStore {
	return {
		async put(payload, ttlMs = FLASH_DEFAULT_TTL_MS) {
			const now = Date.now();
			db.prepare("DELETE FROM admin_flash WHERE expires_at_ms <= ?").run(now);
			const id = newFlashId();
			db.prepare(
				"INSERT INTO admin_flash (id, payload, created_at_ms, expires_at_ms) VALUES (?, ?, ?, ?)",
			).run(id, payload, now, now + ttlMs);
			return { id };
		},

		async consume(id) {
			const row = db
				.prepare("SELECT payload, expires_at_ms FROM admin_flash WHERE id = ?")
				.get(id) as FlashRow | undefined;
			// Delete unconditionally: a read is a consume even when expired, so a
			// replay of the same id can never succeed.
			db.prepare("DELETE FROM admin_flash WHERE id = ?").run(id);
			if (!row || row.expires_at_ms <= Date.now()) {
				return null;
			}
			return row.payload;
		},
	};
}

src/sqlite-runtime/locks.ts.source:
import type { AstropressSqliteDatabaseLike } from "./utils";

export interface ContentLockResult {
	ok: true;
	lockToken: string;
	expiresAt: string;
}

export interface ContentLockConflict {
	ok: false;
	conflict: true;
	lockedByEmail: string;
	lockedByName: string;
	expiresAt: string;
}

const LOCK_TTL_MINUTES = 5;

function lockExpiresAt(): string {
	const d = new Date();
	d.setMinutes(d.getMinutes() + LOCK_TTL_MINUTES);
	return d.toISOString();
}

export function createSqliteLocksOps(getDb: () => AstropressSqliteDatabaseLike) {
	return {
		acquireLock(
			slug: string,
			email: string,
			name: string,
		): ContentLockResult | ContentLockConflict {
			const db = getDb();
			db.exec("BEGIN IMMEDIATE");
			try {
				db.prepare("DELETE FROM content_locks WHERE expires_at <= ?").run(new Date().toISOString());

				const existing = db
					.prepare(
						"SELECT locked_by_email, locked_by_name, expires_at FROM content_locks WHERE slug = ? LIMIT 1",
					)
					.get(slug) as
					| {
							locked_by_email: string;
							locked_by_name: string;
							expires_at: string;
					  }
					| undefined;

				if (existing && existing.locked_by_email !== email) {
					db.exec("ROLLBACK");
					return {
						ok: false,
						conflict: true,
						lockedByEmail: existing.locked_by_email,
						lockedByName: existing.locked_by_name,
						expiresAt: existing.expires_at,
					};
				}

				const lockToken = crypto.randomUUID();
				const expiresAt = lockExpiresAt();
				db.prepare(
					`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
             VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(slug) DO UPDATE SET
               locked_by_email = excluded.locked_by_email,
               locked_by_name = excluded.locked_by_name,
               lock_token = excluded.lock_token,
               expires_at = excluded.expires_at`,
				).run(slug, email, name, lockToken, expiresAt);
				db.exec("COMMIT");
				return { ok: true, lockToken, expiresAt };
			} catch (e) {
				db.exec("ROLLBACK");
				throw e;
			}
		},

		refreshLock(slug: string, lockToken: string): boolean {
			const expiresAt = lockExpiresAt();
			const result = getDb()
				.prepare("UPDATE content_locks SET expires_at = ? WHERE slug = ? AND lock_token = ?")
				.run(expiresAt, slug, lockToken);
			return (result.changes as number) > 0;
		},

		releaseLock(slug: string, lockToken: string): boolean {
			const result = getDb()
				.prepare("DELETE FROM content_locks WHERE slug = ? AND lock_token = ?")
				.run(slug, lockToken);
			return (result.changes as number) > 0;
		},
	};
}

src/sqlite-runtime/search.ts.source:
import type { ContentRecord } from "../persistence-types";
import type { AstropressSqliteDatabaseLike } from "./utils";

/**
 * Search content_overrides using the FTS5 virtual table.
 * Requires ensureFts5SearchIndex to have been called at boot.
 */
export function searchContentOverrides(
	db: AstropressSqliteDatabaseLike,
	query: string,
): ContentRecord[] {
	return db
		.prepare(
			`SELECT co.* FROM content_overrides co
       WHERE co.rowid IN (SELECT rowid FROM content_fts(?) ORDER BY rank)`,
		)
		.all(query) as ContentRecord[];
}

src/sqlite-runtime/webhooks-d1.ts.source:
/**
 * D1 sibling of `webhooks.ts`. Implements the same {@link WebhookStore}
 * contract over D1's promise-returning SDK. The SQL bodies and column lists
 * match the sqlite store byte-for-byte; the ML-DSA signing surface
 * (`createMlDsaKeyPair` / `signMlDsaMessage`) is shared and host-agnostic.
 *
 * The dispatch seam (`admin-store-dispatch.ts` `resolveApiRuntime`) selects
 * this backend whenever a D1 binding is present, so the REST webhook surface
 * and the admin webhook UI no longer require the local runtime alias on a
 * D1-backed host. See issue #137.
 */

import { randomBytes } from "node:crypto";
import { createMlDsaKeyPair, secretKeyToBase64, signMlDsaMessage } from "../crypto-primitives";
import type { D1DatabaseLike } from "../d1-database";
import type { WebhookEvent, WebhookRecord, WebhookStore } from "../platform-contracts";
import { createLogger } from "../runtime-logger";

const logger = createLogger("Webhook");

interface WebhookRow {
	id: string;
	url: string;
	events: string;
	secret_hash: string; // stores the ML-DSA secret key (field naming is historical)
	active: number;
	created_at: string;
	last_fired_at: string | null;
}

const SELECT_COLUMNS = "id, url, events, secret_hash, active, created_at, last_fired_at";

function rowToRecord(row: WebhookRow): WebhookRecord {
	return {
		id: row.id,
		url: row.url,
		events: JSON.parse(row.events) as WebhookEvent[],
		active: row.active === 1,
		createdAt: row.created_at,
		lastFiredAt: row.last_fired_at ?? null,
	};
}

export function createD1WebhookStore(
	db: D1DatabaseLike,
	fetchImpl: typeof fetch = fetch,
): WebhookStore {
	return {
		async list() {
			const { results } = await db
				.prepare(
					`SELECT ${SELECT_COLUMNS} FROM webhooks WHERE deleted_at IS NULL ORDER BY created_at DESC`,
				)
				.all<WebhookRow>();
			return results.map(rowToRecord);
		},

		async create({ url, events }) {
			const id = `wh_${randomBytes(12).toString("hex")}`;
			const keyPair = createMlDsaKeyPair(id, randomBytes(32));
			const now = new Date().toISOString();

			await db
				.prepare(
					"INSERT INTO webhooks (id, url, events, secret_hash, active, created_at) VALUES (?, ?, ?, ?, 1, ?)",
				)
				.bind(id, url, JSON.stringify(events), secretKeyToBase64(keyPair.secretKey), now)
				.run();

			const record: WebhookRecord = {
				id,
				url,
				events,
				active: true,
				createdAt: now,
				lastFiredAt: null,
			};

			return { record, verification: keyPair.verification };
		},

		async delete(id) {
			const now = new Date().toISOString();
			await db
				.prepare("UPDATE webhooks SET deleted_at = ?, active = 0 WHERE id = ?")
				.bind(now, id)
				.run();
		},

		async dispatch(event, payload) {
			const { results } = await db
				.prepare(`SELECT ${SELECT_COLUMNS} FROM webhooks WHERE deleted_at IS NULL AND active = 1`)
				.all<WebhookRow>();

			const subscribers = results.filter((row) => {
				const events = JSON.parse(row.events) as WebhookEvent[];
				return events.includes(event);
			});

			if (subscribers.length === 0) return;

			const bodyText = JSON.stringify({
				event,
				payload,
				timestamp: new Date().toISOString(),
			});
			const now = new Date().toISOString();

			await Promise.allSettled(
				subscribers.map(async (row) => {
					const signature = signMlDsaMessage(bodyText, row.secret_hash);
					try {
						await fetchImpl(
							new Request(row.url, {
								method: "POST",
								headers: {
									"Content-Type": "application/json",
									"X-Astropress-Event": event,
									"X-Astropress-Signature": signature,
									"X-Astropress-Signature-Alg": "ML-DSA-65",
									"X-Astropress-Key-Id": row.id,
								},
								body: bodyText,
							}),
						);
					} catch (err) {
						logger.error(`Failed to dispatch ${event} to ${row.url}`, {
							error: err,
						});
						return;
					}

					await db
						.prepare("UPDATE webhooks SET last_fired_at = ? WHERE id = ?")
						.bind(now, row.id)
						.run();
				}),
			);
		},
	};
}

src/sqlite-seed-helpers.ts.source:
import { hashPasswordArgon2id } from "./crypto-primitives";
import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import { getTableColumns } from "./sqlite-schema-compat.js";

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function guessMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	return "image/jpeg";
}

export function toSqlLiteral(value: unknown): string {
	if (value === null || value === undefined) return "NULL";
	if (typeof value === "number" || typeof value === "bigint") return String(value);
	if (typeof value === "boolean") return value ? "1" : "0";
	if (value instanceof Uint8Array) return `X'${Buffer.from(value).toString("hex")}'`;
	return `'${String(value).replaceAll("'", "''")}'`;
}

export function buildTableImportStatements(db: SqliteDatabaseLike, table: string) {
	const columns = getTableColumns(db, table);
	if (columns.length === 0) return [] as string[];

	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	const rows = db.prepare(`SELECT * FROM ${table}`).all() as Record<string, unknown>[];
	const statements = [`DELETE FROM ${table};`];
	for (const row of rows) {
		const serializedValues = columns.map((column) => toSqlLiteral(row[column]));
		statements.push(
			`INSERT INTO ${table} (${columns.join(", ")}) VALUES (${serializedValues.join(", ")});`,
		);
	}
	return statements;
}

export function buildTableImportSql(db: SqliteDatabaseLike, table: string) {
	return buildTableImportStatements(db, table).join("\n");
}

