import type { Actor, TaxonomyKind, TaxonomyRepository } from "./persistence-types";

type TaxonomyTable = "categories" | "tags";

export interface AstropressTaxonomyRepositoryInput {
	listCategories: TaxonomyRepository["listCategories"];
	listTags: TaxonomyRepository["listTags"];
	slugifyTerm(value: string): string;
	createTaxonomyTerm(input: {
		table: TaxonomyTable;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	updateTaxonomyTerm(input: {
		table: TaxonomyTable;
		id: number;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	deleteTaxonomyTerm(input: { table: TaxonomyTable; id: number }): boolean;
	recordTaxonomyAudit(input: {
		actor: Actor;
		action: `${TaxonomyKind}.create` | `${TaxonomyKind}.update` | `${TaxonomyKind}.delete`;
		summary: string;
		targetId: string;
	}): void;
}

function createTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!name || !slug) {
		return { ok: false as const, error: `${kind} name and slug are required.` };
	}

	const created = input.createTaxonomyTerm({
		table,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!created) {
		return {
			ok: false as const,
			error: `That ${kind} name or slug is already in use.`,
		};
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.create`,
		summary: `Created ${kind} ${name}.`,
		targetId: slug,
	});
	return { ok: true as const };
}

function updateTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { id: number; name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!rawInput.id || !name || !slug) {
		return {
			ok: false as const,
			error: `${kind} id, name, and slug are required.`,
		};
	}

	const updated = input.updateTaxonomyTerm({
		table,
		id: rawInput.id,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!updated) {
		return { ok: false as const, error: `That ${kind} could not be updated.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.update`,
		summary: `Updated ${kind} ${name}.`,
		targetId: String(rawInput.id),
	});
	return { ok: true as const };
}

function deleteTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	id: number,
	actor: Actor,
) {
	const deleted = input.deleteTaxonomyTerm({ table, id });
	if (!deleted) {
		return { ok: false as const, error: `That ${kind} could not be deleted.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.delete`,
		summary: `Deleted ${kind} ${id}.`,
		targetId: String(id),
	});
	return { ok: true as const };
}

export function createAstropressTaxonomyRepository(
	input: AstropressTaxonomyRepositoryInput,
): TaxonomyRepository {
	return {
		listCategories: (...args) => input.listCategories(...args),
		listTags: (...args) => input.listTags(...args),
		createCategory: (rawInput, actor) =>
			createTerm(input, "categories", "category", rawInput, actor),
		updateCategory: (rawInput, actor) =>
			updateTerm(input, "categories", "category", rawInput, actor),
		deleteCategory: (id, actor) => deleteTerm(input, "categories", "category", id, actor),
		createTag: (rawInput, actor) => createTerm(input, "tags", "tag", rawInput, actor),
		updateTag: (rawInput, actor) => updateTerm(input, "tags", "tag", rawInput, actor),
		deleteTag: (id, actor) => deleteTerm(input, "tags", "tag", id, actor),
	};
}

src/turnstile.ts.source:
import { getLoginSecurityConfig, isProductionRuntime } from "./runtime-env";

interface TurnstileVerificationResult {
	ok: boolean;
	error?: string;
}

interface TurnstileResponsePayload {
	success?: boolean;
	"error-codes"?: string[];
}

export function isTurnstileEnabled(locals?: App.Locals | null) {
	return Boolean(getLoginSecurityConfig(locals).turnstileSecretKey);
}

export async function verifyTurnstileToken(input: {
	token: string | null | undefined;
	ipAddress?: string | null;
	locals?: App.Locals | null;
	requireConfigured?: boolean;
}): Promise<TurnstileVerificationResult> {
	const { turnstileSecretKey } = getLoginSecurityConfig(input.locals);
	if (!turnstileSecretKey) {
		if (input.requireConfigured && isProductionRuntime()) {
			return { ok: false, error: "Security challenge is not configured." };
		}

		return { ok: true };
	}

	const token = input.token?.trim();
	if (!token) {
		return { ok: false, error: "Security challenge is required." };
	}

	const payload = new URLSearchParams({
		secret: turnstileSecretKey,
		response: token,
	});

	if (input.ipAddress) {
		payload.set("remoteip", input.ipAddress);
	}

	try {
		const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
			method: "POST",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded",
			},
			body: payload,
		});

		if (!response.ok) {
			return { ok: false, error: "Security challenge could not be verified." };
		}

		const result = (await response.json()) as TurnstileResponsePayload;
		if (!result.success) {
			return {
				ok: false,
				error: result["error-codes"]?.join(", ") || "Security challenge failed.",
			};
		}

		return { ok: true };
	} catch {
		return { ok: false, error: "Security challenge could not be verified." };
	}
}

src/vitest-runtime-alias.ts.source:
export type AstropressVitestPlugin = {
	name: string;
	enforce?: "pre" | "post";
	resolveId: (id: string, importer?: string) => string | undefined;
};

export function isLocalRuntimeModuleId(id: string): boolean {
	return /local-runtime-modules(?:\.[jt]s)?$/.test(id);
}

export function isAstropressSrcImporter(importer: string): boolean {
	const norm = importer.replace(/\\/g, "/");
	if (norm.includes("/astropress/packages/astropress/src/")) return true;
	if (norm.includes("/node_modules/astropress/src/")) return true;
	if (norm.includes("/node_modules/.bun/")) {
		return norm.includes("/astropress/src/");
	}
	return false;
}

export function createAstropressVitestLocalRuntimePlugins(
	localRuntimeModulesPath: string,
): AstropressVitestPlugin[] {
	return [
		{
			name: "astropress-local-runtime-modules-replacer",
			enforce: "pre",
			resolveId(id) {
				if (isLocalRuntimeModuleId(id)) {
					return localRuntimeModulesPath;
				}
			},
		},
		{
			name: "astropress-external-source-rewriter",
			enforce: "pre",
			resolveId(id, importer) {
				if (importer && isAstropressSrcImporter(importer) && isLocalRuntimeModuleId(id)) {
					return localRuntimeModulesPath;
				}
			},
		},
	];
}

src/redirect-repository-factory.ts.source:
import type { Actor, RedirectRepository, RedirectRule } from "./persistence-types";

export interface AstropressRedirectRepositoryInput {
	getRedirectRules: RedirectRepository["getRedirectRules"];
	normalizePath(path: string): string;
	getExistingRedirect(sourcePath: string): { deletedAt: string | null } | null | undefined;
	upsertRedirect(input: {
		sourcePath: string;
		targetPath: string;
		statusCode: 301 | 302;
		actor: Actor;
	}): void;
	markRedirectDeleted(sourcePath: string): boolean;
	recordRedirectAudit(input: {
		actor: Actor;
		action: "redirect.create" | "redirect.delete";
		summary: string;
		targetId: string;
	}): void;
}

export function createAstropressRedirectRepository(
	input: AstropressRedirectRepositoryInput,
): RedirectRepository {
	return {
		getRedirectRules: (...args) => input.getRedirectRules(...args),
		createRedirectRule(rawInput, actor) {
			const sourcePath = input.normalizePath(rawInput.sourcePath);
			const targetPath = input.normalizePath(rawInput.targetPath);
			const statusCode: 301 | 302 = rawInput.statusCode === 302 ? 302 : 301;

			if (!sourcePath || !targetPath) {
				return {
					ok: false as const,
					error: "Both legacy and target paths are required.",
				};
			}

			if (sourcePath === targetPath) {
				return {
					ok: false as const,
					error: "Legacy and target paths must be different.",
				};
			}

			const existing = input.getExistingRedirect(sourcePath);
			if (existing && existing.deletedAt === null) {
				return {
					ok: false as const,
					error: "That legacy path already has a reviewed redirect rule.",
				};
			}

			input.upsertRedirect({
				sourcePath,
				targetPath,
				statusCode,
				actor,
			});

			input.recordRedirectAudit({
				actor,
				action: "redirect.create",
				summary: `Created redirect ${sourcePath} -> ${targetPath} (${statusCode}).`,
				targetId: sourcePath,
			});

			return {
				ok: true as const,
				rule: { sourcePath, targetPath, statusCode } satisfies RedirectRule,
			};
		},
		deleteRedirectRule(sourcePath, actor) {
			const normalizedSourcePath = input.normalizePath(sourcePath);
			const deleted = input.markRedirectDeleted(normalizedSourcePath);
			if (!deleted) {
				return { ok: false as const };
			}

			input.recordRedirectAudit({
				actor,
				action: "redirect.delete",
				summary: `Deleted redirect ${normalizedSourcePath}.`,
				targetId: normalizedSourcePath,
			});

			return { ok: true as const };
		},
	};
}

src/runtime-actions-content-helpers.ts.source:
import type { Actor } from "./persistence-types";

type D1Like = import("./d1-database").D1DatabaseLike;

export type ContentStatus = "draft" | "review" | "published" | "archived";

export const SQL_DETECT_CONFLICT = "SELECT updated_at FROM content_overrides WHERE slug = ?";

export const INSERT_REVISION_SQL = `INSERT INTO content_revisions (id, slug, title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, author_ids, category_ids, tag_ids, canonical_url_override, robots_directive, revision_note, source, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'reviewed', ?)`;
export const UPSERT_CONTENT_OVERRIDE_SQL =
	"INSERT INTO content_overrides (slug, title, status, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, scheduled_at, canonical_url_override, robots_directive, metadata, updated_at, updated_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?) ON CONFLICT(slug) DO UPDATE SET title = excluded.title, status = excluded.status, body = excluded.body, seo_title = excluded.seo_title, meta_description = excluded.meta_description, excerpt = excluded.excerpt, og_title = excluded.og_title, og_description = excluded.og_description, og_image = excluded.og_image, scheduled_at = excluded.scheduled_at, canonical_url_override = excluded.canonical_url_override, robots_directive = excluded.robots_directive, metadata = excluded.metadata, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by";
export const UPSERT_CONTENT_OVERRIDE_NO_META_SQL =
	"INSERT INTO content_overrides (slug, title, status, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, scheduled_at, canonical_url_override, robots_directive, updated_at, updated_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?) ON CONFLICT(slug) DO UPDATE SET title = excluded.title, status = excluded.status, body = excluded.body, seo_title = excluded.seo_title, meta_description = excluded.meta_description, excerpt = excluded.excerpt, og_title = excluded.og_title, og_description = excluded.og_description, og_image = excluded.og_image, scheduled_at = excluded.scheduled_at, canonical_url_override = excluded.canonical_url_override, robots_directive = excluded.robots_directive, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by";
export const SQL_INSERT_CONTENT_ENTRY = `INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at, body, summary, seo_title, meta_description, og_title, og_description, og_image) VALUES (?, ?, ?, 'post', 'content', ?, CURRENT_TIMESTAMP, ?, ?, ?, ?, ?, ?, ?)`;
export const SQL_INSERT_CREATE_OVERRIDE =
	"INSERT INTO content_overrides (slug, title, status, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, canonical_url_override, robots_directive, updated_at, updated_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?)";
export const SQL_SELECT_REVISION =
	"SELECT title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, author_ids, category_ids, tag_ids, canonical_url_override, robots_directive, revision_note FROM content_revisions WHERE slug = ? AND id = ? LIMIT 1";

export function trimOrNull(value: string | undefined | null): string | null {
	return value?.trim() || null;
}

export function cleanIdList(ids: number[] | undefined): number[] {
	return [...new Set((ids ?? []).filter((entry) => Number.isInteger(entry) && entry > 0))];
}

export function normalizeSeoFields(input: {
	excerpt?: string;
	ogTitle?: string;
	ogDescription?: string;
	ogImage?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}) {
	return {
		excerpt: trimOrNull(input.excerpt),
		ogTitle: trimOrNull(input.ogTitle),
		ogDescription: trimOrNull(input.ogDescription),
		ogImage: trimOrNull(input.ogImage),
		canonicalUrlOverride: trimOrNull(input.canonicalUrlOverride),
		robotsDirective: trimOrNull(input.robotsDirective),
	};
}

export function normalizeScheduledAt(value: string | undefined): string | null {
	const trimmed = value?.trim();
	return trimmed ? new Date(value as string).toISOString() : null;
}

export function normalizeLegacyUrl(legacyUrl: string | undefined, slug: string): string {
	const raw = legacyUrl?.trim() || `/${slug}`;
	return raw.startsWith("/") ? raw : `/${raw}`;
}

export function serializeMetadata(
	// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
	metadata: Record<string, unknown>,
): string | null {
	return Object.keys(metadata).length > 0 ? JSON.stringify(metadata) : null;
}

// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
export function nullsToUndefined<T extends Record<string, unknown>>(
	obj: T,
): { [K in keyof T]: Exclude<T[K], null> | undefined } {
	// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
	const result = {} as Record<string, unknown>;
	for (const [key, value] of Object.entries(obj)) {
		result[key] = value ?? undefined;
	}
	return result as { [K in keyof T]: Exclude<T[K], null> | undefined };
}

export async function detectConflict(db: D1Like, slug: string, lastKnownUpdatedAt: string) {
	const row = await db.prepare(SQL_DETECT_CONFLICT).bind(slug).first<{ updated_at: string }>();
	if (row && row.updated_at !== lastKnownUpdatedAt) {
		return {
			ok: false as const,
			error:
				"This record was modified by another editor after you opened it. Reload to see the latest version.",
			conflict: true as const,
		};
	}
	return null;
}

export async function insertContentRevision(
	db: D1Like,
	slug: string,
	r: {
		title: string;
		status: string;
		scheduledAt?: string | null;
		body: string;
		seoTitle: string;
		metaDescription: string;
		seo: ReturnType<typeof normalizeSeoFields>;
		authorIds: string;
		categoryIds: string;
		tagIds: string;
		revisionNote: string | null;
		actor: Actor;
	},
) {
	await db
		.prepare(INSERT_REVISION_SQL)
		.bind(
			`revision-${crypto.randomUUID()}`,
			slug,
			r.title,
			r.status,
			r.scheduledAt ?? null,
			r.body,
			r.seoTitle,
			r.metaDescription,
			r.seo.excerpt,
			r.seo.ogTitle,
			r.seo.ogDescription,
			r.seo.ogImage,
			r.authorIds,
			r.categoryIds,
			r.tagIds,
			r.seo.canonicalUrlOverride,
			r.seo.robotsDirective,
			r.revisionNote,
			r.actor.email,
		)
		.run();
}

src/runtime-actions-content.ts.source:
import { serializeIdList, slugifyContent } from "./admin-normalizers";
import { withLocalStoreFallback } from "./admin-store-dispatch";
import { purgeCdnCache } from "./cache-purge";
import { dispatchPluginContentEvent, getCmsConfig } from "./config";
import { recordD1Audit } from "./d1-audit";
import { createD1SchedulingPart } from "./d1-store-content";
import type { Actor } from "./persistence-types";
import {
	type ContentStatus,
	cleanIdList,
	detectConflict,
	insertContentRevision,
	normalizeLegacyUrl,
	normalizeScheduledAt,
	normalizeSeoFields,
	nullsToUndefined,
	SQL_INSERT_CONTENT_ENTRY,
	SQL_INSERT_CREATE_OVERRIDE,
	serializeMetadata,
	trimOrNull,
	UPSERT_CONTENT_OVERRIDE_SQL,
} from "./runtime-actions-content-helpers";
import {
	ensureD1BaselineRevision,
	findPageRecord,
	mapContentState,
	normalizeContentStatus,
	replaceD1ContentAssignments,
	validateContentTypeFields,
} from "./runtime-actions-content-shared";
import type { SaveContentInput } from "./runtime-actions-content-types";

export async function saveRuntimeContentState(
	slug: string,
	input: SaveContentInput,
	actor: Actor,
	locals?: App.Locals | null,
): Promise<{ ok: false; error: string; conflict?: true } | { ok: true; state?: unknown }> {
	return withLocalStoreFallback<
		{ ok: false; error: string; conflict?: true } | { ok: true; state?: unknown }
	>(
		locals,
		async (db) => {
			const pageRecord = await findPageRecord(slug, locals);
			if (!pageRecord) {
				return {
					ok: false as const,
					error: "The selected content record could not be found.",
				};
			}

			const title = input.title.trim();
			const seoTitle = input.seoTitle.trim();
			const metaDescription = input.metaDescription.trim();
			const status: ContentStatus = normalizeContentStatus(input.status);
			const body = input.body?.trim() || pageRecord.body || "";
			const scheduledAt = normalizeScheduledAt(input.scheduledAt);
			const revisionNote = trimOrNull(input.revisionNote);
			const authorIds = cleanIdList(input.authorIds);
			const categoryIds = cleanIdList(input.categoryIds);
			const tagIds = cleanIdList(input.tagIds);

			if (!title || !seoTitle || !metaDescription) {
				return {
					ok: false as const,
					error: "Title, SEO title, and meta description are required.",
				};
			}

			await ensureD1BaselineRevision(db, pageRecord);

			if (input.lastKnownUpdatedAt) {
				const conflict = await detectConflict(db, pageRecord.slug, input.lastKnownUpdatedAt);
				if (conflict) return conflict;
			}

			// Content type field validation
			const metadata = input.metadata ?? {};
			const fieldError = validateContentTypeFields(pageRecord.templateKey, metadata);
			if (fieldError) {
				return { ok: false as const, error: fieldError };
			}
			const metadataJson = serializeMetadata(metadata);
			const seo = normalizeSeoFields(input);

			await db
				.prepare(UPSERT_CONTENT_OVERRIDE_SQL)
				.bind(
					pageRecord.slug,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
					seo.excerpt,
					seo.ogTitle,
					seo.ogDescription,
					seo.ogImage,
					scheduledAt,
					seo.canonicalUrlOverride,
					seo.robotsDirective,
					metadataJson,
					actor.email,
				)
				.run();

			await replaceD1ContentAssignments(db, pageRecord.slug, {
				authorIds,
				categoryIds,
				tagIds,
			});

			await insertContentRevision(db, pageRecord.slug, {
				title,
				status,
				scheduledAt,
				body,
				seoTitle,
				metaDescription,
				seo,
				authorIds: serializeIdList(authorIds),
				categoryIds: serializeIdList(categoryIds),
				tagIds: serializeIdList(tagIds),
				revisionNote,
				actor,
			});

			await recordD1Audit(
				locals,
				actor,
				"content.update",
				"content",
				pageRecord.slug,
				`Updated reviewed metadata for ${pageRecord.legacyUrl}.`,
			);

			const pluginEvent = {
				slug: pageRecord.slug,
				kind: "post",
				status,
				actor: actor.email,
			};
			await dispatchPluginContentEvent("onContentSave", pluginEvent);
			if (status === "published") {
				await dispatchPluginContentEvent("onContentPublish", pluginEvent);
				// Fire CDN purge asynchronously — failure must not block the publish response
				void purgeCdnCache(pageRecord.slug, getCmsConfig());
			}

			return {
				ok: true as const,
				state: mapContentState(pageRecord, {
					title,
					status,
					scheduledAt: scheduledAt ?? undefined,
					body,
					authorIds,
					categoryIds,
					tagIds,
					seoTitle,
					metaDescription,
					...nullsToUndefined(seo),
				}),
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.saveContentState(slug, input, actor),
	);
}

export async function createRuntimeContentRecord(
	input: {
		title: string;
		slug: string;
		legacyUrl?: string;
		status: string;
		body?: string;
		summary?: string;
		seoTitle: string;
		metaDescription: string;
		excerpt?: string;
		ogTitle?: string;
		ogDescription?: string;
		ogImage?: string;
		canonicalUrlOverride?: string;
		robotsDirective?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
): Promise<{ ok: false; error: string } | { ok: true; state: unknown }> {
	return withLocalStoreFallback<{ ok: false; error: string } | { ok: true; state: unknown }>(
		locals,
		async (db) => {
			const title = input.title.trim();
			const slug = slugifyContent(input.slug);
			const legacyUrl = normalizeLegacyUrl(input.legacyUrl, slug);
			const seoTitle = input.seoTitle.trim() || title;
			const metaDescription = input.metaDescription.trim();
			const status = normalizeContentStatus(input.status);
			const body = input.body?.trim() || "";
			const summary = input.summary?.trim() || "";
			const seo = normalizeSeoFields(input);

			if (!title || !slug || !metaDescription) {
				return {
					ok: false as const,
					error: "Title, slug, and meta description are required.",
				};
			}

			if (
				(await findPageRecord(slug, locals)) ||
				(await findPageRecord(legacyUrl.replace(/^\//, ""), locals))
			) {
				return { ok: false as const, error: "That slug is already in use." };
			}

			try {
				await db
					.prepare(SQL_INSERT_CONTENT_ENTRY)
					.bind(
						slug,
						legacyUrl,
						title,
						`runtime://content/${slug}`,
						body,
						summary,
						seoTitle,
						metaDescription,
						seo.ogTitle,
						seo.ogDescription,
						seo.ogImage,
					)
					.run();
				/* v8 ignore next 3 */
			} catch {
				return {
					ok: false as const,
					error: "That slug or route is already in use.",
				};
			}

			const createSeo = { ...seo, excerpt: seo.excerpt || summary || null };

			await db
				.prepare(SQL_INSERT_CREATE_OVERRIDE)
				.bind(
					slug,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
					createSeo.excerpt,
					createSeo.ogTitle,
					createSeo.ogDescription,
					createSeo.ogImage,
					createSeo.canonicalUrlOverride,
					createSeo.robotsDirective,
					actor.email,
				)
				.run();

			await insertContentRevision(db, slug, {
				title,
				status,
				body,
				seoTitle,
				metaDescription,
				seo: createSeo,
				authorIds: "[]",
				categoryIds: "[]",
				tagIds: "[]",
				revisionNote: "Created new post.",
				actor,
			});

			await recordD1Audit(
				locals,
				actor,
				"content.create",
				"content",
				slug,
				`Created post ${legacyUrl}.`,
			);

			return {
				ok: true as const,
				state: {
					slug,
					legacyUrl,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
				},
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.createContentRecord(input, actor),
	);
}

/**
 * Schedules a content record for future publication, dispatching to D1 when a
 * binding is present and to the local store otherwise. Lets the schedule-publish
 * admin action work on D1-backed hosts without the local runtime alias (#137).
 */
export async function scheduleRuntimePublish(
	slug: string,
	scheduledAt: string,
	locals?: App.Locals | null,
): Promise<{ ok: true } | { ok: false; error: string }> {
	return withLocalStoreFallback<{ ok: true } | { ok: false; error: string }>(
		locals,
		async (db) => {
			await createD1SchedulingPart(db).schedulePublish(slug, scheduledAt);
			return { ok: true as const };
		},
		/* v8 ignore next 4 */
		(localStore) => {
			if (!localStore.schedulePublish) {
				return { ok: false as const, error: "Content scheduling is not available." };
			}
			localStore.schedulePublish(slug, scheduledAt);
			return { ok: true as const };
		},
	);
}

