import { normalizePath } from "./admin-normalizers";
import { getCloudflareBindings } from "./runtime-env";
import {
	parseSettings,
	type RuntimeStructuredPageRouteRecord,
	withSafeRouteRegistryFallback,
} from "./runtime-route-registry-dispatch";
// Shared with the local sqlite row mapper — a single fail-open definition so the
// two structured-page mappers can't drift (see sqlite-runtime/utils).
import { normalizeStructuredTemplateKey } from "./sqlite-runtime/utils";

// ─── Mutations — extracted to runtime-route-registry-pages-mutations.ts ──────
export {
	createRuntimeStructuredPageRoute,
	saveRuntimeStructuredPageRoute,
} from "./runtime-route-registry-pages-mutations";

function mapStructuredPageRow(
	row:
		| {
				path: string;
				status?: string | null;
				title: string;
				summary: string | null;
				seo_title: string | null;
				meta_description: string | null;
				canonical_url_override: string | null;
				robots_directive: string | null;
				og_image: string | null;
				sections_json: string | null;
				settings_json: string | null;
				updated_at: string;
		  }
		| null
		| undefined,
): RuntimeStructuredPageRouteRecord | null {
	if (!row) {
		return null;
	}

	const settings = parseSettings(row.settings_json) ?? {};
	const templateKey = normalizeStructuredTemplateKey(settings.templateKey);
	if (!templateKey) {
		return null;
	}
	return {
		path: row.path,
		// cms_route_variants.status is TEXT NOT NULL (schema-enforced) — the
		// nullish fallback only exists to satisfy the shared row type's
		// optional `status?: string | null`, never to handle a real null.
		/* v8 ignore next */
		status: row.status ?? undefined,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		ogImage: row.og_image ?? undefined,
		templateKey,
		alternateLinks: Array.isArray(settings.alternateLinks)
			? (settings.alternateLinks as Array<{ hreflang: string; href: string }>)
			: [],
		sections: parseSettings(row.sections_json),
		updatedAt: row.updated_at,
	} satisfies RuntimeStructuredPageRouteRecord;
}

export async function listRuntimeStructuredPageRoutes(locals?: App.Locals | null) {
	const db = getCloudflareBindings(locals).DB;
	// No `db` fast-path: withSafeRouteRegistryFallback runs the operation, and a
	// missing binding makes `db!.prepare` throw, which the wrapper catches and
	// resolves through the same local-registry fallback — an identical result.
	return withSafeRouteRegistryFallback(
		(local) => local.listStructuredPageRoutes(),
		[],
		async () => {
			const rows = (
				await db!
					.prepare(
						`
              SELECT v.path, v.status, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive,
                     v.og_image, v.sections_json, v.settings_json, v.updated_at
              FROM cms_route_variants v
              INNER JOIN cms_route_groups g ON g.id = v.group_id
              WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections'
              ORDER BY v.path ASC
            `,
					)
					.all<{
						path: string;
						status: string | null;
						title: string;
						summary: string | null;
						seo_title: string | null;
						meta_description: string | null;
						canonical_url_override: string | null;
						robots_directive: string | null;
						og_image: string | null;
						sections_json: string | null;
						settings_json: string | null;
						updated_at: string;
					}>()
			).results;

			return rows
				.map((row) => mapStructuredPageRow(row))
				.filter((route): route is RuntimeStructuredPageRouteRecord => route !== null);
		},
	);
}

export async function getRuntimeStructuredPageRoute(pathname: string, locals?: App.Locals | null) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	// See listRuntimeStructuredPageRoutes: no `db` fast-path — a missing binding
	// throws inside the operation and the wrapper falls back to the local registry.
	return withSafeRouteRegistryFallback(
		(local) => local.getStructuredPageRoute(normalizedPath),
		null,
		async () => {
			const row = await db!
				.prepare(
					`
            SELECT v.path, v.status, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive,
                   v.og_image, v.sections_json, v.settings_json, v.updated_at
            FROM cms_route_variants v
            INNER JOIN cms_route_groups g ON g.id = v.group_id
            WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' AND v.path = ?
            LIMIT 1
          `,
				)
				.bind(normalizedPath)
				.first<{
					path: string;
					status: string | null;
					title: string;
					summary: string | null;
					seo_title: string | null;
					meta_description: string | null;
					canonical_url_override: string | null;
					robots_directive: string | null;
					og_image: string | null;
					sections_json: string | null;
					settings_json: string | null;
					updated_at: string;
				}>();

			return mapStructuredPageRow(row);
		},
	);
}

src/sections/preview-renderer.ts.source:
/**
 * Plain-string section renderer for the live editor preview.
 *
 * Mirrors the structure of the Astro components in components/sections/ but
 * outputs HTML strings — so the preview can run entirely client-side without
 * a server roundtrip per keystroke. Approximate (not pixel-perfect) but
 * close enough for editing.
 *
 * The full-fidelity renderer remains components/sections/Sections.astro;
 * this module exists only for the editor's live preview iframe.
 */

import type {
	CtaBannerSection,
	FaqSection,
	FeatureGridSection,
	GallerySection,
	HeroSection,
	ImageTextSection,
	RichTextSection,
	Section,
	TestimonialsSection,
} from "./schema";

export interface PreviewContext {
	mediaUrls: Record<string, string>;
	testimonials: Array<{
		id: string;
		name: string;
		role?: string | null;
		company?: string | null;
		quote: string;
		featured?: boolean;
		status?: string | null;
	}>;
	dir?: "ltr" | "rtl";
}

const escapeHtml = (v: string): string =>
	String(v)
		.replace(/&/g, "&amp;")
		.replace(/"/g, "&quot;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");

const escText = (v: string): string =>
	String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const SAFE_HREF_SCHEMES = new Set(["http", "https", "mailto", "tel"]);

/**
 * Neutralizes dangerous link targets before they reach an `href` attribute.
 * `escapeHtml` alone does not stop `javascript:`/`data:`/`vbscript:` URLs, and
 * this renderer now emits CTA anchors to anonymous public visitors (not just the
 * admin preview iframe), so an editor-authored href is untrusted output.
 *
 * Relative URLs, fragments, and paths have no scheme and pass through. Any value
 * carrying an explicit scheme outside the allowlist collapses to "#". Control
 * characters and whitespace (which browsers strip when parsing a scheme, e.g.
 * `java\tscript:`) are removed before the scheme is inspected.
 */
export function safeHref(value: string): string {
	const raw = String(value);
	// Strip characters browsers ignore when parsing a URL scheme (C0 controls,
	// space, DEL, C1 controls) so `java	script:` cannot slip through.
	let cleaned = "";
	for (const ch of raw) {
		const c = ch.codePointAt(0) ?? 0;
		if (c > 0x20 && c !== 0x7f && !(c >= 0x80 && c <= 0x9f)) cleaned += ch;
	}
	// Group 1 always participates on a match, so it needs no second `?.`.
	const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(cleaned)?.[1].toLowerCase();
	if (scheme && !SAFE_HREF_SCHEMES.has(scheme)) return "#";
	return raw.trim();
}

function renderHero(s: HeroSection, ctx: PreviewContext): string {
	const mediaUrl = s.mediaId ? ctx.mediaUrls[s.mediaId] : null;
	const align = s.alignment === "center" ? "center" : "start";
	return `
<section class="ap-section ap-hero" data-align="${escapeHtml(align)}">
  ${mediaUrl ? `<div class="ap-hero__media" aria-hidden="true"><img src="${escapeHtml(mediaUrl)}" alt="" /></div>` : ""}
  <div class="ap-hero__inner">
    <h1 class="ap-hero__headline">${escText(s.headline)}</h1>
    ${s.subhead ? `<p class="ap-hero__subhead">${escText(s.subhead)}</p>` : ""}
    ${
			s.primaryCta || s.secondaryCta
				? `<div class="ap-hero__cta">
      ${s.primaryCta ? `<a class="ap-btn ap-btn--primary" href="${escapeHtml(safeHref(s.primaryCta.href))}">${escText(s.primaryCta.label)}</a>` : ""}
      ${s.secondaryCta ? `<a class="ap-btn ap-btn--secondary" href="${escapeHtml(safeHref(s.secondaryCta.href))}">${escText(s.secondaryCta.label)}</a>` : ""}
    </div>`
				: ""
		}
  </div>
</section>`;
}

function renderFeatureGrid(s: FeatureGridSection): string {
	return `
<section class="ap-section ap-feature-grid" data-columns="${s.columns}">
  <div class="ap-feature-grid__head">
    <h2 class="ap-feature-grid__heading">${escText(s.heading)}</h2>
    ${s.intro ? `<p class="ap-feature-grid__intro">${escText(s.intro)}</p>` : ""}
  </div>
  <ul class="ap-feature-grid__items" role="list">
    ${s.items
			.map(
				(item) => `
    <li class="ap-feature-grid__item">
      ${item.icon ? `<span class="ap-feature-grid__icon" aria-hidden="true">${escText(item.icon)}</span>` : ""}
      <h3 class="ap-feature-grid__title">${escText(item.title)}</h3>
      <p class="ap-feature-grid__body">${escText(item.body)}</p>
    </li>`,
			)
			.join("")}
  </ul>
</section>`;
}

function renderTestimonials(s: TestimonialsSection, ctx: PreviewContext): string {
	const all = ctx.testimonials;
	const isApproved = (t: PreviewContext["testimonials"][number]) =>
		(t.status ?? "approved") === "approved";
	let picked: PreviewContext["testimonials"];
	if (s.source === "ids" && s.ids) {
		const wanted = new Set(s.ids);
		picked = all.filter((t) => wanted.has(t.id));
	} else if (s.source === "featured") {
		picked = all.filter((t) => t.featured === true && isApproved(t));
	} else {
		picked = all.filter(isApproved);
	}
	const layout = s.layout === "carousel" ? "carousel" : "grid";
	return `
<section class="ap-section ap-testimonials" data-layout="${escapeHtml(layout)}">
  ${s.heading ? `<h2 class="ap-testimonials__heading">${escText(s.heading)}</h2>` : ""}
  ${
		picked.length === 0
			? `<p class="ap-testimonials__empty">No testimonials yet.</p>`
			: `<ul class="ap-testimonials__list" role="list">
    ${picked
			.map(
				(t) => `
    <li class="ap-testimonials__item">
      <blockquote class="ap-testimonials__quote">${escText(t.quote)}</blockquote>
      <footer class="ap-testimonials__cite">
        <span class="ap-testimonials__name">${escText(t.name)}</span>
        ${
					t.role || t.company
						? `<span class="ap-testimonials__meta">${escText(
								[t.role, t.company].filter(Boolean).join(" — "),
							)}</span>`
						: ""
				}
      </footer>
    </li>`,
			)
			.join("")}
  </ul>`
	}
</section>`;
}

function renderCtaBanner(s: CtaBannerSection): string {
	return `
<section class="ap-section ap-cta" data-tone="${escapeHtml(s.tone)}">
  <div class="ap-cta__inner">
    <h2 class="ap-cta__headline">${escText(s.headline)}</h2>
    ${s.body ? `<p class="ap-cta__body">${escText(s.body)}</p>` : ""}
    <div class="ap-cta__actions">
      <a class="ap-btn ap-btn--primary" href="${escapeHtml(safeHref(s.primaryCta.href))}">${escText(s.primaryCta.label)}</a>
      ${s.secondaryCta ? `<a class="ap-btn ap-btn--secondary" href="${escapeHtml(safeHref(s.secondaryCta.href))}">${escText(s.secondaryCta.label)}</a>` : ""}
    </div>
  </div>
</section>`;
}

function renderImageText(s: ImageTextSection, ctx: PreviewContext): string {
	const mediaUrl = ctx.mediaUrls[s.mediaId] ?? null;
	const side = s.imageSide === "end" ? "end" : "start";
	return `
<section class="ap-section ap-image-text" data-image-side="${escapeHtml(side)}">
  <div class="ap-image-text__media">
    ${
			mediaUrl
				? `<img src="${escapeHtml(mediaUrl)}" alt="" />`
				: `<div class="ap-image-text__placeholder" aria-hidden="true"></div>`
		}
  </div>
  <div class="ap-image-text__copy">
    <h2 class="ap-image-text__heading">${escText(s.heading)}</h2>
    <div class="ap-image-text__body">${
			// nosemgrep: javascript.express.security.injection.raw-html-format.raw-html-format
			s.body
		}</div>
  </div>
</section>`;
}

function renderFaq(s: FaqSection): string {
	return `
<section class="ap-section ap-faq">
  ${s.heading ? `<h2 class="ap-faq__heading">${escText(s.heading)}</h2>` : ""}
  <ul class="ap-faq__list" role="list">
    ${s.items
			.map(
				(item) => `
    <li class="ap-faq__item">
      <details class="ap-faq__details">
        <summary class="ap-faq__question">${escText(item.question)}</summary>
        <div class="ap-faq__answer">${escText(item.answer)}</div>
      </details>
    </li>`,
			)
			.join("")}
  </ul>
</section>`;
}

function renderGallery(s: GallerySection, ctx: PreviewContext): string {
	const items = s.mediaIds
		.map((id) => ({ id, url: ctx.mediaUrls[id] }))
		.filter((entry) => Boolean(entry.url));
	return `
<section class="ap-section ap-gallery" data-columns="${s.columns}">
  ${s.heading ? `<h2 class="ap-gallery__heading">${escText(s.heading)}</h2>` : ""}
  ${
		items.length === 0
			? `<p class="ap-gallery__empty">No images yet.</p>`
			: `<ul class="ap-gallery__items" role="list">${items
					.map(
						// `it.url` is guaranteed truthy — falsy entries were filtered above.
						(it) => `<li class="ap-gallery__item"><img src="${escapeHtml(it.url)}" alt="" /></li>`,
					)
					.join("")}</ul>`
	}
</section>`;
}

function renderRichText(s: RichTextSection): string {
	return `<section class="ap-section ap-rich-text"><div class="ap-rich-text__inner">${s.html}</div></section>`;
}

function renderSection(section: Section, ctx: PreviewContext): string {
	switch (section.kind) {
		case "hero":
			return renderHero(section, ctx);
		case "feature-grid":
			return renderFeatureGrid(section);
		case "testimonials":
			return renderTestimonials(section, ctx);
		case "cta-banner":
			return renderCtaBanner(section);
		case "image-text":
			return renderImageText(section, ctx);
		case "faq":
			return renderFaq(section);
		case "gallery":
			return renderGallery(section, ctx);
		case "rich-text":
			return renderRichText(section);
	}
}

/**
 * Build a complete <iframe>-ready document containing the rendered sections
 * and the public sections.css. Used as iframe srcdoc.
 */
/**
 * Renders just the sections markup (the `<div class="ap-sections">…</div>`
 * wrapper), without a surrounding HTML document. Public page renderers use this
 * to compose their own `<head>` (SEO metadata, canonical, Open Graph) around the
 * section body, while the admin live preview uses `renderSectionsDocument`.
 */
export function renderSectionsBody(sections: Section[], ctx: PreviewContext): string {
	return `<div class="ap-sections">${sections.map((s) => renderSection(s, ctx)).join("")}</div>`;
}

export function renderSectionsDocument(
	sections: Section[],
	ctx: PreviewContext,
	options: { stylesheetUrl?: string } = {},
): string {
	const dir = ctx.dir === "rtl" ? "rtl" : "ltr";
	const stylesheet = options.stylesheetUrl
		? `<link rel="stylesheet" href="${escapeHtml(options.stylesheetUrl)}" />`
		: "";
	return `<!doctype html>
<html lang="en" dir="${dir}">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Preview</title>
${stylesheet}
<style>body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#0f172a;background:#fff}</style>
</head>
<body>
${renderSectionsBody(sections, ctx)}
</body>
</html>`;
}

