	"INSERT INTO rate_limits (key, count, window_start_ms, window_ms) VALUES (?, 1, ?, ?) ON CONFLICT(key) DO UPDATE SET count = 1, window_start_ms = excluded.window_start_ms, window_ms = excluded.window_ms";
