src/auth-repository-factory.ts.source:
import {
	type AstropressAuthRepositoryInput,
	type AstropressAuthSessionRow,
	type AstropressInviteTokenRecord,
	type AstropressPasswordResetTokenRecord,
	issuePasswordResetToken,
	mapSessionUser,
	resolveUsableInviteToken,
	resolveUsablePasswordResetToken,
	resolveValidSession,
	validatePasswordInput,
} from "./auth-repository-helpers";
import type { AuthRepository, PasswordResetRequest, SessionUser } from "./persistence-types";

export type {
	AstropressAuthRepositoryInput,
	AstropressAuthSessionRow,
	AstropressInviteTokenRecord,
	AstropressPasswordResetTokenRecord,
};

export function createAstropressAuthRepository(
	input: AstropressAuthRepositoryInput,
): AuthRepository & {
	authenticatePersistedAdminUser(email: string, password: string): Promise<SessionUser | null>;
} {
	return {
		async authenticatePersistedAdminUser(email, password) {
			const normalizedEmail = email.trim().toLowerCase();
			if (!normalizedEmail || !password) {
				return null;
			}

			const user = input.findActiveAdminUserByEmail(normalizedEmail);
			if (!user || !input.verifyPassword(password, user.passwordHash)) {
				return null;
			}

			return mapSessionUser(user);
		},
		createSession(user, metadata) {
			const userId = input.findActiveAdminUserIdByEmail(user.email.toLowerCase());
			if (!userId) {
				throw new Error(`Cannot create a session for unknown admin user ${user.email}.`);
			}

			const sessionToken = input.randomId();
			const csrfToken = input.randomId();
			input.insertSession({
				sessionToken,
				userId,
				csrfToken,
				ipAddress: metadata?.ipAddress ?? null,
				userAgent: metadata?.userAgent ?? null,
			});
			return sessionToken;
		},
		getSessionUser(sessionToken) {
			const row = resolveValidSession(sessionToken, input);
			return row ? mapSessionUser(row) : null;
		},
		getCsrfToken(sessionToken) {
			const row = resolveValidSession(sessionToken, input);
			return row ? row.csrfToken : null;
		},
		revokeSession(sessionToken) {
			if (!sessionToken) {
				return;
			}
			input.revokeSessionById(sessionToken);
		},
		createPasswordResetToken(email, actor) {
			return issuePasswordResetToken(email, actor ?? undefined, input);
		},
		getInviteRequest(rawToken) {
			const row = resolveUsableInviteToken(rawToken, input);
			if (!row) {
				return null;
			}

			return {
				email: row.email,
				name: row.name,
				role: row.role,
				expiresAt: row.expiresAt,
			};
		},
		getPasswordResetRequest(rawToken) {
			const row = resolveUsablePasswordResetToken(rawToken, input);
			if (!row) {
				return null;
			}

			return {
				email: row.email,
				name: row.name,
				role: row.role,
				expiresAt: row.expiresAt,
			} as PasswordResetRequest;
		},
		consumeInviteToken(rawToken, password) {
			const pw = validatePasswordInput(password);
			if (!pw.ok) {
				return {
					ok: false as const,
					error: "Password must be at least 12 characters.",
				};
			}

			const row = resolveUsableInviteToken(rawToken, input);
			if (!row) {
				return {
					ok: false as const,
					error: "That invitation link is invalid or has expired.",
				};
			}

			input.updateAdminUserPassword(row.userId, input.hashPassword(pw.trimmedPassword));
			input.acceptInvitesForUser(row.userId);
			input.recordAuthAudit({
				actor: { email: row.email, role: row.role, name: row.name },
				action: "auth.invite_accept",
				summary: `${row.email} accepted an admin invitation.`,
				targetId: row.email,
			});

			return {
				ok: true as const,
				user: {
					email: row.email,
					role: row.role,
					name: row.name,
				},
			};
		},
		consumePasswordResetToken(rawToken, password) {
			const pw = validatePasswordInput(password);
			if (!pw.ok) {
				return {
					ok: false as const,
					error: "Password must be at least 12 characters.",
				};
			}

			const row = resolveUsablePasswordResetToken(rawToken, input);
			if (!row) {
				return {
					ok: false as const,
					error: "That password reset link is invalid or has expired.",
				};
			}

			input.updateAdminUserPassword(row.userId, input.hashPassword(pw.trimmedPassword));
			input.markPasswordResetTokenConsumed(row.id);
			input.revokeSessionsForUser(row.userId);
			input.recordAuthAudit({
				actor: { email: row.email, role: row.role, name: row.name },
				action: "auth.password_reset_complete",
				summary: `${row.email} completed a password reset.`,
				targetId: row.email,
			});

			return {
				ok: true as const,
				user: {
					email: row.email,
					role: row.role,
					name: row.name,
				},
			};
		},
		recordSuccessfulLogin(actor) {
			input.recordAuthAudit({
				actor,
				action: "auth.login",
				summary: `${actor.name} signed in successfully.`,
				targetId: actor.email,
			});
		},
		recordLogout(actor) {
			input.recordAuthAudit({
				actor,
				action: "auth.logout",
				summary: `${actor.name} signed out.`,
				targetId: actor.email,
			});
		},
	};
}

src/cache-purge.ts.source:
import type { CmsConfig } from "./config";
import {
	type ResolvedCdnPurge,
	resolveCdnPurge,
} from "./integrations/resolvers/cdn-purge-resolver.js";

/**
 * Issue a CDN purge for a single content slug against an already-resolved
 * configuration. The split between this function and {@link purgeCdnCache}
 * keeps the imperative I/O branches separate from source resolution —
 * the resolver is unit-tested for every priority/fallback path; this
 * function is unit-tested with mocked fetch for each `kind`.
 *
 * Failures are non-fatal: errors are logged with `console.warn` but
 * never thrown, so a CDN purge failure never blocks a content publish.
 */
export async function purgeCdnCacheForResolved(
	slug: string,
	resolved: ResolvedCdnPurge,
	deps: { readonly fetch?: typeof fetch } = {},
): Promise<void> {
	if (resolved.kind === "none") return;
	const fetchImpl = deps.fetch ?? fetch;
	const purgedAt = new Date().toISOString();

	if (resolved.kind === "cloudflare") {
		try {
			const url = `https://api.cloudflare.com/client/v4/zones/${encodeURIComponent(resolved.zoneId)}/purge_cache`;
			const res = await fetchImpl(url, {
				method: "POST",
				headers: {
					Authorization: `Bearer ${resolved.apiToken}`,
					"Content-Type": "application/json",
				},
				body: JSON.stringify({ tags: [`slug:${slug}`] }),
			});
			if (!res.ok) {
				const body = await res.text().catch(() => "");
				console.warn(
					`[cache-purge] Cloudflare purge failed for slug "${slug}": ${res.status} ${body}`,
				);
			}
		} catch (err) {
			console.warn(`[cache-purge] Cloudflare purge error for slug "${slug}":`, err);
		}
		return;
	}

	// kind === "webhook"
	try {
		const res = await fetchImpl(resolved.url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ slug, purgedAt }),
		});
		if (!res.ok) {
			const body = await res.text().catch(() => "");
			console.warn(`[cache-purge] Webhook purge failed for slug "${slug}": ${res.status} ${body}`);
		}
	} catch (err) {
		console.warn(`[cache-purge] Webhook purge error for slug "${slug}":`, err);
	}
}

/**
 * Legacy entry point — purges via env (Cloudflare) and/or static
 * `config.cdnPurgeWebhook`. Hosts that have admin-connected a
 * Cloudflare CDN provider via the Phase 4 connect flow should call
 * the registry-aware path instead (resolve via
 * {@link resolveCdnPurge} with `registry` populated, then
 * {@link purgeCdnCacheForResolved}).
 *
 * Backward-compatible: keeps the single-arg `(slug, config)` shape
 * that `runtime-actions-content.ts` and downstream callers already
 * use, so call-sites can migrate incrementally without a flag-day.
 */
export async function purgeCdnCache(
	slug: string,
	config: CmsConfig,
	registryFields?: {
		readonly apiToken: string;
		readonly zoneId: string;
	} | null,
): Promise<void> {
	const env = typeof process !== "undefined" ? process.env : undefined;
	const resolved = resolveCdnPurge({
		registry: registryFields,
		env: env
			? {
					CLOUDFLARE_API_TOKEN: env.CLOUDFLARE_API_TOKEN,
					CLOUDFLARE_ZONE_ID: env.CLOUDFLARE_ZONE_ID,
				}
			: undefined,
		config: { cdnPurgeWebhook: config.cdnPurgeWebhook },
	});
	await purgeCdnCacheForResolved(slug, resolved);
}

src/client/redirects-dialog.ts.source:
window.addEventListener("DOMContentLoaded", () => {
	const dialog = document.getElementById("confirm-dialog") as HTMLDialogElement | null;
	const source = document.getElementById("dialog-source");
	const target = document.getElementById("dialog-target");
	const form = document.getElementById("confirm-form") as HTMLFormElement | null;

	for (const button of document.querySelectorAll<HTMLElement>("[data-confirm-delete]")) {
		button.addEventListener("click", () => {
			if (!dialog || !source || !target || !form) {
				return;
			}

			const sourcePath = button.getAttribute("data-source-path") || "";
			source.textContent = sourcePath;
			target.textContent = button.getAttribute("data-target-path") || "";

			const sourcePathField = form.querySelector<HTMLInputElement>('input[name="sourcePath"]');
			if (sourcePathField) {
				sourcePathField.value = sourcePath;
			}

			dialog.showModal();
		});
	}

	for (const button of document.querySelectorAll<HTMLElement>(
		'[data-dialog-close="#confirm-dialog"]',
	)) {
		button.addEventListener("click", () => {
			dialog?.close();
		});
	}
});

