export type AstropressCloudflareViteIntegration = {
	aliases: Array<{ find: string | RegExp; replacement: string }>;
	plugin: {
		name: string;
		enforce: "pre";
		resolveId: (id: string) => string | null;
	};
};

export type AstropressCloudflareViteIntegrationOptions = {
	cloudflareLocalRuntimeStubsPath?: string;
	cloudflareLocalImageStorageStubPath?: string;
	cloudflareLocalMediaStorageStubPath?: string;
	cloudflareSqliteAdapterStubPath?: string;
	cloudflareSqliteAdminRuntimeStubPath?: string;
	cloudflareSqliteBootstrapStubPath?: string;
};

type ResolvedStubPaths = {
	localImageStorage: string;
	localMediaStorage: string;
	sqliteAdapter: string;
	sqliteAdminRuntime: string;
	sqliteBootstrap: string;
	localRuntimeStubs: string;
};

type ResolveIdEntry = {
	check: (id: string, localRuntimeModulesPath: string) => boolean;
	stubKey: keyof ResolvedStubPaths;
};

const aliasPatterns: Array<{
	find: string | RegExp;
	stubKey: keyof ResolvedStubPaths;
}> = [
	{ find: "astropress/local-image-storage", stubKey: "localImageStorage" },
	{
		find: /^.*\/local-image-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localImageStorage",
	},
	{ find: "astropress/local-media-storage", stubKey: "localMediaStorage" },
	{
		find: /^.*\/local-media-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localMediaStorage",
	},
	{ find: "astropress/adapters/sqlite", stubKey: "sqliteAdapter" },
	{ find: /^.*\/adapters\/sqlite(?:\.[cm]?[jt]s)?$/, stubKey: "sqliteAdapter" },
	{ find: "astropress/sqlite-admin-runtime", stubKey: "sqliteAdminRuntime" },
	{
		find: /^.*\/sqlite-admin-runtime(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteAdminRuntime",
	},
	{ find: "astropress/sqlite-bootstrap", stubKey: "sqliteBootstrap" },
	{
		find: /^.*\/sqlite-bootstrap(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteBootstrap",
	},
	{
		find: /^\.\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
	{
		find: /^.*\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
];

const resolveIdEntries: ResolveIdEntry[] = [
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-image-storage"),
		stubKey: "localImageStorage",
	},
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-media-storage"),
		stubKey: "localMediaStorage",
	},
	{ check: (id) => isSqliteAdapterRequest(id), stubKey: "sqliteAdapter" },
	{
		check: (id) => isSqliteAdminRuntimeRequest(id),
		stubKey: "sqliteAdminRuntime",
	},
	{ check: (id) => isSqliteBootstrapRequest(id), stubKey: "sqliteBootstrap" },
	{
		check: (id, lrm) => isLocalRuntimeModuleRequest(id, lrm),
		stubKey: "localRuntimeStubs",
	},
];

function isLocalRuntimeModuleRequest(id: string, localRuntimeModulesPath: string): boolean {
	if (
		id === "./local-runtime-modules" ||
		id === "./local-runtime-modules.ts" ||
		id === "local-runtime-modules" ||
		id === "local-runtime-modules.ts"
	) {
		return true;
	}

	return (
		id === localRuntimeModulesPath ||
		id.endsWith("/local-runtime-modules") ||
		id.endsWith("/local-runtime-modules.ts")
	);
}

function isPackageStorageModuleRequest(
	id: string,
	moduleName: "local-image-storage" | "local-media-storage",
): boolean {
	return (
		id === `astropress/${moduleName}` ||
		id.endsWith(`/${moduleName}`) ||
		id.endsWith(`/${moduleName}.ts`) ||
		id.endsWith(`/${moduleName}.js`)
	);
}

function isSqliteAdminRuntimeRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-admin-runtime" ||
		id.endsWith("/sqlite-admin-runtime") ||
		id.endsWith("/sqlite-admin-runtime.ts") ||
		id.endsWith("/sqlite-admin-runtime.js")
	);
}

function isSqliteAdapterRequest(id: string): boolean {
	return (
		id === "astropress/adapters/sqlite" ||
		id.endsWith("/adapters/sqlite") ||
		id.endsWith("/adapters/sqlite.ts") ||
		id.endsWith("/adapters/sqlite.js")
	);
}

function isSqliteBootstrapRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-bootstrap" ||
		id.endsWith("/sqlite-bootstrap") ||
		id.endsWith("/sqlite-bootstrap.ts") ||
		id.endsWith("/sqlite-bootstrap.js")
	);
}

function normalizeImportId(id: string): string {
	let normalized = id.replaceAll("\\", "/");
	if (normalized.startsWith("file://")) {
		normalized = decodeURIComponent(normalized.replace(/^file:\/\/\/?/, "/"));
	}

	if (/^\/[a-zA-Z]:\//.test(normalized)) {
		return normalized.slice(1);
	}

	return normalized;
}

function resolveStubPaths(options: AstropressCloudflareViteIntegrationOptions): ResolvedStubPaths {
	return {
		localImageStorage:
			options.cloudflareLocalImageStorageStubPath ??
			"astropress/cloudflare-local-image-storage-stub",
		localMediaStorage:
			options.cloudflareLocalMediaStorageStubPath ??
			"astropress/cloudflare-local-media-storage-stub",
		sqliteAdapter:
			options.cloudflareSqliteAdapterStubPath ?? "astropress/cloudflare-sqlite-adapter-stub",
		sqliteAdminRuntime:
			options.cloudflareSqliteAdminRuntimeStubPath ??
			"astropress/cloudflare-sqlite-admin-runtime-stub",
		sqliteBootstrap:
			options.cloudflareSqliteBootstrapStubPath ?? "astropress/cloudflare-sqlite-bootstrap-stub",
		localRuntimeStubs:
			options.cloudflareLocalRuntimeStubsPath ?? "astropress/cloudflare-local-runtime-stubs",
	};
}

function resolvePluginId(
	normalizedId: string,
	localRuntimeModulesPath: string,
	stubs: ResolvedStubPaths,
): string | null {
	const match = resolveIdEntries.find((entry) =>
		entry.check(normalizedId, localRuntimeModulesPath),
	);
	return match ? stubs[match.stubKey] : null;
}

function buildAliases(
	stubs: ResolvedStubPaths,
	localRuntimeModulesPath: string,
): Array<{ find: string | RegExp; replacement: string }> {
	const aliases = aliasPatterns.map((entry) => ({
		find: entry.find,
		replacement: stubs[entry.stubKey],
	}));
	aliases.push({
		find: localRuntimeModulesPath,
		replacement: stubs.localRuntimeStubs,
	});
	return aliases;
}

export function createAstropressCloudflareViteIntegration(
	localRuntimeModulesPath: string,
	options: AstropressCloudflareViteIntegrationOptions = {},
): AstropressCloudflareViteIntegration {
	const stubs = resolveStubPaths(options);

	return {
		aliases: buildAliases(stubs, localRuntimeModulesPath),
		plugin: {
			name: "astropress-cloudflare-local-runtime-stubs",
			enforce: "pre",
			resolveId(id) {
				return resolvePluginId(normalizeImportId(id), localRuntimeModulesPath, stubs);
			},
		},
	};
}

src/cms-route-registry-helpers.ts.source:
import type { Actor } from "./persistence-types";
import type { RuntimeSystemRouteRecord } from "./runtime-route-registry";

export type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

import type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

interface RouteActor extends Actor {}

export type StructuredPageInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
	revisionNote?: string;
};

export type ArchiveRouteInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	revisionNote?: string;
};

/** Normalize structured page input fields, centralising branchy fallback logic. */
export function normalizeStructuredInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || title;
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	const ogImage = rawInput.ogImage?.trim() || null;
	const alternateLinks = rawInput.alternateLinks ?? [];
	const sections = rawInput.sections ?? null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
		ogImage,
		alternateLinks,
		sections,
	};
}

/** Normalize archive route input fields. */
export function normalizeArchiveInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || "";
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
	};
}

export function doSaveSystemRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: {
		title: string;
		summary?: string;
		bodyHtml?: string;
		// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
		settings?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath) {
		return { ok: false as const, error: "A system route path is required." };
	}
	const route = ctx.findSystemRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected system route could not be found.",
		};
	}
	const title = rawInput.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." };
	}
	const summary = rawInput.summary?.trim() || null;
	const bodyHtml = rawInput.bodyHtml?.trim() || null;
	const settings = rawInput.settings ?? null;
	ctx.persistSystemRoute({
		routeId: route.id,
		title,
		summary,
		bodyHtml,
		settingsJson: settings ? JSON.stringify(settings) : null,
		actor,
	});
	ctx.appendSystemRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		locale: ctx.localeFromPath(normalizedPath),
		title,
		summary,
		bodyHtml,
		settings,
		renderStrategy: route.renderStrategy,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "system.update",
		summary: `Updated system route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title,
			summary: summary ?? undefined,
			bodyHtml: bodyHtml ?? undefined,
			settings,
			renderStrategy: route.renderStrategy,
		} satisfies RuntimeSystemRouteRecord,
	};
}

export function doCreateStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath || normalizedPath === "/") {
		return { ok: false as const, error: "A public path is required." };
	}
	if (ctx.isRoutePathTaken(normalizedPath)) {
		return { ok: false as const, error: "That public path is already in use." };
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const locale = ctx.localeFromPath(normalizedPath);
	const shared = {
		pathname: normalizedPath,
		locale,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.insertStructuredRoute(shared);
	const created = ctx.getStructuredPageRoute(normalizedPath);
	const routeId = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!created || !routeId) {
		return {
			ok: false as const,
			error: "The route page could not be created.",
		};
	}
	ctx.appendStructuredRouteRevision({
		routeId: routeId.id,
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || "Created route page.",
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.create",
		summary: `Created route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return { ok: true as const, route: created };
}

export function doSaveStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected route page could not be found.",
		};
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const shared = {
		pathname: normalizedPath,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.persistStructuredRoute({ routeId: route.id, ...shared });
	ctx.appendStructuredRouteRevision({
		routeId: route.id,
		locale: ctx.localeFromPath(normalizedPath),
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || null,
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.update",
		summary: `Updated route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const saved = ctx.getStructuredPageRoute(normalizedPath);
	if (!saved) throw new Error(`Route ${normalizedPath} not found after save`);
	return { ok: true as const, route: saved };
}

export function doSaveArchiveRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: ArchiveRouteInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findArchiveRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected archive route could not be found.",
		};
	}
	const f = normalizeArchiveInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	ctx.persistArchiveRoute({
		routeId: route.id,
		pathname: normalizedPath,
		actor,
		...f,
	});
	ctx.appendArchiveRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		...f,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "archive.update",
		summary: `Updated archive route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const savedArchive = ctx.getArchiveRoute(normalizedPath);
	if (!savedArchive) throw new Error(`Archive route ${normalizedPath} not found after save`);
	return { ok: true as const, route: savedArchive };
}

src/integrations/oauth/registry.ts.source:
/**
 * In-memory registry of OAuth provider definitions. Phase 6 of
 * integration-honesty.
 *
 * Each registered provider declares the static endpoints + scope set
 * needed to start an authorization-code flow. Client credentials are
 * NOT held in the registry — they live in the running process's env
 * (per-deploy, never sealed) so the registry stays cheap to enumerate
 * and is safe to serialise into the admin UI's "available providers"
 * picker.
 *
 * The actual access/refresh tokens that come back from the IdP are
 * sealed via the Phase 2 envelope into `integration_secrets`, just
 * like Phase 4's bearer-token providers.
 *
 * Domain-pairing: every OAuth provider belongs to a single
 * `IntegrationDomain` (e.g. `"deploy-hooks"` for the GitHub deploy
 * provider) so the same `connected_integrations` row can describe
 * either a bearer-token or an OAuth-token connection. Callers route
 * by `(domain, providerId)` exactly as they do for non-OAuth
 * providers.
 */

import type { IntegrationDomain } from "../registry.js";

export interface OAuthProviderDefinition {
	readonly id: string;
	readonly domain: IntegrationDomain;
	readonly label: string;
	readonly authorizationUrl: string;
	readonly tokenUrl: string;
	readonly scopes: readonly string[];
	readonly clientIdEnv: string;
	readonly clientSecretEnv: string;
	/** Path the IdP should redirect to. Combined with the request origin at start time. */
	readonly redirectPath: string;
}

export class OAuthRegistryError extends Error {
	constructor(
		public readonly code: "DUPLICATE_PROVIDER" | "UNKNOWN_PROVIDER",
		message: string,
	) {
		super(message);
		this.name = "OAuthRegistryError";
	}
}

const registry = new Map<string, OAuthProviderDefinition>();

function key(domain: IntegrationDomain, providerId: string): string {
	return `${domain}|${providerId}`;
}

export function registerOAuthProvider(def: OAuthProviderDefinition): OAuthProviderDefinition {
	const k = key(def.domain, def.id);
	if (registry.has(k)) {
		throw new OAuthRegistryError(
			"DUPLICATE_PROVIDER",
			`OAuth provider ${def.id} already registered for domain ${def.domain}`,
		);
	}
	registry.set(k, def);
	return def;
}

export function getOAuthProvider(
	domain: IntegrationDomain,
	providerId: string,
): OAuthProviderDefinition | undefined {
	return registry.get(key(domain, providerId));
}

export function listOAuthProviders(domain: IntegrationDomain): readonly OAuthProviderDefinition[] {
	const out: OAuthProviderDefinition[] = [];
	for (const [k, v] of registry) {
		if (k.startsWith(`${domain}|`)) out.push(v);
	}
	return out;
}

export function _resetOAuthRegistryForTests(): void {
	registry.clear();
}

src/integrations/oauth/state.ts.source:
/**
 * OAuth state-token issuance and verification.
 *
 * The browser hands the IdP a `state` parameter at the start of an
 * authorization-code flow; the IdP returns it verbatim on callback.
 * The state must therefore:
 *
 *   1. be unforgeable by the IdP (so a malicious IdP can't replay
 *      a captured state to land in a different account's context);
 *   2. carry enough server-side context to resume the flow without
 *      cookies (needed for Cloudflare Workers, where setting a
 *      cookie on the redirect-out is awkward);
 *   3. expire so a captured state can't be replayed indefinitely;
 *   4. be single-use so an attacker can't replay a leaked state
 *      across multiple browser sessions.
 *
 * Wire format: hex(JSON envelope `{n, c, e, s}` UTF-8) where:
 *   - `n` is a 16-byte random nonce (hex);
 *   - `c` is the resume-context payload `{domain, providerId, returnTo}`;
 *   - `e` is the expiry as ms-since-epoch;
 *   - `s` is HMAC-SHA-256(rootSecret, JSON.stringify({n,c,e})) as hex.
 *
 * Hex (rather than base64url) keeps the encode/decode path symmetric,
 * trivially URL-safe with no padding, and easy to mutation-test —
 * the trade-off is roughly 1.6× the wire length of base64url, which
 * is well within typical URL-length budgets for an OAuth state.
 *
 * Defensive parsing is intentionally minimal: we hex-decode, JSON-parse,
 * canonical-serialize the inner under the schema we expect, and check
 * the signature. Any structural difference between the attacker's
 * forgery and a real envelope produces a different signature, so a
 * shape mismatch is automatically caught as INVALID_SIGNATURE rather
 * than via a separate per-field type guard. If `JSON.parse` itself
 * throws, or any property access in the canonicalisation throws, we
 * report INVALID_FORMAT.
 *
 * Replay protection requires a nonce store; this module returns the
 * nonce so the caller can register it with the rate-limit /
 * idempotency table and reject re-uses on callback.
 */

import { bytesToHex, constantTimeEqual } from "../../crypto-primitives.js";

export interface OAuthStateContext {
	readonly domain: string;
	readonly providerId: string;
	readonly returnTo: string;
}

export interface IssuedOAuthState {
	readonly token: string;
	readonly nonce: string;
	readonly expiresAt: number;
}

export interface VerifyOAuthStateOk {
	readonly ok: true;
	readonly nonce: string;
	readonly context: OAuthStateContext;
	readonly expiresAt: number;
}

export type VerifyOAuthStateErrorCode =
	| "INVALID_FORMAT"
	| "INVALID_SIGNATURE"
	| "EXPIRED"
	| "CONTEXT_MISMATCH";

export interface VerifyOAuthStateErr {
	readonly ok: false;
	readonly code: VerifyOAuthStateErrorCode;
}

export type VerifyOAuthStateResult = VerifyOAuthStateOk | VerifyOAuthStateErr;

export interface IssueOAuthStateArgs {
	readonly context: OAuthStateContext;
	readonly rootSecret: string;
	readonly nowMs: number;
	readonly ttlMs?: number;
}

export interface VerifyOAuthStateArgs {
	readonly token: string;
	readonly rootSecret: string;
	readonly nowMs: number;
	readonly expectedContext?: Partial<OAuthStateContext>;
}

export const DEFAULT_OAUTH_STATE_TTL_MS = 600_000;
const NONCE_BYTES = 16;
const textEncoder = new TextEncoder();

export function parseHexBytes(hex: string): Uint8Array | null {
	if (!/^[0-9a-fA-F]+$/.test(hex)) return null;
	if (hex.length % 2 !== 0) return null;
	const out = new Uint8Array(hex.length / 2);
	// Stryker disable next-line EqualityOperator: i <= hex.length is observably equivalent — Uint8Array silently drops out-of-bounds writes, returned bytes are identical.
	for (let i = 0; i < hex.length; i += 2) {
		out[i / 2] = Number.parseInt(hex.slice(i, i + 2), 16);
	}
	return out;
}

interface InnerEnvelope {
	readonly n: string;
	readonly c: OAuthStateContext;
	readonly e: number;
}

export function serializeInnerEnvelope(inner: InnerEnvelope): string {
	return JSON.stringify({ n: inner.n, c: inner.c, e: inner.e });
}

async function hmacSha256Hex(secret: string, message: string): Promise<string> {
	const keyBytes = textEncoder.encode(secret);
	const keyBuf = new ArrayBuffer(keyBytes.byteLength);
	new Uint8Array(keyBuf).set(keyBytes);
	const key = await crypto.subtle.importKey(
		"raw",
		keyBuf,
		{ name: "HMAC", hash: "SHA-256" },
		// Stryker disable next-line BooleanLiteral: extractable does not affect the sign output we test.
		false,
		// Stryker disable next-line StringLiteral: any non-empty usage that includes "sign" works; the operation is what we test.
		["sign"],
	);
	const msgBytes = textEncoder.encode(message);
	const msgBuf = new ArrayBuffer(msgBytes.byteLength);
	new Uint8Array(msgBuf).set(msgBytes);
	const sig = new Uint8Array(
		await crypto.subtle.sign({ name: "HMAC", hash: "SHA-256" }, key, msgBuf),
	);
	return bytesToHex(sig);
}

export async function issueOAuthState(args: IssueOAuthStateArgs): Promise<IssuedOAuthState> {
	const nonce = bytesToHex(crypto.getRandomValues(new Uint8Array(NONCE_BYTES)));
	const ttl = args.ttlMs ?? DEFAULT_OAUTH_STATE_TTL_MS;
	const expiresAt = args.nowMs + ttl;
	const inner: InnerEnvelope = { n: nonce, c: args.context, e: expiresAt };
	const sig = await hmacSha256Hex(args.rootSecret, serializeInnerEnvelope(inner));
	const envelope = JSON.stringify({ ...inner, s: sig });
	const token = bytesToHex(textEncoder.encode(envelope));
	return { token, nonce, expiresAt };
}

interface ParsedEnvelope {
	readonly inner: InnerEnvelope;
	readonly signatureHex: string;
}

/**
 * Decode a token to its inner envelope + signature, or `null` if the
 * token is not a hex-encoded envelope our issuer would have produced.
 *
 * The structural type-coercion below is "trusting": if a forger
 * supplied unexpected types, the canonical re-serialisation under
 * {@link serializeInnerEnvelope} will not round-trip, the recomputed
 * signature won't match, and {@link verifyOAuthState} returns
 * `INVALID_SIGNATURE`. So we only need to guard against shapes that
 * would *throw* during canonicalisation (null, missing nested
 * `.c`, etc.) — every other shape difference is caught by the HMAC
 * check downstream.
 */
export function parseStateEnvelope(token: string): ParsedEnvelope | null {
	const decoded = parseHexBytes(token);
	// Stryker disable next-line ConditionalExpression: equivalent — TextDecoder.decode(null) below throws and the catch returns null with the same outcome.
	if (decoded === null) return null;
	try {
		const parsed = JSON.parse(new TextDecoder().decode(decoded)) as {
			n?: unknown;
			c?: { domain?: unknown; providerId?: unknown; returnTo?: unknown };
			e?: unknown;
			s?: unknown;
		};
		const ctx = parsed.c ?? {};
		const inner: InnerEnvelope = {
			n: String(parsed.n ?? ""),
			c: {
				domain: String(ctx.domain ?? ""),
				providerId: String(ctx.providerId ?? ""),
				returnTo: String(ctx.returnTo ?? ""),
			},
			e: typeof parsed.e === "number" ? parsed.e : 0,
		};
		const signatureHex =
			typeof parsed.s === "string" && /^[0-9a-fA-F]+$/.test(parsed.s) ? parsed.s : "";
		return { inner, signatureHex };
	} catch {
		return null;
	}
}

export async function verifyOAuthState(
	args: VerifyOAuthStateArgs,
): Promise<VerifyOAuthStateResult> {
	const parsed = parseStateEnvelope(args.token);
	if (parsed === null) return { ok: false, code: "INVALID_FORMAT" };
	const lhs = parseHexBytes(parsed.signatureHex);
	if (lhs === null) return { ok: false, code: "INVALID_SIGNATURE" };
	const expectedSig = await hmacSha256Hex(args.rootSecret, serializeInnerEnvelope(parsed.inner));
	const rhs = parseHexBytes(expectedSig);
	if (rhs === null) return { ok: false, code: "INVALID_SIGNATURE" };
	if (!constantTimeEqual(lhs, rhs)) {
		return { ok: false, code: "INVALID_SIGNATURE" };
	}
	if (args.nowMs > parsed.inner.e) {
		return { ok: false, code: "EXPIRED" };
	}
	const exp = args.expectedContext;
	if (exp !== undefined) {
		if (exp.domain !== undefined && exp.domain !== parsed.inner.c.domain) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
		if (exp.providerId !== undefined && exp.providerId !== parsed.inner.c.providerId) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
		if (exp.returnTo !== undefined && exp.returnTo !== parsed.inner.c.returnTo) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
	}
	return {
		ok: true,
		nonce: parsed.inner.n,
		context: parsed.inner.c,
		expiresAt: parsed.inner.e,
	};
}

