src/integrations/providers/listmonk.ts.source:
/**
 * Listmonk newsletter provider — push-button registration for the
 * newsletter domain.
 *
 * verify() runs a HEAD against `${baseUrl}/api/health` with HTTP basic
 * authentication built from the connection's apiUser/apiKey. The
 * response status drives a typed error code so the admin UI can
 * localise the connect failure without leaking upstream payloads.
 *
 *   200          → connected
 *   401 / 403    → INTEGRATION_AUTH_REJECTED
 *   404          → INTEGRATION_NOT_FOUND
 *   429          → INTEGRATION_RATE_LIMITED
 *   any other 4xx/5xx → INTEGRATION_VERIFY_FAILED
 *
 * Network/abort failures bubble through the connect-flow sanitiser
 * (TypeError → NETWORK_ERROR, AbortError → TIMEOUT) and never reach
 * the database with raw upstream payload bytes.
 */

import { z } from "zod";

import type { IntegrationErrorCode } from "../../integration-error-sanitizer.js";
import { registerNewsletter } from "../domains.js";
import type { RegisteredProvider } from "../registry.js";

export const LISTMONK_FIELDS = z.object({
	baseUrl: z.string().url(),
	apiUser: z.string().min(1),
	apiKey: z.string().min(1),
});

export type ListmonkFields = z.infer<typeof LISTMONK_FIELDS>;

const HEALTH_PATH = "/api/health";

export class ListmonkVerifyError extends Error {
	constructor(public readonly code: IntegrationErrorCode) {
		super(code);
		this.name = "ListmonkVerifyError";
	}
}

export interface ListmonkVerifyDeps {
	readonly fetch?: typeof fetch;
}

export function buildListmonkHealthUrl(baseUrl: string): string {
	return new URL(HEALTH_PATH, baseUrl).toString();
}

export function buildListmonkAuthHeader(apiUser: string, apiKey: string): string {
	return `Basic ${btoa(`${apiUser}:${apiKey}`)}`;
}

export async function verifyListmonk(
	fields: ListmonkFields,
	ctx: { signal: AbortSignal },
	deps: ListmonkVerifyDeps = {},
): Promise<void> {
	const fetchImpl = deps.fetch ?? fetch;
	const url = buildListmonkHealthUrl(fields.baseUrl);
	const auth = buildListmonkAuthHeader(fields.apiUser, fields.apiKey);
	const res = await fetchImpl(url, {
		method: "HEAD",
		headers: { Authorization: auth },
		signal: ctx.signal,
	});
	if (res.status === 401 || res.status === 403) {
		throw new ListmonkVerifyError("INTEGRATION_AUTH_REJECTED");
	}
	if (res.status === 404) {
		throw new ListmonkVerifyError("INTEGRATION_NOT_FOUND");
	}
	if (res.status === 429) {
		throw new ListmonkVerifyError("INTEGRATION_RATE_LIMITED");
	}
	if (!res.ok) {
		throw new ListmonkVerifyError("INTEGRATION_VERIFY_FAILED");
	}
}

export function registerListmonk(): RegisteredProvider<ListmonkFields> {
	return registerNewsletter<ListmonkFields>({
		id: "listmonk",
		label: "Listmonk",
		fields: LISTMONK_FIELDS,
		verify: verifyListmonk,
		defaultErrorCode: "INTEGRATION_VERIFY_FAILED",
	});
}

src/integrations/resolvers/analytics-sta.source:
/**
 * Resolve a server-to-server analytics-stats configuration.
 *
 * Distinct from `resolveAnalyticsSnippet` (which emits a client-side
 * `<script>` tag for tracking) — this resolver answers "where do I
 * pull aggregated stats from for the AnalyticsPanel?".
 *
 * Today the only supported source is Plausible's `/api/v1/stats`
 * endpoint, surfaced via the Phase 4 `analytics/plausible` provider
 * registered against `connected_integrations`. There is no env-var or
 * static-config fallback — admin connection is the only path. This
 * matches reality: a Plausible Stats API key is a sensitive
 * credential that should always go through the Phase 2 envelope, not
 * sit in plaintext in `app.toml`.
 *
 * The resolver is pure: it consumes a snapshot of the registry data
 * and emits a tagged `ResolvedAnalyticsStats`. Same architectural
 * shape as `resolveCdnPurge` and `resolveNewsletter` so the runtime
 * call sites compose identically.
 */

export type ResolvedAnalyticsStats =
	| {
			readonly kind: "plausible";
			readonly host: string;
			readonly siteId: string;
			readonly apiKey: string;
	  }
	| { readonly kind: "none" };

export interface ResolveAnalyticsStatsInput {
	readonly registry?: {
		readonly host: string;
		readonly siteId: string;
		readonly apiKey: string;
	} | null;
}

function nonEmpty(v: string | undefined | null): v is string {
	return typeof v === "string" && v.length > 0;
}

export function resolveAnalyticsStats(input: ResolveAnalyticsStatsInput): ResolvedAnalyticsStats {
	const registry = input.registry;
	if (!registry) return { kind: "none" };
	if (!nonEmpty(registry.host)) return { kind: "none" };
	if (!nonEmpty(registry.siteId)) return { kind: "none" };
	if (!nonEmpty(registry.apiKey)) return { kind: "none" };
	return {
		kind: "plausible",
		host: registry.host,
		siteId: registry.siteId,
		apiKey: registry.apiKey,
	};
}

src/integrations/webhooks/inbound.ts.source:
/**
 * Inbound webhook signature verifier.
 *
 * Providers sign webhook bodies with HMAC over the raw bytes; the
 * receiver recomputes the HMAC with the shared secret and compares
 * constant-time. GitHub uses `X-Hub-Signature-256: sha256=<hex>`.
 *
 * The body MUST be the raw bytes the upstream signed. Decoding to
 * JSON or trimming whitespace breaks the HMAC, so receivers should
 * `await req.bytes()` once, verify, then parse.
 */

import { constantTimeEqual } from "../../crypto-primitives.js";

export type InboundWebhookAlgorithm = "hmac-sha256" | "hmac-sha512";

export interface VerifyInboundWebhookArgs {
	readonly algo: InboundWebhookAlgorithm;
	/** The raw header value as received (e.g. `"sha256=abcdef…"`). */
	readonly header: string;
	readonly body: Uint8Array;
	readonly secret: string;
}

/**
 * WebCrypto hash-name for the given algorithm. Pure.
 */
export function algorithmHashName(algo: InboundWebhookAlgorithm): "SHA-256" | "SHA-512" {
	if (algo === "hmac-sha256") return "SHA-256";
	return "SHA-512";
}

/**
 * Algorithm prefix that GitHub-style headers use (`sha256=` / `sha512=`).
 * Pure.
 */
export function algorithmHeaderPrefix(algo: InboundWebhookAlgorithm): string {
	if (algo === "hmac-sha256") return "sha256=";
	return "sha512=";
}

/**
 * Strip the algorithm prefix from a header value if present, else
 * return the input verbatim. Pure.
 */
export function extractWebhookHexSignature(header: string, algo: InboundWebhookAlgorithm): string {
	const prefix = algorithmHeaderPrefix(algo);
	if (header.startsWith(prefix)) {
		return header.slice(prefix.length);
	}
	return header;
}

/**
 * Parse a hex string into bytes. Returns `null` on empty input, odd
 * length, or any non-hex character. Pure.
 */
export function parseWebhookHexBytes(hex: string): Uint8Array | null {
	if (!/^[0-9a-fA-F]+$/.test(hex)) return null;
	if (hex.length % 2 !== 0) return null;
	const out = new Uint8Array(hex.length / 2);
	for (let i = 0; i < hex.length; i += 2) {
		out[i / 2] = Number.parseInt(hex.slice(i, i + 2), 16);
	}
	return out;
}

export async function computeWebhookHmacBytes(
	algo: InboundWebhookAlgorithm,
	secret: string,
	body: Uint8Array,
): Promise<Uint8Array> {
	const hash = algorithmHashName(algo);
	const keyBytes = new TextEncoder().encode(secret);
	const keyBuf = new ArrayBuffer(keyBytes.byteLength);
	new Uint8Array(keyBuf).set(keyBytes);
	const key = await crypto.subtle.importKey(
		"raw",
		keyBuf,
		{ name: "HMAC", hash: { name: hash } },
		false,
		["sign"],
	);
	const bodyBuf = new ArrayBuffer(body.byteLength);
	new Uint8Array(bodyBuf).set(body);
	const sig = await crypto.subtle.sign({ name: "HMAC", hash: { name: hash } }, key, bodyBuf);
	return new Uint8Array(sig);
}

export async function verifyInboundWebhookSignature(
	args: VerifyInboundWebhookArgs,
): Promise<boolean> {
	if (args.secret.length === 0) return false;
	const hex = extractWebhookHexSignature(args.header, args.algo);
	const supplied = parseWebhookHexBytes(hex);
	if (supplied === null) return false;
	const expected = await computeWebhookHmacBytes(args.algo, args.secret, args.body);
	return constantTimeEqual(supplied, expected);
}

/**
 * Convenience wrapper for GitHub-style `X-Hub-Signature-256` headers.
 */
export async function verifyGithubWebhookSignature(args: {
	readonly header: string;
	readonly body: Uint8Array;
	readonly secret: string;
}): Promise<boolean> {
	return verifyInboundWebhookSignature({ ...args, algo: "hmac-sha256" });
}

src/local-image-storage.ts.source:
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const workspaceRoot = process.cwd();
const defaultImageRoot = path.join(
	tmpdir(),
	"astropress",
	"local-images",
	path.basename(workspaceRoot),
);

export function getLocalImageRoot() {
	return (
		process.env.ASTROPRESS_LOCAL_IMAGE_ROOT?.trim() ||
		process.env.LOCAL_IMAGE_ROOT?.trim() ||
		defaultImageRoot
	);
}

export function getLocalUploadsDir() {
	return path.join(getLocalImageRoot(), "uploads");
}

export function ensureLocalUploadsDir() {
	mkdirSync(getLocalUploadsDir(), { recursive: true });
}

export function guessImageMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".svg")) return "image/svg+xml";
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	if (lower.endsWith(".avif")) return "image/avif";
	return "image/jpeg";
}

export function resolveLocalImageDiskPath(publicPath: string) {
	if (!publicPath.startsWith("/images/")) {
		throw new Error(`Expected image path under /images/: ${publicPath}`);
	}

	const relativePath = publicPath.slice("/images/".length);
	return path.join(getLocalImageRoot(), relativePath);
}

export function readLocalImageAsset(publicPath: string) {
	const diskPath = resolveLocalImageDiskPath(publicPath);
	if (!existsSync(diskPath)) {
		return { ok: false as const, error: "Image not found." };
	}

	const bytes = readFileSync(diskPath);
	const arrayBuffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);

	return {
		ok: true as const,
		asset: {
			diskPath,
			bytes: arrayBuffer,
			mimeType: guessImageMimeType(diskPath),
		},
	};
}

/**
 * Generate responsive srcset variants (400, 800, 1200px WebP) for an image using Sharp.
 *
 * The `storeVariant` callback handles persistence — it receives a filename and bytes and
 * returns the public URL string, or null when storage fails. This abstraction lets the
 * caller use local disk, R2, or any other backend without this function knowing the
 * difference.
 *
 * Uses `withoutEnlargement: true` so images narrower than a breakpoint skip that variant.
 * Returns null when Sharp is unavailable (e.g. Cloudflare Workers) or on error.
 */
export async function generateSrcset(
	bytes: Uint8Array,
	originalPublicPath: string,
	storeVariant: (filename: string, variantBytes: Uint8Array) => Promise<string | null>,
): Promise<string | null> {
	try {
		const sharp = (await import("sharp")).default;
		const widths = [400, 800, 1200] as const;
		const parts: string[] = [];

		const dot = originalPublicPath.lastIndexOf(".");
		const noExt = dot > 0 ? originalPublicPath.slice(0, dot) : originalPublicPath;
		const basename = noExt.replace(/^\/images\/uploads\//, "").replace(/^\/images\//, "");

		for (const w of widths) {
			const variantBuffer = await sharp(Buffer.from(bytes))
				.resize({ width: w, withoutEnlargement: true })
				.webp()
				.toBuffer();
			const variantFilename = `${basename}-${w}w.webp`;
			const variantPath = await storeVariant(variantFilename, new Uint8Array(variantBuffer));
			if (variantPath) {
				parts.push(`${variantPath} ${w}w`);
			}
		}

		return parts.length > 0 ? parts.join(", ") : null;
	} catch {
		return null;
	}
}

