import { type AdminLabelKey, type AdminLocale, adminLabels } from "./admin-labels";
import { defaultAdminUiConfig } from "./admin-ui-defaults";
import { LABEL_TRANSLATION_KEYS, NAVIGATION_TRANSLATION_KEYS } from "./admin-ui-translation-keys";
import { peekCmsConfig } from "./config";

export type { AdminLabelKey, AdminLocale } from "./admin-labels";
export { adminLabels } from "./admin-labels";

// ---------------------------------------------------------------------------
// Multi-locale admin label resolver + admin UI config
// ---------------------------------------------------------------------------

/**
 * Resolve a localised admin UI label.
 *
 * Falls back through: `locale` -> first site locale from config -> `"en"`.
 * Unknown keys return `key` so missing translations are visible rather than blank.
 *
 * @param key    The label key (e.g. `"saveButton"`).
 * @param locale Optional BCP-47 locale tag. When omitted the first locale from
 *               `getCmsConfig().locales` is used, falling back to `"en"`.
 */
export function getAdminLabel(key: AdminLabelKey, locale?: string): string {
	const configLocale = peekCmsConfig()?.locales?.[0] ?? "en";
	const resolvedLocale = (locale ?? configLocale).split("-")[0] as AdminLocale;
	const map = adminLabels[resolvedLocale] ?? adminLabels.en;
	return (map[key] ?? adminLabels.en[key]) || key;
}

export type AstropressAdminNavKey =
	| "dashboard"
	| "contentGroup"
	| "pages"
	| "posts"
	| "authors"
	| "taxonomies"
	| "routePages"
	| "archives"
	| "users"
	| "access"
	| "media"
	| "comments"
	| "redirects"
	| "translations"
	| "seo"
	| "system"
	| "settings"
	| "services"
	| "fundraising"
	| "testimonials"
	| "cms"
	| "host"
	// Group labels
	| "groupSite"
	| "groupAudience"
	| "groupDiscoverability"
	| "groupIntegrations"
	| "groupAccess"
	| "groupOperations"
	// Site
	| "forms"
	// Content
	| "headlessCmsPanel"
	// Audience
	| "subscribers"
	| "newsletter"
	| "events"
	| "reviews"
	| "referrals"
	| "memberships"
	| "community"
	| "shop"
	| "socialSyndication"
	// Discoverability
	| "structuredData"
	| "sitemaps"
	| "mapsLocal"
	// Integrations
	| "analytics"
	| "heatmaps"
	| "abTesting"
	| "email"
	| "liveChat"
	| "imageCdn"
	| "search"
	| "cdnPurge"
	| "monitoring"
	| "apiTokens"
	| "webhooks"
	| "deployHooks"
	| "plugins"
	// Operations
	| "data"
	| "backups";

export interface AstropressResolvedAdminUiConfig {
	branding: {
		appName: string;
		productName: string;
		shellName: string;
		logoSrc: string | null;
		logoHref: string;
		logoAlt: string;
		faviconHref: string | null;
		stylesheetHref: string | null;
	};
	labels: {
		sidebarTitle: string;
		signedInAsPrefix: string;
		signOut: string;
		themeToggleDark: string;
		themeToggleLight: string;
		loginHeading: string;
		loginDescription: string;
		loginSubmit: string;
		loginEmailLabel: string;
		loginPasswordLabel: string;
		forgotPassword: string;
		invalidCredentials: string;
		rateLimited: string;
		challengeRequired: string;
		passwordResetSuccess: string;
		invitationAcceptedSuccess: string;
		acceptInvitationHeading: string;
		acceptInvitationDescription: string;
		acceptInvitationSubmit: string;
		resetPasswordRequestHeading: string;
		resetPasswordRequestDescription: string;
		resetPasswordTokenHeading: string;
		resetPasswordTokenDescription: string;
		resetPasswordRequestSubmit: string;
		resetPasswordTokenSubmit: string;
		backToLogin: string;
		changeLanguage: string;
	};
	navigation: Record<AstropressAdminNavKey, string>;
}

function mergeWithDefaults() {
	const cmsConfig = peekCmsConfig();
	const admin = cmsConfig?.admin;

	return {
		branding: {
			...defaultAdminUiConfig.branding,
			...admin?.branding,
		},
		labels: {
			...defaultAdminUiConfig.labels,
			...admin?.labels,
		},
		navigation: {
			...defaultAdminUiConfig.navigation,
			...admin?.navigation,
		},
	} satisfies AstropressResolvedAdminUiConfig;
}

/**
 * Merge host-provided CMS config with Astropress defaults to produce a complete
 * admin UI configuration object ready for use in admin layout templates.
 *
 * @example
 * ```ts
 * import { resolveAstropressAdminUiConfig } from "@astropress-diy/astropress";
 *
 * const { branding, labels, navigation } = resolveAstropressAdminUiConfig();
 * console.log(branding.appName); // "Astropress" or host-overridden value
 * ```
 */
export function resolveAstropressAdminUiConfig(
	locale?: AdminLocale,
): AstropressResolvedAdminUiConfig {
	const merged = mergeWithDefaults();
	const translated = locale ? applyTranslations(merged, locale) : merged;
	return {
		branding: {
			...translated.branding,
			shellName: translated.branding.shellName || translated.branding.productName,
			logoAlt: translated.branding.logoAlt || translated.branding.productName,
			logoHref: translated.branding.logoHref || "/ap-admin",
			stylesheetHref: translated.branding.stylesheetHref || null,
		},
		labels: translated.labels,
		navigation: translated.navigation,
	};
}

function applyTranslations(
	merged: AstropressResolvedAdminUiConfig,
	locale: AdminLocale,
): AstropressResolvedAdminUiConfig {
	// Pull every value through getAdminLabel so missing keys fall back to
	// English instead of "undefined" — this is the i18n leak guard. The
	// per-property key tables live in admin-ui-translation-keys.ts so the
	// mutation surface in this file stays focused on logic rather than the
	// long list of literal key names.
	const tr = (key: AdminLabelKey, fallback: string): string =>
		getAdminLabel(key, locale) || fallback;
	const labels = { ...merged.labels } as Record<string, string>;
	for (const [outKey, labelKey] of LABEL_TRANSLATION_KEYS) {
		labels[outKey] = tr(labelKey, labels[outKey] ?? "");
	}
	const navigation = { ...merged.navigation } as Record<string, string>;
	for (const [outKey, labelKey] of NAVIGATION_TRANSLATION_KEYS) {
		navigation[outKey] = tr(labelKey, navigation[outKey] ?? "");
	}
	return {
		branding: merged.branding,
		labels: labels as AstropressResolvedAdminUiConfig["labels"],
		navigation: navigation as AstropressResolvedAdminUiConfig["navigation"],
	};
}

src/auth-emergency-revoke-ops.ts.source:
import { DatabaseSync } from "node:sqlite";
import {
	recordEmergencyRevokeAuditEvent,
	revokeApiTokensInDb,
	revokeSessionsInDb,
} from "./sqlite-runtime/auth-emergency-revoke.js";

export type AuthRevokeScope = "all" | "sessions" | "tokens";

export interface AuthEmergencyRevokeInput {
	dbPath: string;
	scope: AuthRevokeScope;
	userEmail?: string;
}

export interface AuthEmergencyRevokeReport {
	dbPath: string;
	scope: AuthRevokeScope;
	userEmail: string | null;
	sessionsRevoked: number;
	tokensRevoked: number;
}

export function runAuthEmergencyRevokeForCli(
	input: AuthEmergencyRevokeInput,
): AuthEmergencyRevokeReport {
	const { dbPath, scope, userEmail } = input;
	const db = new DatabaseSync(dbPath);

	try {
		let sessionsRevoked = 0;
		let tokensRevoked = 0;

		if (scope === "all" || scope === "sessions") {
			sessionsRevoked = revokeSessionsInDb(db, userEmail);
		}

		if (scope === "all" || scope === "tokens") {
			tokensRevoked = revokeApiTokensInDb(db);
		}

		recordEmergencyRevokeAuditEvent(db, scope, userEmail ?? null, sessionsRevoked, tokensRevoked);

		return {
			dbPath,
			scope,
			userEmail: userEmail ?? null,
			sessionsRevoked,
			tokensRevoked,
		};
	} finally {
		db.close();
	}
}

src/build-time-content-loader.ts.source:
import type {
	AstropressPlatformAdapter,
	ContentStoreRecord,
	ReadableContentKind,
} from "./platform-contracts";

export interface AstropressBuildTimeLoaderOptions {
	/** Locale to filter content by. Defaults to all locales. */
	locale?: string;
}

/**
 * A lazy loader that fetches a collection of records from the provider at
 * build time and returns them for use in Astro content collections.
 */
export interface AstropressContentLoader {
	/**
	 * Fetch all records of this kind from the provider.
	 * By default, only "published" records are returned.
	 */
	load(): Promise<ContentStoreRecord[]>;
	/** The content kind this loader targets. */
	readonly kind: ReadableContentKind;
}

/**
 * Create build-time content collection loaders for a given provider adapter.
 *
 * Each loader calls ContentStore.list with status "published" so that draft
 * content is never included in the static production build.
 *
 * @example
 * ```ts
 * // astro.config.mjs (public site project)
 * import { defineCollection } from "astro:content";
 * import { createAstropressBuildTimeLoader } from "@astropress-diy/astropress";
 * import { adapter } from "./src/astropress/local-runtime-modules";
 *
 * const loader = createAstropressBuildTimeLoader(adapter);
 *
 * export const collections = {
 *   posts: defineCollection({ loader: loader.posts() }),
 *   pages: defineCollection({ loader: loader.pages() }),
 * };
 * ```
 */
export function createAstropressBuildTimeLoader(
	provider: AstropressPlatformAdapter,
	options: AstropressBuildTimeLoaderOptions = {},
): {
	posts(): AstropressContentLoader;
	pages(): AstropressContentLoader;
} {
	function makeLoader(kind: "post" | "page"): AstropressContentLoader {
		return {
			kind,
			async load() {
				const records = await provider.content.list(kind, {
					status: "published",
					locale: options.locale,
				});
				return records;
			},
		};
	}

	return {
		posts: () => makeLoader("post"),
		pages: () => makeLoader("page"),
	};
}

src/import/wix-apply.ts.source:
import { stat } from "node:fs/promises";
import path from "node:path";
import { createAstropressSqliteAdminRuntime } from "../sqlite-admin-runtime";
import { createDefaultAstropressSqliteSeedToolkit } from "../sqlite-bootstrap";

export type WixParsedAuthor = { login: string; displayName: string };
export type WixParsedTerm = {
	kind: "category" | "tag";
	slug: string;
	name: string;
};
export type WixParsedMediaAsset = {
	id: string;
	slug: string;
	title: string;
	sourceUrl: string;
	filename: string;
	mimeType: string;
};
export type WixParsedContentRecord = {
	id: string;
	kind: "post";
	slug: string;
	title: string;
	body: string;
	excerpt: string | undefined;
	status: "draft" | "published";
	legacyUrl: string;
	publishedAt: string | undefined;
	authorLogins: string[];
	categorySlugs: string[];
	tagSlugs: string[];
};

export type WixParsedBundle = {
	authors: WixParsedAuthor[];
	terms: WixParsedTerm[];
	contentRecords: WixParsedContentRecord[];
	mediaAssets: WixParsedMediaAsset[];
	warnings: string[];
};

const WIX_IMPORT_ACTOR = {
	email: "wix-import@astropress.local",
	role: "admin" as const,
	name: "Wix Import",
};

export async function fileSizeOrNull(targetPath: string): Promise<number | null> {
	try {
		return (await stat(targetPath)).size;
	} catch {
		return null;
	}
}

export function resolveAdminDbPath(workspaceRoot: string, adminDbPath?: string): string {
	if (adminDbPath)
		return path.isAbsolute(adminDbPath) ? adminDbPath : path.join(workspaceRoot, adminDbPath);
	return createDefaultAstropressSqliteSeedToolkit().getDefaultAdminDbPath(workspaceRoot);
}

type WixAdminDb = ReturnType<
	ReturnType<typeof createDefaultAstropressSqliteSeedToolkit>["openSeedDatabase"]
>;
type WixAdminRuntime = ReturnType<typeof createAstropressSqliteAdminRuntime>;

function importWixTerms(
	db: WixAdminDb,
	bundle: WixParsedBundle,
): {
	categoryIdsBySlug: Map<string, number>;
	tagIdsBySlug: Map<string, number>;
} {
	const upsertCategory = db.prepare(`
    INSERT INTO categories (slug, name, description, deleted_at) VALUES (?, ?, ?, NULL)
    ON CONFLICT(slug) DO UPDATE SET name = excluded.name, deleted_at = NULL, updated_at = CURRENT_TIMESTAMP
  `);
	const upsertTag = db.prepare(`
    INSERT INTO tags (slug, name, description, deleted_at) VALUES (?, ?, ?, NULL)
    ON CONFLICT(slug) DO UPDATE SET name = excluded.name, deleted_at = NULL, updated_at = CURRENT_TIMESTAMP
  `);
	const selectCategoryId = db.prepare("SELECT id FROM categories WHERE slug = ? LIMIT 1");
	const selectTagId = db.prepare("SELECT id FROM tags WHERE slug = ? LIMIT 1");
	const categoryIdsBySlug = new Map<string, number>();
	const tagIdsBySlug = new Map<string, number>();
	for (const term of bundle.terms) {
		if (term.kind === "category") {
			upsertCategory.run(term.slug, term.name, null);
			const row = selectCategoryId.get(term.slug) as { id: number } | undefined;
			if (row) categoryIdsBySlug.set(term.slug, row.id);
		} else {
			upsertTag.run(term.slug, term.name, null);
			const row = selectTagId.get(term.slug) as { id: number } | undefined;
			if (row) tagIdsBySlug.set(term.slug, row.id);
		}
	}
	return { categoryIdsBySlug, tagIdsBySlug };
}

function importWixContentRecords(
	db: WixAdminDb,
	runtime: WixAdminRuntime,
	bundle: WixParsedBundle,
	authorIdsByLogin: Map<string, number>,
	categoryIdsBySlug: Map<string, number>,
	tagIdsBySlug: Map<string, number>,
) {
	for (const record of bundle.contentRecords) {
		const authorIds = record.authorLogins
			.map((l) => authorIdsByLogin.get(l))
			.filter((v): v is number => typeof v === "number");
		const categoryIds = record.categorySlugs
			.map((s) => categoryIdsBySlug.get(s))
			.filter((v): v is number => typeof v === "number");
		const tagIds = record.tagSlugs
			.map((s) => tagIdsBySlug.get(s))
			.filter((v): v is number => typeof v === "number");
		const revisionInput = {
			title: record.title,
			status: record.status,
			body: record.body,
			seoTitle: record.title,
			metaDescription: record.excerpt ?? record.title,
			excerpt: record.excerpt,
			authorIds,
			categoryIds,
			tagIds,
			revisionNote: `Wix import ${record.id}`,
		};

		const existing = runtime.sqliteAdminStore.content.getContentState(record.slug);
		if (existing) {
			const saved = runtime.sqliteAdminStore.content.saveContentState(
				record.slug,
				revisionInput,
				WIX_IMPORT_ACTOR,
			);
			if (!saved.ok) throw new Error(saved.error);
			db.prepare(
				"UPDATE content_entries SET kind = ?, legacy_url = ?, summary = ? WHERE slug = ?",
			).run(record.kind, record.legacyUrl, record.excerpt ?? "", record.slug);
		} else {
			const created = runtime.sqliteAdminStore.content.createContentRecord(
				{
					title: record.title,
					slug: record.slug,
					legacyUrl: record.legacyUrl,
					body: record.body,
					summary: record.excerpt ?? "",
					status: record.status,
					seoTitle: record.title,
					metaDescription: record.excerpt ?? record.title,
					excerpt: record.excerpt,
				},
				WIX_IMPORT_ACTOR,
			);
			if (!created.ok) throw new Error(created.error);
			const saved = runtime.sqliteAdminStore.content.saveContentState(
				record.slug,
				revisionInput,
				WIX_IMPORT_ACTOR,
			);
			if (!saved.ok) throw new Error(saved.error);
			db.prepare(
				"UPDATE content_entries SET kind = ?, legacy_url = ?, summary = ? WHERE slug = ?",
			).run(record.kind, record.legacyUrl, record.excerpt ?? "", record.slug);
		}
	}
}

async function importWixMedia(
	db: WixAdminDb,
	bundle: WixParsedBundle,
	artifactDir: string | undefined,
) {
	const upsertMedia = db.prepare(`
    INSERT INTO media_assets (id, source_url, local_path, mime_type, file_size, alt_text, title, uploaded_by, deleted_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL)
    ON CONFLICT(id) DO UPDATE SET
      source_url = excluded.source_url, local_path = excluded.local_path,
      mime_type = excluded.mime_type, file_size = excluded.file_size,
      title = excluded.title, uploaded_by = excluded.uploaded_by, deleted_at = NULL
  `);
	for (const asset of bundle.mediaAssets) {
		const downloadedPath = artifactDir
			? path.join(artifactDir, "downloads", path.basename(asset.filename))
			: undefined;
		const hasFile = downloadedPath ? (await fileSizeOrNull(downloadedPath)) !== null : false;
		const localPath = hasFile ? (downloadedPath as string) : asset.sourceUrl;
		upsertMedia.run(
			asset.id,
			asset.sourceUrl,
			localPath,
			asset.mimeType,
			hasFile ? await fileSizeOrNull(downloadedPath as string) : null,
			"",
			asset.title,
			WIX_IMPORT_ACTOR.email,
		);
	}
}

export async function applyWixImportToLocalRuntime(input: {
	bundle: WixParsedBundle;
	artifactDir?: string;
	workspaceRoot: string;
	adminDbPath?: string;
}): Promise<{
	appliedRecords: number;
	appliedMedia: number;
	appliedAuthors: number;
	adminDbPath: string;
}> {
	const seedToolkit = createDefaultAstropressSqliteSeedToolkit();
	const resolvedDbPath = resolveAdminDbPath(input.workspaceRoot, input.adminDbPath);
	seedToolkit.seedDatabase({
		dbPath: resolvedDbPath,
		workspaceRoot: input.workspaceRoot,
	});

	const db = seedToolkit.openSeedDatabase(resolvedDbPath);
	const runtime = createAstropressSqliteAdminRuntime({ getDatabase: () => db });

	try {
		db.exec("BEGIN");

		const upsertAuthor = db.prepare(`
      INSERT INTO authors (slug, name, bio, deleted_at) VALUES (?, ?, ?, NULL)
      ON CONFLICT(slug) DO UPDATE SET name = excluded.name, bio = excluded.bio, deleted_at = NULL, updated_at = CURRENT_TIMESTAMP
    `);
		const selectAuthorId = db.prepare("SELECT id FROM authors WHERE slug = ? LIMIT 1");
		const authorIdsByLogin = new Map<string, number>();
		for (const author of input.bundle.authors) {
			upsertAuthor.run(author.login, author.displayName, null);
			const row = selectAuthorId.get(author.login) as { id: number } | undefined;
			if (row) authorIdsByLogin.set(author.login, row.id);
		}

		const { categoryIdsBySlug, tagIdsBySlug } = importWixTerms(db, input.bundle);
		importWixContentRecords(
			db,
			runtime,
			input.bundle,
			authorIdsByLogin,
			categoryIdsBySlug,
			tagIdsBySlug,
		);
		await importWixMedia(db, input.bundle, input.artifactDir);

		db.exec("COMMIT");
		return {
			appliedRecords: input.bundle.contentRecords.length,
			appliedMedia: input.bundle.mediaAssets.length,
			appliedAuthors: input.bundle.authors.length,
			adminDbPath: resolvedDbPath,
		};
	} catch (error) {
		db.exec("ROLLBACK");
		throw error;
	} finally {
		db.close();
	}
}

