			normalizeContentStatus: (value) => (value === "draft" ? "draft" : "published"),
			findContentRecord: () => baseRecord(),
			listContentRecords: () => [baseRecord()],
			getPersistedOverride: vi.fn(),
			getContentAssignments: () => ({
				authorIds: [],
				categoryIds: [],
				tagIds: [],
			}),
