				status: "draft",
				scheduledAt: undefined,
				body: "<p>Body</p>",
				seoTitle: "SEO",
				metaDescription: "Meta",
				excerpt: undefined,
				ogTitle: undefined,
				ogDescription: undefined,
				ogImage: undefined,
				canonicalUrlOverride: undefined,
				robotsDirective: undefined,
				metadata: undefined,
