	it("netlify: returns ok:false with the status code when the hook returns 503", async () => {
		globalThis.fetch = mockFetch(503);
		const result = await triggerPublish({
			type: "netlify",
			env: { NETLIFY_BUILD_HOOK_URL: "https://example.test/h" },
