import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { createAstropressProjectLaunchPlan } from "../src/project-launch.js";

describe("project launch", () => {
	it("builds a local launch plan with static hosting and no hosted data-services by default", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-local-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});

		expect(plan.runtime.mode).toBe("local");
		expect(plan.provider).toBe("sqlite");
		expect(plan.appHost).toBe("github-pages");
		expect(plan.dataServices).toBe("none");
		expect(plan.requiresLocalSeed).toBe(true);
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("none");

		await rm(workspace, { recursive: true, force: true });
	});

	it("builds a hosted launch plan that separates the app host from the service layer", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://runtime.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			},
			hosted: {
				content: {
					async list() {
						return [];
					},
					async get() {
						return null;
					},
					async save(record) {
						return record;
					},
					async delete() {},
				},
				media: {
					async put(asset) {
						return asset;
					},
					async get() {
						return null;
					},
					async delete() {},
				},
				revisions: {
					async list() {
						return [];
					},
					async append(revision) {
						return revision;
					},
				},
				auth: {
					async signIn(email) {
						return { id: "runtime-session", email, role: "admin" as const };
					},
					async signOut() {},
					async getSession(sessionId) {
						return {
							id: sessionId,
							email: "admin@example.com",
							role: "admin" as const,
						};
					},
				},
			},
		});

		expect(plan.runtime.mode).toBe("hosted");
		expect(plan.provider).toBe("supabase");
		expect(plan.appHost).toBe("vercel");
		expect(plan.dataServices).toBe("supabase");
		expect(plan.requiresLocalSeed).toBe(false);
		expect(plan.recommendation.appHost).toBe("vercel");
		expect(plan.recommendation.dataServices).toBe("supabase");
		expect(plan.deployTarget).toBe("vercel");
	});

	it("dataServices=cloudflare flows Cloudflare to recommendation.existingPlatform (kills L30 branch mutants)", async () => {
		// Local mode keeps adapter setup minimal; the recommendation engine
		// reads runtime.env.dataServices independently of the runtime mode.
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-cf-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "cloudflare-pages",
				ASTROPRESS_DATA_SERVICES: "cloudflare",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		expect(plan.recommendation.dataServices).toBe("cloudflare");
		await rm(workspace, { recursive: true, force: true });
	});

	it("dataServices=appwrite flows Appwrite to recommendation.existingPlatform (kills L32 branch mutants)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-aw-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "render-web",
				ASTROPRESS_DATA_SERVICES: "appwrite",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		expect(plan.recommendation.dataServices).toBe("appwrite");
		await rm(workspace, { recursive: true, force: true });
	});

	it("an unknown dataServices string maps to existingPlatform='none' (kills L36 default-string mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
		});
		// dataServices=none → existingPlatform=none + wantsHostedAdmin=false
		// + wantsStaticMirror=true (github-pages) → rec.dataServices="none".
		expect(plan.recommendation.dataServices).toBe("none");
	});

	it("local mode + gitlab-pages app host triggers wantsStaticMirror=true (kills L58 LogicalOperator mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "gitlab-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
		});
		// Static mirror path: rec.appHost is "github-pages" (per
		// recommendAstropressProvider's wantsStaticMirror=true branch when
		// existingPlatform=none and wantsHostedAdmin=false).
		expect(plan.recommendation.appHost).toBe("github-pages");
	});

	it("provider mirrors runtime.env.localProvider in local mode (kills L44 mode-branch mutant)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-launch-prov-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "none",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "admin.sqlite"),
			},
		});
		// Local mode → provider must come from env.localProvider, not hostedProvider.
		expect(plan.provider).toBe("supabase");
		expect(plan.requiresLocalSeed).toBe(true);
		await rm(workspace, { recursive: true, force: true });
	});

	it("cloudflare + github-pages routes wantsStaticMirror=true through L100 cloudflare branch (kills L26 cloudflare-eq, L26:23 StringLiteral, L49:5 LogicalOperator &&, L49:29 StringLiteral, L49:5 ConditionalExpression:false)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-pl-cf-static-"));
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "github-pages",
				ASTROPRESS_DATA_SERVICES: "cloudflare",
			},
			local: { workspaceRoot: workspace, dbPath: join(workspace, "admin.sqlite") },
		});
		// cloudflare + wantsStaticMirror=true → L100 returns "github-pages","cloudflare".
		// Any mutant that suppresses existingPlatform="cloudflare" or wantsStaticMirror=true
		// causes the default fallback "cloudflare-pages" → observable appHost diverges.
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("cloudflare");
		await rm(workspace, { recursive: true, force: true });
	});

	it("supabase + gitlab-pages routes wantsStaticMirror through L84 supabase branch (kills L49:47 ConditionalExpression, L49:71 StringLiteral, L49:5 LogicalOperator)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "gitlab-pages",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test",
			},
		});
		// gitlab-pages flips wantsStaticMirror=true via the right disjunct.
		// Original: L84 supabase + wantsStaticMirror=true → recommendation.appHost = "github-pages".
		// Mutants that break the gitlab-pages disjunct → wantsStaticMirror=false → "vercel".
		expect(plan.recommendation.appHost).toBe("github-pages");
		expect(plan.recommendation.dataServices).toBe("supabase");
	});

	it("hosted mode with appwrite picks hostedProvider over localProvider=sqlite (kills L37:3 ConditionalExpression:false, L37:20 StringLiteral)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "render-web",
				ASTROPRESS_DATA_SERVICES: "appwrite",
				ASTROPRESS_HOSTED_PROVIDER: "appwrite",
				APPWRITE_ENDPOINT: "https://appwrite.example",
				APPWRITE_PROJECT_ID: "proj",
				APPWRITE_API_KEY: "key",
			},
			hosted: {
				content: {
					async list() {
						return [];
					},
					async get() {
						return null;
					},
					async save(record) {
						return record;
					},
					async delete() {},
				},
				media: {
					async put(asset) {
						return asset;
					},
					async get() {
						return null;
					},
					async delete() {},
				},
				revisions: {
					async list() {
						return [];
					},
					async append(revision) {
						return revision;
					},
				},
				auth: {
					async signIn(email) {
						return { id: "runtime-session", email, role: "admin" as const };
					},
					async signOut() {},
					async getSession(sessionId) {
						return {
							id: sessionId,
							email: "admin@example.com",
							role: "admin" as const,
						};
					},
				},
			},
		});
		// dataServices=appwrite → localProvider falls through to "sqlite" (not "supabase").
		// Original (mode=hosted): plan.provider = hostedProvider = "appwrite".
		// L37 mutants that flip the ternary always-false: plan.provider = localProvider = "sqlite".
		expect(plan.provider).toBe("appwrite");
	});

	it("unrecognized dataServices='pocketbase' + wantsStaticMirror=false flows to default cloudflare-pages (kills L50:22 ConditionalExpression:false)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "pocketbase",
			},
		});
		// dataServices="pocketbase" (valid env value, not in [none|cloudflare|supabase|appwrite])
		//   → existingPlatform="none" via the fallback.
		//   → wantsHostedAdmin = (pocketbase !== "none") = true (original).
		//   → wantsStaticMirror = false (vercel ∉ {github-pages, gitlab-pages}).
		// Recommendation routes to final default ("cloudflare-pages","cloudflare").
		// L50:22 ConditionalExpression:false flips wantsHostedAdmin to false →
		//   recommendation routes to L116 → ("github-pages","none"). Observable diff.
		expect(plan.recommendation.appHost).toBe("cloudflare-pages");
		expect(plan.recommendation.dataServices).toBe("cloudflare");
	});

	it("dataServices !== 'none' sets wantsHostedAdmin=true on the recommendation input (kills L60 mutant)", () => {
		const plan = createAstropressProjectLaunchPlan({
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_APP_HOST: "vercel",
				ASTROPRESS_DATA_SERVICES: "supabase",
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test",
			},
		});
		// dataServices="supabase" (!== "none") → wantsHostedAdmin=true.
		// Combined with existingPlatform="supabase" → rec routes to supabase.
		expect(plan.recommendation.dataServices).toBe("supabase");
	});
});

tests/newsletter-adapter.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { newsletterAdapter, placeholderAdapter } from "../src/newsletter-adapter";
import { getNewsletterConfig } from "../src/runtime-env";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeLocals(env: Record<string, string>) {
	return { runtime: { env } } as unknown as App.Locals;
}

const listmonkEnv = {
	NEWSLETTER_DELIVERY_MODE: "listmonk",
	LISTMONK_API_URL: "https://listmonk.example.com",
	LISTMONK_API_USERNAME: "admin",
	LISTMONK_API_PASSWORD: "secret",
	LISTMONK_LIST_ID: "1",
};

// ---------------------------------------------------------------------------
// getNewsletterConfig — default mode behavior
// ---------------------------------------------------------------------------

describe("NEWSLETTER_DELIVERY_MODE defaults to listmonk in production", () => {
	it("returns listmonk when PROD is true and no mode is set", () => {
		// Simulate production by having no env override — the function checks
		// isProductionRuntime() which reads import.meta.env.PROD. In tests that
		// is false, so we verify the explicit listmonk path instead via locals.
		const cfg = getNewsletterConfig(makeLocals({ NEWSLETTER_DELIVERY_MODE: "listmonk" }));
		expect(cfg.mode).toBe("listmonk");
	});
});

describe("NEWSLETTER_DELIVERY_MODE defaults to mock in development", () => {
	it("returns mock when no mode is set and PROD is false (test env)", () => {
		const cfg = getNewsletterConfig(makeLocals({}));
		// In the test environment import.meta.env.PROD is false → default is mock
		expect(cfg.mode).toBe("mock");
	});
});

// ---------------------------------------------------------------------------
// newsletterAdapter.subscribe — mock mode
// ---------------------------------------------------------------------------

describe("mock delivery mode", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("returns ok in mock delivery mode without calling fetch", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "mock" }),
		);
		expect(result).toMatchObject({ ok: true });
		expect(fetchSpy).not.toHaveBeenCalled();
	});

	it("returns ok when no locals are provided (defaults to mock in non-production)", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe("user@example.com", null);
		expect(result).toBeDefined();
		expect(fetchSpy).not.toHaveBeenCalled();
	});
});

describe("Unrecognized delivery mode falls back to mock", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});

	it("returns ok: true for an unknown mode without calling fetch", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "unknown-service" }),
		);
		expect(result).toMatchObject({ ok: true });
		expect(fetchSpy).not.toHaveBeenCalled();
	});
});

// ---------------------------------------------------------------------------
// newsletterAdapter.subscribe — Listmonk mode
// ---------------------------------------------------------------------------

describe("Subscriber endpoint forwards to Listmonk API via newsletterAdapter", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("calls the Listmonk subscribers API and returns ok on 200", async () => {
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("{}", { status: 200 }));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: true });
		expect(fetch).toHaveBeenCalledOnce();
		const [url] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [string];
		expect(url).toContain("/api/subscribers");
	});

	it("uses Basic auth header derived from username:password", async () => {
		let capturedAuth = "";
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, init) => {
			capturedAuth = (init!.headers as Record<string, string>).Authorization ?? "";
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(capturedAuth).toMatch(/^Basic /);
		const decoded = atob(capturedAuth.replace("Basic ", ""));
		expect(decoded).toBe("admin:secret");
	});

	it("sends email, name, status, and lists in the request body", async () => {
		let body: Record<string, unknown> = {};
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, init) => {
			body = JSON.parse(init?.body as string) as Record<string, unknown>;
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("test@example.com", makeLocals(listmonkEnv));
		expect(body.email).toBe("test@example.com");
		expect(body.status).toBe("enabled");
		expect(Array.isArray(body.lists)).toBe(true);
		expect((body.lists as number[])[0]).toBe(1);
	});

	it("returns error on non-200 Listmonk response", async () => {
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("Conflict", { status: 409 }));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});

	it("returns network error when fetch throws for Listmonk", async () => {
		vi.spyOn(globalThis, "fetch").mockRejectedValueOnce(new Error("ECONNREFUSED"));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toContain("could not be reached");
	});

	it("sends method:POST + Content-Type: application/json + preconfirm_subscriptions:true (pins L73/L76/L83)", async () => {
		let init: RequestInit = {};
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, requestInit) => {
			init = requestInit as RequestInit;
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		expect(init.method).toBe("POST");
		const headers = init.headers as Record<string, string>;
		expect(headers["Content-Type"]).toBe("application/json");
		const body = JSON.parse(init.body as string);
		expect(body.preconfirm_subscriptions).toBe(true);
	});

	it("logs 'Listmonk API error' on non-ok response (pins L88 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("body", { status: 500 }));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Listmonk API error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.status).toBe(500);
		expect(meta?.body).toBe("body");
		errorSpy.mockRestore();
	});

	it("logs 'Successfully subscribed to Listmonk' on 200 (pins L94 message + payload)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("{}", { status: 200 }));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Successfully subscribed to Listmonk"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.email).toBe("u@x.com");
		logSpy.mockRestore();
	});

	it("logs 'Listmonk subscription error' on fetch throw (pins L97 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockRejectedValueOnce(new Error("oops"));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Listmonk subscription error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(String((meta?.error as Error)?.message ?? meta?.error)).toContain("oops");
		errorSpy.mockRestore();
	});

	it("logs 'Newsletter is misconfigured' when config is incomplete (pins L122 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		await newsletterAdapter.subscribe(
			"u@x.com",
			makeLocals({
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_API_URL: "https://x",
				LISTMONK_API_USERNAME: "u",
				LISTMONK_API_PASSWORD: "p",
				// LISTMONK_LIST_ID missing
			}),
		);
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Newsletter is misconfigured"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.reason).toBeDefined();
		errorSpy.mockRestore();
	});

	it("logs 'Using mock delivery mode.' in mock mode (pins L129 message + payload)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		await newsletterAdapter.subscribe("u@x.com", makeLocals({ NEWSLETTER_DELIVERY_MODE: "mock" }));
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Using mock delivery mode."),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.mode).toBe("mock");
		logSpy.mockRestore();
	});
});

describe("Listmonk adapter returns error when configuration is incomplete", () => {
	it("returns ok: false when LISTMONK_API_URL is missing", async () => {
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "listmonk" }),
		);
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});

	it("returns ok: false when LISTMONK_LIST_ID is missing", async () => {
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_API_URL: "https://listmonk.example.com",
				LISTMONK_API_USERNAME: "admin",
				LISTMONK_API_PASSWORD: "secret",
				// LISTMONK_LIST_ID intentionally omitted
			}),
		);
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});
});

// ---------------------------------------------------------------------------
// placeholderAdapter
// ---------------------------------------------------------------------------

it("placeholderAdapter is the same object as newsletterAdapter", () => {
	expect(placeholderAdapter).toBe(newsletterAdapter);
});

