import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { makeDb } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

describe("cloudflare provider integration", () => {
	it("creates a D1-backed Cloudflare adapter surface", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		expect(cloudflare.capabilities.name).toBe("cloudflare");
		expect(cloudflare.capabilities.database).toBe(true);
		expect(cloudflare.capabilities.objectStorage).toBe(true);
		expect(cloudflare.capabilities.staticPublishing).toBe(true);
		expect(cloudflare.capabilities.hostedAdmin).toBe(true);
		expect(cloudflare.capabilities.previewEnvironments).toBe(true);
		expect(cloudflare.capabilities.serverRuntime).toBe(true);
		expect(cloudflare.capabilities.gitSync).toBe(true);

		const user = await cloudflare.auth.signIn("admin@example.com", "password");
		expect(user?.isAdmin).toBe(true);
		expect(user?.id).toHaveLength(36);
		const storedSession = db.prepare("SELECT id FROM admin_sessions LIMIT 1").get() as {
			id: string;
		};
		expect(storedSession.id).not.toBe(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(await cloudflare.content.get("cloudflare-post")).toMatchObject({
			slug: "cloudflare-post",
			kind: "post",
			title: "Cloudflare post",
		});
		expect(await cloudflare.media.get("cloudflare-media-1")).toMatchObject({
			id: "cloudflare-media-1",
			mimeType: "image/png",
		});
		expect(await cloudflare.revisions.list("cloudflare-post")).toMatchObject([
			{
				id: "revision-cloudflare-1",
				recordId: "cloudflare-post",
			},
		]);
		await cloudflare.auth.signOut(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toBeNull();

		db.close();
	});

	it("persists writable records through the D1-backed Cloudflare adapter", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		const savedPost = await cloudflare.content.save({
			id: "cloudflare-write-post",
			kind: "post",
			slug: "cloudflare-write-post",
			status: "published",
			title: "Cloudflare write post",
			body: "<p>Writable Cloudflare body</p>",
			metadata: {
				metaDescription: "Writable Cloudflare record",
				seoTitle: "Cloudflare write post",
				legacyUrl: "/cloudflare-write-post",
			},
		});
		expect(savedPost.slug).toBe("cloudflare-write-post");
		expect(await cloudflare.content.get("cloudflare-write-post")).toMatchObject({
			slug: "cloudflare-write-post",
			kind: "post",
			title: "Cloudflare write post",
		});

		const translation = await cloudflare.content.save({
			id: "/es/cloudflare-write-post",
			kind: "translation",
			slug: "/es/cloudflare-write-post",
			status: "draft",
			metadata: {
				state: "translated",
			},
		});
		expect(translation.metadata).toMatchObject({
			state: "translated",
		});

		const redirect = await cloudflare.content.save({
			id: "/legacy-cloudflare-write-post",
			kind: "redirect",
			slug: "/legacy-cloudflare-write-post",
			status: "published",
			metadata: {
				targetPath: "/cloudflare-write-post",
				statusCode: 301,
			},
		});
		expect(redirect.metadata).toMatchObject({
			targetPath: "/cloudflare-write-post",
			statusCode: 301,
		});

		const settings = await cloudflare.content.save({
			id: "site-settings",
			kind: "settings",
			slug: "site-settings",
			status: "published",
			metadata: {
				siteTitle: "Cloudflare Writable Site",
			},
		});
		expect(settings.title).toBe("Cloudflare Writable Site");

		await cloudflare.media.put({
			id: "cloudflare-upload",
			filename: "cloudflare-upload.png",
			mimeType: "image/png",
			publicUrl: "https://cdn.example.com/cloudflare-upload.png",
			metadata: {
				altText: "Cloudflare upload",
				title: "cloudflare-upload.png",
			},
		});
		expect(await cloudflare.media.get("cloudflare-upload")).toMatchObject({
			id: "cloudflare-upload",
			mimeType: "image/png",
		});

		await cloudflare.revisions.append({
			id: "cloudflare-write-revision",
			recordId: "cloudflare-write-post",
			createdAt: "2026-01-01T00:00:00.000Z",
			actorId: "admin@example.com",
			summary: "Cloudflare write revision",
			snapshot: {
				title: "Cloudflare write post",
				status: "published",
				body: "<p>Writable Cloudflare body</p>",
				seoTitle: "Cloudflare write post",
				metaDescription: "Writable Cloudflare record",
			},
		});
		expect(await cloudflare.revisions.list("cloudflare-write-post")).toEqual(
			expect.arrayContaining([
				expect.objectContaining({
					id: "cloudflare-write-revision",
					recordId: "cloudflare-write-post",
				}),
			]),
		);

		await cloudflare.content.delete("/legacy-cloudflare-write-post");
		await cloudflare.media.delete("cloudflare-upload");

		expect(await cloudflare.content.get("/legacy-cloudflare-write-post")).toBeNull();
		expect(await cloudflare.media.get("cloudflare-upload")).toBeNull();

		db.close();
	});

	it("throws when saving an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		await expect(
			cloudflare.content.save({
				id: "comment-1",
				kind: "comment",
				slug: "comment-1",
				status: "published",
				metadata: {},
			} as Parameters<typeof cloudflare.content.save>[0]),
		).rejects.toThrow("does not support saving comment records yet");

		db.close();
	});

	it("returns without throwing when deleting an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();

		// Insert a comment record — the Cloudflare adapter lists comments via readStore
		// and surfaces them through content.get(). The delete path now degrades gracefully.
		db.prepare(
			`INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		).run(
			"comment-del-1",
			"Test Author",
			"test@example.com",
			"Test comment",
			"/blog",
			"pending",
			"open-moderated",
			"2026-01-01T00:00:00.000Z",
		);

		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Unsupported record kind — adapter degrades gracefully (no-op) rather than throwing
		await expect(cloudflare.content.delete("comment-del-1")).resolves.toBeUndefined();

		db.close();
	});
});

tests/nhost-adapter.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import {
	createAstropressNhostAdapter,
	createAstropressNhostHostedAdapter,
	readAstropressNhostHostedConfig,
} from "../src/adapters/nhost.js";
import { createAstropressInMemoryPlatformAdapter } from "../src/in-memory-platform-adapter.js";

describe("readAstropressNhostHostedConfig", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("reads all required env vars", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("super-secret-key");
	});

	it("builds the correct API base URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.apiBaseUrl).toBe(
			"https://abcdefgh.eu-central-1.nhost.run/v1/functions/astropress",
		);
	});

	it("builds the correct preview (console) URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.previewBaseUrl).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
	});

	it("throws when NHOST_SUBDOMAIN is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_SUBDOMAIN: undefined,
			}),
		).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("throws when NHOST_REGION is missing", () => {
		expect(() => readAstropressNhostHostedConfig({ ...validEnv, NHOST_REGION: undefined })).toThrow(
			/NHOST_REGION/,
		);
	});

	it("throws when NHOST_ADMIN_SECRET is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_ADMIN_SECRET: undefined,
			}),
		).toThrow(/NHOST_ADMIN_SECRET/);
	});

	it("strips whitespace from env values", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  abcdefgh  ",
			NHOST_REGION: "  eu-central-1  ",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("secret");
	});
});

describe("createAstropressNhostAdapter", () => {
	it("creates an adapter with full capabilities", () => {
		const adapter = createAstropressNhostAdapter();
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});
});

describe("createAstropressNhostHostedAdapter", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("creates a hosted API adapter with full capabilities", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("sets the Nhost Console hostPanel link", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		const panel = adapter.capabilities.hostPanel as {
			url: string;
			label: string;
			mode: string;
		};
		expect(panel).toBeTruthy();
		expect(panel.url).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
		expect(panel.label).toBe("Nhost Console");
		// Pins L94 StringLiteral `mode: "link"`.
		expect(panel.mode).toBe("link");
	});

	it("routes through the hosted-API adapter when no stores are provided and invokes fetchImpl (pins L78 condition chain)", async () => {
		const fetchImpl = vi.fn(async () => new Response(JSON.stringify([]), { status: 200 }) as never);
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			fetchImpl: fetchImpl as never,
		});
		await adapter.content.list("post");
		expect(fetchImpl).toHaveBeenCalled();
		expect(String(fetchImpl.mock.calls[0]?.[0])).toContain("functions/astropress");
	});

	it.each([["backingAdapter"], ["content"], ["media"], ["revisions"], ["auth"]] as const)(
		"does NOT call fetchImpl when only `%s` is supplied (pins each L78 `!options.x &&` clause)",
		async (key) => {
			const fetchImpl = vi.fn(async () => new Response("nope", { status: 500 }) as never);
			const backing = createAstropressInMemoryPlatformAdapter({
				capabilities: { name: "sqlite" },
			});
			const isolated: Record<string, unknown> = {};
			if (key === "backingAdapter") {
				isolated.backingAdapter = backing;
			} else {
				isolated[key] = backing[key as "content" | "media" | "revisions" | "auth"];
			}
			const adapter = createAstropressNhostHostedAdapter({
				env: validEnv,
				...(isolated as Parameters<typeof createAstropressNhostHostedAdapter>[0]),
				fetchImpl: fetchImpl as never,
			});
			await adapter.content.list("post");
			expect(fetchImpl).not.toHaveBeenCalled();
		},
	);

	it("accepts explicit config bypassing env read", () => {
		const adapter = createAstropressNhostHostedAdapter({
			config: {
				subdomain: "xyz",
				region: "us-east-1",
				adminSecret: "s3cr3t",
				apiBaseUrl: "https://xyz.us-east-1.nhost.run/v1/functions/astropress",
				previewBaseUrl: "https://xyz.us-east-1.nhost.run/console",
			},
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("falls back to hosted platform adapter when backing stores are provided", () => {
		const mockContent = {
			async list() {
				return [];
			},
			async get() {
				return null;
			},
			async save(r: unknown) {
				return r as never;
			},
			async delete() {},
		};
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			content: mockContent,
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("throws when required env vars are missing and no explicit config", () => {
		expect(() => createAstropressNhostHostedAdapter({ env: {} })).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("trims whitespace from NHOST_SUBDOMAIN (pins L53 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  xyz  ",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.subdomain).toBe("xyz");
	});

	it("treats whitespace-only NHOST_SUBDOMAIN as missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				NHOST_SUBDOMAIN: "   ",
				NHOST_REGION: "us-east-1",
				NHOST_ADMIN_SECRET: "secret",
			}),
		).toThrow();
	});

	it("trims whitespace from NHOST_REGION (pins L54 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "  us-east-1  ",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.region).toBe("us-east-1");
	});

	it("trims whitespace from NHOST_ADMIN_SECRET (pins L55 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.adminSecret).toBe("secret");
	});
});

tests/webhooks-d1.test.ts.source:
// Mutation-coverage + behavioral tests for the D1 webhook store
// (src/sqlite-runtime/webhooks-d1.ts), exercised through the SqliteBackedD1Database
// fixture. The D1 sibling #137 added must match the sqlite store's create /
// list / delete / dispatch semantics — including the ML-DSA signing headers and
// the last_fired_at bookkeeping — on every host that provides a D1 binding.
import { describe, expect, it, vi } from "vitest";

import { verifyMlDsaMessage } from "../src/crypto-primitives.js";
import { createD1WebhookStore } from "../src/sqlite-runtime/webhooks-d1.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

const { loggerErrorSpy } = vi.hoisted(() => ({ loggerErrorSpy: vi.fn() }));

vi.mock("../src/runtime-logger", () => ({
	createLogger: () => ({
		info: vi.fn(),
		warn: vi.fn(),
		error: loggerErrorSpy,
	}),
}));

function makeStore(fetchImpl: typeof fetch = fetch) {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1WebhookStore(d1, fetchImpl) };
}

describe("createD1WebhookStore", () => {
	it("create: returns a one-time ML-DSA verification bundle and stores only the secret", async () => {
		const { db, store } = makeStore();
		const { record, verification } = await store.create({
			url: "https://example.com/hook",
			events: ["content.published"],
		});

		expect(verification.algorithm).toBe("ML-DSA-65");
		expect(verification.keyId).toBe(record.id);
		expect(verification.publicKey.length).toBeGreaterThan(100);
		expect(record.id.startsWith("wh_")).toBe(true);
		expect(record.active).toBe(true);
		expect(record.events).toEqual(["content.published"]);

		const row = db.prepare("SELECT secret_hash FROM webhooks WHERE id = ?").get(record.id) as {
			secret_hash: string;
		};
		expect(row.secret_hash).not.toBe(verification.publicKey);
	});

	it("list: returns only active, non-deleted webhooks newest-first", async () => {
		const { store } = makeStore();
		const { record: r1 } = await store.create({
			url: "https://a.com/hook",
			events: ["content.published"],
		});
		const { record: r2 } = await store.create({
			url: "https://b.com/hook",
			events: ["media.uploaded"],
		});
		await store.delete(r1.id);

		const active = await store.list();
		expect(active.some((w) => w.id === r2.id)).toBe(true);
		expect(active.some((w) => w.id === r1.id)).toBe(false);
	});

	it("list: maps the active column to a boolean", async () => {
		const { db, store } = makeStore();
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_on", "https://on.example.com", JSON.stringify(["content.published"]), "secret", 1);
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_off", "https://off.example.com", JSON.stringify(["content.published"]), "secret", 0);

		const list = await store.list();
		expect(list.find((w) => w.id === "wh_on")?.active).toBe(true);
		expect(list.find((w) => w.id === "wh_off")?.active).toBe(false);
	});

	it("delete: soft-deletes (sets deleted_at) so the webhook drops out of list", async () => {
		const { db, store } = makeStore();
		const { record } = await store.create({
			url: "https://c.com/hook",
			events: ["content.deleted"],
		});

		await store.delete(record.id);
		const row = db.prepare("SELECT deleted_at FROM webhooks WHERE id = ?").get(record.id) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
		expect((await store.list()).some((w) => w.id === record.id)).toBe(false);
	});

	it("dispatch: POSTs an ML-DSA-65 signed body with the documented headers", async () => {
		let captured: Request | undefined;
		const mockFetch = async (req: Request) => {
			captured = req;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		const { record, verification } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "post-1", status: "published" });

		expect(captured?.method).toBe("POST");
		expect(captured?.headers.get("content-type")).toBe("application/json");
		expect(captured?.headers.get("x-astropress-signature-alg")).toBe("ML-DSA-65");
		expect(captured?.headers.get("x-astropress-key-id")).toBe(record.id);

		const sig = captured?.headers.get("x-astropress-signature");
		const body = await captured?.clone().text();
		expect(verifyMlDsaMessage(body, sig as string, verification.publicKey)).toBe(true);

		const parsed = JSON.parse(body ?? "{}") as {
			event?: string;
			payload?: { id?: string; status?: string };
			timestamp?: string;
		};
		expect(parsed.event).toBe("content.published");
		expect(parsed.payload).toEqual({ id: "post-1", status: "published" });
		expect(typeof parsed.timestamp).toBe("string");
	});

	it("dispatch: skips webhooks not subscribed to the event", async () => {
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		await store.create({ url: "https://media.example.com/hook", events: ["media.uploaded"] });

		await store.dispatch("content.published", { id: "x" });
		expect(callCount).toBe(0);
	});

	it("dispatch: records last_fired_at on success", async () => {
		const mockFetch = async () => new Response("ok", { status: 200 });
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).not.toBeNull();

		const listed = (await store.list()).find((w) => w.id === record.id);
		expect(typeof listed?.lastFiredAt).toBe("string");
	});

	it("dispatch: a failed delivery leaves last_fired_at NULL, logs the error, and does not throw", async () => {
		loggerErrorSpy.mockClear();
		const mockFetch = async () => {
			throw new Error("Network error");
		};
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});

		await expect(store.dispatch("content.updated", { id: "x" })).resolves.not.toThrow();

		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).toBeNull();

		expect(loggerErrorSpy).toHaveBeenCalledTimes(1);
		const [message, meta] = loggerErrorSpy.mock.calls[0] as [string, { error?: unknown }];
		expect(message).toContain("content.updated");
		expect(message).toContain("https://fail.example.com/hook");
		expect(meta.error).toBeInstanceOf(Error);
	});
});

tests/platform-contracts.test.ts.source:
import {
	type AstropressPlatformAdapter,
	type AuthUser,
	assertProviderContract,
	type ContentStoreRecord,
	isAuthUserAdmin,
	type MediaAssetRecord,
	normalizeProviderCapabilities,
	type RevisionRecord,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

function createInMemoryAdapter(): AstropressPlatformAdapter {
	const records = new Map<string, ContentStoreRecord>();
	const media = new Map<string, MediaAssetRecord>();
	const revisions = new Map<string, RevisionRecord[]>();
	const sessions = new Map<string, AuthUser>();

	return {
		capabilities: normalizeProviderCapabilities({
			name: "custom",
			hostedAdmin: true,
			database: true,
			gitSync: true,
		}),
		content: {
			async list(kind) {
				return [...records.values()].filter((record) => !kind || record.kind === kind);
			},
			async get(id) {
				return records.get(id) ?? null;
			},
			async save(record) {
				records.set(record.id, record);
				return record;
			},
			async delete(id) {
				records.delete(id);
			},
		},
		media: {
			async put(asset) {
				media.set(asset.id, asset);
				return asset;
			},
			async get(id) {
				return media.get(id) ?? null;
			},
			async delete(id) {
				media.delete(id);
			},
		},
		revisions: {
			async list(recordId) {
				return revisions.get(recordId) ?? [];
			},
			async append(revision) {
				const existing = revisions.get(revision.recordId) ?? [];
				existing.push(revision);
				revisions.set(revision.recordId, existing);
				return revision;
			},
		},
		auth: {
			async signIn(email) {
				const user = { id: "u1", email, role: "admin" as const };
				sessions.set("session-1", user);
				return user;
			},
			async signOut(sessionId) {
				sessions.delete(sessionId);
			},
			async getSession(sessionId) {
				return sessions.get(sessionId) ?? null;
			},
		},
		gitSync: {
			async exportSnapshot(targetDir) {
				return { targetDir, fileCount: 4 };
			},
			async importSnapshot(sourceDir) {
				return { sourceDir, fileCount: 4 };
			},
		},
	};
}

describe("platform contracts", () => {
	it("fills omitted capability flags with false and preserves explicitly set flags", () => {
		const result = normalizeProviderCapabilities({
			name: "supabase",
			database: true,
		});
		expect(result.name).toBe("supabase");
		expect(result.database).toBe(true);
		const defaultFalseFlags = [
			"staticPublishing",
			"hostedAdmin",
			"previewEnvironments",
			"serverRuntime",
			"objectStorage",
			"gitSync",
		] as const;
		for (const flag of defaultFalseFlags) {
			expect(result[flag]).toBe(false);
		}
	});

	it("defaults database flag to false when omitted", () => {
		const result = normalizeProviderCapabilities({ name: "static-only" });
		expect(result.database).toBe(false);
	});

	it("preserves unknown provider names as-is", () => {
		const result = normalizeProviderCapabilities({
			name: "my-custom-provider",
		});
		expect(result.name).toBe("my-custom-provider");
	});

	it("accepts an adapter that satisfies the required contracts", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());
		const saved = await adapter.content.save({
			id: "page-1",
			kind: "page",
			slug: "home",
			status: "draft",
			title: "Home",
		});

		expect(saved.slug).toBe("home");
		expect((await adapter.content.list("page")).length).toBe(1);
	});

	it("rejects adapters that omit required stores", () => {
		expect(() =>
			assertProviderContract({
				capabilities: normalizeProviderCapabilities({ name: "custom" }),
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects adapters with no capabilities name", () => {
		expect(() =>
			assertProviderContract({
				...createInMemoryAdapter(),
				capabilities: { ...normalizeProviderCapabilities({ name: "" }) },
			}),
		).toThrow(/must declare a name/i);
	});

	it("rejects an adapter missing only the content store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				content: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the media store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				media: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the revisions store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				revisions: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the auth store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				auth: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("normalizeProviderCapabilities preserves an explicitly-provided hostPanel and deployHook", () => {
		const result = normalizeProviderCapabilities({
			name: "custom",
			hostPanel: { url: "https://panel.example" },
			deployHook: { url: "https://deploy.example" },
		});
		expect(result.hostPanel).toEqual({ url: "https://panel.example" });
		expect(result.deployHook).toEqual({ url: "https://deploy.example" });
	});

	describe("isAuthUserAdmin", () => {
		const base: AuthUser = { id: "u", email: "x@y", role: "admin" };
		it("returns true when isAdmin === true", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: true })).toBe(true);
		});
		it("returns false when isAdmin is false", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: false })).toBe(false);
		});
		it("returns false when isAdmin is undefined", () => {
			expect(isAuthUserAdmin(base)).toBe(false);
		});
		// Pin the strict equality check: isAdmin === true must reject truthy non-true.
		it("returns false when isAdmin is a truthy non-boolean (1)", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: 1 as unknown as boolean })).toBe(false);
		});
	});

	it("supports full content CRUD lifecycle", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());

		const record = await adapter.content.save({
			id: "post-1",
			kind: "post",
			slug: "hello",
			status: "draft",
			title: "Hello",
		});
		expect(record.id).toBe("post-1");

		const fetched = await adapter.content.get("post-1");
		expect(fetched?.slug).toBe("hello");

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(1);

		await adapter.content.delete("post-1");
		expect(await adapter.content.get("post-1")).toBeNull();
		expect(await adapter.content.list("post")).toHaveLength(0);
	});
});

tests/integrations/registry.test.ts.source:
import { afterEach, describe, expect, it } from "vitest";
import { z } from "zod";

import {
	registerAbTesting,
	registerAnalytics,
	registerCdnPurge,
	registerDeployHooks,
	registerForms,
	registerMonitoring,
	registerNewsletter,
	registerSearch,
} from "../../src/integrations/domains";
import {
	_resetRegistryForTests,
	getProvider,
	IntegrationRegistryError,
	listProviders,
	registerProvider,
} from "../../src/integrations/registry";

const noopVerify = async () => {
	/* no-op */
};

const baseDef = {
	id: "test-provider",
	label: "Test Provider",
	fields: z.object({ apiKey: z.string() }),
	verify: noopVerify,
};

afterEach(() => {
	_resetRegistryForTests();
});

describe("integration registry", () => {
	it("registers and looks up a provider by (domain, id)", () => {
		registerProvider("newsletter", baseDef);
		const found = getProvider("newsletter", "test-provider");
		expect(found?.id).toBe("test-provider");
		expect(found?.domain).toBe("newsletter");
	});

	it("isolates providers per domain (same id, different domain)", () => {
		registerProvider("newsletter", baseDef);
		registerProvider("analytics", baseDef);
		expect(getProvider("newsletter", "test-provider")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "test-provider")?.domain).toBe("analytics");
	});

	it("rejects duplicate registration in the same domain", () => {
		registerProvider("newsletter", baseDef);
		expect(() => registerProvider("newsletter", baseDef)).toThrowError(IntegrationRegistryError);
	});

	it("rejects an unknown domain", () => {
		expect(() =>
			// @ts-expect-error — runtime guard for hosts cast through `any`
			registerProvider("not-a-domain", baseDef),
		).toThrowError(IntegrationRegistryError);
	});

	it("listProviders returns only matches for the domain", () => {
		registerProvider("newsletter", { ...baseDef, id: "a" });
		registerProvider("newsletter", { ...baseDef, id: "b" });
		registerProvider("analytics", { ...baseDef, id: "a" });
		const newsletterIds = listProviders("newsletter")
			.map((p) => p.id)
			.sort();
		expect(newsletterIds).toEqual(["a", "b"]);
	});

	it("every typed wrapper pins the right domain", () => {
		registerNewsletter({ ...baseDef, id: "ml1" });
		registerAnalytics({ ...baseDef, id: "an1" });
		registerAbTesting({ ...baseDef, id: "ab1" });
		registerSearch({ ...baseDef, id: "se1" });
		registerCdnPurge({ ...baseDef, id: "cd1" });
		registerMonitoring({ ...baseDef, id: "mn1" });
		registerForms({ ...baseDef, id: "fm1" });
		registerDeployHooks({ ...baseDef, id: "dh1" });
		expect(getProvider("newsletter", "ml1")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "an1")?.domain).toBe("analytics");
		expect(getProvider("ab-testing", "ab1")?.domain).toBe("ab-testing");
		expect(getProvider("search", "se1")?.domain).toBe("search");
		expect(getProvider("cdn-purge", "cd1")?.domain).toBe("cdn-purge");
		expect(getProvider("monitoring", "mn1")?.domain).toBe("monitoring");
		expect(getProvider("forms", "fm1")?.domain).toBe("forms");
		expect(getProvider("deploy-hooks", "dh1")?.domain).toBe("deploy-hooks");
	});

	it("getProvider returns undefined for unknown id", () => {
		registerProvider("newsletter", baseDef);
		expect(getProvider("newsletter", "missing")).toBeUndefined();
	});

	it("preserves verify callback and runtimeShape on lookup", () => {
		const fields = z.object({ apiKey: z.string() });
		const runtimeShape = z.object({ apiKey: z.string().min(8) });
		registerProvider("newsletter", {
			id: "shape",
			label: "Shape",
			fields,
			runtimeShape,
			verify: noopVerify,
		});
		const found = getProvider("newsletter", "shape");
		expect(found?.runtimeShape).toBe(runtimeShape);
		expect(found?.verify).toBe(noopVerify);
	});

	it("IntegrationRegistryError carries the typed code", () => {
		registerProvider("newsletter", baseDef);
		try {
			registerProvider("newsletter", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect(err).toBeInstanceOf(IntegrationRegistryError);
			expect((err as IntegrationRegistryError).code).toBe("DUPLICATE_PROVIDER");
			expect((err as Error).name).toBe("IntegrationRegistryError");
		}
	});

	it("UNKNOWN_DOMAIN error code is set", () => {
		try {
			// @ts-expect-error
			registerProvider("bogus", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as IntegrationRegistryError).code).toBe("UNKNOWN_DOMAIN");
		}
	});

	it("listProviders returns empty array for empty domain", () => {
		expect(listProviders("monitoring")).toEqual([]);
	});

	it("registerProvider returns the registered entry with domain pinned", () => {
		const out = registerProvider("forms", { ...baseDef, id: "tally" });
		expect(out.domain).toBe("forms");
		expect(out.id).toBe("tally");
		expect(out.label).toBe("Test Provider");
	});

	it("INTEGRATION_DOMAINS contains every typed domain literal", () => {
		// Forces each string literal to remain in the typed array; a
		// stryker StringLiteral mutant on any of them would break a
		// registration with that domain.
		registerProvider("newsletter", { ...baseDef, id: "p" });
		registerProvider("analytics", { ...baseDef, id: "p" });
		registerProvider("ab-testing", { ...baseDef, id: "p" });
		registerProvider("search", { ...baseDef, id: "p" });
		registerProvider("cdn-purge", { ...baseDef, id: "p" });
		registerProvider("monitoring", { ...baseDef, id: "p" });
		registerProvider("forms", { ...baseDef, id: "p" });
		registerProvider("deploy-hooks", { ...baseDef, id: "p" });
		expect(getProvider("newsletter", "p")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "p")?.domain).toBe("analytics");
		expect(getProvider("ab-testing", "p")?.domain).toBe("ab-testing");
		expect(getProvider("search", "p")?.domain).toBe("search");
		expect(getProvider("cdn-purge", "p")?.domain).toBe("cdn-purge");
		expect(getProvider("monitoring", "p")?.domain).toBe("monitoring");
		expect(getProvider("forms", "p")?.domain).toBe("forms");
		expect(getProvider("deploy-hooks", "p")?.domain).toBe("deploy-hooks");
	});

	it("DUPLICATE_PROVIDER error message names the domain and id", () => {
		registerProvider("newsletter", baseDef);
		try {
			registerProvider("newsletter", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as Error).message).toContain("test-provider");
			expect((err as Error).message).toContain("newsletter");
		}
	});

	it("UNKNOWN_DOMAIN error message names the offending domain", () => {
		try {
			// @ts-expect-error
			registerProvider("not-real", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as Error).message).toContain("not-real");
		}
	});
});

tests/sections/templates-coverage.test.t.source:
/**
 * Branch / literal coverage for sections/templates.ts.
 */
import { describe, expect, it } from "vitest";
import { parseSections } from "../../src/sections/schema";
import {
	buildTemplate,
	isTemplateKey,
	TEMPLATE_CATALOG,
	TEMPLATE_KEYS,
} from "../../src/sections/templates";

describe("templates are scaffold-safe (issue #190)", () => {
	// Every built template must pass the same validator the save action runs, so
	// "pick a template → Save" never fails on a missing required field.
	for (const key of TEMPLATE_KEYS) {
		it(`buildTemplate("${key}") produces sections that pass parseSections`, () => {
			const result = parseSections(buildTemplate(key));
			expect(result.ok, result.ok ? "" : JSON.stringify(result.errors)).toBe(true);
		});
	}
});

describe("templates content", () => {
	it("landing[0] hero alignment is 'center' with headline + subhead + primaryCta", () => {
		const sections = buildTemplate("landing");
		const hero = sections[0];
		if (hero.kind !== "hero") throw new Error();
		expect(hero.alignment).toBe("center");
		expect(hero.headline).toBe("Tell your story");
		expect(hero.subhead).toContain("Replace this copy");
		expect(hero.primaryCta).toEqual({ label: "Get started", href: "#" });
	});

	it("landing feature-grid has 3 columns and 3 items", () => {
		const sections = buildTemplate("landing");
		const fg = sections[1];
		if (fg.kind !== "feature-grid") throw new Error();
		expect(fg.columns).toBe(3);
		expect(fg.items).toHaveLength(3);
		expect(fg.heading).toBe("What you get");
	});

	it("landing testimonials section is featured + grid", () => {
		const sections = buildTemplate("landing");
		const t = sections[2];
		if (t.kind !== "testimonials") throw new Error();
		expect(t.source).toBe("featured");
		expect(t.layout).toBe("grid");
		expect(t.heading).toBe("Trusted by people like you");
	});

	it("landing cta-banner uses 'accent' tone", () => {
		const sections = buildTemplate("landing");
		const c = sections[3];
		if (c.kind !== "cta-banner") throw new Error();
		expect(c.tone).toBe("accent");
		expect(c.headline).toBe("Ready to start?");
		expect(c.body).toBe("Take the next step.");
		expect(c.primaryCta).toEqual({ label: "Sign up", href: "#" });
	});

	it("about hero alignment is 'start'", () => {
		const sections = buildTemplate("about");
		const hero = sections[0];
		if (hero.kind !== "hero") throw new Error();
		expect(hero.alignment).toBe("start");
		expect(hero.headline).toBe("About us");
	});

	it("about image-text imageSide is 'start' with empty mediaId", () => {
		const sections = buildTemplate("about");
		const img = sections[1];
		if (img.kind !== "image-text") throw new Error();
		expect(img.imageSide).toBe("start");
		expect(img.mediaId).toBe("");
		expect(img.heading).toBe("Our story");
	});

	it("about feature-grid uses 2 columns and 2 items", () => {
		const sections = buildTemplate("about");
		const fg = sections[2];
		if (fg.kind !== "feature-grid") throw new Error();
		expect(fg.columns).toBe(2);
		expect(fg.items).toHaveLength(2);
	});

	it("about cta-banner uses 'neutral' tone", () => {
		const sections = buildTemplate("about");
		const c = sections[3];
		if (c.kind !== "cta-banner") throw new Error();
		expect(c.tone).toBe("neutral");
		expect(c.primaryCta.label).toBe("Contact us");
	});

	it("contact image-text imageSide is 'end'", () => {
		const sections = buildTemplate("contact");
		const img = sections[1];
		if (img.kind !== "image-text") throw new Error();
		expect(img.imageSide).toBe("end");
	});

	it("contact faq has 2 items", () => {
		const sections = buildTemplate("contact");
		const faq = sections[2];
		if (faq.kind !== "faq") throw new Error();
		expect(faq.items).toHaveLength(2);
		expect(faq.heading).toBe("Frequently asked");
	});

	it("contact cta-banner href is mailto:", () => {
		const sections = buildTemplate("contact");
		const c = sections[3];
		if (c.kind !== "cta-banner") throw new Error();
		expect(c.primaryCta.href).toBe("mailto:hello@example.com");
		expect(c.primaryCta.label).toBe("Send a message");
	});
});

describe("templates id generation", () => {
	it("default id generator yields unique ids within a single template", () => {
		const sections = buildTemplate("landing");
		const ids = sections.map((s) => s.id);
		expect(new Set(ids).size).toBe(ids.length);
		expect(ids[0]).toMatch(/^tmpl-/);
	});

	it("custom idGen receives sequential calls", () => {
		const ids: string[] = [];
		let n = 0;
		const sections = buildTemplate("landing", () => {
			n += 1;
			const id = `id-${n}`;
			ids.push(id);
			return id;
		});
		expect(sections.map((s) => s.id)).toEqual(ids);
		expect(ids).toEqual(["id-1", "id-2", "id-3", "id-4"]);
	});

	it("blank template doesn't invoke idGen", () => {
		let calls = 0;
		buildTemplate("blank", () => {
			calls += 1;
			return `x-${calls}`;
		});
		expect(calls).toBe(0);
	});
});

describe("templates safety", () => {
	it("buildTemplate with unknown key returns empty array", () => {
		// Cast — the function signature requires TemplateKey but the runtime
		// guard handles unknown keys defensively.
		const sections = buildTemplate("nope" as never);
		expect(sections).toEqual([]);
	});

	it("isTemplateKey returns true for every TEMPLATE_KEYS entry", () => {
		for (const key of TEMPLATE_KEYS) expect(isTemplateKey(key)).toBe(true);
	});

	it("isTemplateKey rejects empty string", () => {
		expect(isTemplateKey("")).toBe(false);
	});
});

describe("templates catalog", () => {
	it("blank entry has empty section list and 'Blank' title", () => {
		const blank = TEMPLATE_CATALOG.find((e) => e.key === "blank");
		expect(blank?.defaultTitle).toBe("Blank");
		expect(blank?.sectionKinds).toEqual([]);
		expect(blank?.defaultDescription).toBe("Start from scratch.");
	});

	it("landing entry has 4 section kinds in order", () => {
		const e = TEMPLATE_CATALOG.find((c) => c.key === "landing");
		expect(e?.sectionKinds).toEqual(["hero", "feature-grid", "testimonials", "cta-banner"]);
		expect(e?.defaultTitle).toBe("Landing page");
	});

	it("about entry catalog details", () => {
		const e = TEMPLATE_CATALOG.find((c) => c.key === "about");
		expect(e?.defaultTitle).toBe("About page");
		expect(e?.sectionKinds).toEqual(["hero", "image-text", "feature-grid", "cta-banner"]);
	});

	it("contact entry catalog details", () => {
		const e = TEMPLATE_CATALOG.find((c) => c.key === "contact");
		expect(e?.defaultTitle).toBe("Contact page");
		expect(e?.sectionKinds).toEqual(["hero", "image-text", "faq", "cta-banner"]);
	});

	it("TEMPLATE_KEYS is in canonical order", () => {
		expect(TEMPLATE_KEYS).toEqual(["blank", "landing", "about", "contact"]);
	});
});

tests/upgrade-path-e2e.test.ts.source:
/**
 * Upgrade path E2E tests — verifies schema migration, compat layer, and rollback round-trips.
 *
 * All tests are fully in-process: DatabaseSync + real schema SQL, no CLI invocations.
 */

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
	checkSchemaVersionAhead,
	rollbackAstropressLastMigration,
	runAstropressMigrations,
} from "../src/sqlite-bootstrap.js";
import { ensureLegacySchemaCompatibility, getTableColumns } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

// Minimal v0.0.1 schema — mirrors what a real pre-upgrade backup would contain
const V001_SCHEMA = `
  CREATE TABLE IF NOT EXISTS content_entries (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'post'
  );

  CREATE TABLE IF NOT EXISTS content_overrides (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('draft', 'published')),
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS content_revisions (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'reviewed',
    title TEXT NOT NULL,
    status TEXT NOT NULL,
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by TEXT,
    updated_at TEXT NOT NULL,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS media_assets (
    id TEXT PRIMARY KEY,
    filename TEXT NOT NULL,
    mime_type TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS admin_users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'editor'
  );
`;

let tempDir: string;

beforeEach(() => {
	tempDir = mkdtempSync(join(tmpdir(), "astropress-upgrade-"));
});

afterEach(() => {
	rmSync(tempDir, { recursive: true, force: true });
});

describe("compat upgrade: old schema → current schema", () => {
	it("ensureLegacySchemaCompatibility adds metadata and scheduled_at to v0.0.1 schema", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		const overrideCols = getTableColumns(db, "content_overrides");
		expect(overrideCols).not.toContain("metadata");

		ensureLegacySchemaCompatibility(db);

		const colsAfter = getTableColumns(db, "content_overrides");
		expect(colsAfter).toContain("metadata");
		expect(colsAfter).toContain("scheduled_at");
		db.close();
	});

	it("content rows survive the compat upgrade", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by)
       VALUES ('surviving-post', 'Surviving Post', 'published', 'admin@example.com')`,
		).run();

		ensureLegacySchemaCompatibility(db);

		const row = db
			.prepare("SELECT slug, title FROM content_overrides WHERE slug = 'surviving-post'")
			.get() as { slug: string; title: string } | undefined;

		expect(row?.slug).toBe("surviving-post");
		expect(row?.title).toBe("Surviving Post");
		db.close();
	});
});

describe("migration runner", () => {
	it("applies pending migrations and records them in schema_migrations", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_test_column.sql"),
			"ALTER TABLE content_overrides ADD COLUMN upgrade_test_col TEXT;",
		);
		writeFileSync(
			join(migrationsDir, "0001_add_test_column.down.sql"),
			"-- cannot drop column in SQLite",
		);

		const result = runAstropressMigrations(db, migrationsDir);
		expect(result.applied).toContain("0001_add_test_column.sql");

		const cols = getTableColumns(db, "content_overrides");
		expect(cols).toContain("upgrade_test_col");
		db.close();
	});

	it("rollbackAstropressLastMigration removes the last migration record", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_rollback_test.sql"),
			"ALTER TABLE content_overrides ADD COLUMN rollback_test_col TEXT;",
		);
		writeFileSync(
			join(migrationsDir, "0001_rollback_test.down.sql"),
			"-- rollback: column removal not supported in SQLite without table rebuild",
		);

		runAstropressMigrations(db, migrationsDir);

		const beforeCount = (
			db.prepare("SELECT COUNT(*) as c FROM schema_migrations").get() as {
				c: number;
			}
		).c;
		const rolledBack = rollbackAstropressLastMigration(db);
		const afterCount = (
			db.prepare("SELECT COUNT(*) as c FROM schema_migrations").get() as {
				c: number;
			}
		).c;

		expect(rolledBack).toBe("0001_rollback_test.sql");
		expect(afterCount).toBe(beforeCount - 1);
		db.close();
	});
});

describe("checkSchemaVersionAhead", () => {
	it("returns isAhead:true when DB has more migrations than the baseline", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		for (let i = 1; i <= 5; i++) {
			writeFileSync(
				join(migrationsDir, `000${i}_migration.sql`),
				`ALTER TABLE content_overrides ADD COLUMN extra_col_${i} TEXT;`,
			);
		}

		runAstropressMigrations(db, migrationsDir);

		const result = checkSchemaVersionAhead(db, 1);
		expect(result).not.toBeNull();
		expect(result?.isAhead).toBe(true);
		expect(result?.dbCount).toBeGreaterThan(1);
		db.close();
	});

	it("returns isAhead:false on a fresh schema with no extra migrations", () => {
		const db = makeDb();

		// No migrations applied — baseline is 1 (framework migration)
		const result = checkSchemaVersionAhead(db, 1);
		expect(result).not.toBeNull();
		// The fresh schema has 0 rows in schema_migrations (framework uses ensureLegacySchemaCompatibility, not migrations table)
		expect(result?.isAhead).toBe(false);
		db.close();
	});
});

