import { describe, expect, it, vi } from "vitest";
import { createAstropressAuthorRepository } from "../src/author-repository-factory";

const actor = { email: "admin@example.com", role: "admin" as const, name: "Admin" };

function makeRepo(overrides: Partial<Parameters<typeof createAstropressAuthorRepository>[0]> = {}) {
	const recordAuthorAudit = vi.fn();
	const createAuthor = vi.fn(() => true);
	const updateAuthor = vi.fn(() => true);
	const deleteAuthor = vi.fn(() => true);
	const listAuthors = vi.fn(() => []);
	const slugifyTerm = (value: string) => value.toLowerCase().replace(/\s+/g, "-");
	const repository = createAstropressAuthorRepository({
		listAuthors,
		slugifyTerm,
		createAuthor,
		updateAuthor,
		deleteAuthor,
		recordAuthorAudit,
		...overrides,
	});
	return { repository, recordAuthorAudit, createAuthor, updateAuthor, deleteAuthor, listAuthors };
}

describe("author repository factory — create", () => {
	it("trims name, slug, and bio and dispatches the audit", () => {
		const { repository, createAuthor, recordAuthorAudit } = makeRepo();
		const result = repository.createAuthor(
			{ name: "  Alice Smith  ", slug: " Alice Smith ", bio: "  bio body  " },
			actor,
		);
		expect(result).toEqual({ ok: true });
		expect(createAuthor).toHaveBeenCalledWith({
			slug: "alice-smith",
			name: "Alice Smith",
			bio: "bio body",
		});
		expect(recordAuthorAudit).toHaveBeenCalledWith({
			actor,
			action: "author.create",
			summary: "Created author Alice Smith.",
			targetId: "alice-smith",
		});
	});

	it("defaults bio to empty string when omitted", () => {
		const { repository, createAuthor } = makeRepo();
		repository.createAuthor({ name: "Bob" }, actor);
		expect(createAuthor).toHaveBeenCalledWith({ slug: "bob", name: "Bob", bio: "" });
	});

	it("rejects when name trims to empty", () => {
		const { repository, createAuthor, recordAuthorAudit } = makeRepo();
		const result = repository.createAuthor({ name: "   " }, actor);
		expect(result).toEqual({ ok: false, error: "Author name and slug are required." });
		expect(createAuthor).not.toHaveBeenCalled();
		expect(recordAuthorAudit).not.toHaveBeenCalled();
	});

	it("rejects when slug slugifies to empty", () => {
		const { repository } = makeRepo({ slugifyTerm: () => "" });
		const result = repository.createAuthor({ name: "Alice" }, actor);
		expect(result).toEqual({ ok: false, error: "Author name and slug are required." });
	});

	it("returns the in-use error verbatim when createAuthor returns false", () => {
		const { repository, recordAuthorAudit } = makeRepo({ createAuthor: vi.fn(() => false) });
		const result = repository.createAuthor({ name: "Alice" }, actor);
		expect(result).toEqual({
			ok: false,
			error: "That author name or slug is already in use.",
		});
		expect(recordAuthorAudit).not.toHaveBeenCalled();
	});
});

describe("author repository factory — update", () => {
	it("trims name, slug, and bio and dispatches the audit with stringified id", () => {
		const { repository, updateAuthor, recordAuthorAudit } = makeRepo();
		const result = repository.updateAuthor(
			{ id: 9, name: "  Alice  ", slug: " Alice ", bio: "  bio  " },
			actor,
		);
		expect(result).toEqual({ ok: true });
		expect(updateAuthor).toHaveBeenCalledWith({
			id: 9,
			slug: "alice",
			name: "Alice",
			bio: "bio",
		});
		expect(recordAuthorAudit).toHaveBeenCalledWith({
			actor,
			action: "author.update",
			summary: "Updated author Alice.",
			targetId: "9",
		});
	});

	it("defaults bio to empty string when omitted on update", () => {
		const { repository, updateAuthor } = makeRepo();
		repository.updateAuthor({ id: 3, name: "Bob" }, actor);
		expect(updateAuthor).toHaveBeenCalledWith({ id: 3, slug: "bob", name: "Bob", bio: "" });
	});

	it("rejects when id is zero", () => {
		const { repository, updateAuthor } = makeRepo();
		const result = repository.updateAuthor({ id: 0, name: "Alice" }, actor);
		expect(result).toEqual({
			ok: false,
			error: "Author id, name, and slug are required.",
		});
		expect(updateAuthor).not.toHaveBeenCalled();
	});

	it("rejects when name trims to empty on update", () => {
		const { repository } = makeRepo();
		const result = repository.updateAuthor({ id: 1, name: "   " }, actor);
		expect(result).toEqual({
			ok: false,
			error: "Author id, name, and slug are required.",
		});
	});

	it("rejects when slug slugifies to empty on update", () => {
		const { repository } = makeRepo({ slugifyTerm: () => "" });
		const result = repository.updateAuthor({ id: 1, name: "Alice" }, actor);
		expect(result).toEqual({
			ok: false,
			error: "Author id, name, and slug are required.",
		});
	});

	it("returns the could-not-be-updated error when updateAuthor returns false", () => {
		const { repository, recordAuthorAudit } = makeRepo({ updateAuthor: vi.fn(() => false) });
		const result = repository.updateAuthor({ id: 7, name: "Alice" }, actor);
		expect(result).toEqual({
			ok: false,
			error: "That author could not be updated.",
		});
		expect(recordAuthorAudit).not.toHaveBeenCalled();
	});
});

describe("author repository factory — delete", () => {
	it("calls deleteAuthor with the id and dispatches the audit", () => {
		const { repository, deleteAuthor, recordAuthorAudit } = makeRepo();
		const result = repository.deleteAuthor(7, actor);
		expect(result).toEqual({ ok: true });
		expect(deleteAuthor).toHaveBeenCalledWith(7);
		expect(recordAuthorAudit).toHaveBeenCalledWith({
			actor,
			action: "author.delete",
			summary: "Deleted author 7.",
			targetId: "7",
		});
	});

	it("returns the could-not-be-deleted error when deleteAuthor returns false", () => {
		const { repository, recordAuthorAudit } = makeRepo({ deleteAuthor: vi.fn(() => false) });
		const result = repository.deleteAuthor(99, actor);
		expect(result).toEqual({
			ok: false,
			error: "That author could not be deleted.",
		});
		expect(recordAuthorAudit).not.toHaveBeenCalled();
	});
});

describe("author repository factory — list passthrough", () => {
	it("forwards listAuthors result and call count", () => {
		const expected = [{ id: 1, slug: "a", name: "A", bio: "" }];
		const listAuthors = vi.fn(() => expected);
		const { repository } = makeRepo({
			listAuthors: listAuthors as unknown as Parameters<
				typeof createAstropressAuthorRepository
			>[0]["listAuthors"],
		});
		const result = repository.listAuthors();
		expect(result).toBe(expected);
		expect(listAuthors).toHaveBeenCalledTimes(1);
	});
});

tests/monitoring.test.ts.source:
/**
 * Monitoring tests — verifies the unauthenticated Prometheus metrics endpoint behavior.
 *
 * Tests use mocked store/content to avoid requiring a full SQLite runtime.
 */

import { afterEach, describe, expect, it, vi } from "vitest";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(monitoring?: { prometheusEnabled?: boolean }) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		monitoring,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

// Mock the runtime store so the endpoint doesn't need real SQLite. Both content
// and media are now read through this one host-agnostic seam (getReadStore
// dispatches D1 vs local), so the test mocks both here — no admin-store mock.
vi.mock("../src/runtime-page-store.js", () => ({
	listRuntimeContentStates: vi.fn().mockResolvedValue([
		{
			slug: "post-1",
			kind: "post",
			status: "published",
			title: "Post 1",
			updatedAt: "2026-01-01",
		},
		{
			slug: "post-2",
			kind: "post",
			status: "published",
			title: "Post 2",
			updatedAt: "2026-01-01",
		},
		{
			slug: "page-1",
			kind: "page",
			status: "published",
			title: "Page 1",
			updatedAt: "2026-01-01",
		},
	]),
	searchRuntimeContentStates: vi.fn().mockResolvedValue([]),
	getRuntimeMediaAssets: vi
		.fn()
		.mockResolvedValue([{ id: "media-1" }, { id: "media-2" }, { id: "media-3" }]),
}));

import { getRuntimeMediaAssets } from "../src/runtime-page-store.js";

const mockGetRuntimeMediaAssets = getRuntimeMediaAssets as unknown as ReturnType<typeof vi.fn>;

afterEach(() => {
	clearCmsConfig();
	vi.clearAllMocks();
});

async function callMetricsEndpoint(locals: Record<string, unknown> = {}) {
	// Dynamic import to pick up mocks
	const { GET } = await import("../pages/ap/metrics.js");
	const request = new Request("http://localhost/ap/metrics");
	return GET({ request, locals } as Parameters<typeof GET>[0]);
}

describe("GET /ap/metrics — disabled by default", () => {
	it("returns 404 when monitoring.prometheusEnabled is absent", async () => {
		setCmsConfig(undefined);
		const response = await callMetricsEndpoint();
		expect(response.status).toBe(404);
	});

	it("returns 404 when monitoring.prometheusEnabled is false", async () => {
		setCmsConfig({ prometheusEnabled: false });
		const response = await callMetricsEndpoint();
		expect(response.status).toBe(404);
	});
});

describe("GET /ap/metrics — enabled", () => {
	it("returns 200 with correct Content-Type when prometheusEnabled is true", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const response = await callMetricsEndpoint();
		expect(response.status).toBe(200);
		expect(response.headers.get("Content-Type")).toBe("text/plain; version=0.0.4");
	});

	it("sets Cache-Control: no-store", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const response = await callMetricsEndpoint();
		expect(response.headers.get("Cache-Control")).toBe("no-store");
	});

	it("body contains HELP and TYPE lines for ap_content_total", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const response = await callMetricsEndpoint();
		const body = await response.text();
		expect(body).toContain("# HELP ap_content_total");
		expect(body).toContain("# TYPE ap_content_total gauge");
		expect(body).toContain('ap_content_total{kind="post"}');
	});

	it("body contains ap_uptime_seconds with a non-negative value", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const response = await callMetricsEndpoint();
		const body = await response.text();
		const match = body.match(/ap_uptime_seconds (\d+)/);
		expect(match).not.toBeNull();
		expect(Number(match?.[1])).toBeGreaterThanOrEqual(0);
	});

	it("body contains ap_media_total metric", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const response = await callMetricsEndpoint();
		const body = await response.text();
		expect(body).toContain("# HELP ap_media_total");
		expect(body).toContain("ap_media_total 3");
	});

	it("does not require Authorization header", async () => {
		setCmsConfig({ prometheusEnabled: true });
		// No auth headers in the request — should still return 200
		const response = await callMetricsEndpoint();
		expect(response.status).toBe(200);
	});
});

// Issue #140: media must be counted through the host-agnostic runtime seam,
// not the local-only admin store — otherwise a D1/hosted deployment (which
// has no local runtime alias) reports a misleading ap_media_total 0.
describe("GET /ap/metrics — host-agnostic media count (issue #140)", () => {
	it("reads media through the runtime seam, passing the request locals through", async () => {
		setCmsConfig({ prometheusEnabled: true });
		const d1Locals = { runtime: { env: { DB: {} } } };
		await callMetricsEndpoint(d1Locals);
		expect(mockGetRuntimeMediaAssets).toHaveBeenCalledWith(d1Locals);
	});

	it("reports the real media count on a D1-backed host (not a silent zero)", async () => {
		setCmsConfig({ prometheusEnabled: true });
		// A host with no local runtime alias but real D1 media: the seam returns
		// the records. The pre-fix code read safeLoadLocalAdminStore() -> null
		// here and published ap_media_total 0.
		mockGetRuntimeMediaAssets.mockResolvedValueOnce([
			{ id: "d1-1" },
			{ id: "d1-2" },
			{ id: "d1-3" },
			{ id: "d1-4" },
			{ id: "d1-5" },
		]);
		const response = await callMetricsEndpoint({ runtime: { env: { DB: {} } } });
		const body = await response.text();
		expect(body).toContain("ap_media_total 5");
	});

	it("reports zero only when there is genuinely no media", async () => {
		setCmsConfig({ prometheusEnabled: true });
		mockGetRuntimeMediaAssets.mockResolvedValueOnce([]);
		const response = await callMetricsEndpoint();
		const body = await response.text();
		expect(body).toContain("ap_media_total 0");
	});

	it("stays 200 and reports zero media if the media read throws", async () => {
		setCmsConfig({ prometheusEnabled: true });
		mockGetRuntimeMediaAssets.mockRejectedValueOnce(new Error("store unavailable"));
		const response = await callMetricsEndpoint();
		expect(response.status).toBe(200);
		const body = await response.text();
		expect(body).toContain("ap_media_total 0");
	});
});

tests/crypto-primitives.test.ts.source:
import { describe, expect, it } from "vitest";
import {
	bytesToBase64,
	bytesToHex,
	constantTimeEqual,
	createKmacDigest,
	createMlDsaKeyPair,
	hashPasswordArgon2id,
	isArgon2idHash,
	secretKeyToBase64,
	signMlDsaMessage,
	verifyArgon2idPassword,
	verifyMlDsaMessage,
} from "../src/crypto-primitives.js";

describe("bytesToBase64", () => {
	it("encodes bytes to standard base64", () => {
		expect(bytesToBase64(new Uint8Array([104, 105]))).toBe("aGk=");
	});

	it("encodes an empty array to an empty string", () => {
		expect(bytesToBase64(new Uint8Array([]))).toBe("");
	});
});

describe("bytesToHex", () => {
	it("encodes bytes to lowercase hex", () => {
		expect(bytesToHex(new Uint8Array([0xde, 0xad, 0xbe, 0xef]))).toBe("deadbeef");
	});

	it("zero-pads single-digit byte values to two hex chars", () => {
		expect(bytesToHex(new Uint8Array([0, 1, 15, 16]))).toBe("00010f10");
	});

	it("encodes an empty array to an empty string", () => {
		expect(bytesToHex(new Uint8Array([]))).toBe("");
	});
});

describe("constantTimeEqual", () => {
	it("returns true for identical byte arrays", () => {
		expect(constantTimeEqual(new Uint8Array([1, 2, 3]), new Uint8Array([1, 2, 3]))).toBe(true);
	});

	it("returns false for same-length arrays that differ in one byte", () => {
		expect(constantTimeEqual(new Uint8Array([1, 2, 3]), new Uint8Array([1, 2, 4]))).toBe(false);
	});

	it("returns false when the left array is longer than the right", () => {
		expect(constantTimeEqual(new Uint8Array([1, 2, 3]), new Uint8Array([1, 2]))).toBe(false);
	});

	it("returns false when the left array is shorter than the right", () => {
		// left shorter: the loop bound is left.length, so without the early
		// length-mismatch return the shared prefix would compare as equal.
		expect(constantTimeEqual(new Uint8Array([1, 2]), new Uint8Array([1, 2, 3]))).toBe(false);
	});

	it("returns true for two empty arrays", () => {
		expect(constantTimeEqual(new Uint8Array([]), new Uint8Array([]))).toBe(true);
	});

	it("detects a mismatch in the first byte", () => {
		expect(constantTimeEqual(new Uint8Array([9, 2, 3]), new Uint8Array([1, 2, 3]))).toBe(false);
	});
});

describe("createKmacDigest", () => {
	it("produces a deterministic 64-char hex digest by default", () => {
		const digest = createKmacDigest("value", "secret", "purpose");
		expect(digest).toMatch(/^[a-f0-9]{64}$/);
		expect(createKmacDigest("value", "secret", "purpose")).toBe(digest);
	});

	it("honours a custom output length", () => {
		expect(createKmacDigest("value", "secret", "purpose", 16)).toMatch(/^[a-f0-9]{32}$/);
	});

	it("domain-separates by purpose tag", () => {
		expect(createKmacDigest("value", "secret", "purpose-a")).not.toBe(
			createKmacDigest("value", "secret", "purpose-b"),
		);
	});

	it("changes when the secret changes", () => {
		expect(createKmacDigest("value", "secret-a", "purpose")).not.toBe(
			createKmacDigest("value", "secret-b", "purpose"),
		);
	});

	it("changes when the value changes", () => {
		expect(createKmacDigest("value-a", "secret", "purpose")).not.toBe(
			createKmacDigest("value-b", "secret", "purpose"),
		);
	});
});

describe("hashPasswordArgon2id / verifyArgon2idPassword / isArgon2idHash", () => {
	it("produces a verifiable v3 argon2id hash", { timeout: 60_000 }, () => {
		const hash = hashPasswordArgon2id("correct-horse", { memoryKiB: 256, iterations: 1 });
		expect(hash.startsWith("v3:argon2id$")).toBe(true);
		expect(isArgon2idHash(hash)).toBe(true);
		expect(verifyArgon2idPassword("correct-horse", hash)).toBe(true);
		expect(verifyArgon2idPassword("wrong-horse", hash)).toBe(false);
	});

	it("embeds the configured cost parameters in the hash string", { timeout: 60_000 }, () => {
		const hash = hashPasswordArgon2id("pw", { iterations: 3, memoryKiB: 512, parallelism: 1 });
		const [prefix, iterations, memory, parallelism] = hash.split("$");
		expect(prefix).toBe("v3:argon2id");
		expect(iterations).toBe("3");
		expect(memory).toBe("512");
		expect(parallelism).toBe("1");
	});

	it("uses default cost parameters when options are omitted", { timeout: 60_000 }, () => {
		const hash = hashPasswordArgon2id("pw");
		const [, iterations, memory, parallelism] = hash.split("$");
		expect(iterations).toBe("2");
		expect(memory).toBe("19456");
		expect(parallelism).toBe("1");
	});

	it("isArgon2idHash rejects non-argon2id strings", () => {
		expect(isArgon2idHash("plain-text")).toBe(false);
		expect(isArgon2idHash("v2:argon2id$x")).toBe(false);
	});

	it("verifyArgon2idPassword rejects a hash without the argon2id prefix", () => {
		expect(verifyArgon2idPassword("pw", "not-a-hash")).toBe(false);
	});

	it("verifyArgon2idPassword rejects a hash with empty segments", () => {
		expect(verifyArgon2idPassword("pw", "v3:argon2id$$$$$")).toBe(false);
	});

	it("verifyArgon2idPassword rejects a hash with non-numeric cost parameters", () => {
		expect(verifyArgon2idPassword("pw", "v3:argon2id$x$y$z$c2FsdA==$aGFzaA==")).toBe(false);
	});

	it("verifyArgon2idPassword returns false when base64 decoding throws", () => {
		expect(verifyArgon2idPassword("pw", "v3:argon2id$2$256$1$!!!bad!!!$!!!bad!!!")).toBe(false);
	});
});

describe("ML-DSA signing", () => {
	it("creates a key pair carrying the verification metadata", () => {
		const pair = createMlDsaKeyPair("key-1");
		expect(pair.keyId).toBe("key-1");
		expect(pair.verification).toEqual({
			algorithm: "ML-DSA-65",
			keyId: "key-1",
			publicKey: bytesToBase64(pair.publicKey),
			encoding: "base64",
		});
	});

	it("verifies a signature produced for the matching message and key", () => {
		const pair = createMlDsaKeyPair("key-2");
		const secretKeyBase64 = secretKeyToBase64(pair.secretKey);
		const signature = signMlDsaMessage("hello world", secretKeyBase64);
		expect(verifyMlDsaMessage("hello world", signature, pair.verification.publicKey)).toBe(true);
	});

	it("rejects a signature checked against a different message", () => {
		const pair = createMlDsaKeyPair("key-3");
		const signature = signMlDsaMessage("original", secretKeyToBase64(pair.secretKey));
		expect(verifyMlDsaMessage("tampered", signature, pair.verification.publicKey)).toBe(false);
	});

	it("secretKeyToBase64 matches bytesToBase64", () => {
		const pair = createMlDsaKeyPair("key-4");
		expect(secretKeyToBase64(pair.secretKey)).toBe(bytesToBase64(pair.secretKey));
	});
});

