import {
	type AstropressCmsConfig,
	type AstropressHostPanelCapability,
	type AstropressPlatformAdapter,
	assertProviderContract,
	normalizeProviderCapabilities,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

function createTestAdapter(hostPanel?: AstropressHostPanelCapability): AstropressPlatformAdapter {
	return assertProviderContract({
		capabilities: normalizeProviderCapabilities({
			name: "test",
			database: true,
			hostPanel,
		}),
		content: {
			async list() {
				return [];
			},
			async get() {
				return null;
			},
			async save(r) {
				return r;
			},
			async delete() {},
		},
		media: {
			async put(a) {
				return a;
			},
			async get() {
				return null;
			},
			async delete() {},
		},
		revisions: {
			async list() {
				return [];
			},
			async append(r) {
				return r;
			},
		},
		auth: {
			async signIn() {
				return null;
			},
			async signOut() {},
			async getSession() {
				return null;
			},
		},
	});
}

describe("AstropressCmsConfig types", () => {
	it("payload cms config is correctly typed", () => {
		const config: AstropressCmsConfig = {
			type: "payload",
			mode: "iframe",
			url: "http://localhost:3000",
		};

		expect(config.type).toBe("payload");
		expect(config.mode).toBe("iframe");
		expect(config.url).toBe("http://localhost:3000");
	});

	it("contentful cloud cms uses link mode", () => {
		const config: AstropressCmsConfig = {
			type: "contentful",
			mode: "link",
			url: "https://app.contentful.com/spaces/abc123",
			label: "Contentful",
		};

		expect(config.mode).toBe("link");
		expect(config.label).toBe("Contentful");
	});

	it("all supported cms types are valid", () => {
		const types: AstropressCmsConfig["type"][] = [
			"payload",
			"sanity",
			"directus",
			"strapi",
			"tina",
			"contentful",
			"storyblok",
			"keystatic",
			"custom",
		];

		for (const type of types) {
			const config: AstropressCmsConfig = {
				type,
				mode: "link",
				url: "https://example.com",
			};
			expect(config.type).toBe(type);
		}
	});

	it("iframe allow attribute is optional", () => {
		const withAllow: AstropressCmsConfig = {
			type: "directus",
			mode: "iframe",
			url: "https://cms.example.com",
			iframeAllow: "fullscreen",
		};
		const withoutAllow: AstropressCmsConfig = {
			type: "directus",
			mode: "iframe",
			url: "https://cms.example.com",
		};

		expect(withAllow.iframeAllow).toBe("fullscreen");
		expect(withoutAllow.iframeAllow).toBeUndefined();
	});
});

describe("AstropressHostPanelCapability", () => {
	it("adapter with hostPanel includes it in capabilities", () => {
		const adapter = createTestAdapter({
			mode: "link",
			url: "https://app.supabase.com/project/abc",
			label: "Supabase Studio",
		});

		expect(adapter.capabilities.hostPanel).toBeDefined();
		expect(adapter.capabilities.hostPanel?.label).toBe("Supabase Studio");
		expect(adapter.capabilities.hostPanel?.mode).toBe("link");
		expect(adapter.capabilities.hostPanel?.url).toBe("https://app.supabase.com/project/abc");
	});

	it("adapter without hostPanel has undefined hostPanel", () => {
		const adapter = createTestAdapter();
		expect(adapter.capabilities.hostPanel).toBeUndefined();
	});

	it("pocketbase self-hosted adapter uses iframe mode", () => {
		const adapter = createTestAdapter({
			mode: "iframe",
			url: "http://localhost:8090/_/",
			label: "PocketBase Admin",
		});

		expect(adapter.capabilities.hostPanel?.mode).toBe("iframe");
	});

	it("normalizeProviderCapabilities passes through hostPanel", () => {
		const caps = normalizeProviderCapabilities({
			name: "supabase",
			database: true,
			hostPanel: {
				mode: "link",
				url: "https://supabase.com/dashboard",
				label: "Supabase Studio",
			},
		});

		expect(caps.hostPanel).toBeDefined();
		expect(caps.hostPanel?.label).toBe("Supabase Studio");
	});

	it("normalizeProviderCapabilities without hostPanel leaves it undefined", () => {
		const caps = normalizeProviderCapabilities({
			name: "sqlite",
			database: true,
		});
		expect(caps.hostPanel).toBeUndefined();
	});
});

describe("Host nav visibility rules", () => {
	it("host panel is visible only for admin role", () => {
		// Simulates the nav filtering logic in AdminLayout
		const hasHostPanel = true;
		const roleAdmin = "admin";
		const roleEditor = "editor";

		const adminSees = hasHostPanel && roleAdmin === "admin";
		const editorSees = hasHostPanel && roleEditor === "admin";

		expect(adminSees).toBe(true);
		expect(editorSees).toBe(false);
	});

	it("cms nav is visible to all authenticated users when cms is configured", () => {
		const hasCms = true;
		const roleAdmin = "admin";
		const roleEditor = "editor";

		// CMS nav has no adminOnly restriction
		expect(hasCms && roleAdmin.length > 0).toBe(true);
		expect(hasCms && roleEditor.length > 0).toBe(true);
	});

	it("cms nav is hidden when no cms is configured", () => {
		const hasCms = false;
		expect(hasCms).toBe(false);
	});
});

describe("deployHook capability", () => {
	it("normalizeProviderCapabilities passes through deployHook", () => {
		const caps = normalizeProviderCapabilities({
			name: "cloudflare",
			staticPublishing: true,
			deployHook: {
				type: "cloudflare-pages",
				configuredViaEnv: ["CF_PAGES_DEPLOY_HOOK_URL"],
			},
		});

		expect(caps.deployHook?.type).toBe("cloudflare-pages");
		expect(caps.deployHook?.configuredViaEnv).toContain("CF_PAGES_DEPLOY_HOOK_URL");
	});

	it("deployHook is optional — undefined when not declared", () => {
		const caps = normalizeProviderCapabilities({ name: "sqlite" });
		expect(caps.deployHook).toBeUndefined();
	});
});

tests/sqlite-admin-runtime-users.test.ts.source:
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
	createRuntimeFixture,
	type RuntimeFixture,
} from "./helpers/sqlite-admin-runtime-fixture.js";

let fixture: RuntimeFixture;

beforeAll(() => {
	fixture = createRuntimeFixture();
});

afterAll(() => {
	fixture.db.close();
});

// ─── Users ────────────────────────────────────────────────────────────────────

describe("users", () => {
	it("listAdminUsers returns active, suspended, and invited statuses", () => {
		const users = fixture.store.users.listAdminUsers();
		expect(users.some((u) => u.email === "admin@test.local" && u.status === "active")).toBe(true);
		expect(users.some((u) => u.email === "suspended@test.local" && u.status === "suspended")).toBe(
			true,
		);
		expect(users.some((u) => u.email === "invited@test.local" && u.status === "invited")).toBe(
			true,
		);
	});

	it("inviteAdminUser creates a new user", () => {
		const result = fixture.store.users.inviteAdminUser(
			{ email: "new-editor@test.local", role: "editor", name: "New Editor" },
			fixture.actor,
		);
		expect(result.ok).toBe(true);
	});

	it("inviteAdminUser returns error for duplicate email", () => {
		fixture.store.users.inviteAdminUser(
			{ email: "dup-editor@test.local", role: "editor", name: "Dup" },
			fixture.actor,
		);
		const result = fixture.store.users.inviteAdminUser(
			{ email: "dup-editor@test.local", role: "editor", name: "Dup Again" },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
	});

	it("suspendAdminUser and unsuspendAdminUser toggle active state", () => {
		fixture.store.users.inviteAdminUser(
			{ email: "toggle@test.local", role: "editor", name: "Toggle" },
			fixture.actor,
		);
		expect(fixture.store.users.suspendAdminUser("toggle@test.local", fixture.actor).ok).toBe(true);
		expect(fixture.store.users.unsuspendAdminUser("toggle@test.local", fixture.actor).ok).toBe(
			true,
		);
	});

	it("suspendAdminUser returns error for unknown user", () => {
		expect(fixture.store.users.suspendAdminUser("nobody@test.local", fixture.actor).ok).toBe(false);
	});
});

// ─── Audit ────────────────────────────────────────────────────────────────────

describe("audit", () => {
	it("getAuditEvents returns events with correct targetType mapping", () => {
		for (const [action, type, id] of [
			["test.redirect", "redirect", "/old"],
			["test.comment", "comment", "c1"],
			["test.content", "content", "post-1"],
			["test.auth", "auth", "site-settings"],
			["test.unknown", "media", "asset-1"],
		] as const) {
			fixture.db
				.prepare(
					"INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary) VALUES (?, ?, ?, ?, ?)",
				)
				.run("admin@test.local", action, type, id, `${type} audit`);
		}

		const events = fixture.store.audit.getAuditEvents();
		expect(events.some((e) => e.targetType === "redirect")).toBe(true);
		expect(events.some((e) => e.targetType === "comment")).toBe(true);
		expect(events.some((e) => e.targetType === "content")).toBe(true);
		expect(events.some((e) => e.targetType === "auth")).toBe(true);
	});
});

// ─── User management error branches ──────────────────────────────────────────

describe("users additional error branches", () => {
	it("inviteAdminUser: empty name returns error", () => {
		expect(
			fixture.store.users.inviteAdminUser(
				{ email: "valid@test.local", role: "editor", name: "" },
				fixture.actor,
			).ok,
		).toBe(false);
	});

	it("inviteAdminUser: invalid role returns error (role normalizes to empty string)", () => {
		expect(
			fixture.store.users.inviteAdminUser(
				{ email: "valid2@test.local", role: "superuser" as string, name: "X" },
				fixture.actor,
			).ok,
		).toBe(false);
	});

	it("inviteAdminUser: invalid email format returns error", () => {
		expect(
			fixture.store.users.inviteAdminUser(
				{ email: "not-an-email", role: "editor", name: "X" },
				fixture.actor,
			).ok,
		).toBe(false);
	});

	it("suspendAdminUser: empty email returns error", () => {
		expect(fixture.store.users.suspendAdminUser("", fixture.actor).ok).toBe(false);
	});

	it("suspendAdminUser: suspending yourself returns error", () => {
		expect(fixture.store.users.suspendAdminUser("admin@test.local", fixture.actor).ok).toBe(false);
	});

	it("unsuspendAdminUser: empty email returns error", () => {
		expect(fixture.store.users.unsuspendAdminUser("", fixture.actor).ok).toBe(false);
	});

	it("unsuspendAdminUser: non-existent user returns error", () => {
		expect(fixture.store.users.unsuspendAdminUser("nobody@test.local", fixture.actor).ok).toBe(
			false,
		);
	});
});

// ─── Users inviteAdminUser role branches ─────────────────────────────────────

describe("users inviteAdminUser role branches", () => {
	it("inviteAdminUser with 'admin' role (covers the 'admin' arm of the nested ternary)", () => {
		const result = fixture.store.users.inviteAdminUser(
			{ email: "new-admin@test.local", role: "admin", name: "New Admin" },
			fixture.actor,
		);
		expect(result.ok).toBe(true);
	});
});

tests/api-tokens-d1.test.ts.source:
// Mutation-coverage + behavioral tests for the D1 API-token store
// (src/sqlite-runtime/api-tokens-d1.ts). The D1 backend is exercised through
// the SqliteBackedD1Database fixture so the async `.bind().run()/.first()/.all()`
// surface, the hashed-token storage, and the verify() reason literals are all
// observable — the D1 sibling that #137 added must behave identically to the
// sqlite store on every host that provides a D1 binding.
import { describe, expect, it } from "vitest";

import { createD1ApiTokenStore } from "../src/sqlite-runtime/api-tokens-d1.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function makeStore() {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1ApiTokenStore(d1) };
}

describe("createD1ApiTokenStore", () => {
	it("create: stores the hash (not the raw token) and returns the raw token once", async () => {
		const { db, store } = makeStore();
		const { record, rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("agent");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.id.startsWith("tok_")).toBe(true);
		expect(record.revokedAt).toBeNull();
		expect(record.lastUsedAt).toBeNull();

		const row = db.prepare("SELECT token_hash FROM api_tokens WHERE id = ?").get(record.id) as {
			token_hash: string;
		};
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("create: persists expiresAt and defaults it to null when omitted", async () => {
		const { store } = makeStore();
		const noExpiry = await store.create({ label: "a", scopes: ["content:read"] });
		expect(noExpiry.record.expiresAt).toBeNull();

		const future = new Date(Date.now() + 60_000).toISOString();
		const withExpiry = await store.create({
			label: "b",
			scopes: ["content:read"],
			expiresAt: future,
		});
		expect(withExpiry.record.expiresAt).toBe(future);
	});

	it("list: returns all tokens newest-first without exposing the hash", async () => {
		const { store } = makeStore();
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		expect(tokens.map((t) => t.label)).toEqual(expect.arrayContaining(["alpha", "beta"]));
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid token succeeds and stamps lastUsedAt", async () => {
		const { store } = makeStore();
		const { rawToken } = await store.create({ label: "agent", scopes: ["content:read"] });

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");
		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: unknown token is rejected with a 'not found' reason", async () => {
		const { store } = makeStore();
		const result = await store.verify("definitely-not-a-real-token");
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/not found/i);
	});

	it("verify: revoked token is rejected with a 'revoked' reason", async () => {
		const { store } = makeStore();
		const { record, rawToken } = await store.create({
			label: "revoke-me",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/revoked/i);
	});

	it("verify: expired token is rejected with an 'expired' reason", async () => {
		const { store } = makeStore();
		const past = new Date(Date.now() - 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "expired",
			scopes: ["content:read"],
			expiresAt: past,
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/expired/i);
	});

	it("verify: future-expiry token still verifies", async () => {
		const { store } = makeStore();
		const future = new Date(Date.now() + 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "future",
			scopes: ["content:read"],
			expiresAt: future,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
	});

	it("revoke: marks the token revoked while keeping it listed for admin display", async () => {
		const { store } = makeStore();
		const { record } = await store.create({ label: "revocable", scopes: ["content:write"] });
		await store.revoke(record.id);

		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked).toBeDefined();
		expect(revoked?.revokedAt).not.toBeNull();
	});
});

