import { beforeEach, describe, expect, test, vi } from "vitest";
import type { AccessSnapshot } from "../src/access/d1-access-store";
import { getAccessContext } from "../src/access/request-context";

let mockD1Result: AccessSnapshot | null = null;

vi.mock("../src/access/d1-access-store", () => ({
	loadAccessSnapshotFromD1: vi.fn(async () => mockD1Result),
}));

function makeD1Locals(adminUser: { email: string; isAdmin: boolean; id?: string }) {
	const fakeDb = {
		prepare: () => ({ bind: () => ({ first: async () => null, all: async () => [] }) }),
	};
	return {
		adminUser,
		runtime: { env: { DB: fakeDb } },
	} as unknown as App.Locals;
}

describe("getAccessContext — D1 branch (kill NoCoverage mutants)", () => {
	beforeEach(() => {
		mockD1Result = null;
	});

	test("uses the D1 snapshot when loadAccessSnapshotFromD1 returns a non-null result", async () => {
		mockD1Result = {
			userId: "u-42",
			isAdmin: false,
			roles: ["editor"],
			attributes: { dept: "eng" },
			policies: [
				{
					id: "p1",
					effect: "allow",
					action: "media:upload",
					source: { kind: "direct" },
				},
			],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "u@example.com", isAdmin: false }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("u-42");
		expect(ctx.subject.roles).toEqual(["editor"]);
		expect(ctx.subject.attributes).toEqual({ dept: "eng" });
		expect(ctx.subject.isAdmin).toBe(false);
		expect(ctx.can("media:upload").decision).toBe("allow");
	});

	test("the D1 snapshot OR-combines with isAuthUserAdmin (auth flag wins over stale is_admin column)", async () => {
		mockD1Result = {
			userId: "u-1",
			isAdmin: false,
			roles: [],
			attributes: {},
			policies: [],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "a@example.com", isAdmin: true }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(true);
	});

	test("the D1 snapshot keeps isAdmin true when the DB already says is_admin = 1", async () => {
		mockD1Result = {
			userId: "u-2",
			isAdmin: true,
			roles: [],
			attributes: {},
			policies: [],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "a@example.com", isAdmin: false }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(true);
	});

	test("falls back to admin-only snapshot when D1 returns null (kills adminOnlySnapshot NoCoverage)", async () => {
		mockD1Result = null;
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "missing@example.com", isAdmin: true }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("email:missing@example.com");
		expect(ctx.subject.isAdmin).toBe(true);
		expect(ctx.subject.roles).toEqual([]);
		expect(ctx.subject.attributes).toEqual({});
	});

	test("admin-only fallback uses adminUser.id when present (pins ?? operand order)", async () => {
		mockD1Result = null;
		const locals = {
			adminUser: { id: "id-explicit", email: "x@example.com", isAdmin: true },
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("id-explicit");
	});

	test("admin-only fallback (non-admin user, D1 returns null) emits empty roles/policies", async () => {
		mockD1Result = null;
		const locals = {
			adminUser: { email: "editor@example.com", isAdmin: false },
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(false);
		// Non-admin with empty policies → can() denies arbitrary actions
		expect(ctx.can("media:upload").decision).toBe("deny");
	});
});

tests/deploy-and-sync.contract.test.ts.source:
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import { createAstropressCloudflarePagesDeployTarget } from "../src/deploy/cloudflare-pages.js";
import { createAstropressGitHubPagesDeployTarget } from "../src/deploy/github-pages.js";
import { createAstropressGitLabPagesDeployTarget } from "../src/deploy/gitlab-pages.js";
import { createAstropressNetlifyDeployTarget } from "../src/deploy/netlify.js";
import { createAstropressRenderDeployTarget } from "../src/deploy/render.js";
import { createAstropressVercelDeployTarget } from "../src/deploy/vercel.js";
import { createAstropressGitSyncAdapter } from "../src/sync/git.js";

describe("deploy and sync contracts", () => {
	it("deploys a build directory to the github pages target", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-gh-pages-"));
		const buildDir = join(workspace, "dist");
		const outputDir = join(workspace, "deployments");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		const target = createAstropressGitHubPagesDeployTarget({
			outputDir,
			baseUrl: "https://example.com/docs",
		});

		const result = await target.deploy({
			buildDir,
			projectName: "demo-site",
		});

		expect(result.url).toBe("https://example.com/docs/demo-site/");
		expect(await readFile(join(outputDir, "demo-site", "index.html"), "utf8")).toContain(
			"Astropress",
		);
		expect(
			await readFile(join(outputDir, "demo-site", ".astropress-deploy.json"), "utf8"),
		).toContain('"provider": "github-pages"');

		await rm(workspace, { recursive: true, force: true });
	});

	it("prepares build directories for the other app-host deploy targets", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-host-deploys-"));
		const buildDir = join(workspace, "dist");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		for (const [factory, provider] of [
			[createAstropressCloudflarePagesDeployTarget, "cloudflare-pages"],
			[createAstropressVercelDeployTarget, "vercel"],
			[createAstropressNetlifyDeployTarget, "netlify"],
			[createAstropressRenderDeployTarget, "render-web"],
			[createAstropressGitLabPagesDeployTarget, "gitlab-pages"],
		] as const) {
			const outputDir = join(workspace, provider);
			const target = factory({ outputDir } as never);
			const result = await target.deploy({
				buildDir,
				projectName: "demo-site",
			});

			expect(result.deploymentId).toContain("demo-site");
			expect(
				await readFile(join(outputDir, "demo-site", ".astropress-deploy.json"), "utf8"),
			).toContain(provider);
		}

		await rm(workspace, { recursive: true, force: true });
	});

	it("round-trips a project snapshot through git sync", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-sync-"));
		const projectDir = join(workspace, "project");
		const snapshotDir = join(workspace, "snapshot");
		await mkdir(join(projectDir, "src"), { recursive: true });
		await writeFile(join(projectDir, "package.json"), '{"name":"demo"}');
		await writeFile(join(projectDir, "src", "index.ts"), "export const demo = true;");

		const sync = createAstropressGitSyncAdapter({ projectDir });
		const exported = await sync.exportSnapshot(snapshotDir);
		await writeFile(join(projectDir, "src", "index.ts"), "export const demo = false;");
		const imported = await sync.importSnapshot(snapshotDir);

		expect(exported.fileCount).toBeGreaterThan(0);
		expect(imported.fileCount).toBe(exported.fileCount);
		expect(await readFile(join(projectDir, "src", "index.ts"), "utf8")).toContain("demo = true");

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/html-optimization.test.ts.source:
import { optimizeImageLoading } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

describe("optimizeImageLoading()", () => {
	it("adds loading='lazy' to images without a loading attribute", () => {
		const result = optimizeImageLoading(
			'<img src="/first.jpg" alt="First"><img src="/second.jpg" alt="Second">',
		);
		expect(result).toContain('loading="lazy"');
	});

	it("does not modify images that already have a loading attribute", () => {
		const html = '<img src="/photo.jpg" alt="Photo" loading="eager">';
		const result = optimizeImageLoading(html);
		expect(result).not.toContain('loading="lazy"');
		expect(result).toContain('loading="eager"');
	});

	it("skips the first image (likely hero/LCP) to avoid performance regression", () => {
		const html = '<img src="/hero.jpg" alt="Hero">';
		const result = optimizeImageLoading(html);
		expect(result).not.toContain('loading="lazy"');
	});

	it("adds loading='lazy' to second and subsequent images", () => {
		const html = [
			'<img src="/hero.jpg" alt="Hero">',
			'<img src="/second.jpg" alt="Second">',
			'<img src="/third.jpg" alt="Third">',
		].join("");
		const result = optimizeImageLoading(html);
		const lazyCount = (result.match(/loading="lazy"/g) ?? []).length;
		expect(lazyCount).toBe(2);
	});

	it("skips first image if it has fetchpriority attribute", () => {
		const html =
			'<img src="/hero.jpg" alt="Hero" fetchpriority="high"><img src="/next.jpg" alt="Next">';
		const result = optimizeImageLoading(html);
		expect(result).not.toMatch(/<img[^>]*fetchpriority="high"[^>]*loading="lazy"[^>]*>/);
	});

	it("returns HTML unchanged if there are no img tags", () => {
		const html = "<p>No images here.</p>";
		expect(optimizeImageLoading(html)).toBe(html);
	});

	it("never appends a second loading attr to an image that already has one (non-first position)", () => {
		// First img is the LCP candidate; second already has loading=eager.
		// The loading-check branch must short-circuit so the explicit
		// loading=eager image never gets a duplicate loading="lazy" appended.
		const html = '<img src="/hero.jpg"><img src="/explicit.jpg" loading="eager">';
		const result = optimizeImageLoading(html);
		// Exactly one `loading=` attribute on the second img, and it's "eager".
		const matches = result.match(/loading="[^"]*"/g) ?? [];
		expect(matches).toEqual(['loading="eager"']);
	});

	it("a leading explicit-loading image still consumes the firstImage slot (kills BooleanLiteral mutant in the loading branch)", () => {
		// If the loading branch did NOT set firstImage=false, the second img
		// would be treated as the LCP and skip lazy.
		const html = '<img src="/hero.jpg" loading="eager"><img src="/next.jpg">';
		const result = optimizeImageLoading(html);
		expect(result).toContain('<img src="/next.jpg" loading="lazy">');
	});

	it("never appends loading='lazy' to a non-first image that has fetchpriority", () => {
		// fetchpriority=high signals a non-LCP image we explicitly want to
		// keep eager (e.g. above-the-fold non-hero). Must short-circuit even
		// when not in the firstImage slot.
		const html = '<img src="/hero.jpg"><img src="/banner.jpg" fetchpriority="high">';
		const result = optimizeImageLoading(html);
		// The fetchpriority image must NOT have loading attribute appended.
		expect(result).not.toMatch(/fetchpriority="high"\s+loading=/);
	});

	it("a leading fetchpriority image still consumes the firstImage slot (kills BooleanLiteral mutant in the fetchpriority branch)", () => {
		// If the fetchpriority branch did NOT set firstImage=false, the
		// second img would be treated as the LCP and skip lazy.
		const html = '<img src="/banner.jpg" fetchpriority="high"><img src="/next.jpg">';
		const result = optimizeImageLoading(html);
		expect(result).toContain('<img src="/next.jpg" loading="lazy">');
	});
});

tests/admin-locale-links.test.ts.source:
import { afterEach, describe, expect, it } from "vitest";

import { getAdminLocalePair, normalizeRoute } from "../src/admin-locale-links";
import { registerCms } from "../src/config";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
});

const TRANSLATION_STATUS = [
	{
		route: "/es/sobre",
		locale: "es",
		englishSourceUrl: "/about",
		translationState: "published",
	},
	{
		route: "/es/contacto",
		locale: "es",
		englishSourceUrl: "/contact",
		translationState: "in_progress",
	},
];

function setup() {
	registerCms({
		siteUrl: "https://example.org",
		templateKeys: ["home"],
		seedPages: [],
		archives: [],
		translationStatus: TRANSLATION_STATUS as never,
	} as never);
}

describe("getAdminLocalePair", () => {
	it("returns es pair when route matches a localized entry", () => {
		setup();
		const pair = getAdminLocalePair("/es/sobre");
		expect(pair).toEqual({
			currentLocale: "es",
			englishRoute: "/about",
			localizedRoute: "/es/sobre",
			translationState: "published",
		});
	});

	it("returns en pair when route matches an englishSourceUrl", () => {
		setup();
		const pair = getAdminLocalePair("/about");
		expect(pair).toEqual({
			currentLocale: "en",
			englishRoute: "/about",
			localizedRoute: "/es/sobre",
			translationState: "published",
		});
	});

	it("returns null when route matches nothing", () => {
		setup();
		expect(getAdminLocalePair("/nope")).toBeNull();
	});

	it("normalizes trailing slashes before matching (localized side)", () => {
		setup();
		expect(getAdminLocalePair("/es/sobre/")?.currentLocale).toBe("es");
		expect(getAdminLocalePair("/es/sobre//")?.currentLocale).toBe("es");
	});

	it("normalizes trailing slashes before matching (english side)", () => {
		setup();
		expect(getAdminLocalePair("/about/")?.currentLocale).toBe("en");
	});

	it("treats empty input as '/' (no match in fixture)", () => {
		setup();
		expect(getAdminLocalePair("")).toBeNull();
	});

	it("treats only-slash input as '/'", () => {
		setup();
		expect(getAdminLocalePair("/")).toBeNull();
	});

	it("a string of all slashes normalizes to '/'", () => {
		setup();
		// "////" → trim trailing slashes leaves "" → return "/"
		expect(getAdminLocalePair("////")).toBeNull();
	});

	it("propagates translationState verbatim from the matching entry", () => {
		setup();
		expect(getAdminLocalePair("/es/contacto")?.translationState).toBe("in_progress");
	});
});

describe("normalizeRoute", () => {
	it("returns '/' for empty input", () => {
		expect(normalizeRoute("")).toBe("/");
	});

	it("returns '/' for undefined-coerced falsy input", () => {
		// Pins the !route branch — a mutant that drops it would try to
		// regex-replace on "" and return "" instead.
		expect(normalizeRoute("")).toBe("/");
	});

	it("returns '/' for a single slash", () => {
		expect(normalizeRoute("/")).toBe("/");
	});

	it("returns '/' for any all-slashes string", () => {
		// Pins the `trimmed === "" ? "/" : trimmed` ternary — without the
		// fallback the function would return "" for these inputs.
		expect(normalizeRoute("//")).toBe("/");
		expect(normalizeRoute("///")).toBe("/");
		expect(normalizeRoute("////")).toBe("/");
	});

	it("strips a single trailing slash", () => {
		expect(normalizeRoute("/about/")).toBe("/about");
	});

	it("strips multiple trailing slashes", () => {
		expect(normalizeRoute("/about///")).toBe("/about");
	});

	it("returns the route unchanged when there is no trailing slash", () => {
		expect(normalizeRoute("/about")).toBe("/about");
		expect(normalizeRoute("/es/sobre")).toBe("/es/sobre");
	});

	it("does not strip non-trailing slashes", () => {
		expect(normalizeRoute("/a/b/c")).toBe("/a/b/c");
		expect(normalizeRoute("/a//b/")).toBe("/a//b");
	});
});

tests/d1-local-integration.test.ts.source:
/**
 * D1 local integration tests — exercises the Cloudflare adapter through a real
 * SQLite-backed D1 shim (SqliteBackedD1Database).
 *
 * These tests use a local SQLite-backed D1 shim. Cloudflare D1 uses SQLite under
 * the hood and the shim is functionally equivalent for integration testing purposes.
 * No Cloudflare account or credentials required.
 */

import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";
import { makeDb, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

beforeEach(() => {
	registerCms(STANDARD_CMS_CONFIG);
});

describe("D1 adapter: auth round-trip via SQLite shim", () => {
	it("creates a session, retrieves it, and revokes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Sign in
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");
		expect(session?.isAdmin).toBe(true);

		// Retrieve session
		const retrieved = await adapter.auth.getSession(session?.id);
		expect(retrieved?.email).toBe("admin@example.com");

		// Revoke session
		await adapter.auth.signOut(session?.id);
		const revoked = await adapter.auth.getSession(session?.id);
		expect(revoked).toBeNull();
	});
});

describe("D1 adapter: content CRUD via SQLite shim", () => {
	it("creates a content record, reads it back, updates it, and deletes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Create
		const saved = await adapter.content.save({
			id: "d1-test-slug",
			slug: "d1-test-slug",
			kind: "post",
			title: "D1 Test Post",
			status: "draft",
			body: "<p>Initial body</p>",
			metadata: {
				seoTitle: "D1 Test Post",
				metaDescription: "Testing D1",
				legacyUrl: "/d1-test-slug",
				templateKey: "content",
				updatedAt: new Date().toISOString(),
				summary: "",
			},
		});
		expect(saved.slug).toBe("d1-test-slug");

		// Read back
		const fetched = await adapter.content.get("d1-test-slug");
		expect(fetched?.title).toBe("D1 Test Post");
		expect(fetched?.status).toBe("draft");

		// Update
		const updated = await adapter.content.save({
			...saved,
			title: "D1 Updated Post",
			status: "published",
		});
		expect(updated.title).toBe("D1 Updated Post");
		expect(updated.status).toBe("published");

		// Delete (soft delete — archives the record)
		await adapter.content.delete("d1-test-slug");
		const afterDelete = await adapter.content.get("d1-test-slug");
		// The Cloudflare adapter soft-deletes posts by setting status to "archived"
		expect(afterDelete?.status).toBe("archived");
	});
});

describe("D1 adapter: schema bootstrap via SQLite shim", () => {
	it("bootstraps the schema and confirms schema_migrations table exists", () => {
		const db = makeDb();

		const tableRow = db
			.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='schema_migrations'")
			.get() as { name: string } | undefined;

		expect(tableRow?.name).toBe("schema_migrations");
	});

	it("D1 shim executes SQL statements via prepare().all()", async () => {
		const db = await createSeededCloudflareDatabase();
		const d1 = new SqliteBackedD1Database(db);

		const result = await d1
			.prepare("SELECT COUNT(*) as count FROM admin_users")
			.first<{ count: number }>();
		expect(result).not.toBeNull();
		expect(result?.count).toBeGreaterThan(0);
	});
});

tests/content-search.test.ts.source:
/**
 * Content search tests — verifies FTS5 virtual table creation, trigger-based sync,
 * and search query behavior.
 *
 * All tests run in-process using DatabaseSync with the real schema.
 */

import { describe, expect, it, vi } from "vitest";

import { searchContentOverrides } from "../src/sqlite-runtime/search.js";
import { ensureFts5SearchIndex, getTableSql } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(search?: { enabled?: boolean }) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		search,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

describe("FTS5 search index creation", () => {
	it("ensureFts5SearchIndex creates content_fts virtual table", () => {
		const db = makeDb();
		expect(getTableSql(db, "content_fts")).toBeUndefined();

		ensureFts5SearchIndex(db);

		// FTS5 virtual tables appear in sqlite_master as type 'table'
		const row = db.prepare("SELECT name FROM sqlite_master WHERE name = 'content_fts'").get() as
			| { name: string }
			| undefined;
		expect(row?.name).toBe("content_fts");
		db.close();
	});

	it("ensureFts5SearchIndex is idempotent — calling twice does not throw", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);
		expect(() => ensureFts5SearchIndex(db)).not.toThrow();
		db.close();
	});
});

describe("FTS5 search query", () => {
	it("returns a record whose body matches a unique phrase", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-test-post', 'FTS Test Post', 'published', 'admin@example.com', 'uniqueftstestphrase searchable content')`,
		).run();

		const results = searchContentOverrides(db, "uniqueftstestphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-test-post");
		db.close();
	});

	it("returns updated content after an UPDATE trigger fires", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-update-test', 'Update Test', 'draft', 'admin@example.com', 'originalbodycontent')`,
		).run();

		// Update the body — the AFTER UPDATE trigger should sync the FTS index
		db.prepare(
			`UPDATE content_overrides SET body = 'replacedftsbodyphrase' WHERE slug = 'fts-update-test'`,
		).run();

		const results = searchContentOverrides(db, "replacedftsbodyphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-update-test");

		// Original phrase should no longer match
		const oldResults = searchContentOverrides(db, "originalbodycontent");
		expect(oldResults).toHaveLength(0);
		db.close();
	});
});

describe("searchRuntimeContentStates gating", () => {
	it("returns empty array with a warning when search.enabled is false", async () => {
		setCmsConfig({ enabled: false });
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

		// Import after setting config to ensure peekCmsConfig resolves correctly
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("hello");

		expect(results).toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("search.enabled"));
		warnSpy.mockRestore();
		clearCmsConfig();
	});
});

