import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import {
	createAstropressProjectAdapter,
	resolveAstropressProjectAdapterMode,
} from "../src/adapters/project.js";

describe("project adapter integration", () => {
	it("selects project adapters from runtime mode and project env", async () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosted",
			}),
		).toBe("hosted");

		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-adapter-"));
		const localAdapter = createAstropressProjectAdapter({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "project-adapter.sqlite"),
			},
		});

		expect(localAdapter.capabilities.name).toBe("supabase");

		await rm(workspace, { recursive: true, force: true });
	});

	it("trims surrounding whitespace before matching the 'hosted' mode (kills .trim removal)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "  hosted  ",
			}),
		).toBe("hosted");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is the literal 'local'", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "local",
			}),
		).toBe("local");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is undefined (no env)", () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
	});

	it("returns 'local' for any value other than 'hosted' (e.g. typo)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosting",
			}),
		).toBe("local");
	});

	it("explicit options.mode overrides any env-derived mode (kills ?? to && mutant)", async () => {
		// env says hosted, but options.mode="local" should win.
		const workspace = await mkdtemp(join(tmpdir(), "astropress-mode-override-"));
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "mode-override.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});

	it("creates a hosted adapter when mode='hosted' (kills BlockStatement/ConditionalExpression mutants on the if-branch)", () => {
		const adapter = createAstropressProjectAdapter({
			mode: "hosted",
			env: {
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test-service-key",
			},
		});
		// Hosted adapter advertises hostedAdmin capability.
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("explicit options.local.provider overrides projectEnv.localProvider (kills ?? to && in local branch)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-local-prov-"));
		// env says sqlite; options.local.provider="supabase" must win and
		// route through the supabase-sqlite adapter (capabilities.name="supabase").
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: { ASTROPRESS_LOCAL_PROVIDER: "sqlite" },
			local: {
				provider: "supabase",
				workspaceRoot: workspace,
				dbPath: join(workspace, "local-prov.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});
});

tests/data-portability.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { createSqlitePurgeOps } from "../src/sqlite-runtime/purge.js";
import { makeDb } from "./helpers/make-db.js";

function seedUser(db: DatabaseSync, email: string, name = "Test User") {
	db.prepare(
		`INSERT INTO admin_users (email, password_hash, name, is_admin)
     VALUES (?, 'hash', ?, 0)`,
	).run(email, name);
	const row = db.prepare("SELECT id FROM admin_users WHERE email = ? LIMIT 1").get(email) as {
		id: number;
	};

	// Insert a session for the user
	db.prepare(
		`INSERT INTO admin_sessions (id, user_id, csrf_token)
     VALUES (?, ?, 'csrf')`,
	).run(`sess-${email}`, row.id);

	// Insert audit events
	db.prepare(
		`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary)
     VALUES (?, 'content.update', 'content', 'post-1', 'Updated post')`,
	).run(email);

	// Insert a comment
	db.prepare(
		`INSERT INTO comments (id, author, email, body, route, status, policy)
     VALUES (?, 'Test User', ?, 'A comment', '/post-1', 'approved', 'open-moderated')`,
	).run(`comment-${email}`, email);

	// Insert a contact submission
	db.prepare(
		`INSERT INTO contact_submissions (name, email, message, submitted_at)
     VALUES ('Test User', ?, 'Hello', CURRENT_TIMESTAMP)`,
	).run(email);
}

describe("createSqlitePurgeOps — user data purge (GDPR)", () => {
	let db: DatabaseSync;
	let purge: ReturnType<typeof createSqlitePurgeOps>;

	beforeEach(() => {
		db = makeDb();
		purge = createSqlitePurgeOps(() => db);
	});

	it("revokes sessions for the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.ok).toBe(true);
		expect(result.revokedSessions).toBe(1);
	});

	it("anonymises audit events", () => {
		seedUser(db, "alice@test.com");
		purge.purgeUserData("alice@test.com");
		const row = db.prepare("SELECT user_email FROM audit_events LIMIT 1").get() as {
			user_email: string;
		};
		expect(row.user_email).toBe("[deleted]");
	});

	it("deletes comments by the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.deletedComments).toBe(1);
		const remaining = db
			.prepare("SELECT COUNT(*) as cnt FROM comments WHERE email = 'alice@test.com'")
			.get() as { cnt: number };
		expect(remaining.cnt).toBe(0);
	});

	it("deletes contact submissions by the user", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.deletedContactSubmissions).toBe(1);
	});

	it("suspends admin user by default", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com");
		expect(result.adminUserAction).toBe("suspended");
		const row = db
			.prepare("SELECT active FROM admin_users WHERE email = 'alice@test.com'")
			.get() as { active: number };
		expect(row.active).toBe(0);
	});

	it("deletes admin user when deleteAccount: true", () => {
		seedUser(db, "alice@test.com");
		const result = purge.purgeUserData("alice@test.com", {
			deleteAccount: true,
		});
		expect(result.adminUserAction).toBe("deleted");
		const row = db
			.prepare("SELECT COUNT(*) as cnt FROM admin_users WHERE email = 'alice@test.com'")
			.get() as { cnt: number };
		expect(row.cnt).toBe(0);
	});

	it("returns not_found when user does not exist", () => {
		const result = purge.purgeUserData("nobody@test.com");
		expect(result.adminUserAction).toBe("not_found");
		expect(result.revokedSessions).toBe(0);
	});
});

tests/sections/schema.test.ts.source:
import { describe, expect, it } from "vitest";
import { parseSections, parseSectionsFromJson, SECTION_KINDS } from "../../src/sections/schema";

describe("parseSections", () => {
	it("returns empty array for null/undefined input", () => {
		expect(parseSections(null)).toEqual({ ok: true, sections: [] });
		expect(parseSections(undefined)).toEqual({ ok: true, sections: [] });
	});

	it("returns empty array for an empty object", () => {
		expect(parseSections({})).toEqual({ ok: true, sections: [] });
	});

	it("accepts a top-level array", () => {
		const r = parseSections([{ id: "h", kind: "hero", headline: "Hello", alignment: "center" }]);
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(1);
	});

	it("accepts the {sections: [...]} envelope shape", () => {
		const r = parseSections({
			sections: [{ id: "h", kind: "hero", headline: "Hello", alignment: "center" }],
		});
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(1);
	});

	it("rejects an unknown kind with a path-keyed error", () => {
		const r = parseSections([{ id: "x", kind: "weird-kind" }]);
		expect(r.ok).toBe(false);
		if (!r.ok)
			expect(r.errors[0]).toMatchObject({
				path: "$[0].kind",
				message: expect.stringContaining("unknown section kind"),
			});
	});

	it("requires hero.headline", () => {
		const r = parseSections([{ id: "h", kind: "hero", alignment: "start" }]);
		expect(r.ok).toBe(false);
		if (!r.ok)
			expect(r.errors).toContainEqual({
				path: "$[0].headline",
				message: "headline is required",
			});
	});

	it("validates feature-grid item shape", () => {
		const r = parseSections([
			{
				id: "fg",
				kind: "feature-grid",
				heading: "X",
				columns: 3,
				items: [{ title: "ok", body: "" }],
			},
		]);
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors[0].path).toBe("$[0].items[0].body");
	});

	it("normalises invalid columns to 3", () => {
		const r = parseSections([
			{
				id: "fg",
				kind: "feature-grid",
				heading: "X",
				columns: 99,
				items: [],
			},
		]);
		expect(r.ok).toBe(true);
		if (r.ok) {
			const fg = r.sections[0];
			if (fg.kind === "feature-grid") expect(fg.columns).toBe(3);
		}
	});

	it("requires testimonials.ids when source=ids", () => {
		const r = parseSections([{ id: "t", kind: "testimonials", source: "ids", layout: "grid" }]);
		expect(r.ok).toBe(false);
	});

	it("accepts a fully populated landing-page payload", () => {
		const r = parseSections([
			{
				id: "1",
				kind: "hero",
				headline: "H",
				alignment: "center",
				primaryCta: { label: "Go", href: "#" },
			},
			{
				id: "2",
				kind: "feature-grid",
				heading: "Why",
				columns: 3,
				items: [{ title: "T", body: "B" }],
			},
			{
				id: "3",
				kind: "cta-banner",
				headline: "Now",
				primaryCta: { label: "Yes", href: "#" },
				tone: "accent",
			},
			{ id: "4", kind: "rich-text", html: "<p>x</p>" },
		]);
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toHaveLength(4);
	});

	it("covers all eight section kinds in the catalog", () => {
		expect(SECTION_KINDS).toHaveLength(8);
	});

	it("parseSectionsFromJson handles invalid JSON", () => {
		const r = parseSectionsFromJson("{not json");
		expect(r.ok).toBe(false);
		if (!r.ok) expect(r.errors[0].message).toContain("invalid JSON");
	});

	it("parseSectionsFromJson treats empty string as no sections", () => {
		const r = parseSectionsFromJson("");
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.sections).toEqual([]);
	});
});

tests/sqlite-runtime/catalog.test.ts.source:
import { describe, expect, it } from "vitest";

import type { Actor } from "../../src/persistence-types.js";
import { createSqliteCatalogStore } from "../../src/sqlite-runtime/catalog.js";
import { makeDb } from "../helpers/make-db.js";

const actor: Actor = { email: "admin@example.com", role: "admin", name: "Admin" };

describe("createSqliteCatalogStore", () => {
	it("author repository creates a row that listAuthors reads back", () => {
		const db = makeDb();
		const { sqliteAuthorRepository } = createSqliteCatalogStore(() => db);

		const result = sqliteAuthorRepository.createAuthor({ name: "Ada Lovelace" }, actor);
		expect(result.ok).toBe(true);

		expect(sqliteAuthorRepository.listAuthors().map((a) => a.name)).toContain("Ada Lovelace");
	});

	it("author repository returns ok:false when the slug collides (catch branch)", () => {
		const db = makeDb();
		const { sqliteAuthorRepository } = createSqliteCatalogStore(() => db);

		expect(sqliteAuthorRepository.createAuthor({ name: "Ada Lovelace" }, actor).ok).toBe(true);
		// A second insert with the same name slugifies identically; the unique
		// constraint throws and the catch returns false, surfacing as ok:false.
		const dup = sqliteAuthorRepository.createAuthor({ name: "Ada Lovelace" }, actor);
		expect(dup.ok).toBe(false);
	});

	it("taxonomy repository returns ok:false when a category slug collides (catch branch)", () => {
		const db = makeDb();
		const { sqliteTaxonomyRepository } = createSqliteCatalogStore(() => db);

		expect(sqliteTaxonomyRepository.createCategory({ name: "Featured" }, actor).ok).toBe(true);
		const dup = sqliteTaxonomyRepository.createCategory({ name: "Featured" }, actor);
		expect(dup.ok).toBe(false);
	});

	it("author repository update + delete round-trip via id", () => {
		const db = makeDb();
		const { sqliteAuthorRepository } = createSqliteCatalogStore(() => db);

		expect(sqliteAuthorRepository.createAuthor({ name: "Original" }, actor).ok).toBe(true);
		const created = sqliteAuthorRepository.listAuthors()[0];
		expect(created).toBeDefined();
		if (!created) return;

		const upd = sqliteAuthorRepository.updateAuthor(
			{ id: created.id, slug: created.slug, name: "Renamed", bio: "Updated bio" },
			actor,
		);
		expect(upd.ok).toBe(true);
		expect(sqliteAuthorRepository.listAuthors()[0]?.name).toBe("Renamed");

		const del = sqliteAuthorRepository.deleteAuthor(created.id, actor);
		expect(del.ok).toBe(true);
		expect(sqliteAuthorRepository.listAuthors()).toHaveLength(0);
	});

	it("taxonomy repository creates a category that listCategories reads back", () => {
		const db = makeDb();
		const { sqliteTaxonomyRepository } = createSqliteCatalogStore(() => db);

		const result = sqliteTaxonomyRepository.createCategory({ name: "Announcements" }, actor);
		expect(result.ok).toBe(true);

		expect(sqliteTaxonomyRepository.listCategories().map((c) => c.name)).toContain("Announcements");
	});

	it("taxonomy repository creates, lists tags, and deletes them", () => {
		const db = makeDb();
		const { sqliteTaxonomyRepository } = createSqliteCatalogStore(() => db);

		expect(sqliteTaxonomyRepository.createTag({ name: "Featured" }, actor).ok).toBe(true);
		const tag = sqliteTaxonomyRepository.listTags()[0];
		expect(tag?.name).toBe("Featured");
		if (!tag) return;

		const del = sqliteTaxonomyRepository.deleteTag(tag.id, actor);
		expect(del.ok).toBe(true);
		expect(sqliteTaxonomyRepository.listTags()).toHaveLength(0);
	});
});

