import { describe, expect, it, vi } from "vitest";
import type { Actor } from "../src/persistence-types";
import { createAstropressTranslationRepository } from "../src/translation-repository-factory";

const actor: Actor = {
	email: "editor@example.com",
	role: "editor",
	name: "Editor Example",
};

describe("createAstropressTranslationRepository", () => {
	it("rejects invalid translation states", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.updateTranslationState("/about", "wrong", actor)).toEqual({
			ok: false,
			error:
				"Invalid translation state. Must be one of: not_started, partial, fallback_en, translated, reviewed, published",
		});
	});

	it("persists a valid translation state and records audit data", () => {
		const persistTranslationState = vi.fn();
		const recordTranslationAudit = vi.fn();
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(),
			persistTranslationState,
			recordTranslationAudit,
		});

		expect(repository.updateTranslationState("/about", "published", actor)).toEqual({ ok: true });
		expect(persistTranslationState).toHaveBeenCalledWith("/about", "published", actor);
		expect(recordTranslationAudit).toHaveBeenCalledWith({
			actor,
			route: "/about",
			state: "published",
		});
	});

	it("falls back when no translation override exists", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => null),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.getEffectiveTranslationState("/about", "reviewed")).toBe("reviewed");
	});

	it("normalizes the stored translation state", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => "PUBLISHED"),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.getEffectiveTranslationState("/about")).toBe("published");
	});

	it("uses 'not_started' as the default fallback when caller omits the fallback arg", () => {
		// Pins the default-arg StringLiteral: omit fallback, ensure stored value
		// missing → returns "not_started".
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => null),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});
		expect(repository.getEffectiveTranslationState("/about")).toBe("not_started");
	});
});

tests/integration-secret-dump-leak.test..source:
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { readAstropressSqliteSchemaSql } from "../src/sqlite-bootstrap.js";
import { createIntegrationsRepository } from "../src/sqlite-runtime/integrations";

/**
 * Privacy invariant: a sqlite dump of the live database must never
 * contain integration plaintext. Ciphertext is fine; raw API keys
 * are the bug. Mirrors design doc §4.4.
 *
 * Uses an on-disk database (rather than `:memory:`) so we can VACUUM
 * INTO a sibling file and grep its bytes for the canary.
 */

const ROOT = "test-root-current";
const NOW = "2026-05-02T12:00:00.000Z";
const CANARY = "PLAINTEXT-CANARY-DUMP-Q4F7";

let tmp: string;
let dbPath: string;
let db: DatabaseSync;

beforeEach(() => {
	tmp = mkdtempSync(join(tmpdir(), "astropress-secret-dump-"));
	dbPath = join(tmp, "test.db");
	db = new DatabaseSync(dbPath);
	db.exec(readAstropressSqliteSchemaSql());
	db.exec("PRAGMA foreign_keys = ON");
});

afterEach(() => {
	try {
		db.close();
	} catch {
		// already closed
	}
	rmSync(tmp, { recursive: true, force: true });
});

describe("integration_secrets sqlite-dump privacy", () => {
	it("plaintext canary never appears in a VACUUM INTO of the database", async () => {
		const repo = createIntegrationsRepository({
			getDb: () => db as never,
			now: () => NOW,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: '{"baseUrl":"https://example.test"}',
				secretFields: { apiKey: CANARY },
				now: NOW,
			},
			ROOT,
		);

		const dumpPath = join(tmp, "dump.db");
		db.exec(`VACUUM INTO '${dumpPath.replace(/'/g, "''")}'`);

		const bytes = readFileSync(dumpPath);
		const text = bytes.toString("binary");
		expect(text).not.toContain(CANARY);
	});

	it("plaintext canary stays absent after disconnect", async () => {
		const repo = createIntegrationsRepository({
			getDb: () => db as never,
			now: () => NOW,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: CANARY },
				now: NOW,
			},
			ROOT,
		);
		expect(repo.disconnect("newsletter", "listmonk")).toBe(true);

		const dumpPath = join(tmp, "dump-after-disconnect.db");
		db.exec(`VACUUM INTO '${dumpPath.replace(/'/g, "''")}'`);
		const bytes = readFileSync(dumpPath);
		expect(bytes.toString("binary")).not.toContain(CANARY);
	});
});

