import { describe, expect, it } from "vitest";
import {
	listSqliteContentRecords,
	type SqliteActor,
	type SqliteAdminRuntime,
	saveSqlitePageOrPost,
} from "../src/adapters/sqlite-helpers";

const actor: SqliteActor = { email: "a@b.test", role: "admin", name: "A" };

function buildRuntime(content: Record<string, unknown>): SqliteAdminRuntime {
	const empty = () => [];
	return {
		sqliteAdminStore: {
			content,
			redirects: { getRedirectRules: empty },
			comments: { getComments: empty },
			users: { listAdminUsers: empty },
			media: { listMediaAssets: empty },
			settings: { getSettings: () => ({ siteTitle: "" }) },
		},
	} as unknown as SqliteAdminRuntime;
}

describe("listSqliteContentRecords outer kind-filter guard (L21)", () => {
	it("does NOT touch content.listContentStates when kind is non-content", () => {
		let called = false;
		const runtime = buildRuntime({
			listContentStates: () => {
				called = true;
				throw new Error("listContentStates must not be called for kind=redirect");
			},
		});
		listSqliteContentRecords(runtime, (() => {}) as never, "redirect");
		expect(called).toBe(false);
	});

	it("DOES call content.listContentStates when kind is page", () => {
		let called = false;
		const runtime = buildRuntime({
			listContentStates: () => {
				called = true;
				return [];
			},
		});
		listSqliteContentRecords(runtime, (() => {}) as never, "page");
		expect(called).toBe(true);
	});
});

describe("saveSqlitePageOrPost throw guards", () => {
	it("throws result.error when saveContentState returns ok:false (L164 existing-branch guard)", () => {
		const runtime = buildRuntime({
			getContentState: () => ({ title: "x", body: "b", summary: "s" }),
			saveContentState: () => ({ ok: false, error: "SAVE_REJECTED_SENTINEL" }),
		});
		expect(() =>
			saveSqlitePageOrPost(
				runtime,
				"slug-x",
				{ id: "slug-x", kind: "page", slug: "slug-x", status: "published", title: "T" },
				actor,
			),
		).toThrow("SAVE_REJECTED_SENTINEL");
	});

	it("throws result.error when createContentRecord returns ok:false (L183 new-branch guard)", () => {
		const runtime = buildRuntime({
			getContentState: () => null,
			createContentRecord: () => ({ ok: false, error: "CREATE_REJECTED_SENTINEL" }),
		});
		expect(() =>
			saveSqlitePageOrPost(
				runtime,
				"slug-y",
				{ id: "slug-y", kind: "page", slug: "slug-y", status: "published", title: "T" },
				actor,
			),
		).toThrow("CREATE_REJECTED_SENTINEL");
	});
});

tests/access-action-registry.test.ts.source:
import { afterEach, describe, expect, test } from "vitest";

import {
	_resetAccessActionRegistryForTests,
	getAccessAction,
	listAccessActions,
	registerAccessAction,
} from "../src/access";

afterEach(() => {
	_resetAccessActionRegistryForTests();
});

describe("access action registry", () => {
	test("built-in actions are registered at module load", () => {
		const all = listAccessActions();
		expect(all.length).toBeGreaterThan(20);
		expect(getAccessAction("posts:edit")?.pluginId).toBe("core");
		expect(getAccessAction("roles:manage")?.pluginId).toBe("core");
	});

	test("plugin can register a new action", () => {
		registerAccessAction({
			id: "myplugin:doThing",
			description: "Do the thing",
			pluginId: "my-plugin",
		});
		expect(getAccessAction("myplugin:doThing")?.pluginId).toBe("my-plugin");
	});

	test("re-registering same id by same plugin is allowed (idempotent setup)", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "v1",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "v2 (updated)",
				pluginId: "my-plugin",
			}),
		).not.toThrow();
		expect(getAccessAction("myplugin:thing")?.description).toBe("v2 (updated)");
	});

	test("a different plugin cannot hijack an existing action id", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "owned by my-plugin",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "stolen",
				pluginId: "other-plugin",
			}),
		).toThrow(/already registered/);
	});

	test("listAccessActions returns alphabetically sorted IDs", () => {
		const ids = listAccessActions().map((a) => a.id);
		const sorted = [...ids].sort();
		expect(ids).toEqual(sorted);
	});

	test("_resetAccessActionRegistryForTests clears plugin actions and re-seeds built-ins", () => {
		registerAccessAction({
			id: "ephemeral:goAway",
			description: "ephemeral",
			pluginId: "ephemeral-plugin",
		});
		expect(getAccessAction("ephemeral:goAway")).toBeDefined();
		_resetAccessActionRegistryForTests();
		expect(getAccessAction("ephemeral:goAway")).toBeUndefined();
		expect(getAccessAction("posts:edit")?.pluginId).toBe("core");
	});
});

