		expect(result).toEqual({
			ok: true,
			settings: {
				siteTitle: "Acme Corp",
				siteTagline: "Food",
				donationUrl: "/donate",
				newsletterEnabled: false,
				commentsDefaultPolicy: "open-moderated",
				adminSlug: "ap-admin",
