			[
				{
					id: "h",
					kind: "hero",
					headline: "x",
					alignment: "start",
					primaryCta: { label: "Go", href: "/path" },
				},
			],
			ctx,
		);
		expect(html).toContain('href="/path"');
		expect(html).toContain(">Go</a>");
	});

	it("secondary cta link contains both href and label", () => {
