		expect(html).toContain('class="ap-btn ap-btn--secondary"');
	});

	it("hero cta wrapper class is ap-hero__cta when CTAs present", () => {
		const html = renderSectionsDocument(
			[
				{
					id: "h",
					kind: "hero",
					headline: "x",
					alignment: "start",
					primaryCta: { label: "Go", href: "/" },
				},
			],
			ctx,
		);
