import { describe, expect, it } from "vitest";
import { renderSectionsDocument, safeHref } from "../../src/sections/preview-renderer";
import type { Section } from "../../src/sections/schema";

const ctx = { mediaUrls: {}, testimonials: [] };

describe("renderSectionsDocument", () => {
	it("renders an empty document for no sections", () => {
		const html = renderSectionsDocument([], ctx);
		expect(html).toContain("<!doctype html>");
		expect(html).toContain('class="ap-sections"');
	});

	it("includes the stylesheet link when stylesheetUrl is given", () => {
		const html = renderSectionsDocument([], ctx, {
			stylesheetUrl: "/sections.css",
		});
		expect(html).toContain('rel="stylesheet"');
		expect(html).toContain("/sections.css");
	});

	it("renders dir=rtl when context dir is rtl", () => {
		const html = renderSectionsDocument([], { ...ctx, dir: "rtl" });
		expect(html).toContain('dir="rtl"');
	});

	it("escapes HTML in plain-text fields", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: '<img src=x onerror="alert(1)">',
				alignment: "start",
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).not.toMatch(/<img\s+src=x\s+onerror/);
		expect(html).toContain("&lt;img");
	});

	it("renders hero with primary CTA href escaped", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: "Hi",
				alignment: "center",
				primaryCta: { label: "Go", href: 'javascript"' },
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("&quot;");
	});

	it("neutralizes a javascript: CTA href to '#' in rendered output", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: "Hi",
				alignment: "center",
				primaryCta: { label: "Go", href: "javascript:alert(1)" },
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).not.toContain("javascript:alert");
		expect(html).toContain(`href="#"`);
	});

	it("renders rich-text html as-is (sanitization runs at save time)", () => {
		const sections: Section[] = [{ id: "r", kind: "rich-text", html: "<p>preserved</p>" }];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("<p>preserved</p>");
	});
});

describe("safeHref", () => {
	it("passes through safe schemes and relative URLs unchanged", () => {
		for (const href of [
			"/about",
			"#section",
			"?q=1",
			"https://example.com",
			"http://example.com",
			"mailto:a@b.com",
			"tel:+15551234",
			"contact",
		]) {
			expect(safeHref(href)).toBe(href);
		}
	});

	it("collapses script-executing and opaque schemes to '#'", () => {
		expect(safeHref("javascript:alert(1)")).toBe("#");
		expect(safeHref("JavaScript:alert(1)")).toBe("#");
		expect(safeHref("data:text/html,<script>x</script>")).toBe("#");
		expect(safeHref("vbscript:msgbox(1)")).toBe("#");
	});

	it("defeats control-character scheme obfuscation", () => {
		expect(safeHref("java\tscript:alert(1)")).toBe("#");
		expect(safeHref("java\nscript:alert(1)")).toBe("#");
		expect(safeHref(" javascript:alert(1)")).toBe("#");
	});

	it("strips every ignorable control-char class before reading the scheme", () => {
		// Each of these code points is one a browser drops when parsing a scheme,
		// so each must be removed before the allowlist check — pinning the exact
		// boundaries of the cleaning loop (C0, space, DEL, and the C1 range).
		for (const ctrl of ["\x01", "\x1f", "\x7f", "\x80", "\x85", "\x9f"]) {
			expect(safeHref(`java${ctrl}script:alert(1)`), `code point ${ctrl.codePointAt(0)}`).toBe("#");
		}
	});

	it("keeps code points just outside the ignorable range (U+00A0) intact", () => {
		// U+00A0 is above the C1 range, so it is NOT stripped: the value keeps its
		// literal non-breaking space and never reads as a `javascript:` scheme.
		expect(safeHref("java\u00a0script:alert(1)")).toBe("java\u00a0script:alert(1)");
	});

	it("only treats a scheme at the very start of the value as a scheme", () => {
		// The scheme regex is anchored, so a colon inside a relative path is not a
		// scheme and the value passes through unchanged.
		expect(safeHref("/foo:bar")).toBe("/foo:bar");
		expect(safeHref("path/to:file")).toBe("path/to:file");
	});

	it("trims surrounding whitespace from the returned value", () => {
		expect(safeHref("  https://example.com/x  ")).toBe("https://example.com/x");
	});

	it("renders gallery with valid media urls", () => {
		const sections: Section[] = [
			{
				id: "g",
				kind: "gallery",
				mediaIds: ["a", "b"],
				columns: 3,
			},
		];
		const html = renderSectionsDocument(sections, {
			...ctx,
			mediaUrls: { a: "/a.png", b: "/b.png" },
		});
		expect(html).toContain("/a.png");
		expect(html).toContain("/b.png");
	});

	it("falls back to placeholder when image-text mediaId is missing", () => {
		const sections: Section[] = [
			{
				id: "it",
				kind: "image-text",
				heading: "X",
				body: "<p>y</p>",
				mediaId: "missing",
				imageSide: "end",
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		expect(html).toContain("ap-image-text__placeholder");
	});

	it("renders all eight section kinds without throwing", () => {
		const all: Section[] = [
			{ id: "1", kind: "hero", headline: "H", alignment: "start" },
			{
				id: "2",
				kind: "feature-grid",
				heading: "F",
				columns: 3,
				items: [{ title: "t", body: "b" }],
			},
			{ id: "3", kind: "testimonials", source: "approved", layout: "grid" },
			{
				id: "4",
				kind: "cta-banner",
				headline: "Now",
				primaryCta: { label: "X", href: "/" },
				tone: "neutral",
			},
			{
				id: "5",
				kind: "image-text",
				heading: "I",
				body: "<p>b</p>",
				mediaId: "",
				imageSide: "start",
			},
			{ id: "6", kind: "faq", items: [{ question: "q?", answer: "a" }] },
			{ id: "7", kind: "gallery", mediaIds: [], columns: 2 },
			{ id: "8", kind: "rich-text", html: "<p>x</p>" },
		];
		const html = renderSectionsDocument(all, ctx);
		expect(html).toContain("ap-hero");
		expect(html).toContain("ap-feature-grid");
		expect(html).toContain("ap-testimonials");
		expect(html).toContain("ap-cta");
		expect(html).toContain("ap-image-text");
		expect(html).toContain("ap-faq");
		expect(html).toContain("ap-gallery");
		expect(html).toContain("ap-rich-text");
	});
});

describe("render branch guards", () => {
	it("renders an empty primary-cta slot when only a secondary CTA is set", () => {
		const sections: Section[] = [
			{
				id: "h",
				kind: "hero",
				headline: "Hi",
				alignment: "start",
				secondaryCta: { label: "More", href: "/more" },
			},
		];
		const html = renderSectionsDocument(sections, ctx);
		// The primary-cta ternary's empty branch must render nothing between the
		// cta wrapper and the secondary link (kills the `: ""` StringLiteral).
		expect(html).toMatch(/<div class="ap-hero__cta">\s*<a class="ap-btn ap-btn--secondary"/);
	});

	it("uses the featured branch when a non-ids testimonials section carries an ids array", () => {
		const testimonials = [
			{ id: "feat", name: "F", quote: "FEATURED-QUOTE", featured: true, status: "approved" },
			{ id: "plain", name: "P", quote: "PLAIN-QUOTE", featured: false, status: "approved" },
		];
		const sections: Section[] = [
			{
				id: "t",
				kind: "testimonials",
				source: "featured",
				layout: "grid",
				ids: ["plain"],
			} as Section,
		];
		const html = renderSectionsDocument(sections, { ...ctx, testimonials });
		// source=featured must select the featured testimonial, not the ids-listed
		// one (kills `s.source === "ids"` → `true`).
		expect(html).toContain("FEATURED-QUOTE");
		expect(html).not.toContain("PLAIN-QUOTE");
	});
});

tests/sqlite-bootstrap-helpers.test.ts.source:
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { checkpointSqliteWal, loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

// A fully controllable stand-in for the `bun:sqlite` Database class. Setting
// `globalThis.Bun` routes loadSqliteDatabase() through the Bun branch so tests
// can drive checkpointSqliteWal's database interactions deterministically.
const { fakeBunDatabase, bunDbState } = vi.hoisted(() => {
	const bunDbState = {
		// Value returned by `PRAGMA wal_checkpoint(TRUNCATE)`.get()
		pragmaRow: { log: 0, checkpointed: 1 } as { log: number; checkpointed: number } | null,
		throwOnConstruct: false,
		// When true, the `bun:sqlite` mock factory throws — making the dynamic
		// import (and therefore loadSqliteDatabase) reject.
		importThrows: false,
		closeCalls: 0,
	};
	class FakeBunDatabase {
		constructor(public readonly filename: string) {
			if (bunDbState.throwOnConstruct) {
				throw new Error(`cannot open ${filename}`);
			}
		}
		prepare(_sql: string) {
			return {
				get: () => bunDbState.pragmaRow,
				run: () => ({}),
				all: () => [],
			};
		}
		exec() {}
		close() {
			bunDbState.closeCalls += 1;
		}
	}
	return { fakeBunDatabase: FakeBunDatabase, bunDbState };
});

vi.mock("bun:sqlite", () => ({
	// A getter so each access can be toggled to throw — accessing `m.Database`
	// inside loadSqliteDatabase then makes that function's promise reject.
	get Database() {
		if (bunDbState.importThrows) {
			throw new Error("bun:sqlite Database unavailable");
		}
		return fakeBunDatabase;
	},
}));

let testRoot: string;

beforeEach(() => {
	testRoot = mkdtempSync(join(tmpdir(), "astropress-helpers-test-"));
	bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
	bunDbState.throwOnConstruct = false;
	bunDbState.importThrows = false;
	bunDbState.closeCalls = 0;
});

afterEach(() => {
	rmSync(testRoot, { recursive: true, force: true });
	delete (globalThis as { Bun?: unknown }).Bun;
	vi.resetModules();
});

describe("loadSqliteDatabase", () => {
	it("returns a constructor that can open an in-memory database", async () => {
		const DbClass = await loadSqliteDatabase();
		const db = new DbClass(":memory:");
		db.exec("CREATE TABLE t (id INTEGER PRIMARY KEY)");
		db.prepare("INSERT INTO t VALUES (1)").run();
		const row = db.prepare("SELECT id FROM t").get() as { id: number };
		expect(row.id).toBe(1);
		db.close();
	});

	it("returns the node:sqlite DatabaseSync constructor when not running under Bun", async () => {
		// Pins the node branch: a non-Bun runtime must resolve to node:sqlite's
		// DatabaseSync, never the bun:sqlite stub.
		expect("Bun" in globalThis).toBe(false);
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).not.toBe(fakeBunDatabase);
		expect(DbClass.name).toBe("DatabaseSync");
	});

	it("returns the bun:sqlite Database constructor when running under Bun", async () => {
		// Pins the `"Bun" in globalThis` guard and the `bun:sqlite` import: with
		// Bun present, loadSqliteDatabase must resolve to bun:sqlite's Database.
		(globalThis as { Bun?: unknown }).Bun = {};
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).toBe(fakeBunDatabase);
	});
});

describe("checkpointSqliteWal", () => {
	it("returns true and emits no warning for a real WAL-mode SQLite file", async () => {
		const DbClass = await loadSqliteDatabase();
		const dbPath = join(testRoot, "real.sqlite");

		// Create a real SQLite DB in WAL mode with some data
		const db = new DbClass(dbPath);
		db.prepare("PRAGMA journal_mode = WAL").get();
		db.exec("CREATE TABLE items (id INTEGER PRIMARY KEY, val TEXT)");
		db.prepare("INSERT INTO items VALUES (1, 'hello')").run();
		db.close();

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(dbPath, (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("returns false and warns when the file is not a valid SQLite database", async () => {
		const badPath = join(testRoot, "bad.sqlite");
		writeFileSync(badPath, "this is not sqlite", "utf8");

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(badPath, (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("bad.sqlite");
	});

	it("returns false (not a rejection) when the driver constructor itself throws on an unopenable path", async () => {
		// Path under a non-existent directory makes node:sqlite throw inside
		// `new DatabaseSync(path)` synchronously, leaving `db` undefined inside
		// the checkpoint helper. The finally block must still resolve cleanly —
		// `db?.close()`'s optional chain is load-bearing here.
		const unopenablePath = join(testRoot, "no-such-dir", "db.sqlite");

		const warnings: string[] = [];
		await expect(checkpointSqliteWal(unopenablePath, (msg) => warnings.push(msg))).resolves.toBe(
			false,
		);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("WAL checkpoint failed");
	});

	it("warns and returns false when loadSqliteDatabase rejects", async () => {
		// Drives the first catch block: with Bun present but `bun:sqlite`'s
		// Database export unresolvable, loadSqliteDatabase rejects and
		// checkpointSqliteWal must emit the "checkpoint skipped" warning.
		bunDbState.importThrows = true;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/skipme.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(1);
		expect(warnings[0]).toContain("SQLite WAL checkpoint skipped for /tmp/skipme.sqlite");
	});

	it("returns false without warning when the WAL is not fully flushed (log > 0)", async () => {
		// Pins `row.log === 0`: a non-zero log page count means the checkpoint
		// did not fully truncate, so the helper must report false — and must NOT
		// warn (no error occurred, the WAL simply wasn't fully flushed).
		bunDbState.pragmaRow = { log: 3, checkpointed: 0 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/partial.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns false without warning when the checkpoint pragma yields no row", async () => {
		// Pins `row != null`: a null pragma result must short-circuit to false
		// without dereferencing `row.log` (which would throw and warn).
		bunDbState.pragmaRow = null;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/norow.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns true when the WAL is fully flushed (log === 0)", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 5 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/clean.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("closes the database in the finally block after a successful checkpoint", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
		(globalThis as { Bun?: unknown }).Bun = {};

		await checkpointSqliteWal("/tmp/closeme.sqlite", () => {});

		expect(bunDbState.closeCalls).toBe(1);
	});
});

tests/services-config.test.ts.source:
import { beforeEach, describe, expect, it } from "vitest";
import {
	type AstropressServiceConfig,
	clearAstropressServices,
	getAstropressService,
	getAstropressServices,
	registerAstropressService,
	registerTestimonialsServiceIfConfigured,
	unregisterAstropressService,
} from "../src/services-config";

const cmsService: AstropressServiceConfig = {
	provider: "cms",
	label: "Payload CMS",
	description: "Open-source TypeScript CMS.",
	proxyTarget: "http://localhost:3000",
	adminPath: "/ap-admin/services/cms",
};

const shopService: AstropressServiceConfig = {
	provider: "shop",
	label: "Medusa",
	description: "Open-source headless commerce.",
	proxyTarget: "http://localhost:9000",
	adminPath: "/ap-admin/services/shop",
};

beforeEach(() => {
	clearAstropressServices();
});

describe("registerAstropressService", () => {
	it("registers a service and makes it retrievable", () => {
		registerAstropressService(cmsService);
		expect(getAstropressService("cms")).toEqual(cmsService);
	});

	it("replaces an existing service with the same provider", () => {
		registerAstropressService(cmsService);
		const updated = { ...cmsService, label: "Payload v3" };
		registerAstropressService(updated);
		expect(getAstropressService("cms")?.label).toBe("Payload v3");
		expect(getAstropressServices()).toHaveLength(1);
	});

	it("registers multiple services independently", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		expect(getAstropressServices()).toHaveLength(2);
	});
});

describe("getAstropressServices", () => {
	it("returns an empty array when no services are registered", () => {
		expect(getAstropressServices()).toEqual([]);
	});

	it("returns a copy so callers cannot mutate the registry", () => {
		registerAstropressService(cmsService);
		const list = getAstropressServices();
		list.pop();
		expect(getAstropressServices()).toHaveLength(1);
	});

	it("preserves registration order", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		const [first, second] = getAstropressServices();
		expect(first.provider).toBe("cms");
		expect(second.provider).toBe("shop");
	});
});

describe("getAstropressService", () => {
	it("returns undefined for an unregistered provider", () => {
		expect(getAstropressService("email")).toBeUndefined();
	});

	it("finds a registered service by provider key", () => {
		registerAstropressService(shopService);
		expect(getAstropressService("shop")?.label).toBe("Medusa");
	});
});

describe("unregisterAstropressService", () => {
	it("removes a specific service", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		unregisterAstropressService("cms");
		expect(getAstropressService("cms")).toBeUndefined();
		expect(getAstropressService("shop")).toBeDefined();
	});

	it("is a no-op for a provider that was never registered", () => {
		expect(() => unregisterAstropressService("community")).not.toThrow();
	});
});

describe("clearAstropressServices", () => {
	it("removes all registered services", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		clearAstropressServices();
		expect(getAstropressServices()).toEqual([]);
	});
});

describe("registerTestimonialsServiceIfConfigured", () => {
	it("is a no-op when url is absent", () => {
		registerTestimonialsServiceIfConfigured({ type: "typebot" });
		expect(getAstropressService("testimonials")).toBeUndefined();
	});

	it("is a no-op when url is empty string", () => {
		registerTestimonialsServiceIfConfigured({ type: "typebot", url: "" });
		expect(getAstropressService("testimonials")).toBeUndefined();
	});

	it("registers a typebot service with the typebot label and description when url is set", () => {
		registerTestimonialsServiceIfConfigured({
			type: "typebot",
			url: "http://localhost:8080",
		});
		const svc = getAstropressService("testimonials");
		expect(svc?.label).toBe("Typebot");
		expect(svc?.description).toBe("Conversational testimonial and referral capture flows.");
		expect(svc?.proxyTarget).toBe("http://localhost:8080");
		expect(svc?.adminPath).toBe("/ap-admin/services/testimonials");
	});

	it("registers a non-typebot type with the Formbricks label and description", () => {
		registerTestimonialsServiceIfConfigured({
			type: "formbricks",
			url: "http://localhost:9000",
		});
		const svc = getAstropressService("testimonials");
		expect(svc?.label).toBe("Formbricks");
		expect(svc?.description).toBe("Survey and testimonial collection with referral support.");
	});

	it("uses the explicit label when provided, regardless of type", () => {
		registerTestimonialsServiceIfConfigured({
			type: "typebot",
			url: "http://localhost:8080",
			label: "My Custom Label",
		});
		expect(getAstropressService("testimonials")?.label).toBe("My Custom Label");
	});
});

tests/redirect-repository-factory.test.t.source:
import { describe, expect, it, vi } from "vitest";
import { createAstropressRedirectRepository } from "../src/redirect-repository-factory";

describe("redirect repository factory", () => {
	it("creates and deletes redirects through package-owned repository assembly", () => {
		const upsertRedirect = vi.fn();
		const markRedirectDeleted = vi.fn(() => true);
		const recordRedirectAudit = vi.fn();

		const repository = createAstropressRedirectRepository({
			getRedirectRules: vi.fn(() => []),
			normalizePath(path) {
				return path.startsWith("/") ? path : `/${path}`;
			},
			getExistingRedirect: vi.fn(() => null),
			upsertRedirect,
			markRedirectDeleted,
			recordRedirectAudit,
		});

		const created = repository.createRedirectRule(
			{
				sourcePath: "legacy",
				targetPath: "/next",
				statusCode: 302,
			},
			{ email: "admin@example.com", role: "admin", name: "Admin" },
		);

		expect(created).toEqual({
			ok: true,
			rule: { sourcePath: "/legacy", targetPath: "/next", statusCode: 302 },
		});
		expect(upsertRedirect).toHaveBeenCalledWith(
			expect.objectContaining({
				sourcePath: "/legacy",
				targetPath: "/next",
				statusCode: 302,
			}),
		);

		const deleted = repository.deleteRedirectRule("legacy", {
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
		});

		expect(deleted).toEqual({ ok: true });
		expect(markRedirectDeleted).toHaveBeenCalledWith("/legacy");
		expect(recordRedirectAudit).toHaveBeenCalledWith(
			expect.objectContaining({
				action: "redirect.delete",
				targetId: "/legacy",
			}),
		);
	});
});

tests/import/fetch-wordpress.test.ts.source:
import { beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// Playwright mock
// ---------------------------------------------------------------------------

type MockPage = {
	goto: ReturnType<typeof vi.fn>;
	fill: ReturnType<typeof vi.fn>;
	click: ReturnType<typeof vi.fn>;
	waitForURL: ReturnType<typeof vi.fn>;
	url: ReturnType<typeof vi.fn>;
	locator: ReturnType<typeof vi.fn>;
	waitForSelector: ReturnType<typeof vi.fn>;
	waitForEvent: ReturnType<typeof vi.fn>;
	content: ReturnType<typeof vi.fn>;
};

const mocks = vi.hoisted(() => {
	const page: MockPage = {
		goto: vi.fn(),
		fill: vi.fn(),
		click: vi.fn(),
		waitForURL: vi.fn(),
		url: vi.fn(),
		locator: vi.fn(),
		waitForSelector: vi.fn(),
		waitForEvent: vi.fn(),
		content: vi.fn(),
	};

	const context = {
		newPage: vi.fn().mockResolvedValue(page),
		close: vi.fn(),
	};

	const browser = {
		newContext: vi.fn().mockResolvedValue(context),
		close: vi.fn(),
	};

	return { page, context, browser };
});

vi.mock("playwright", () => ({
	chromium: {
		launch: vi.fn().mockResolvedValue(mocks.browser),
	},
}));

import { chromium } from "playwright";
import {
	BotDetectionError,
	CaptchaDetectedError,
	fetchWordPressExport,
	InsufficientPermissionsError,
	InvalidCredentialsError,
	NotWordPressSiteError,
	SiteNotReachableError,
	TwoFactorRequiredError,
} from "../../src/import/fetch-wordpress.js";

const BASE_OPTS = {
	siteUrl: "https://mysite.com",
	username: "admin",
	password: "secret",
	downloadDir: "/tmp/wp-downloads",
};

function makeLocator(opts: { count?: number; exists?: boolean } = {}) {
	return {
		count: vi.fn().mockResolvedValue(opts.count ?? 0),
		first: vi.fn().mockReturnThis(),
		click: vi.fn(),
		waitFor: vi.fn(),
	};
}

function setupBrowserChain() {
	vi.mocked(chromium.launch).mockResolvedValue(mocks.browser as never);
	mocks.browser.newContext.mockResolvedValue(mocks.context);
	mocks.context.newPage.mockResolvedValue(mocks.page);
	// Safe defaults — individual tests can override
	mocks.page.content.mockResolvedValue("<html></html>");
	mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
	mocks.page.locator.mockReturnValue(makeLocator({ count: 0 }));
	mocks.page.goto.mockResolvedValue({ status: () => 200 });
}

describe("fetchWordPressExport — success path", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();

		// goto succeeds
		mocks.page.goto.mockResolvedValue({ status: () => 200 });

		// login page looks like WordPress
		mocks.page.content.mockResolvedValue(
			'<html><body><form id="loginform"><input id="user_login" /><input id="user_pass" /></form></body></html>',
		);

		// after login submit, URL changes to dashboard (not still on login page)
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");

		// export page: no 2FA, no CAPTCHA, has export link
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel.includes("two-factor") || sel.includes("mfa") || sel.includes("captcha")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});

		// download event
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "wordpress-export.xml",
			saveAs: vi.fn(),
		});
	});

	it("navigates to wp-login.php, fills credentials, and submits", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.goto).toHaveBeenCalledWith(
			expect.stringContaining("wp-login.php"),
			expect.any(Object),
		);
		expect(mocks.page.fill).toHaveBeenCalledWith("#user_login", "admin");
		expect(mocks.page.fill).toHaveBeenCalledWith("#user_pass", "secret");
		expect(mocks.page.click).toHaveBeenCalledWith("#wp-submit");
	});

	it("returns the path to the downloaded export file with an empty warnings array", async () => {
		const result = await fetchWordPressExport(BASE_OPTS);
		expect(result.exportPath).toContain("wordpress-export.xml");
		expect(result.warnings).toEqual([]);
	});

	it("navigates to wp-admin/export.php with timeout + waitUntil:'domcontentloaded'", async () => {
		await fetchWordPressExport(BASE_OPTS);
		const exportCall = mocks.page.goto.mock.calls.find(
			([url]) => typeof url === "string" && url.endsWith("/wp-admin/export.php"),
		);
		expect(exportCall).toBeDefined();
		expect(exportCall?.[0]).toBe("https://mysite.com/wp-admin/export.php");
		expect(exportCall?.[1]).toMatchObject({
			timeout: expect.any(Number),
			waitUntil: "domcontentloaded",
		});
	});

	it("does NOT click submit when the #submit locator's count is 0 (download still proceeds via waitForEvent)", async () => {
		const submitLocator = makeLocator({ count: 0 });
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel === "#submit") return submitLocator;
			if (sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});
		await fetchWordPressExport(BASE_OPTS);
		expect(submitLocator.click).not.toHaveBeenCalled();
	});

	it("requests the page's #submit locator AND clicks it when the count is > 0", async () => {
		const submitLocator = makeLocator({ count: 1 });
		// Override the locator implementation so we can spy on the #submit locator specifically
		// while still returning count=0 for 2FA selectors.
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel === "#submit") return submitLocator;
			if (sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.locator).toHaveBeenCalledWith("#submit");
		expect(submitLocator.click).toHaveBeenCalled();
	});

	it("waits for the 'download' event with a timeout option", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.waitForEvent).toHaveBeenCalledWith(
			"download",
			expect.objectContaining({ timeout: expect.any(Number) }),
		);
	});

	it("creates the browser context with acceptDownloads enabled", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.browser.newContext).toHaveBeenCalledWith({ acceptDownloads: true });
	});

	it("closes the browser even on success", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.browser.close).toHaveBeenCalled();
	});
});

describe("fetchWordPressExport — failure modes", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("throws SiteNotReachableError when goto fails with network error", async () => {
		mocks.page.goto.mockRejectedValue(
			Object.assign(new Error("net::ERR_NAME_NOT_RESOLVED"), { name: "Error" }),
		);
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(SiteNotReachableError);
	});

	it("SiteNotReachableError message names the hostname", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED mysite.com"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: DNS lookup failed",
		);
	});

	it("throws NotWordPressSiteError when wp-login.php is not found", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 404 });
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(NotWordPressSiteError);
	});

	it("throws NotWordPressSiteError with clear message", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 404 });
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"does not appear to be a WordPress site",
		);
	});

	it("throws InvalidCredentialsError when still on login page after submit", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<html><body><div id="login_error">Error: The password you entered</div><form id="loginform"></form></body></html>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(InvalidCredentialsError);
	});

	it("InvalidCredentialsError has a clear human-readable message", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<form id="loginform"><div id="login_error">wrong</div></form>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Login failed: username or password was incorrect",
		);
	});

	it("throws TwoFactorRequiredError when 2FA form is detected", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel.includes("two-factor") || sel.includes("authcode")) {
				return makeLocator({ count: 1 });
			}
			return makeLocator({ count: 0 });
		});

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(TwoFactorRequiredError);
	});

	it("TwoFactorRequiredError message tells user to use --source instead", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({ count: sel.includes("authcode") ? 1 : 0 }),
		);

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Two-factor authentication is required",
		);
	});

	it("throws CaptchaDetectedError when login page has CAPTCHA", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<html><form id="loginform"><div class="g-recaptcha"></div></form></html>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(CaptchaDetectedError);
	});

	it("throws InsufficientPermissionsError when export.php redirects back to login", async () => {
		mocks.page.goto
			.mockResolvedValueOnce({ status: () => 200 }) // wp-login.php
			.mockResolvedValueOnce({ status: () => 200 }); // export.php redirects
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url
			.mockReturnValueOnce("https://mysite.com/wp-admin/") // after login
			.mockReturnValueOnce("https://mysite.com/wp-login.php"); // after navigating to export
		mocks.page.locator.mockReturnValue(makeLocator({ count: 0 }));

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(
			InsufficientPermissionsError,
		);
	});

	it("always closes the browser even when an error is thrown", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow();
		expect(mocks.browser.close).toHaveBeenCalled();
	});
});

// ---------------------------------------------------------------------------
// Exact error-class name and message assertions (kill StringLiteral mutants
// on `override name` and the constructor super(...) messages).
// ---------------------------------------------------------------------------

describe("typed Error classes — exact name and message", () => {
	it("SiteNotReachableError has name='SiteNotReachableError' and the documented hostname:reason format", () => {
		const err = new SiteNotReachableError("example.com", "boom");
		expect(err.name).toBe("SiteNotReachableError");
		expect(err.message).toBe("Cannot reach example.com: boom");
	});

	it("NotWordPressSiteError has name='NotWordPressSiteError' and references the URL with the documented message", () => {
		const err = new NotWordPressSiteError("https://x.test");
		expect(err.name).toBe("NotWordPressSiteError");
		expect(err.message).toBe(
			"The URL does not appear to be a WordPress site — wp-login.php was not found at https://x.test",
		);
	});

	it("InvalidCredentialsError has name='InvalidCredentialsError' and the documented message", () => {
		const err = new InvalidCredentialsError();
		expect(err.name).toBe("InvalidCredentialsError");
		expect(err.message).toBe("Login failed: username or password was incorrect");
	});

	it("TwoFactorRequiredError has name='TwoFactorRequiredError' and the documented message", () => {
		const err = new TwoFactorRequiredError();
		expect(err.name).toBe("TwoFactorRequiredError");
		expect(err.message).toBe(
			"Two-factor authentication is required — export the file manually and use --source",
		);
	});

	it("CaptchaDetectedError has name='CaptchaDetectedError' and both documented lines of guidance", () => {
		const err = new CaptchaDetectedError();
		expect(err.name).toBe("CaptchaDetectedError");
		expect(err.message).toContain("CAPTCHA detected — the site requires human verification.");
		expect(err.message).toContain(
			"Export the file manually via Tools → Export in your WordPress dashboard and use --source.",
		);
	});

	it("BotDetectionError has name='BotDetectionError' and both documented lines of guidance", () => {
		const err = new BotDetectionError();
		expect(err.name).toBe("BotDetectionError");
		expect(err.message).toContain(
			"Bot detection triggered (Cloudflare or similar security layer).",
		);
		expect(err.message).toContain(
			"Export the file manually via Tools → Export in your WordPress dashboard and use --source.",
		);
	});

	it("InsufficientPermissionsError has name='InsufficientPermissionsError' and both documented lines of guidance", () => {
		const err = new InsufficientPermissionsError();
		expect(err.name).toBe("InsufficientPermissionsError");
		expect(err.message).toContain("Insufficient permissions");
		expect(err.message).toContain(
			"Log into WordPress, go to Users → Your Profile, and confirm the role is Administrator.",
		);
	});
});

// ---------------------------------------------------------------------------
// classifyNetworkError — exercised via fetchWordPressExport with goto rejections
// ---------------------------------------------------------------------------

describe("classifyNetworkError (via goto rejection)", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("classifies ERR_CONNECTION_REFUSED as the documented 'connection refused' reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_CONNECTION_REFUSED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: connection refused — is the site running?",
		);
	});

	it("classifies ERR_CERT_* / SSL / certificate errors as the documented SSL reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_CERT_AUTHORITY_INVALID"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: SSL/TLS error — try using http:// instead of https://",
		);
	});

	it("classifies TIMEOUT errors (case-insensitive) as the documented timed-out reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("Navigation TIMEOUT exceeded"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: timed out — the server took too long to respond",
		);
	});

	it("classifies EAI_AGAIN as the documented DNS-lookup-failed reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("getaddrinfo EAI_AGAIN mysite.com"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: DNS lookup failed — check the site URL is correct",
		);
	});

	it("falls back to the raw error message verbatim when no classifier matches", async () => {
		mocks.page.goto.mockRejectedValue(new Error("strange unknown problem"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: strange unknown problem",
		);
	});

	it("stringifies non-Error rejection values via String(err)", async () => {
		mocks.page.goto.mockRejectedValue("plain-string-rejection");
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: plain-string-rejection",
		);
	});
});

// ---------------------------------------------------------------------------
// isBotBlocked — every cf-* token triggers BotDetectionError independently
// ---------------------------------------------------------------------------

describe("isBotBlocked (via login-page content)", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");
	});

	const tokens = [
		"cf-browser-verification",
		"cf-challenge",
		"cf-spinner",
		"window._cf_chl_opt",
		"__cf_chl_jschl_tk__",
	];
	for (const token of tokens) {
		it(`throws BotDetectionError when the login page contains '${token}' (NOT CaptchaDetectedError)`, async () => {
			mocks.page.content.mockResolvedValue(
				`<html><body><form id="loginform"></form><script>${token}</script></body></html>`,
			);
			await expect(fetchWordPressExport({ ...BASE_OPTS, headless: false })).rejects.toBeInstanceOf(
				BotDetectionError,
			);
		});
	}
});

// ---------------------------------------------------------------------------
// Public API — headless retry semantics
// ---------------------------------------------------------------------------

describe("fetchWordPressExport — headless retry on bot detection", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("with headless=false explicit, skips the headless attempt and runs visible-only", async () => {
		const launch = vi.mocked(chromium.launch);
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<form id="loginform"></form>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({
				count:
					sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor") ? 0 : 1,
			}),
		);
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "x.xml",
			saveAs: vi.fn(),
		});

		await fetchWordPressExport({ ...BASE_OPTS, headless: false });
		// Single launch with headless: false — no headless first-pass.
		expect(launch).toHaveBeenCalledTimes(1);
		expect(launch).toHaveBeenCalledWith({ headless: false });
	});

	it("retries with headless=false after a headless BotDetectionError, and writes the documented stderr notice", async () => {
		const launch = vi.mocked(chromium.launch);
		// Both attempts succeed past initial nav; the FIRST attempt's content trips bot detection.
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		const captchaContent = '<form id="loginform"></form><script>cf-challenge</script>';
		const cleanContent = '<form id="loginform"></form>';
		// First call (headless pass): bot-blocked content
		// Subsequent calls (visible retry): clean content
		mocks.page.content.mockResolvedValueOnce(captchaContent).mockResolvedValue(cleanContent);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({
				count:
					sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor") ? 0 : 1,
			}),
		);
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "x.xml",
			saveAs: vi.fn(),
		});

		const stderrWrite = vi.spyOn(process.stderr, "write").mockReturnValue(true);
		await fetchWordPressExport(BASE_OPTS);

		expect(launch).toHaveBeenCalledTimes(2);
		expect(launch).toHaveBeenNthCalledWith(1, { headless: true });
		expect(launch).toHaveBeenNthCalledWith(2, { headless: false });

		const allWrites = stderrWrite.mock.calls.map((c) => String(c[0])).join("");
		expect(allWrites).toContain(
			"[astropress] Bot detection or CAPTCHA triggered in headless mode.",
		);
		expect(allWrites).toContain(
			"[astropress] Opening a visible browser — please solve any challenge that appears,",
		);
		expect(allWrites).toContain("[astropress] then the export will continue automatically.");
		stderrWrite.mockRestore();
	});

	it("does NOT retry when the headless attempt throws a non-bot-detection error", async () => {
		const launch = vi.mocked(chromium.launch);
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(SiteNotReachableError);
		expect(launch).toHaveBeenCalledTimes(1);
	});
});

