import { describe, expect, it, vi } from "vitest";
import { createAstropressCmsRouteRegistry } from "../src/cms-route-registry-factory";

const actor = {
	email: "admin@example.com",
	role: "admin" as const,
	name: "Admin",
};

describe("createAstropressCmsRouteRegistry", () => {
	it("saves a system route through injected persistence", () => {
		const persistSystemRoute = vi.fn();
		const appendSystemRouteRevision = vi.fn();
		const recordRouteAudit = vi.fn();
		const registry = createAstropressCmsRouteRegistry({
			normalizePath: (pathname) => (pathname.startsWith("/") ? pathname : `/${pathname}`),
			localeFromPath: () => "en",
			listSystemRoutes: () => [],
			getSystemRoute: () => null,
			listStructuredPageRoutes: () => [],
			getStructuredPageRoute: () => null,
			getArchiveRoute: () => null,
			listArchiveRoutes: () => [],
			findSystemRouteForUpdate: () => ({
				id: "route-1",
				renderStrategy: "generated_text",
			}),
			persistSystemRoute,
			appendSystemRouteRevision,
			isRoutePathTaken: () => false,
			findStructuredRouteForUpdate: () => null,
			insertStructuredRoute: vi.fn(),
			persistStructuredRoute: vi.fn(),
			appendStructuredRouteRevision: vi.fn(),
			findArchiveRouteForUpdate: () => null,
			persistArchiveRoute: vi.fn(),
			appendArchiveRouteRevision: vi.fn(),
			recordRouteAudit,
		});

		const result = registry.saveSystemRoute("/about", { title: "About", summary: "Body" }, actor);
		expect(result.ok).toBe(true);
		expect(persistSystemRoute).toHaveBeenCalled();
		expect(appendSystemRouteRevision).toHaveBeenCalled();
		expect(recordRouteAudit).toHaveBeenCalled();
	});

	it("creates a structured page route", () => {
		const insertStructuredRoute = vi.fn();
		const appendStructuredRouteRevision = vi.fn();
		const registry = createAstropressCmsRouteRegistry({
			normalizePath: (pathname) => (pathname.startsWith("/") ? pathname : `/${pathname}`),
			localeFromPath: () => "en",
			listSystemRoutes: () => [],
			getSystemRoute: () => null,
			listStructuredPageRoutes: () => [],
			getStructuredPageRoute: () => ({
				path: "/programs",
				title: "Programs",
				templateKey: "content",
				alternateLinks: [],
				sections: null,
			}),
			getArchiveRoute: () => null,
			listArchiveRoutes: () => [],
			findSystemRouteForUpdate: () => null,
			persistSystemRoute: vi.fn(),
			appendSystemRouteRevision: vi.fn(),
			isRoutePathTaken: () => false,
			findStructuredRouteForUpdate: () => ({ id: "route-2" }),
			insertStructuredRoute,
			persistStructuredRoute: vi.fn(),
			appendStructuredRouteRevision,
			findArchiveRouteForUpdate: () => null,
			persistArchiveRoute: vi.fn(),
			appendArchiveRouteRevision: vi.fn(),
			recordRouteAudit: vi.fn(),
		});

		const result = registry.createStructuredPageRoute(
			"/programs",
			{ title: "Programs", templateKey: "content" },
			actor,
		);
		expect(result.ok).toBe(true);
		expect(insertStructuredRoute).toHaveBeenCalled();
		expect(appendStructuredRouteRevision).toHaveBeenCalled();
	});

	it("saves an archive route", () => {
		const persistArchiveRoute = vi.fn();
		const appendArchiveRouteRevision = vi.fn();
		const registry = createAstropressCmsRouteRegistry({
			normalizePath: (pathname) => (pathname.startsWith("/") ? pathname : `/${pathname}`),
			localeFromPath: () => "en",
			listSystemRoutes: () => [],
			getSystemRoute: () => null,
			listStructuredPageRoutes: () => [],
			getStructuredPageRoute: () => null,
			getArchiveRoute: () => ({ path: "/blog", title: "Blog" }),
			listArchiveRoutes: () => [],
			findSystemRouteForUpdate: () => null,
			persistSystemRoute: vi.fn(),
			appendSystemRouteRevision: vi.fn(),
			isRoutePathTaken: () => false,
			findStructuredRouteForUpdate: () => null,
			insertStructuredRoute: vi.fn(),
			persistStructuredRoute: vi.fn(),
			appendStructuredRouteRevision: vi.fn(),
			findArchiveRouteForUpdate: () => ({ id: "route-3" }),
			persistArchiveRoute,
			appendArchiveRouteRevision,
			recordRouteAudit: vi.fn(),
		});

		const result = registry.saveArchiveRoute("/blog", { title: "Blog" }, actor);
		expect(result.ok).toBe(true);
		expect(persistArchiveRoute).toHaveBeenCalled();
		expect(appendArchiveRouteRevision).toHaveBeenCalled();
	});

	function makeReadOnlyRegistry(overrides: Record<string, unknown> = {}) {
		const normalizePath = vi.fn((p: string) => (p.startsWith("/") ? p : `/${p}`) as string);
		const base = {
			normalizePath,
			localeFromPath: () => "en",
			listSystemRoutes: vi.fn(() => [{ path: "/about" }]),
			getSystemRoute: vi.fn(() => ({ path: "/about", title: "About" })),
			listStructuredPageRoutes: vi.fn(() => [{ path: "/programs" }]),
			getStructuredPageRoute: vi.fn(() => ({ path: "/programs" })),
			getArchiveRoute: vi.fn(() => ({ path: "/blog", title: "Blog" })),
			listArchiveRoutes: vi.fn(() => [{ path: "/blog" }]),
			findSystemRouteForUpdate: () => null,
			persistSystemRoute: vi.fn(),
			appendSystemRouteRevision: vi.fn(),
			isRoutePathTaken: () => false,
			findStructuredRouteForUpdate: () => null,
			insertStructuredRoute: vi.fn(),
			persistStructuredRoute: vi.fn(),
			appendStructuredRouteRevision: vi.fn(),
			findArchiveRouteForUpdate: () => null,
			persistArchiveRoute: vi.fn(),
			appendArchiveRouteRevision: vi.fn(),
			recordRouteAudit: vi.fn(),
			...overrides,
		} as never;
		return { input: base, registry: createAstropressCmsRouteRegistry(base) };
	}

	it("listSystemRoutes forwards to input.listSystemRoutes", () => {
		const { input, registry } = makeReadOnlyRegistry();
		expect(registry.listSystemRoutes()).toEqual([{ path: "/about" }]);
		expect(
			(input as { listSystemRoutes: ReturnType<typeof vi.fn> }).listSystemRoutes,
		).toHaveBeenCalled();
	});

	it("getSystemRoute normalizes the path before delegating", () => {
		const { input, registry } = makeReadOnlyRegistry();
		const result = registry.getSystemRoute("about");
		expect(result).toEqual({ path: "/about", title: "About" });
		const i = input as {
			normalizePath: ReturnType<typeof vi.fn>;
			getSystemRoute: ReturnType<typeof vi.fn>;
		};
		expect(i.normalizePath).toHaveBeenCalledWith("about");
		expect(i.getSystemRoute).toHaveBeenCalledWith("/about");
	});

	it("listStructuredPageRoutes forwards verbatim", () => {
		const { input, registry } = makeReadOnlyRegistry();
		expect(registry.listStructuredPageRoutes()).toEqual([{ path: "/programs" }]);
		expect(
			(input as { listStructuredPageRoutes: ReturnType<typeof vi.fn> }).listStructuredPageRoutes,
		).toHaveBeenCalled();
	});

	it("getStructuredPageRoute normalizes the path before delegating", () => {
		const { input, registry } = makeReadOnlyRegistry();
		expect(registry.getStructuredPageRoute("programs")).toEqual({
			path: "/programs",
		});
		const i = input as {
			normalizePath: ReturnType<typeof vi.fn>;
			getStructuredPageRoute: ReturnType<typeof vi.fn>;
		};
		expect(i.normalizePath).toHaveBeenCalledWith("programs");
		expect(i.getStructuredPageRoute).toHaveBeenCalledWith("/programs");
	});

	it("getArchiveRoute normalizes the path before delegating", () => {
		const { input, registry } = makeReadOnlyRegistry();
		expect(registry.getArchiveRoute("blog")).toEqual({
			path: "/blog",
			title: "Blog",
		});
		const i = input as {
			normalizePath: ReturnType<typeof vi.fn>;
			getArchiveRoute: ReturnType<typeof vi.fn>;
		};
		expect(i.normalizePath).toHaveBeenCalledWith("blog");
		expect(i.getArchiveRoute).toHaveBeenCalledWith("/blog");
	});

	it("listArchiveRoutes forwards verbatim", () => {
		const { input, registry } = makeReadOnlyRegistry();
		expect(registry.listArchiveRoutes()).toEqual([{ path: "/blog" }]);
		expect(
			(input as { listArchiveRoutes: ReturnType<typeof vi.fn> }).listArchiveRoutes,
		).toHaveBeenCalled();
	});

	it("saveStructuredPageRoute persists through doSaveStructuredPageRoute", () => {
		const persistStructuredRoute = vi.fn();
		const appendStructuredRouteRevision = vi.fn();
		const recordRouteAudit = vi.fn();
		const { registry } = makeReadOnlyRegistry({
			findStructuredRouteForUpdate: () => ({ id: "route-x" }),
			persistStructuredRoute,
			appendStructuredRouteRevision,
			recordRouteAudit,
		});
		const result = registry.saveStructuredPageRoute(
			"/programs",
			{ title: "Programs", templateKey: "content" },
			actor,
		);
		expect(result.ok).toBe(true);
		expect(persistStructuredRoute).toHaveBeenCalled();
		expect(appendStructuredRouteRevision).toHaveBeenCalled();
	});
});

tests/integrations/oauth/registry.test.t.source:
import { afterEach, describe, expect, it } from "vitest";

import {
	_resetOAuthRegistryForTests,
	getOAuthProvider,
	listOAuthProviders,
	OAuthRegistryError,
	registerOAuthProvider,
} from "../../../src/integrations/oauth/registry";

const GITHUB = {
	id: "github",
	domain: "deploy-hooks" as const,
	label: "GitHub",
	authorizationUrl: "https://github.com/login/oauth/authorize",
	tokenUrl: "https://github.com/login/oauth/access_token",
	scopes: ["repo:status", "read:org"] as const,
	clientIdEnv: "GITHUB_OAUTH_CLIENT_ID",
	clientSecretEnv: "GITHUB_OAUTH_CLIENT_SECRET",
	redirectPath: "/ap-admin/oauth/callback/github",
};

afterEach(() => _resetOAuthRegistryForTests());

describe("registerOAuthProvider", () => {
	it("registers and returns the same definition", () => {
		const r = registerOAuthProvider({ ...GITHUB });
		expect(r).toEqual(GITHUB);
	});

	it("getOAuthProvider returns the registered definition for matching (domain, id)", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("deploy-hooks", "github")).toEqual(GITHUB);
	});

	it("getOAuthProvider returns undefined for the wrong domain even if id matches", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("newsletter", "github")).toBeUndefined();
	});

	it("getOAuthProvider returns undefined for the wrong id even if domain matches", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("deploy-hooks", "gitlab")).toBeUndefined();
	});

	it("rejects duplicate (domain, id) pairs with DUPLICATE_PROVIDER", () => {
		registerOAuthProvider({ ...GITHUB });
		let caught: unknown;
		try {
			registerOAuthProvider({ ...GITHUB });
		} catch (e) {
			caught = e;
		}
		expect(caught).toBeInstanceOf(OAuthRegistryError);
		const err = caught as OAuthRegistryError;
		expect(err.name).toBe("OAuthRegistryError");
		expect(err.code).toBe("DUPLICATE_PROVIDER");
		expect(err.message).toContain("github");
		expect(err.message).toContain("deploy-hooks");
		expect(err.message).toContain("already registered");
	});

	it("allows the same providerId across different domains", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(() => registerOAuthProvider({ ...GITHUB, domain: "newsletter" })).not.toThrow();
	});

	it("listOAuthProviders is domain-scoped", () => {
		registerOAuthProvider({ ...GITHUB });
		registerOAuthProvider({ ...GITHUB, id: "gitlab" });
		registerOAuthProvider({ ...GITHUB, domain: "newsletter", id: "mailchimp" });
		const deploy = listOAuthProviders("deploy-hooks");
		expect(deploy.map((p) => p.id).sort()).toEqual(["github", "gitlab"]);
		const newsletter = listOAuthProviders("newsletter");
		expect(newsletter.map((p) => p.id)).toEqual(["mailchimp"]);
	});

	it("listOAuthProviders returns an empty array for an unregistered domain", () => {
		expect(listOAuthProviders("analytics")).toEqual([]);
	});
});

tests/provider-targets.test.ts.source:
import { describe, expect, it } from "vitest";

import type { ProviderKind } from "../src/platform-contracts";
import {
	getFirstPartyProviderTarget,
	listFirstPartyProviderTargets,
} from "../src/provider-targets";

describe("provider targets", () => {
	it("includes the required first-party providers for v1", () => {
		const providers = listFirstPartyProviderTargets().map((provider) => provider.id);
		expect(providers).toEqual(expect.arrayContaining(["github-pages", "cloudflare", "supabase"]));
	});

	it("describes github pages as a static publish target without a database", () => {
		const provider = getFirstPartyProviderTarget("github-pages");
		expect(provider.runtime).toBe("static");
		expect(provider.capabilities.staticPublishing).toBe(true);
		expect(provider.capabilities.database).toBe(false);
		expect(provider.capabilities.gitSync).toBe(true);
	});

	it("describes cloudflare and supabase as admin-capable runtimes", () => {
		for (const providerId of ["cloudflare", "supabase"] as const) {
			const provider = getFirstPartyProviderTarget(providerId);
			expect(provider.adminSurface).toBe("astropress");
			expect(provider.capabilities.hostedAdmin).toBe(true);
			expect(provider.capabilities.database).toBe(true);
		}
	});

	it("listFirstPartyProviderTargets returns no duplicates", () => {
		const ids = listFirstPartyProviderTargets().map((t) => t.id);
		expect(new Set(ids).size).toBe(ids.length);
	});

	it("entries carry the FirstPartyProviderTarget shape", () => {
		for (const t of listFirstPartyProviderTargets()) {
			expect(typeof t.id).toBe("string");
			expect(t.id.length).toBeGreaterThan(0);
			expect(typeof t.label).toBe("string");
			expect(typeof t.runtime).toBe("string");
			expect(typeof t.canonicalDeploySurface).toBe("string");
			expect(["astropress", "provider-managed"]).toContain(t.adminSurface);
		}
	});

	const ALL: ProviderKind[] = ["github-pages", "cloudflare", "supabase", "custom"];

	it.each(ALL)("getFirstPartyProviderTarget — id matches for %s", (key) => {
		const t = getFirstPartyProviderTarget(key);
		expect(t).toBeDefined();
		expect(t.id).toBe(key);
	});

	it("returns the same reference across calls for the same key", () => {
		const a = getFirstPartyProviderTarget("cloudflare");
		const b = getFirstPartyProviderTarget("cloudflare");
		expect(a).toBe(b);
	});
});

