import { describe, expect, it } from "vitest";

import { resolveNewsletter } from "../../../src/integrations/resolvers/newsletter-resolver";

const REG = { baseUrl: "https://lm.example.com", apiUser: "u", apiKey: "k" };
const FULL_ENV = {
	LISTMONK_API_URL: "https://lm-env.example.com",
	LISTMONK_API_USERNAME: "envU",
	LISTMONK_API_PASSWORD: "envP",
	LISTMONK_LIST_ID: "42",
};

describe("resolveNewsletter — NEWSLETTER_DELIVERY_MODE=mock forces mock", () => {
	it("returns mock when env explicitly forces it, even if registry has credentials", () => {
		const r = resolveNewsletter({
			registry: REG,
			env: { ...FULL_ENV, NEWSLETTER_DELIVERY_MODE: "mock" },
		});
		expect(r).toEqual({ kind: "mock" });
	});

	it("returns mock when env explicitly forces it, even if env has all four LISTMONK_*", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, NEWSLETTER_DELIVERY_MODE: "mock" },
		});
		expect(r).toEqual({ kind: "mock" });
	});

	it("does NOT force mock for any other NEWSLETTER_DELIVERY_MODE value (e.g. 'listmonk')", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, NEWSLETTER_DELIVERY_MODE: "listmonk" },
		});
		expect(r.kind).toBe("listmonk");
	});
});

describe("resolveNewsletter — listId is required for any listmonk path", () => {
	it("returns mock when LISTMONK_LIST_ID is missing even with full registry credentials", () => {
		const r = resolveNewsletter({
			registry: REG,
			env: {
				LISTMONK_API_URL: "x",
				LISTMONK_API_USERNAME: "u",
				LISTMONK_API_PASSWORD: "p",
			},
		});
		expect(r).toEqual({ kind: "mock" });
	});

	it("returns mock when LISTMONK_LIST_ID is empty string", () => {
		const r = resolveNewsletter({
			registry: REG,
			env: { LISTMONK_LIST_ID: "" },
		});
		expect(r).toEqual({ kind: "mock" });
	});

	it("returns mock when env is undefined (no listId reachable)", () => {
		const r = resolveNewsletter({ registry: REG });
		expect(r).toEqual({ kind: "mock" });
	});
});

describe("resolveNewsletter — registry takes priority over env", () => {
	it("returns listmonk/registry credentials when both registry and full env are present", () => {
		const r = resolveNewsletter({ registry: REG, env: FULL_ENV });
		expect(r).toEqual({
			kind: "listmonk",
			baseUrl: REG.baseUrl,
			apiUser: REG.apiUser,
			apiKey: REG.apiKey,
			listId: FULL_ENV.LISTMONK_LIST_ID,
			credentialSource: "registry",
		});
	});

	it("propagates the env's LISTMONK_LIST_ID even when credentials come from registry", () => {
		const r = resolveNewsletter({
			registry: REG,
			env: { ...FULL_ENV, LISTMONK_LIST_ID: "99" },
		});
		expect(r.kind).toBe("listmonk");
		if (r.kind === "listmonk") expect(r.listId).toBe("99");
	});

	it("does not mutate or trim the registry's apiKey", () => {
		const r = resolveNewsletter({
			registry: { ...REG, apiKey: "  pad  " },
			env: { LISTMONK_LIST_ID: "1" },
		});
		expect(r.kind).toBe("listmonk");
		if (r.kind === "listmonk") expect(r.apiKey).toBe("  pad  ");
	});
});

describe("resolveNewsletter — env-only credentials", () => {
	it("returns listmonk/env when registry is null and all four env vars are set", () => {
		const r = resolveNewsletter({ registry: null, env: FULL_ENV });
		expect(r).toEqual({
			kind: "listmonk",
			baseUrl: FULL_ENV.LISTMONK_API_URL,
			apiUser: FULL_ENV.LISTMONK_API_USERNAME,
			apiKey: FULL_ENV.LISTMONK_API_PASSWORD,
			listId: FULL_ENV.LISTMONK_LIST_ID,
			credentialSource: "env",
		});
	});

	it("returns mock when LISTMONK_API_URL is missing", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, LISTMONK_API_URL: undefined },
		});
		expect(r.kind).toBe("mock");
	});

	it("returns mock when LISTMONK_API_USERNAME is missing", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, LISTMONK_API_USERNAME: undefined },
		});
		expect(r.kind).toBe("mock");
	});

	it("returns mock when LISTMONK_API_PASSWORD is missing", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, LISTMONK_API_PASSWORD: undefined },
		});
		expect(r.kind).toBe("mock");
	});

	it("returns mock when LISTMONK_API_URL is empty string", () => {
		const r = resolveNewsletter({ env: { ...FULL_ENV, LISTMONK_API_URL: "" } });
		expect(r.kind).toBe("mock");
	});

	it("returns mock when LISTMONK_API_USERNAME is empty string", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, LISTMONK_API_USERNAME: "" },
		});
		expect(r.kind).toBe("mock");
	});

	it("returns mock when LISTMONK_API_PASSWORD is empty string", () => {
		const r = resolveNewsletter({
			env: { ...FULL_ENV, LISTMONK_API_PASSWORD: "" },
		});
		expect(r.kind).toBe("mock");
	});
});

describe("resolveNewsletter — explicit listmonk + missing config returns misconfigured", () => {
	it("returns misconfigured when mode=listmonk but LISTMONK_LIST_ID is missing", () => {
		const r = resolveNewsletter({
			env: { NEWSLETTER_DELIVERY_MODE: "listmonk" },
		});
		expect(r.kind).toBe("misconfigured");
		if (r.kind === "misconfigured") expect(r.reason).toMatch(/LIST_ID/);
	});

	it("returns misconfigured when mode=listmonk and listId set but credentials missing and no registry", () => {
		const r = resolveNewsletter({
			env: {
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_LIST_ID: "1",
			},
		});
		expect(r.kind).toBe("misconfigured");
		if (r.kind === "misconfigured") expect(r.reason).toMatch(/credentials/i);
	});

	it("does NOT return misconfigured when mode=listmonk and registry has credentials (uses registry)", () => {
		const r = resolveNewsletter({
			registry: REG,
			env: {
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_LIST_ID: "1",
			},
		});
		expect(r.kind).toBe("listmonk");
	});
});

describe("resolveNewsletter — empty result", () => {
	it("returns mock when input is entirely empty", () => {
		expect(resolveNewsletter({})).toEqual({ kind: "mock" });
	});

	it("returns mock when input is explicitly null/undefined for both sources", () => {
		expect(resolveNewsletter({ registry: null, env: null })).toEqual({
			kind: "mock",
		});
	});
});

tests/admin-normalizers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	normalizeEmail,
	normalizePath,
	normalizeRedirectPath,
	parseIdList,
	serializeIdList,
	slugify,
} from "../src/admin-normalizers";

describe("normalizePath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizePath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizePath("   ")).toBe("");
	});

	it("prepends slash when path lacks one", () => {
		expect(normalizePath("about")).toBe("/about");
	});

	it("preserves existing leading slash", () => {
		expect(normalizePath("/about")).toBe("/about");
	});

	it("trims surrounding whitespace before normalizing", () => {
		expect(normalizePath("  /about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizeRedirectPath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizeRedirectPath("   ")).toBe("");
	});

	it("rejects protocol-relative URLs (open redirect vector)", () => {
		expect(normalizeRedirectPath("//evil.example.com")).toBe("");
	});

	it("rejects protocol-relative URLs with trailing whitespace trimmed first", () => {
		expect(normalizeRedirectPath("  //evil.example.com/path  ")).toBe("");
	});

	it("prepends slash to relative paths", () => {
		expect(normalizeRedirectPath("dashboard")).toBe("/dashboard");
	});

	it("preserves existing leading slash", () => {
		expect(normalizeRedirectPath("/dashboard")).toBe("/dashboard");
	});
});

describe("normalizeEmail", () => {
	it("lowercases and trims the value", () => {
		expect(normalizeEmail("  Admin@Example.COM  ")).toBe("admin@example.com");
	});
});

describe("slugify", () => {
	it("lowercases, replaces non-alphanumeric runs with hyphens, strips leading/trailing hyphens", () => {
		expect(slugify("Hello World!")).toBe("hello-world");
	});
});

describe("parseIdList", () => {
	it.each([null, undefined, ""])("returns empty array for falsy input: %s", (value) => {
		expect(parseIdList(value)).toEqual([]);
	});

	it("returns empty array for invalid JSON string", () => {
		expect(parseIdList("not-json")).toEqual([]);
	});

	it("returns empty array when JSON is a non-array value", () => {
		expect(parseIdList('{"id":1}')).toEqual([]);
	});

	it("filters out non-integer and non-positive entries", () => {
		expect(parseIdList('["a", -1, 0, 1.5, 2]')).toEqual([2]);
	});

	it("parses a valid array of positive integers", () => {
		expect(parseIdList("[1, 2, 3]")).toEqual([1, 2, 3]);
	});
});

describe("serializeIdList", () => {
	it("serializes a sorted array of positive integers", () => {
		expect(serializeIdList([3, 1, 2])).toBe("[1,2,3]");
	});

	it("filters out non-positive entries before serializing", () => {
		expect(serializeIdList([0, -1, 3, 1])).toBe("[1,3]");
	});

	it("filters out non-integer entries", () => {
		expect(serializeIdList([1.5, 2, 3])).toBe("[2,3]");
	});

	it("returns empty array for all-negative input", () => {
		expect(serializeIdList([-1, -2, -3])).toBe("[]");
	});

	it("returns empty array for empty input", () => {
		expect(serializeIdList([])).toBe("[]");
	});
});

describe("slugify — edge cases", () => {
	it("collapses consecutive non-alphanumeric characters into a single hyphen", () => {
		expect(slugify("hello  world")).toBe("hello-world");
	});

	it("strips leading hyphens from special-char prefix", () => {
		expect(slugify("!hello")).toBe("hello");
	});

	it("strips trailing hyphens from special-char suffix", () => {
		expect(slugify("hello!")).toBe("hello");
	});

	it("strips multiple consecutive trailing hyphens", () => {
		// Kills Regex mutation: -+$ → -$ (only strips one trailing hyphen)
		expect(slugify("hello!!")).toBe("hello");
	});

	it("strips multiple consecutive leading hyphens", () => {
		// Kills Regex mutation: ^-+ → ^- (only strips one leading hyphen)
		expect(slugify("!!hello")).toBe("hello");
	});

	it("strips both leading and trailing hyphens", () => {
		expect(slugify("---hello world---")).toBe("hello-world");
	});

	it("collapses internal runs of hyphens produced by adjacent special chars", () => {
		expect(slugify("hello!!world")).toBe("hello-world");
	});

	it("handles leading and trailing whitespace without explicit trim", () => {
		expect(slugify("  hello  ")).toBe("hello");
	});

	it("returns empty string for all non-alphanumeric input", () => {
		expect(slugify("!!!")).toBe("");
	});

	it("trims whitespace before processing", () => {
		expect(slugify("  hello world  ")).toBe("hello-world");
	});
});

describe("parseIdList — boundary cases", () => {
	it("filters out zero (entry > 0 not >=)", () => {
		expect(parseIdList("[0]")).toEqual([]);
	});

	it("parses mixed valid and invalid values", () => {
		expect(parseIdList("[1, 0, -5, 3]")).toEqual([1, 3]);
	});
});

describe("normalizeEmail — individual transforms", () => {
	it("lowercases without trimming when no whitespace present", () => {
		expect(normalizeEmail("ADMIN@EXAMPLE.COM")).toBe("admin@example.com");
	});

	it("trims without case-folding when already lowercase", () => {
		expect(normalizeEmail("  admin@example.com  ")).toBe("admin@example.com");
	});
});

describe("normalizePath — whitespace without slash", () => {
	it("prepends slash to a path with inner whitespace stripped", () => {
		expect(normalizePath("  about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath — additional branches", () => {
	it("rejects path that is exactly '//'", () => {
		expect(normalizeRedirectPath("//")).toBe("");
	});

	it("accepts a single slash", () => {
		expect(normalizeRedirectPath("/")).toBe("/");
	});
});

tests/integrations/webhooks/registry.tes.source:
import { afterEach, describe, expect, it } from "vitest";

import {
	_resetInboundWebhookRegistryForTests,
	getInboundWebhookProvider,
	InboundWebhookRegistryError,
	listInboundWebhookProviders,
	registerInboundWebhookProvider,
} from "../../../src/integrations/webhooks/registry";

const GITHUB = {
	id: "github",
	label: "GitHub",
	signatureHeader: "X-Hub-Signature-256",
	algorithm: "hmac-sha256" as const,
	eventHeader: "X-GitHub-Event",
};

afterEach(() => _resetInboundWebhookRegistryForTests());

describe("registerInboundWebhookProvider", () => {
	it("registers a provider and returns the same definition", () => {
		expect(registerInboundWebhookProvider({ ...GITHUB })).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns the registered provider", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		expect(getInboundWebhookProvider("github")).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns undefined for an unregistered id", () => {
		expect(getInboundWebhookProvider("github")).toBeUndefined();
	});

	it("rejects duplicate ids with DUPLICATE_PROVIDER", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		let caught: unknown;
		try {
			registerInboundWebhookProvider({ ...GITHUB });
		} catch (e) {
			caught = e;
		}
		expect(caught).toBeInstanceOf(InboundWebhookRegistryError);
		const err = caught as InboundWebhookRegistryError;
		expect(err.name).toBe("InboundWebhookRegistryError");
		expect(err.code).toBe("DUPLICATE_PROVIDER");
		expect(err.message).toContain("github");
		expect(err.message).toContain("already registered");
	});

	it("listInboundWebhookProviders returns all registered providers", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		registerInboundWebhookProvider({ ...GITHUB, id: "stripe" });
		const ids = listInboundWebhookProviders()
			.map((p) => p.id)
			.sort();
		expect(ids).toEqual(["github", "stripe"]);
	});

	it("listInboundWebhookProviders returns an empty array when none registered", () => {
		expect(listInboundWebhookProviders()).toEqual([]);
	});
});

